-- Add Korean localization for existing locales_broadcast_text entries.
-- Only Korean locale columns are changed; other locales and base text are preserved.
SET NAMES utf8mb4;

INSERT INTO `locales_broadcast_text` (`entry`, `female_text_loc1`) VALUES
(12407, '마케팅 - iCoke 교환 안내 (S.H.E.)'),
(12426, '마케팅 - iCoke 교환 안내 (S.H.E. 비퀘스트)'),
(12829, '마케팅 - iCoke 교환 안내 (S.H.E. 선물 상자)'),
(12831, 'iCoke - 안내 (S.H.E. 선물 상자)'),
(17907, '매타조는 고귀한 생물입니다. 언제나 성심을 다해 다뤄야 합니다. 화난 매타조보다 위험한 것도 없으니 말입니다.'),
(18925, '우리 종족에게 당신의 가치와 헌신을 보여주기 전까지는 매타조를 구입할 수 없답니다.\n블러드 엘프들 사이에서 확고한 동맹의 평판을 얻기 전에는 돌아오지 마십시오. 이만 가주세요!'),
(47045, '이제는 살아갈 의욕도 없어요. 그냥 들짐승들이 절 잡아먹게 내버려 두세요.\r\n\r\n도시에 짐승이 없다고요? 정부에 득실대는 괴물들은 그럼 뭐라고 부르죠!\r\n\r\n전 꿈에도 못 꿀 만큼 부자가 될 수 있었어요. 그런데 그들이 그걸 빼앗아 갔다고요! 우리가 영원히 가난하게 살도록 꾸민 음모가 틀림없어요.'),
(49300, '얼라이언스의 영웅들이여, 우리의 요청에 응해 주셔서 감사합니다.'),
(49301, '호드의 영웅들이여, 우리의 요청에 응해 주셔서 감사합니다.'),
(49302, '현재 상황을 설명해 드리겠습니다. 이 일을 바로잡을 기회는 단 한 번뿐이니 잘 들어 주세요.'),
(49303, '무한의 용군단 요원들이 이 전투의 결과를 바꾸어 역사를 뒤틀려 하고 있습니다.'),
(49304, '그들은 오크 전사로 변장해 전세를 오크의 승리 쪽으로 기울이려 하고 있습니다.'),
(49305, '그들은 얼라이언스 병사로 변장해 전세를 자신들에게 유리하게 바꾸려 하고 있습니다.'),
(49306, '그들의 계획이 성공한다면 현재의 세계에 재앙과도 같은 결과가 닥칠 것입니다.'),
(49307, '다행히도 그들의 요원을 찾아내고 음모를 저지할 방법이 있습니다.'),
(49308, '전장을 수색해 희미하게 깜빡이는 시간의 불꽃을 찾아 알루르지온에게 가져가 분석을 맡기세요.'),
(49309, '시간의 불꽃을 총 100개 모으면 그들의 지도자가 누구인지 드러날 것입니다.'),
(49310, '하지만 조심하세요. 공격을 받으면 본래 모습으로 돌아가 자신의 힘을 전부 드러낼 가능성이 큽니다.'),
(49311, '희미하게 깜빡이는 시간의 불꽃을 많이 가져올수록 그들의 지도자는 약해집니다. 중앙 섬을 지키는 것이 승리의 열쇠예요. 그곳을 장악하지 못하면 불꽃을 제출할 수 없습니다.'),
(49312, '행운을 빌어요, 영웅들이여. 미래가 여러분에게 달려 있습니다.'),
(51239, '그들이 모든 걸 빼앗아 갔어요. 제 친구들은 감옥에 갇혔고요. 우리가 대체 무슨 잘못을 했기에 이런 대우를 받아야 하죠?\r\n\r\n크론 터스크는 사람들을 도우려 했을 뿐이에요. 가난을 없애고, 모두가 부자가 되는 세상을 만들려 했죠.\r\n\r\n생각해 보세요. 대체 어떤 대족장이 그런 일을 반대하겠어요?'),
(60473, '우리는 외부의 위험뿐 아니라 내부의 위험에도 늘 경계해야 합니다. 최근 텔드랏실에서 소요가 늘어나 더 많은 병력을 순찰에 투입하고 숲 전역에서 조사를 벌이고 있습니다.'),
(70003, '어머, 진짜 여행자시군요! 만나서 반가워요!'),
(70004, '어머, 손님이 오셨네요!$B$B<딩카가 잠시 생각에 잠깁니다.>$B$B아쉽지만 제 마법은 충분히 많은 곳을 여행한 분에게만 통하거든요. 세상을 좀 더 둘러보고 나서 다시 와 주세요.'),
(70005, '자, 자, 천천히 하세요. 서두를 필요 없어요. 전 어디 안 가니까요!'),
(90668, '제 유니콘은 실버문 잔존 세력의 엘프들과 그들에게 확고한 동맹으로 인정받은 분들에게만 판매하고 있어요.'),
(100004, '<크로미가 창백한 얼굴로 당신을 바라봅니다.>')
ON DUPLICATE KEY UPDATE `female_text_loc1` = VALUES(`female_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(98, '너희는 자신들의 땅을 망쳤다. 내 땅까지 망치게 두지는 않겠다.'),
(338, '비전 예술과 과학 아카데미에 온 것을 환영합니다. 오늘은 무엇을 도와드릴까요?'),
(392, '놀라지 마시오, $r. 나는 이미 오래전에 이 땅을 떠난 몸이지만, 그대 종족에게 해를 끼칠 생각은 없소. 살아생전 너무나 많은 죽음을 보았지. 이제 내가 바라는 것은 오직 평화뿐이오. 어쩌면 그대가 내 뜻을 도와줄 수 있을지도 모르겠군.'),
(1042, '반갑네, $n.'),
(1266, '[PH] 주문 시전을 취소할 수 있을 때까지 사용하는 임시 동작입니다.'),
(1285, '내가 언제나 당신을 사랑한다는 걸 기억해 주오...'),
(2263, '사우스쇼어에는 무슨 일로 왔소?'),
(3209, '마음 놓고 쉬거라, 젊은이여. 대지모신께서는 멀고어의 모든 자식들을 굽어살피시며, 우리 용사들은 언제나 경계를 늦추지 않는다.'),
(3802, '줄파락 - 위글리 블라스트퓨즈 - 기본 인사말.'),
(3810, '줄파락 - 하사관 블라이 - 기본 인사말.'),
(6894, '[테스트] 공격 전 $n 사망'),
(6895, '[테스트] 공격 후 $n 사망'),
(7878, '환영합니다, 여행자여.'),
(8176, '대장기술은 정교한 예술이지. 여기에 배치되기 전, 해머폴에서 꽤 오랫동안 대장기술을 연마했소.'),
(10116, '아스다스'),
(12387, '오, 진짜? <PH>'),
(12392, '3단계! <PH>'),
(12808, '이벤트 - 스컬지 침공, 신비술사 - 남은 시간, 단계 0'),
(12809, '이벤트 - 스컬지 침공, 신비술사 - 남은 시간, 단계 1'),
(12810, '이벤트 - 스컬지 침공, 신비술사 - 남은 시간, 단계 2'),
(12957, '이곳의 작업은 아주 순조롭게 진행되고 있습니다!'),
(13760, '점령 지점 경합 1'),
(13761, '점령 지점 경합 2'),
(13762, '점령 지점 승리 1'),
(13763, '점령 지점 승리 2'),
(13764, '점령 지점 진행 1'),
(13765, '점령 지점 진행 2'),
(16680, '아니 도대체 상황이 얼마나 절박하기에 가축을 동료로 받아들인답니까?'),
(30001, '너희는... 아무것도 모른다... 난 너희 모두보다 강력했다.'),
(30002, '우리는 이제 어둠을 받아들였다... 이리와서 그 힘을 보여주마!'),
(30003, '하하하하! 난 하주리의 영웅이다, 너는 누구냐 이봐?!'),
(30004, '내가 줄하주를 지배한다... 넌 날 절대로 죽이지 못한다...'),
(30005, '펄볼그는 살아남아야 한다! 이를 위해서라면 무엇이든 하겠다!'),
(30006, '숲을 보호해야 한다! 넌 날 막지 못한다!'),
(30007, '너희의 방해 따위로 우리를 막을 수는 없다!'),
(30008, '나는 주인님을 충실히 섬겼다! 방해하게 두지 않겠다!'),
(30009, '너... 너희는 여기 있으면 안 돼, 저리 가!'),
(30010, '이곳은 나의 영역이다, 용납하지 않겠다!'),
(30011, '장막 너머가 보이는구나... 내가 틀렸다... 고맙다 용감한 자여, 난 이제 자유다.'),
(30012, '지혜롭다는 것은 지식을 갖고, 자신보다 더 많이 보고 아는 이들의 조언에 귀를 기울이는 것이다. 이 세상에서 진정으로 발전하고 싶다면, 불편하고 경험해 보지 못한 영역으로 나아가야 한다. 성장하고, 새로운 것을 경험하며, 새로운 지식을 탐구해라. 때가 되면, 어린 자여, 많은 것에서 지혜를 얻게 될 것이다.'),
(30013, '덕이 있다는 것은 정의롭고 선한 사람이 되는 것이다. 우리 동족의 마을은 마음씨 선한 이들의 행동 위에 세워졌다. 여행 중에 많은 결정을 내려야 할 것이며, 항상 자신뿐만 아니라 모두를 위한 좋은 결과를 모색해야 한다. 동족의 유익을 위해 희생하는 것이 덕을 세우며 사는 삶이니, 이것을 항상 기억하고 옳은 일을 행하라.'),
(30014, '겸손하게 사는 것은 절제하며 사는 것이요, 필요한 것 이상을 탐하지 않고 미래를 위해 모든 것을 아끼는 것이다. 교만과 오만에서 벗어나라. 그것들은 진정한 발전을 방해할 뿐이다. 할 수 없는 이들을 위해 행하고, 남는 것을 필요한 이들에게 나누어라. 공동체의 기둥이 되어라. 사람들이 의지할 사람을 찾는 어두운 날이 올지니, 어린 자여, 그 사람이 바로 너이길 바란다.'),
(30015, '어이 두목, 선원 전부를 데려갈 순 없어. 다들 자기 할 일이 있고 배도 아직 출항할 준비가 안 됐다고. 이건 어려운 방법으로 해결해야겠어.'),
(30016, '죽음이 나를 거둔 모양이군, $r. 나는 엘드레탈라스의 비전술사이자 기록관인 소바티르다. 내 영혼과 기억의 일부를 그 일지 속에 넣어두었는데, 네가 주문을 읊어 나를 불러냈다. 하지만 그게 네 생명력을 조금 갉아먹었다는 건 알아두어라. 너무 많이는 아니길 바라지만.\n\n이제 네가 일지의 주인이니, 너는 나의 주인이다. 나를 지루하지 않게 해주고 더 많은 지식을 찾게 해주는 한, 내 지식은 너의 것이다. 그리고 다른 이들은 나를 볼 수 없다는 점을 명심해라.'),
(30017, '이 상자 안에 무언가 있는 것 같습니다.'),
(30018, '여기 선착장 말이오? 글쎄, 예전에 저 나이트 엘프 동네로 가던 배를 탈 수 있었지. 이름이 뭐였더라? 아, 오버다인이었나.\n\n그래요. 스톰윈드 항구로 가보는 게 좋을 거요. 요즘엔 적어도 스톰윈드에서 사람들이 왔다 갔다 한다고 들었거든요. 확실히는 모르겠소, 난 그저 짐을 싣고 내릴 뿐이라.'),
(30019, '쿠키가 아주 어렸을 때 배에 태웠었지. 처음엔 적대적이고 고약했지만, 자네가 찾은 그 책을 통해 유대감을 쌓게 되었다네. 어떤 면에서 쿠키는 단 한 마디도 몰라도 사람들을 이해할 수 있었지.\n\n자네에게 무슨 말을 해야 할지 모르겠군, 이봐. 쿠키는 내 친구였는데 자네를 보내 놈을 끝장내게 했으니... 내 생애 가장 큰 후회가 될지도 모르겠네.'),
(30020, '나는 호랑이의 힘을 부여받았다. 과정에서 얼마나 많은 상처를 입든, 반드시 승리하겠다!'),
(30021, '내 물건들을 둘러보시오. 난 이 빛조차 저주한 마을에서 제일가는 재봉사요.'),
(30022, '시국이 험난하지만, 사업 기회는 언제나 있는 법이지.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(30023, '빈둥거리는 광부나 감옥에 처넣는 줄 알았는데, 이제 진짜 싸움이 시작되는군!'),
(30024, '젠장. 놈들이 날 찾아낼 줄 알았지. 슬프게도, 모든 좋은 일엔 끝이 있는 법. 목숨을 걸고 싸우기 전에 누가 널 보냈는지 말해라. 몰티모어냐?'),
(30025, '역시 그 늙은 멍청이었군. 내 죽음이 모든 걸 해결해 줄 거라 생각하다니... 아, 얼마나 착각인지! 내 죽음으로 바뀌는 건 아무것도 없다!'),
(30026, '네가 알기만 했어도... 몰티모어, 뒤틀린 황천이... 널 삼켜버리길...'),
(30027, '손해 보는 거래였군...'),
(30028, '우리 검은창 부족은 고향에서 두 번이나 도망쳐야 했네. 구루바시가 가시덩굴 골짜기에서 쫓아냈을 때 한 번, 그리고 나가들이 섬에서 쫓아냈을 때 또 한 번이었지. 우리는 잃어버리는 아픔을 아네.'),
(30029, '나도 보았네. 하지만 놈들의 의도를 믿기가 어렵군. 칼림도어에 남은 몇 안 되는 트롤 부족 중, 파르라기 부족은 우코르즈가 정권을 잡기 전부터 평판이 최악이었네.'),
(30030, '호드는 갈 곳 없는 자라면 누구든 환영하네. 스랄은 2차 호드 시절 트롤의 역사에도 불구하고 검은창 부족을 받아주었지. 내 동족을 이 사막에 버려둘 순 없네.\n\n지금 당장 호드에 합류시키겠다는 건 아니지만, 도와줄 수는 있네. 그리고 줄파락의 광기를 막아야 하지.'),
(30031, '난 센진의 아들 볼진이다. 검은창 제도에서 도망친 지 오래되었지만, 이곳 듀로타에서 호드와 함께 새로운 고향과 미래를 찾았지.\n\n우리 부족은 끈질기다. 강물이 어떻게 흐르든 바위는 남아있는 법. 부두교를 멀리하고, 로아가 영원히 네 걸음을 인도하길 바란다, 친구여.\n\n검은창 부족을 위하여, 호드를 위하여!'),
(30032, '이 늪지대에는 많은 비밀이 숨겨져 있네. 주의 깊게 살펴보기만 하면 되지.'),
(30033, '멀록 오두막은 버려지고 방치된 것처럼 보입니다.'),
(30034, '둥지가 비어 있습니다.'),
(30035, '뭐라고요? 그 여자애가 외지인에게 그걸 말했단 말이오? 빛이여... 이건 생각했던 것보다 더 심각하군요. 제발 마지 블랙우드와 이야기해 보시오. 그녀가 이 마을의 조사관이자 현재 여러 사건을 담당하고 있소. 그녀에게 말하면 모든 걸 설명해 줄 거요. 아무래도 난 오늘 밤 밖에서 자야 할 것 같구려.'),
(30036, '어흠, 더 자세히 물어보는 분들께 이걸 읽어주라고 들었습니다. 무슨 소린지 이해가 안 가실 수도 있겠지만, 저도 마찬가지니까요. 자, 들어보세요...\n\n"이곳에 전시된 작품들은 서버 플레이어들이 제작한 것이며, 향후 더 많은 작품을 유치하기 위한 커뮤니티 공간입니다. 기여도에 따라 미술관이 확장될 수 있습니다! 멋진 작품을 제출하고 기여해 주신 모든 분께 감사드립니다. ~ 터틀 스태프"\n\n보세요, 저한테도 별로 말이 안 되는 소리라니까요.'),
(30037, '북녘골 수도원은 정말 멋지고 조용한 곳입니다.'),
(30038, '적이 다가온다, 호드의 형제자매들이여! 전쟁의 부름에 응답하여 감히 우리에게 도전하는 적들을 퇴치하라!'),
(30039, '우리 마그람은 적들과 전쟁 중이다. 동굴에 사는 겔키스와 달리 우리는 용맹함으로 유명하지...\n\n내가 이곳의 칸이다. 날 위해 무엇을 할 수 있느냐?'),
(30040, '<칸이 사나운 눈빛으로 노려봅니다.>'),
(30041, '너에겐 마그람의 정신이 있구나. 마셔라. 우리 피를 나눠라. 마그람이 되어라. 강해져라. 우리가 되어라!\n\n<거대한 칸이 엉겨붙은 붉은 피로 가득 찬 해골 술잔을 내밀어 보입니다.>'),
(30044, '나는 샤카다. 이곳을 지배하고 겔키스를 이끌지. 대담하게 굴지 마라, 외지인이여. 현명하지 못한 행동이다.'),
(30045, '너는 그 어떤 외지인보다 겔키스를 많이 도와주었다. 너에게 축복을 내려 명예 겔키스로 만들어 주고자 한다!\n\n<거대한 칸이 강렬한 향이 피어오르는 의식용 대접을 내밀어 보입니다.>'),
(30046, '비열한 호드 쓰레기들! 너희가 세상에 가져온 모든 배신과 비극에 대한 대가로 이 땅에서 지워지게 될 것이다!'),
(30047, '쿨 티라스는 너희가 아제로스에 가져온 고통을 결코 잊지 않을 것이다... 닻이 서 있는 한, 너희는 결코 평화를 누리지 못하리라...'),
(30048, '원하는 게 뭐냐, 풋내기?'),
(30049, '너희는 영원히 저주받으리라!'),
(30050, '그-그 사람도 날 사랑해 주었더라면...'),
(30051, '엄청나게 오래되어 보이는 고대 징입니다.'),
(30052, '모든 것입니다! 매복, 공격, 야생 동물 자체가 반란을 일으켰고, 심지어 그 놈의 원숭이들까지 나무에서 내려와 내 인부들을 공격했단 말입니다!\n\n섬 전역에 지속 가능하고 수익성 있는 수확 기반 기지들이 있었는데, 유인원들과 모르고인지 뭔지 하는 왕 때문에 다 미쳐 돌아가고 있습니다!\n\n일손도 부족하고 인력도 턱없이 모자라서 도움이 절실하니, 질문은 그만두십시오.'),
(30053, '텔아빔에서 다음 현상금을 수행할 자를 찾고 있습니다. 완료 증명이 확인되면 보상금이 지급됩니다!'),
(30054, '내 거야, 돌려주지 않을 테다!'),
(30055, '고양이 정령의 시선이 당신의 영혼을 꿰뚫습니다.'),
(30056, '네, 전설에 따르면 일 년 중 이 시기에는 고대정령이 다시 한번 이 땅을 거닌다고 합니다. 정확히 어디인지는 말씀드릴 수 없습니다. 말씀드렸다시피, 우리의 교감은 주로 드루이드들이 꾸는 꿈을 통해 이루어지니까요.'),
(30057, '흠... 전설에서는 겨울 족장을 물리적으로 어디서 찾을 수 있는지 언급하지 않지만, 멀고어는 오랫동안 우리 조상의 고향이었고 쫓겨났을 때조차도 다시 찾아갔던 곳입니다. 저라면 거기서 수색을 시작하겠어요. 전설을 찾을 때는 조심하십시오 어린 자여, 처음엔 구하지 않았던 답을 얻게 될지도 모르니.'),
(30058, '곰 아버지를 찾으시나요? 그렇다면 잿빛골짜기로 가셔야 합니다. 곰 아버지는 잿빛골짜기로 내려오는 이 시기를 제외하고 일 년 내내 하이잘 산의 얼음 슬로프에 거주한다고 합니다. 그를 찾더라도 분노를 사지 않도록 조심하십시오.'),
(30059, '그분을 찾고 계신가요? 그럼 우리 땅을 찾아보셔야 합니다. 정령은 드워프들보다 훨씬 전부터 여기에 있었고, 그들이 죽은 후에도 오랫동안 여기에 남아있을 테니까요.'),
(30060, '에? 전설이라는 거 알고 계시죠? 어쨌든 전설을 찾아 나선 첫 번째 사람이 되진 않을 겁니다. 일 년 중 이 시기에 눈으로 온 땅을 덮으며 거닌다고 하더군요. 던 모로에는 일 년 내내 눈이 내리니 주변 지역을 찾아보시는 걸 추천합니다. 모단 호수나 습지대는 어떨까요? 그 사이 산맥을 수색해 보는 것도 좋겠군요.'),
(30061, '헤? 그 사람 무릎에 앉기라도 하고 싶으신가요? 운이 좋으시네요, 바로 여기 골짜기에 계시니까요! 무릎에 앉혀주진 않겠지만, 약간의 요금을 내면 같이 사진을 찍을 수 있어요!'),
(30062, '글쎄요, 어디서부터 시작해야 할까요? 난 서부 몰락지대로 가서 그곳에 교회를 세우는 것을 도왔습니다. 지역 주민들은 매우 친절했고 신앙심 깊은 사람들이었으며 가능한 모든 방법으로 도왔지요. 나와 그들 모두가 공동체를 하나로 모았고, 강한 유대를 형성하며 서로 도왔습니다.'),
(30063, '하지만 한 세대 전부터 이어진 몰슨 가문과 이스턴 가문 두 가문 사이에 땅 소유권과 결혼 문제, 누구 소유인가를 둘러싼 분쟁이 있었지요.\n\n몰슨 가문 사람들은 이스턴 가문의 재산을 물려받을 거라는 생각을 품게 되었는데, 특히 카버라는 이름의 젊은 친구는 별별 문제에 휘말리던 불량배였습니다.'),
(30064, '이 무렵부터 악당들이 나타나기 시작했고, 카버 소년은 재빠르게 그들에 합류했습니다. 데피아즈단은 폭력과 살인 행위로 가족들이 땅을 떠나도록 위협했죠.\n\n곧이어 이스턴 가문은 냉혹하게 살해당했고, 다른 많은 가문도 비슷한 운명을 맞이하고 싶지 않아 그냥 떠나버렸습니다.'),
(30065, '내 교회에 나오는 사람들은 점차 줄어들었습니다. 소수의 신도가 있었지만 데피아즈단이 존재감을 드러내며 떠나라고 위협했고, 거절하자 죽기 직전까지 때렸습니다. 난 고집이 셌지만 죽을 만큼 고집스럽진 않았죠. 그래서 스톰윈드로 떠났고, 내 이야기는 여기서 이어집니다.'),
(30066, '내가... 설명해야겠군요. 그래요, 지금까지 당신에게 거짓말을 했습니다. 파라드와 고블린 기계의 도움을 받아 내가 골렘들을 만들었습니다. 수년 전 우리는 이곳 문브룩에 살았었죠.\n\n우린 그저 이 똥통 같은 곳을 벗어나고 싶었습니다. 그래서 농부들을 돕고 그들의 돈을 벌기 위해 수확 골렘을 만들었죠. 하지만 일반 농부가 사기엔 너무 비싸다는 걸 알고 아주 아주 저렴한 가격에 팔았습니다. 그 때문에 큰 손해를 보고 있었죠.'),
(30067, '어디로 흘러갈지 이미 알고 계실 겁니다. 자랑스러운 부분은 아닙니다. 꿍꿍이가 있었죠. 모두의 밭이 골렘으로 보호받게 되면, 그들의 본성을 활성화할 생각이었습니다.\n\n살인 기계가 되는 것이죠. 사악한 흑마법사나 다른 누구에게 덮어씌우면 그만이었습니다. 중요한 건 아주 비싼 가격에 골렘을 고칠 수 있는 사람이 우리뿐이라는 것이었죠.'),
(30068, '적어도 계획은 그랬습니다. 욕심에 눈이 돌아간 나는 파라드가 작업장에서 골렘들을 만지고 있을 때 살상 스위치를 켰습니다. 그가 죽어서 모든 돈이 내 차지가 되길 바랐죠.\n\n나중에 들으니 그는 살아남았고 시력만 잃었다고 하더군요. 나를 증오했습니다. 어찌 되었든 내가 일으킨 파괴를 보았습니다. 골렘들을 다시 유순하게 만들고 싶었지만... 우리 주문이 듣지 않았습니다.'),
(30069, '제작 과정에서의 실수인지, 기술 부족인지는 영영 알 수 없겠죠. 골렘들을 고칠 수 없었습니다. 서부 몰락지대는 황무지가 되었고, 데피아즈단이 파라드를 등에 업고 나타났습니다.\n\n뒷이야기는 알고 계실 겁니다. 나를 비난하고 괴물이라 생각하셔도 좋습니다. 사실, 당신 말이 맞을 겁니다. 난 괴물이었습니다. 하지만 고치기 위해 할 수 있는 모든 걸 했습니다. 그리고 빛이여, 부디 그것으로 충분하기만을 바랄 뿐입니다.'),
(30070, '우리를 도와주고 싶다니 기쁩니다. 현재 상황을 최대한 요약해 드리죠.'),
(30071, '상황을 설명하겠습니다. 저는 칼레드라 던브리즈라고 합니다. 2차 대전 당시에는 순찰대장 지휘관이었지만 지금은 그저 스톰윈드의 시민일 뿐이죠. 퀘엘탈라스를 잃은 후 우리 동족은 마법 중독으로 깊은 고통을 겪었습니다.\n\n옛 왕자 캘타스가 이끄는 일부는 어둠의 마법에 유혹당했고, 들리는 바에 의하면 나가라는 생물들의 편에 서서 얼라이언스를 배신했다고 합니다.'),
(30072, '더... 우려스러운 소식들도 들었지만, 어쨌든 그들은 우리를 떠났습니다. 우린 얼라이언스에 남기로 선택한 이들에게 집중해야 합니다. 몇 달 전, 저는 순찰대 요새 같은 외곽 정착지들에서 우리 동족의 대표들을 모으는 데 성공했습니다.'),
(30073, '우리 동족이 힘을 합쳐 스스로의 보금자리를 만들어야 할 때가 왔다는 것에 합의한 회의가 있었습니다. 언젠가 우리 동족을 재건할 수 있는 보금자리 말입니다. 군사 요새나 다른 종족의 도시에 얹혀사는 것은 우리 문화를 재건하는 길이 아닙니다.'),
(30074, '다행히 달라란의 살아남은 기록 보관소가 기회를 제공했습니다. 약 1세기 전, 퀘엘탈라스 근처 반도에 전초기지가 건설되었습니다. 그 전초기지는 태양의 샘 자체의 에너지로 가득 찬 비전 수정에 의해 작동합니다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(30075, '다시 말해, 우리가 시달려온 마법 중독에 대처할 수 있는 방법입니다. 수정이 영원히 지속되지는 않겠지만, 치료법을 찾을 시간을 벌어줄 것입니다.\n\n정찰병들이 그 부지를 찾아냈고 주거가 가능하다는 것을 확인했습니다. 우리 동족은 그 전초기지에 정착하기 시작했고, 우리 언어로 빛의 땅이라는 뜻의 알라탈라스라고 이름 붙였습니다.'),
(30076, '하지만 건물이 오래되었고 제대로 관리되지 않았습니다. 전초기지를 보호하는 마법을 유지할 시약과 재료가 부족합니다.\n\n마찬가지로 근처 광산은 괴물들로 들끓고 있죠. 즉, 도와주신다면 정말 감사하겠습니다!'),
(30077, '알리아나요? 아, 그렇군요. 직접 찾아왔어야 했는데! 당연히 도와드리죠. 그 아이에게 태도와 용모가 전부라고 전해 주세요. 어린 새들에게 부모나 스승이 아니라 친구이자 동등한 존재로 말하는 겁니다. 그들도 이 접근 방식을 존중할 것이고, 그들의 존중을 얻어야만 서로의 격차를 줄일 수 있을 테니까요.\n\n그들이 여전히 야생 동물이라는 점을 기억하세요. 그들이 우리에게 제공하는 힘과 봉사는 그들의 의지일 뿐, 우리가 길들였거나 요구해서가 아닙니다.\n\n이 조언을 가지고 알리아나에게 돌아가 주시고, 그리고 혹시 그녀에게 전해줄 수 있다면... 난 여전히 밤마다 그녀의 편지에 입을 맞추곤 합니다. 언젠가 개인 교습을 받으러 절 찾아와야 할 텐데요.'),
(30078, '네, 알리아나가 몇 달 전에 고민을 담아 편지를 보냈었죠. 문페더 가문은 엘룬이 아끼는 생물들과 교감하는 타고난 재능을 축복받았고, 그 생물들 역시 그들을 존중합니다.\n\n흠... 만약 그 생물들이 그녀나 그녀의 말을 인정하지 않는다면, 아직 숲의 존중을 얻지 못했기 때문일지도 모릅니다. 어린 새들은 본능만으로 그녀가 자신들이 선택한 자인지 알 수 있죠. 내가 태어난 숲을 방문한 지 오래되었지만, 그녀를 가치 있다고 판단할 숲의 왕이나 족장이 분명히 있을 겁니다.\n\n어쩌면 그녀는 이러한 생물 중 하나를 찾아내어 그들의 은총을 얻어야 할 지도 모르겠군요.'),
(30079, '아이고 이런, 끔찍해라!\n\n알리아나는 문페더 가문이지요? 저는 그녀가 자신에게 가장 잘 맞는 방법을 찾아낼 것이라 확신합니다. 히포그리프를 다루는 것은 매우 개인적인 수행이라 스승마다 다루는 방식이 다르니까요.\n\n그건 그렇고, 우리 신성한 숲의 동쪽 지역도 북쪽처럼 황폐해지고 있다고 들었습니다. 그녀에게 심심한 위로를 전하며, 엘룬께서 그녀에게 힘을 주시기를 바랍니다. 마음을 다스리기 위해 잠시 휴식을 취하는 것도 도움이 될 것입니다.\n\n결국 마음이 어지러운 상태에서는 야생수를 침착하게 만들 수 없으니까요.'),
(30080, '<그는 맡은 짐승들의 먹이를 채워주다 말고 고개를 들어 흙묻은 때묻은 손으로 이마의 땀을 닦아냅니다.>\n\n저는 지금 업무를 수행하느라 매우 바쁩니다, $c. 알리아나가 형제자매들의 뒤를 잇고 싶다면, 이런 엄숙한 자리를 얻기 위해 들어가는 피와 땀, 눈물의 시간, 날, 세월을 기꺼이 바칠 준비가 되어 있어야 할 겁니다.\n\n그럼 이만 실례하겠습니다.'),
(30081, '날카로운발톱은 당신이 다가가자 눈에 띄게 긴장하지만, 문페더라는 이름을 듣고 안도합니다. 결국 날갯짓을 멈추고 바닥에 둥지를 틀며 고개를 숙여 경의를 표하는 지저귐을 내뱉습니다.'),
(30082, '전략과 생명의 가치 문제입니다. 결국 모든 것은 그것으로 귀결되죠. 스타윈드는 지휘하에 있는 자들을 집결시키고 영광과 고향 방어에 대한 연설로 그들의 피를 끓어오르게 했습니다. 고결하긴 하지만, 우리가 트롤 광전사는 아니지 않습니까! 우리는 칼도레이입니다. 고결하고, 강하고, 지혜롭지요. 가슴이 너무나 아프게도, 이제 막 첫 세기를 지낸 수습생들과 어린 파수꾼 자매들이 우리 고향의 베어낸 나무 사이에서 오크, 고블린과 소규모 전투를 벌이기 위해 달려가는 것이 보입니다.'),
(30083, '물론 그들을 도울 수 있습니다. 강철과 손톱, 피와 분노의 혼란 속으로 다른 이들과 함께 돌진할 수 있죠. 호드가 가장 강한 곳을 강타하고 우리의 무자비한 힘으로 놈들을 축출할 수도 있습니다. 하지만 그렇게 예방할 수 있는 인명 피해에 대해 제가 명을 내리고 책임져야 한다고 생각하신다면? 그렇다면 당신도 그 여자만큼이나 어리석은 겁니다.'),
(30084, '아닙니다! 우리가 공략할 수 있는 약점이 있고, 호드 전쟁 기계의 핵심 부위를 파괴하여 놈들을 무력하게 만들 수 있습니다. 최소한의 위험으로 이 전쟁에서 승리할 수 있죠. 말했듯이, 매는 여우 앞에 서서 여우의 방식대로 싸우지 않습니다...'),
(30085, '바로 그겁니다. 그렇게 생각하는 것이 차갑고 계산적으로 보일지 모르지만, 어린 자매들을 무의미한 전투로 보낸 것은 제가 아닙니다. 내 양심은 깨끗합니다. 이것이 가장 빠르고 효과적으로 승리하는 길일 것입니다. 성급한 지휘관이 믿지 않더라도 저를 믿어보십시오!'),
(30086, '물론, 아직 안 하셨다면 스타윈드 지휘관과 이야기해 보십시오. 하지만 이것만은 알아두십시오 - 한 시간이 지날 때마다 엘룬의 또 다른 선택받은 자가 토끼풀을 덮고 눕게 될 것입니다.'),
(30087, '정찰병들이 우리 땅에 대한 침입을 보고한 순간, 저는 근처에 배치된 자들을 집결시켰습니다. 우유부단함 때문에 호드가 전초기지를 세우고 벌목장을 짓게 되었습니다!\n\n더 이상은 안 됩니다. 대부분은 이미 싸우러 갔지만, 아이언글레이드는 무슨 마스터 플랜을 짜느니, 속임수가 어쩌느니 소리를 하고 있습니다! 그가 의자에 편히 앉아 말만 하는 동안, 우리는 싸우느라 바쁩니다. 그리고 그 겁쟁이는 돕기를 거부하고 후퇴해서 재정비하길 원합니다!'),
(30088, '$c, 우리 싸움 방식에 대해 잘 모르시죠? 우리는 나무 우림의 그림자 속에 녹아들었다가, 필요할 때 타격을 가할 수 있습니다.\n\n여기에는 힘이 있습니다. 후퇴하는 자매는 보이지 않는 화살과 단검의 도움을 받을 것입니다. 우리 모두가 후퇴한다면, 지금까지 흘린 피는 무용지물이 될 것이고, 그 과정에서 많은 우리가 죽고 사로잡힐 것입니다. 절대 안 됩니다.'),
(30089, '선택의 여지가 없습니다. 저는 호드에게 우리의 뒷모습을 보이지도 않을 것이며, 후퇴라는 비겁함을 변명하지도 않을 것입니다. 도망치는 동안 놈들에게 사로잡힐 기회조차 주지 않을 것입니다. 그가 돕지 않는다면 저에게 힘을 보태주십시오. 호드의 기세를 꺾고 칼도레이 땅을 침범한다는 것이 무엇을 의미하는지 보여줍시다.'),
(30090, '영광은 결과일 뿐, 우리는 고향을 위해 희생합니다. 그리고 저는 우리가 죽느니 그 녹색 피부 놈들이 우리 고향을 위해 죽게 만드는 편이 훨씬 낫습니다. 동의하십니까, 아니면 실제로 싸우고 있는 동안 다른 이들처럼 머뭇거리며 지체하시겠습니까?'),
(30091, '편하게 하되 서두르십시오. 브롤탄 아이언글레이드와 이야기해 보세요. 그가 있든 없든 싸울 준비가 되면 돌아오십시오.'),
(30092, '나, 에본로크 주공이 어떻게 이토록 비참한 처지가 되었는지 곰곰이 생각하고 있을지도 모르겠구나. 하지만 많은 비극적인 이야기들이 그렇듯, 내 이야기도 권력에 대한 끝없는 갈증에서 시작되었다. 그랜드 해믈릿의 통치자로서 나는 더 많은 것을 열망했고, 스톰윈드의 권좌에 가까워지기를 갈망했으며, 가장 영향력 있는 인물들을 만나 사회적 신분을 올리고 마침내 왕관 자체를 목표로 삼았다.\n\n더 큰 권력에 대한 욕망에 눈이 멀어 내 동족조차 안중에 없었고, 원하는 것을 얻기 위해 무자비하고 잔혹하며 불의한 짓을 서슴지 않았다. 내가 저지른 만행은 차마 다시 떠올리기조차 버겁구나. 그럼에도 불행히도 내 악행은 그 저주받은 마법사 메디브의 죄악에 비하면 아무것도 아니다. 그의 사악한 행위는 내가 죽은 후에도 나를 괴롭히고 있으니.'),
(30093, '카라잔의 위대한 주공인 메디브를 알현하기를 갈망하며, 내가 이 우뚝 솟은 구조물에 처음 눈을 돌린 지 수년이 지났다. 아, 그 힘과 지식을 얼마나 탐냈던가.\n\n카라잔 안에 숨겨진 비밀들이 나를 불렀고, 내 목표를 달성하기 위해 휘두를 수 있는 어둠의 마법과 오묘한 신비들을 약속했다. 그리하여 나는 집착하게 되었고, 내 임무와 동족, 심지어 내 가족마저 버린 채 수없이 탑을 방문했다. 오직 그 마법사와 이야기할 기회를 얻기 위해서.\n\n하지만 슬프게도 내 노력은 수포로 돌아갔다. 내가 아무리 간절히 청해도 메디브는 결코 나를 알현해 주지 않았다. 그가 개최한 호화로운 연회와 성대한 파티에 다른 이들이 초대받는 것을 보았다. 왜 그는 나만 피했던 것일까?'),
(30094, '이제 지나고 나서야 내 집착이 얼마나 어리석었는지 깨닫는다. 헛된 권력의 약속을 위해 얼마나 많은 것을 희생했던가. 사소한 것 하나 이루지 못한 채 말이다. 그럼에도 내 마음은 놓친 기회들과 낭비된 세월에 대한 후회로 여전히 아프다. 내가 지금 아는 것을 그때 알았더라면. 하지만 슬프게도 과거는 돌에 새겨져 바꿀 수 없고, 나는 내 집착의 그림자에 영원히 갇힌 채, 이루지 못한 가능성들과 수많은 만약을 곰곰이 생각하도록 남겨졌다.\n\n모든 것을 바꾼 날은 한 마리의 단순한 까마귀 형태로 찾아왔다. 까마귀는 카라잔의 집사인 모로스로부터 온 편지를 들고 내 거처로 날아왔는데, 탑의 벽 안에서 열리는 성대한 무도회에 나를 초대한다는 내용이었다.'),
(30095, '절대 놓칠 수 없는 기회였다. 마침내 위대한 메디브를 만나 그의 한없는 지혜를 배울 기회였으니까.\n\n두 번 생각할 것도 없이 나는 성에서 뛰쳐나와 내 임무와 동족을 뒤로한 채 카라잔으로 향했다. 열병 같은 에너지에 이끌려, 어떤 대가를 치르더라도 그곳에 있어야 한다는 느낌에 사로잡혀 있었다. 지금 돌이켜보면, 내가 그의 신성한 성채에 발을 들여놓기도 전에 메디브는 이미 나를 조종하기 시작했던 것 같다.'),
(30096, '탑에 도착하자 나는 안으로 안내되었고, 메디브 자신이 다른 손님들과 섞이는 동안 자유롭게 거닐 수 있도록 허락받았다. 평생 잊지 못할 경험이었다. 탑은 이전에 본 적 없는 마법과 놀라움으로 살아 움직이고 있었으니까. 이 모든 것이 메디브에게는 그저 게임에 불과했던 걸까? 손님들을 점점 더 깊은 영향력과 권력의 그물 속으로 끌어들이며 장난치는 방법이었던 걸까?\n\n그날 밤을 돌이켜보면, 그것이 내 종말의 시작이었음을 깨닫는다. 내 몰락과 파멸, 그리고 결국 영원한 저주로 이어질 길의 첫걸음이었음을.\n\n카라잔의 구불구불한 복도와 끝없는 무도회장을 거니는 동안 시간은 내게서 빠져나가는 것 같았다. 겨우 몇 분이 지난 것처럼 느껴졌다. 바로 그때 무언가 잘못되었다는 것을 깨달았다. 탑이 불과 몇 순간 전에 감탄하던 것과는 확연히 달라졌기 때문이었다.'),
(30097, '한때 흥겨움과 웃음이 가득했던 곳에 이제는 텅 빔과 쇠락만이 남아있었다. 환영들이 복도를 기어 다녔고, 그들의 신음과 속삭임이 빈 홀에 울려 퍼졌다. 내가 처음 도착한 이후 얼마나 많은 시간이 흘렀던가? 알 수 없었다. 카라잔의 경계 안에서는 시간이 다르게 흘렀으니까.\n\n바로 그때 내 몸을 바라보았지만, 볼 수 있는 몸이 없다는 것을 깨달았다. 나와 모든 손님들이 살해당했고, 우리의 정수가 메디브의 어두운 계획을 위한 연료로 빨려 나간 것이다. 번개처럼 깨달음이 내리쳤고, 나는 그의 힘을 믿고 그의 지식을 구했던 내가 참으로 어리석었음을 알게 되었다.\n\n내 오만함과 권력에 대한 집착의 기억이 내 안에서 타올랐고, 내 어리석음을 끊임없이 일깨워주었다. 그리하여 나는 과거의 유령으로 남아, 카라잔의 홀을 영원히 떠돌며 그 안에 숨겨진 위험을 다른 이들에게 경고하도록 저주받았다.'),
(30098, '이 저주받은 탑에 묶인 내 영혼은 과거의 기억과 나를 둘러싼 공포로 고통받으며 감돌고 있다. 이곳의 어둠은 한때 이 홀을 거닐던 이들의 영혼을 삼켜버려 그들을 길 잃고 미치게 만들었다. 하지만 나는 겨우겨우 제정신을 유지하고 있다.\n\n나는 메디브에게 복수를 구하지 않는다. 내 운명을 받아들인 지 오래되었기 때문이다. 대신 내 유일한 욕망은 그가 이 탑에 숨겨둔 비밀을 밝쳐내는 것이다. 통치자로서 나는 권력과 지식을 구했고, 이제 나는 같은 갈증에 이끌리고 있지만, 이유는 다르다.'),
(30099, '카라잔의 하층부는 내가 구하는 지식의 일부만을 가지고 있다. 이 탑의 진정한 힘은 집사인 모로스가 봉인한 상층부를 통해서만 접근할 수 있다. 그는 상층 탑의 열쇠를 지독한 헌신으로 지키고 있으며, 나는 그가 이제 훨씬 더 어두운 주인을 섬기고 있다고 믿는다...\n\n이 탑의 신비를 파헤치도록 나를 도와주길 간청한다. 카라잔 상층부에서 찾는 지식을 나와 공유해 다오. 함께라면 이 저주받은 곳에서 무슨 일이 일어났는지 진실을 조각조각 맞추고, 아직 이곳에 머물고 있는 고통받는 영혼들에게 어느 정도의 평화를 가져다줄 수 있을지도 모른다.'),
(30100, '많은 이들이 달라란 파괴 이후 내가 늙고 삶에 지쳐 은퇴했다고 믿는다. 하지만 진실은, 카라잔에 숨겨진 힘을 구하는 자들의 질문에 답하는 것을 피하기 위해 이 외딴곳에 숨어버린 것이다. 언젠가 누군가 나를 찾아와 그 방들의 비밀을 풀 지식을 구하리라는 것을 알고 있었다.\n\n나는 그저 열쇠와 함께 당신을 돌려보내고 내 지식을 혼자 간직할 수도 있지만, 내 깊은 곳에서는 그렇게 할 수 없다는 것을 안다. 당신이 상상할 수 있는 것보다 더 어두운 세력들이 이미 카라잔 상층부에 자리를 잡았고, 그들이 아제로스에 풀려나는 것을 막을 시간이 얼마 남지 않았다는 것이 두렵다.'),
(30101, '카라잔의 지맥을 이용하려는 세력의 정확한 본질은 아직 알 수 없지만, 꿈속에서 나는 불타는 그림자가 내가 소중히 여기는 모든 것을 천천히 삼키는 것을 보았고, 이 환상이 현실이 되게 둘 수는 없다. 이번에는 실패하지 않을 것이다. 걸린 것이 너무나 크기 때문이다.\n\n나는 과거에 실패했고, 내 실패는 세상의 파멸을 가져올 뻔했다. 내 친구 메디브가 어둠에 굴복하도록 방치했고, 다시는 같은 실수을 반복하는 것을 견딜 수 없다. 비록 과거를 바꿀 수는 없지만, 당신이 미래에 그것을 반복하는 것을 도울 수는 있다. 그러니 내 경고에 귀를 기울이고 최악의 상황에 대비하라.'),
(30102, '오늘날 당신이 보는 이 땅은 예전에 코르탄 왕국이라 불렸다. 세대를 거쳐 습격자 왕이라는 칭호를 받을 자격이 있는 모든 사람은 남은 생 동안 지배하고 섬겨야 할 땅의 이름을 따서 코르탄이라 불렸다.'),
(30103, '여러 세대 동안 우리는 우리가 원했던 것을 정확히 가졌다. 우리는 전쟁과 전투의 왕국이었다! 전투에 대한 우리의 갈증은 그 누구와도 같지 않았다. 우리는 정복의 사내들이었지만 영토를 확장하지는 않았다. 패배한 모든 적은 자신의 위치를 알고 있었다.'),
(30104, '세대를 거쳐 살아있는 불꽃의 수호자로서 우리 아들 딸들은 제스 또는 제스타리아라는 이름을 가졌고, 우리 종교의 바로 그 상징이 되어야 했다. 우리가 처음 대화했을 때 내가 제스타리아의 저주를 말했던 것을 기억할 것이다. 실제로 우리 모두를 영원한 언데드로 저주한 것은 내 딸이었다.'),
(30105, '꽤 긴 이야기다. 제스타리아는 언제나 코르탄을 사랑했다. 우리 조상인 아조타가 좋든 나쁘든 이 세상에 우리를 남겨둔 만큼, 그녀는 이 세상에서 더 좋은 것을 알지 못했다. 코르탄에 대한 그녀의 사랑은 그녀를 미치게 만들었다.\n\n나는 국왕에게 그와 수호자의 딸과의 결합이 왕국에 큰 도움이 될 것이라고 설득했지만, 결혼식 날 코르탄은 평민 애인과 함께 나타났다.'),
(30106, '솔직히 말해서 우리 왕에게 나쁜 감정은 없다, 친구여. 우리는 우리가 사랑하는 사람을 선택하지 않으니까. 하지만 제스타리아는 그녀가 배신이라고 부른 이 일을 좋게 받아들이지 않았다.'),
(30107, '제스타리아는 영원한 죽음의 군주와 무서운 계약을 맺었고, 그리하여 코르탄과 그의 아내, 그리고 그의 왕국을 영원한 언데드로 저주했다... 이제 우리는 시간에 표류된 채 여기에 남아있다.'),
(30108, '무슨 소리를 하는 거요? 경비병을 부르게 만들지 마시오!'),
(30109, '리비아가 호드 단원을 보낼 줄은 몰랐는데. 무슨 생각이었지?\n\n어쨌든. 이 봉인된 보고서가 그녀에게 전달되도록 하시오.'),
(30110, '이런 추위 속에서도 빛 안에서 찾을 수 있는 따뜻함을 품을 수 있습니다. 잠시 기도할 시간이 있으신가요 $c?'),
(30111, '당신에게 할 말 없습니다. 내 눈앞에서 사라지시오.'),
(30112, '우리가 교류해야 한다고 생각하지 않습니다. 나에게 다시는 말을 걸지 말아주시길 정중히 요청합니다.'),
(30113, '거대한 밸브가 격렬하게 증기를 뿜어냅니다.'),
(30114, '바닥에 다음과 같은 글자가 새겨진 오래된 레버입니다.\n\'예비 펌프 레버\''),
(30115, '<불길이 기분 나쁘게 빛납니다.>'),
(30116, '이 우체통은 오랫동안 여기에 있었던 것 같습니다.\n두려움의 기운이 피어오르는 듯하니, 오래 머물지 않는 것이 좋습니다.'),
(30117, '에메랄드의 꿈이 무엇인지 아는가, 필멸자여?\n\n본질적으로 아제로스와 에메랄드의 꿈은 서로 기묘하게 얽혀 있으면서도 고유한 성질을 지닌 평행한 반사체로 인지될 수 있다. 에메랄드의 꿈은 필멸자의 개입으로 손상되지 않은 아제로스의 태초 모습을 보여주는 신비한 렌즈 역할을 하지.\n\n에메랄드의 꿈 안에는 대격변의 분열로 훼손되지 않은 칼림도어의 원형 대륙이 존재하며, 영원한 세월 동안 무성하게 번성해 온 울창한 에메랄드빛 숲으로 덮여 있다.'),
(30118, '깨어있는 아제로스 세계의 방문자들은, 지각이 있든 야생이든 가리지 않고 알게 모르게 이 천상의 영역으로 흘러들게 된다.\n\n이 생물들은 잠을 통해 꿈에 들어가 필멸자 세계의 속삭임을 가져온다. 이 마법의 영역에서 꿈은 깊은 의미를 지니며, 귀 기울여 듣는 이들에게 예언과 지침의 환영을 자아내곤 하지.'),
(30119, '에메랄드의 꿈은 고결한 녹색의 위상 이세라의 영토이며, 우리 녹색용군단은 이 영역을 어떤 대가를 치르더라도 수호하겠다는 단호한 의지로 그녀의 곁을 굳건히 지키고 있다.\n\n우리 동족의 대부분은 꿈속에 거주하며, 그들의 영혼과 육체는 그 천상의 품 안에 얽혀 있지. 먼 옛날, 무한한 지혜에 이끌려 이세라는 우리 동족 중 하나인 솔니우스를 깨우는 자라는 중대한 역할로 선택했다.\n\n비참한 위기에 처했을 때 꿈속에서 잠자고 있는 녹색용들을 깨우는 권능을 부여받은 솔니우스는 막중한 책임을 지고 있었지.'),
(30120, '하지만 우리 중 누구도 악몽의 음흉한 출현을 예견하지 못했다. 출처를 알 수 없는 사악한 세력인 악몽은 손에 닿는 모든 것을 삼켜버리고 파멸과 광기만을 남긴다.\n\n슬프게도 솔니우스는 이 비열한 타락의 움켜쥠에 굴복했고, 그의 정수 자체가 악몽의 손아귀에 사로잡히고 말았다.'),
(30121, '우리는 솔니우스가 꿈에서 우리 동족을 깨우는 것을 막아야 한다. 그들의 영혼 파편이 꿈에 묶여 있는 동안 육신이 필멸자의 영역으로 돌아온다면, 그들은 악몽의 음흉한 오염에 지독하게 취약해질 것이다.\n\n타락은 그들의 영혼에 침투하여 결국 그들의 육신을 오염시킬 것이며, 악몽은 아제로스로 유해한 길을 찾아낼 것이다—경계가 없고 진격을 저지하려는 모든 시도를 무력화하는 세력이지.'),
(30122, '우리의 유일한 희망은 솔니우스를 저지하고 그를 다시 꿈의 품으로 되돌리는 버거운 과업에 달려 있다. 비록 그의 목숨을 끊는 최후의 수단에 호소하는 것을 의미할지라도 말이다. 그것이 우리의 유일한 희망이다.'),
(30123, '간단히 말하겠다.\n\n겐 그레이메인은 길네아스를 세상의 나머지 지역을 괴롭히는 문제들로부터 차단하고자 했다. 그는 우리가 홀로 설 수 있는 힘과 탄력성을 가지고 있으며, 외부 세계는 투쟁만을 가져온다고 굳게 믿었다. 그리고 한동안은 그의 말이 맞았던 것 같았다. 가공할 그레이메인 성벽이 완성된 직후, 무서운 스컬지가 북부에 몰아쳐 황량함과 폐허만을 남겼다.\n\n하지만 우리의 고립된 삶은 그 자체의 도전을 가져왔다. 식량 부족과 무력화시키는 무역 제한이 우리를 괴롭혔다. 스컬지와 워겐은 우리 왕국으로 들어올 길을 찾아냈다. 이러한 고난에도 불구하고 국왕은 단호함을 유지하며 어리석게도 우리 문을 열기를 거부하고 그의 귀족들과 백성들로부터 더욱 소외되어 갔다.'),
(30124, '그는 자신의 가족이라는 울타리 안에 들어앉아 더욱 고립되어 갔다. 그리고 성벽 안에서 안식처를 찾았던 알터랙 쓰레기인 할로우 가문이 찾아왔다. 그들은 겐의 귀에 독을 속삭이며, 그를 충성스러운 귀족들과 평민들로부터 더욱 격리시켰다.\n\n부족한 자원을 보존하기 위해 나를 포함한 많은 귀족들은 재분배를 위해 영지와 재산을 압류당했다. 고통스러운 일격이었다. 나는 국왕의 결정에 강력히 반대해 왔었기 때문이다. 영지를 박탈당한 나에게 남은 것은 내 안에서 타오르는 의로운 분노의 불꽃뿐이었다.\n\n이 혼란 속에서도 아내 미아에 대한 겐의 변함없는 사랑은 얼마간의 제정신을 제공했다. 그녀의 청에 따라 그는 은둔에서 벗어나 길네아스 백성들에게 식량과 옷을 나누어주는 공개 행사를 조직했다. 유감스럽게도 빈약한 자원은 금세 줄어들었고 평민들과 경비병들 사이에 충돌이 일어났다. 이어진 혼란 속에서 미아는 비극적으로 목숨을 잃었다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(30125, '절망한 겐은 저택의 경계로 물러나 대중의 시선에서 사라졌다. 할로우 가문은 섭정으로서 권력을 잡고 길네아스에 폭정을 피웠다. 미아 살해 혐의로 억울하게 누명을 쓴 나는 평민들의 지지를 모아 압제적인 정권에 맞서 일어설 수밖에 없었다.\n\n내 마음속 깊은 곳에서 겐이 더 이상 살아있는 자들 사이에 없음을 안다. 비록 제정신이 아닌 상태라 할지라도, 그는 결코 그런 불의가 판치도록 내버려 두지 않았을 테니까. 이 반란을 계속 이끌어 나가면서, 우리는 정의를 되찾고 억압의 손아귀로부터 길네아스를 해방하기 위해 노력할 것이다.'),
(30126, '급하게 만들어진 무덤입니다. 서툰 글씨체로 나무에 다음과 같은 글이 새겨져 있습니다.\n<프랭클린 블랙하트. 편히 쉬게 형제여.>'),
(30127, '돌이 부드럽게 웅웅거립니다.'),
(30128, '캐서린에게 무슨 짓을 한 거냐? 물러서라!'),
(30129, '낫을 내놓아라. 그러면 목숨만은 살려줄 수도 있다.'),
(30130, '우리가 널 찾아낼 것이다...'),
(30131, '흠, 그러고 보니 들려줄 이야기가 하나 있군요.$B$B얼마 전 축제가 열렸을 때 메디브께서 손님들을 몇 차례 찾아오셨습니다. 그런데 그중 한 번은 뭔가 이상했어요. 길고 검은 물건 같은 것을 들고 계셨고, 식당에 있는 대리석 조각상을 살펴보셨죠. 몇 초 뒤 그분이 자리를 떠나는 것을 봤는데, 그때는 그 검은 물건을 들고 있지 않았습니다.$B$B별일 아닐 수도 있지만, 이상하게도 그 장면이 계속 마음에 걸렸습니다. 물론 이런 수작이라면 메디브와 그의 마법이 관련되어 있을 거라고 생각합니다.'),
(30132, '<이 대리석 조각상은 이곳에 있기에는 묘하게 어울리지 않아 보인다.>'),
(30133, '<구체가 강렬한 암흑 에너지를 내뿜으며 빛난다. 표면을 따라 불길이 흐르는 것이 보인다. 구체에 가까이 다가가려 하면 형체가 희미해져 반투명해지고, 물질이 그대로 통과해 버린다. 이곳에는 강력한 마법이 깃들어 있는 듯하다.>'),
(30134, '감히 내 먹잇감에 끼어들어? 저 여자는 내 것이다! 저 여자를 끝장낸 다음엔 네 차례다!'),
(30135, '이걸로 끝난 줄 알아라! 언젠가 반드시 널 찾아내겠다… 오늘 네가 빼앗아 간 영혼의 대가는 네 영혼으로 치르게 될 것이다.'),
(30136, '그냥 가라. 이제는 네 족속과 이야기하는 것조차 즐겁지 않다. 아니, 정확히 말하자면.$B$B썩 꺼져라.'),
(30137, '무슨 일이냐, 필멸자여? 안으로 들어가고 싶다고? 그래, 들어가도 좋다. 아직 눈은 제대로 보이는 것 같군. 네 앞을 막는 것이 아무것도 없다는 건 알겠지. 그렇지?'),
(30138, '내 것을 빼앗아 가지 못할 것이다!'),
(30139, '아버지...'),
(30140, '우리 와일드해머 중에는 과거를 잘 모르는 이들이 많다네. 모디무스 대왕 아래 하나였던 세 부족의 시절도, 위대한 그림 바톨의 몰락도 말이지. 나 같은 전승지기의 일은 어린 녀석들이 날개를 펴기 전에 자신들의 뿌리를 잊지 않도록 일깨워 주는 것이지.'),
(30141, '좋다, 녀석들아. 잘 들어라. 너희 무기는 받아 봤다. 솔직히 말해서 실망스럽구나. 너희 이방인을 자기들 이익을 위해 이용한 것도 모자라, 대장장이의 기술까지 하찮은 자존심을 세우는 데 써먹었더구나.'),
(30142, '브록. 네 도끼는 신드리의 자신감만큼이나 허약하구나. 새김 광석만으로는 튼튼한 금속을 만들 수 없어. 다른 재료와 섞어야 한다. 안 그러면 결국 이런 꼴이 나지. 내가 엉덩이로 깔고 앉기만 해도 부러뜨릴 수 있겠구나! 네 작품에 생각을 좀 더 담아라.'),
(30143, '신드리. 네 철퇴는 이론대로라면 흠잡을 데 없이 잘 만들었다. 하지만 영혼이 없어. 대장장이는 자신이 만든 것에 생명을 불어넣는 법이지. 그런데 네 것은 아니구나. 이 물건은 브록이 맥주 열 잔을 마신 뒤만큼이나 할 말이 없군. 네 기술을 느끼는 법을 배우지 못한다면, 썬더포지의 이름에 걸맞은 무기는 절대 만들지 못할 게다.'),
(30144, '마지막으로 한마디만 하마. 서로 말을 좀 들어라. 카드로스의 이름으로, 너희는 형제잖느냐! 누가 더 잘났는지 따지는 걸 그만두면 이 창 같은 무기를 만들어서 평생 한 번쯤은 날 감탄시킬 수도 있을 게다. 자, 망치 들고 두드리기 시작해!'),
(30145, '네, 어머니...'),
(30146, '듣고 있어, 프리그.'),
(30147, '밀린 골조 물량을 받으러 왔습니다.'),
(30148, '아, 그거 말이지... 그래, 창고에 있어. 바로 맞은편 건물이야. 인력이... 조금 부족해지는 바람에 러스트게이트로 보내질 못했거든.$B$B맥슬로에게 그렇게 전하면 알아들을 거야, 알겠지?$B$B<고블린이 음흉하게 윙크한다.>'),
(30149, '이제 더는 저 폭군의 명령 따위 따르지 않겠다!'),
(30150, '우린 이익과 부를 약속받았어. 그런데 이건 그냥 노예 노동이잖아!'),
(30151, '와인은 진정한 흑마법사였습니다. 어두운 겉모습 아래에는 우리가 만난 누구보다 진실한 사람이 있었습니다. 그가 없는 흑마법사 대화창은 다시는 예전 같지 않을 것입니다.'),
(30152, '갈리프레이와 같은 길드에서 함께하며 게임의 모든 것을 가르쳐 주고 친구라 부를 수 있었던 것은 영광이었습니다. 부디 영원히 그 하얀 늑대를 타고 달리기를!'),
(30153, '틸라사쉬 아랄린.'),
(30154, '셰를마 나 샤르.'),
(30155, '아쉬드라실 샬다 렌.'),
(30156, '아셉아발라 나!'),
(30157, '롬매스, 나의 충실한 종복이여. 마지막으로 이야기를 나눈 뒤 너무나 오랜 시간이 흘렀구나.'),
(30158, '왕자님. 무사하신 모습을 뵈니 안심이 됩니다. 보고드릴 것이 많습니다...'),
(30159, '하지만 내게 시간이 많지 않다. 내 백성들은 잘 지내고 있느냐?'),
(30160, '예, 왕자님. 하지만 우리의 갈증을 채울 수 없어 많은 이들이 쇠약해지고 있습니다. 게다가 섭정 의회마저 분열되어...'),
(30161, '정치 이야기로 날 지루하게 하지 마라, 롬매스. 그런 것에는 관심 없다. 머지않아 우리 백성은 더는 굶주리지 않을 것이다. 내가 반드시 그렇게 만들겠다.'),
(30162, '언제입니까, 왕자님? 많은 이들이 왕자님께서 우리를 버렸다고 믿고 있습니다. 배신자라고까지 부릅니다. 저는 더는 그 모욕을 견딜 수 없습니다...'),
(30163, '곧이다, 롬매스. 지금은 침묵을 지켜라. 내가 돌아갈 때까지는 차라리 그들이 나를 잊는 편이 낫다. 백성들이 한낱 관념에 의지해서는 안 된다. 그들에게 필요한 것은 손에 잡히는 해결책이다. 헛된 희망을 심어 주지 마라. 우리를 구원할 길을 찾아낸 뒤에야 나는 돌아갈 것이다.'),
(30164, '알겠습니다. 돌아오실 날을 기다리겠습니다.'),
(30165, '나 역시 다시 내 백성 곁으로 돌아갈 날을 기다릴 수 없구나. 오래 걸리지는 않을 것이다. 약속하마.'),
(30166, '언제나 태양샘의 빛을 기억하시길 바랍니다, 왕자님.'),
(30167, '순간이동'),
(30168, '네가 지금 어떤 힘에 끼어들고 있는지조차 모르는구나!'),
(30169, '내 영원한 사명을 방해할 수 있다고 생각하느냐? 필멸자들이여, \'각성\'은 너희 종족이 태어나기 훨씬 전부터 예언되어 있었다. 우리의 성스러운 땅에 발을 들인 것을 후회하게 해 주마!'),
(30170, '꿈이 우리 모두를 부른다. 너희는 이곳에 영원히 남게 되리라...'),
(30171, '너무나 오래 기다렸다... 각성은 멈출 수 없어. 너희 따위가 막을 수 없다... 용군단을 깨워야 한다... 이 일을 끝낼 수 있는 건 오직 나뿐이야... 나는... 멈출 수... 없어...'),
(30172, '너희의 행동이 모든 것을 어지럽힐 것이다... 썩 물러가라!'),
(30173, '그림자가 승리하게 둘 수는 없다... 용군단은... 그에 맞서야 한다...'),
(30174, '그림자가... 사라지는군... 내 정신을 집어삼킨 악몽에서 해방되었다. 모험가들이여, 고맙다. 너희가 나를 광기에서 구해 주었구나. 각성은 저지되었고, 이제야 마침내 편히 쉴 수 있겠어.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(30176, '거기서 뭘 하는 거죠? 그리즈비에게 무슨 짓을 한 겁니까?'),
(30177, '누구도 투자개발회사에서 마음대로 빠져나갈 수 없어! 놈들은 전부 무역 연합의 배신자다!'),
(30178, '이 물건에 깃든 위험을 조심하십시오. 가지고 있는 것만으로도 위험합니다.'),
(30179, '당신이 타레사인가요? 대마법사의 집중의 보주를 내게 주고 탑으로 돌아가세요.'),
(30180, '그 사기꾼은 다른 필멸자 마법사들과 마찬가지로 허울뿐이다! 아제로스의 마법은 그것을 진정으로 다루고 이해할 수 있는 자들의 것이다!'),
(30181, '받침대에서 사람을 끌어당기는 듯한 오묘한 기운이 흘러나옵니다.'),
(30182, '수정과 보주를 받침대 위에 올려놓습니다.'),
(30183, '산브 부족은 전능한 새 인도자들의 아래에서 다시 하나가 될 것이다!'),
(30184, '땅속에서 새어 나오는 순수한 힘이 엄청나군요. 몰랐다면 이 땅이 마력으로 터져 나가기 직전이라고 생각했을 겁니다.'),
(30185, '나는 산브 부족의 일원이다. 수십 년 전, 오크 호드가 드레노어에 남아 있던 것마저 파괴했을 때, 우리의 족장 균열군주 산브 타스달은 부족민들에게 죽어 가는 세계를 떠나 다른 곳으로 피신하라고 명했다. 산브 클라와 그의 동료들은 내 인도 아래, 내 균열 마법으로 아제로스, 즉 그대들의 고향 세계로 통하는 관문을 열었다. 아이러니하게도 우리는 오크들이 침공했던 바로 그곳으로 도망쳐 온 셈이지.'),
(30186, '다른 부족민들에게는 무슨 일이 있었나요?'),
(30187, '그것을 알아내고 싶어서 내가 피난처에서 사라졌던 것이다. 산브 타스달은 아주 오랜 세월 동안 우리 부족에서 가장 강력한 균열방랑자였으니, 언젠가는 반드시 우리와 합류하리라 믿어 의심치 않았다. 하지만 세월이 흐르자 의심이 생겼고, 균열 이동을 이용해 그를 찾아 나섰다. 산브 클라와 다른 이들을 두고 떠나는 건 괴로웠지만, 그들과 나 자신을 위해서라도 가야만 했다.'),
(30188, '무엇을 알아냈나요?'),
(30189, '진작 느꼈어야 했던 무언가를. 드레노어에 남은 부족과 교신하려 했을 때, 지금의 붉은 황무지가 된 그곳을 잠깐 보게 되었다. 땅은 고통에 울부짖고, 정령들은 날뛰며, 악마들이 도처를 활보하고 있었지. 하지만 나를 가장 큰 충격에 빠뜨린 건 내 동족에게 일어난 일이었다. 그들은 이제 불타는 군단의 하수인이 되어 사실상 스스로를 노예로 바쳤고, 우리의 성스럽고 고대된 균열 이동술을 군단의 목적에 악용하고 있었다. 눈앞에 펼쳐진 광경을 받아들이지 못한 나는 뒤틀린 황천의 결 속에서 나를 찾아낸 산브 타스달을 미처 감지하지 못했고, 그가 내 집중을 끊어 버렸다.'),
(30190, '그리고 어떻게 됐나요?'),
(30191, '균열방랑자의 집중을 방해하는 것은 대부분 죽음을 뜻한다. 다행히 나는 그런 운명은 피했지. 대신 뒤틀린 황천을 가로질러 이 낯선 곳으로 내던져졌고, 돌아갈 방법도 잃었다. 이제 산브 타스달이 우리 부족이 아직 살아 있다는 사실을 알게 되었으니, 그가 피난처를 조종해 불타는 군단에 굴복시키려 할 것임을 확신한다.'),
(30192, '계속 말씀해 주세요.'),
(30193, '$N, 우리 부족의 자유를 위해 그대의 도움이 반드시 필요하다. 부디 나를 도와주게. 그 은혜는 우리 백성이 영원히 잊지 않을 것이다.'),
(30194, '균열방랑자여, 당신의 이야기를 들려주세요.'),
(30195, '숨이 가빠 보이는군요. 무슨 일이 있었나요?'),
(30196, '<카스탈이 보냈습니다. 그는 당신 백성의 안전을 걱정하고 있어요!>'),
(30197, '무슨 말씀인지 모르겠어요. 대체 뭘...?'),
(30198, '산브 클라. 너와 내가 잃어버린 다른 양들을 수년간 찾아 헤맸는데, 마침내 모습을 드러냈구나.'),
(30199, '가엾게 숨어 지낼 필요는 이제 없다, 형제들이여. 내가 우리의 고향 세계에 안전한 피난처를 마련해 두었다. 너희 모두가 돌아와야 할 곳이지.'),
(30200, '나와 함께하라. 네가 원하는 것은 무엇이든 주겠다. 무엇보다도 너희에게 목적을 줄 수 있다. 너희가 상상조차 할 수 없는 위대한 목적을!'),
(30201, '우리 구원자들의 충만한 품으로 나와 함께 돌아갈 자는 앞으로 나오라! 그리고 나를 거역하려는 자들은...'),
(30202, '끝없는 뒤틀린 황천의 망각 속으로 던져질 준비를 해라!'),
(30203, '나약한 종족들이여. 피할 수 없는 죽음 앞에서 너희의 저항은 우습기 짝이 없구나. 죽어라. 깨달은 자들이 나아갈 길에 너희 시체를 깔아 주마!'),
(30204, '피난처의 벗들이여! 경계를 늦추지 마라! 이 사악한 망령을 우리의 새 보금자리에서 몰아내는 데 힘을 보태라. 타락한 자와 악마들에게 이곳에 설 자리는 없다!'),
(30205, '건방진 어리석은 놈! 그 보잘것없는 마법으로는 아무것도 바꿀 수 없다! 네 운명은 이미 정해졌다!'),
(30206, '안 돼! 이게 끝은 아니다. 이제 너희가 숨을 곳은 어디에도 없다!'),
(30207, '옛 주인의 사악한 그림자가 다시 공허로 쫓겨났다. 벗들이여, 내가 힘을 회복하는 동안 산브 클라와 이야기해라.'),
(30208, '놈들이 돌아왔다! 살고 싶으면 도망쳐!'),
(30220, '좀 더 자세히 살펴봅니다.'),
(30221, '눈앞의 존재를 바라보자 한 번도 겪어 보지 못한 방식으로 머리가 아파옵니다. 광기에 찬 속삭임과 엄청난 압박이 두개골 안으로 스며들고, 두 개의 붉은 눈이 당신을 집요하게 응시합니다. 정신을 떼어 놓으려 애써 보지만 아무 소용이 없는 듯합니다.'),
(30222, '계속 저항합니다.'),
(30223, '당신을 공격하는 무언가는 정신을 단단히 붙잡고 놓아줄 생각이 없습니다. 거의 포기하려는 순간 눈앞에 밝은 빛이 나타납니다. 달빛처럼 눈부신 흰 털을 지닌 수사슴이 자부심과 따뜻한 사랑의 기운으로 잠시 당신을 감싸며, 정신을 옭아매던 끔찍한 속박을 끊어 냅니다. 나타났을 때처럼 갑작스럽게 사라지고, 그 자리에는 어둠에 잠긴 망령만 남습니다.'),
(30224, '추억의 지팡이를 그 앞에 들어 보입니다.'),
(30225, '그자를 내 손아귀에서 빼앗아 갈 수는 없다...'),
(30226, '이 세계의 균형을 지키기 위해 보여 준 그대의 행동과 헌신은 실로 뛰어났습니다. 자연의 수호자들에게 바친 그대의 정성은 드루이드의 길을 걷고자 하는 모든 이의 본보기가 될 것입니다. 오늘 그대가 막아 낸 위기는 달의 숲과 하이잘 전역에 알려질 것입니다. $N, 앞으로의 여정에도 평안이 함께하기를.'),
(30227, '내게 원하는 게 무엇이지?'),
(30228, '끝났다! 그런데... 뭔가 이상하군...'),
(30229, '준비됐습니다. 의식을 시작하세요, 아넬레이스.'),
(30230, '오, 이 세계와 저 너머의 원초적인 마력이여!'),
(30231, '이 지팡이 안으로 흘러들어 다시 힘을 불어넣어라!'),
(30232, '필멸의 힘과 불멸의 힘, 모두로 더욱 강해져라!'),
(30233, '서로 상반된 힘이 하나로 합쳐져...'),
(30234, '...강대한 유물이 다시 태어난다!'),
(30235, '이 무기들이 스컬지를 쓰러뜨릴 것이다!'),
(30236, '그 무기들이... 우리 적들의 손에...')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(30237, '내가 곧 낙스라마스의 의지다!'),
(30238, '어리석은 놈들, 내게서 아무것도 알아내지 못할 것이다!'),
(30239, '정기 보조 조치 3b를 실행합니다. 제거!'),
(30240, '핵심 동력 응답 없음... 예, 예, 예비 동력 복구 중... 실패...'),
(30241, '뭐지, 고해성사라도 하러 왔나?'),
(30242, '자유다... 마침내...'),
(30243, '뭐야?! 너희는 가시덤불 골짜기에서 온 녀석들이 아니잖아!'),
(30244, '이번 일로 한몫 단단히 벌 생각이었는데!'),
(30245, '느껴지십니까? 빛의 광휘가.'),
(30246, '내 믿음이... 충분히 강하지 못했어.'),
(30247, '이곳은 우리의 타고난 권리다. 너희가 있을 자리는 없다!'),
(30248, '나는 끝내 그 비밀을 알아내지 못하겠군...'),
(30249, '보르겐도르의 보주를 불꽃 속에 넣습니다.'),
(30250, '불길이 불길한 녹색으로 타오르고, 기묘한 마력이 주변 공기에 맴돕니다.'),
(30251, '무엇을 알아내셨나요?'),
(30252, '그 낫의 어두운 역사는 늑대인간의 운명과 깊이 얽혀 있습니다. 본래 늑대인간은 엘룬의 총애를 받은 자손으로, 다가오는 어둠을 막는 수호자가 되도록 만들어졌습니다. 그들의 피는 달샘의 물처럼 순수했고 엘룬과 깊이 이어져 있었지요. 하지만 그들 사이에서 혈마법이 퍼지며 고귀한 혈통이 타락하기 시작했습니다.$B$B이 사악한 마법의 대가인 프리콜리치들은 권력을 장악한 뒤 낫이 그릇된 자들의 손에 들어가는 것을 막기 위해 봉인했습니다. 그러나 그들의 야망과 지배욕까지 봉인할 수는 없었습니다. 프리콜리치 중 하나가 우리 세계를 발견하자 자신의 영향력을 넓힐 기회로 여겼습니다. 그는 속임수로 벨린데에게 자신이 엘룬이라고 믿게 만들고 낫을 선물했습니다. 벨린데가 자신도 모르는 사이 그의 늑대인간 하수인들을 불러내리라는 것을 알고 있었던 것이지요.'),
(30253, '벨린데는 엘룬의 뜻을 따른다고 믿으며 타락한 존재들을 우리 세계에 풀어놓았습니다. 처음에는 수백 년간의 전투 경험을 지닌 그들이 군단에 맞서 용맹하게 싸우며 강력한 동맹이 되어 주었습니다. 하지만 여러 겹의 마법 아래 감춰져 있던 진짜 본성이 곧 드러났습니다.$B$B프리콜리치들이 늑대인간에게 미치는 영향력은 절대적이었습니다. 그들은 하수인에게서 자유의지를 빼앗아 자아조차 없는 순종적인 병사로 만들었습니다. 벨린데의 지배력이 약해질수록 프리콜리치의 힘은 커졌고, 결국 한 프리콜리치가 아제로스에 도착하기에 이르렀습니다. 그렇게 벨린데의 비극은 시작되었고 늑대인간에 대한 그녀의 통제는 완전히 무너졌습니다. 그녀에게 어떤 최후가 닥쳤는지는 당신도 잘 알고 있겠지요...'),
(30254, '고개를 들어 하늘을 바라보십시오. 눈치채셨습니까? 푸른 아이가 돌아왔습니다. 이 천문 현상은 늑대인간의 도래를 알리는 징조이자 프리콜리치들의 계획이 진척되고 있다는 신호입니다. 상상조차 할 수 없는 어둠과 공포의 세계, 보르겐도르로 통하는 차원문을 그들이 열기 전에 서둘러 막아야 합니다.$B$B내 까마귀들의 보고에 따르면 한 명도 아닌 두 명의 프리콜리치가 우리 세계에 침투했습니다. 낫을 정화해 우리의 여신께 돌려드리기 전에 그들을 더러운 세계로 추방해야 합니다. 그중 하나인 수호자 날문은 쉽게 찾아냈습니다. 하수인들의 소환을 받아 카라잔에 몸을 숨겼지요. 카라잔의 비밀은 필멸자의 손에도 허락되지 않은 것이며, 하물며 프리콜리치에게는 더더욱 안 됩니다. 그가 어둠의 지식을 손에 넣기 전에 반드시 찾아내 처치해야 합니다.'),
(30255, '두 번째 프리콜리치는 수수께끼에 싸여 있습니다. 정찰병들이 길니아스에서 목격했다는 보고를 했지만 정확한 위치는 아직 알 수 없습니다. 단서 하나하나를 끈질기게 추적해 그의 은신처를 밝혀내야 합니다. 단 한 명의 프리콜리치라도 방치하기에는 위험이 너무 큽니다.$B$B준비하십시오, 젊은이. 앞에 놓인 임무는 위험천만하지만 아제로스의 안전과 엘룬께서 내리신 선물을 지키기 위해 반드시 해내야 합니다. 신속하고 단호하게 움직여 프리콜리치들을 막고 낫에 깃든 타락을 씻어내야 합니다. 엘룬의 빛이 우리를 인도할 것입니다.'),
(30256, '시작하죠.'),
(30257, '사크고스에게서 어떤 교훈을 얻을 수 있겠나?'),
(30258, '그가 더 강했다면 성공했을 겁니다.'),
(30259, '자만심이 그를 잘못된 길로 이끌었습니다.'),
(30260, '적을 힘으로 압도하는 것이 승리하는 유일한 방법입니다.'),
(30261, '옳다. 그렇다면 클라녹에게서는 어떤 교훈을 얻을 수 있겠나?'),
(30262, '누구나 스스로를 지킬 준비가 되어 있어야 합니다.'),
(30263, '전투의 광기에 몸을 맡기면 더 강해집니다.'),
(30264, '무엇을 위해 무기를 드는지 잊지 말아야 합니다.'),
(30265, '옳다. 그렇다면 카파이에게서는 어떤 교훈을 얻을 수 있겠나?'),
(30266, '언제든 기술을 갈고닦아야 합니다.'),
(30267, '규율을 지키고 자신의 의무를 잊지 말아야 합니다.'),
(30268, '전쟁의 기술이야말로 가장 중요한 것이다.'),
(30269, '훌륭하군. 내 말을 제대로 들은 모양이야.'),
(30270, '틀렸다. 다음에는 좀 더 귀 기울여 듣는 게 좋겠군.'),
(30271, '브라이트하트 사부님께서 실패에 관한 이야기를 찾아보라고 하셨습니다. 하나 들려주시겠습니까?'),
(30272, '개인적인 질문이긴 하지만, 사부님의 뜻을 의심할 생각은 없네. 사부님도 자신의 실수만큼 좋은 스승은 없다고 하시겠지만, 다른 이의 잘못에서도 배울 것은 많지.$B$B내가 사부님의 가르침을 받기 시작한 지 얼마 되지 않았을 때, 겉보기에는 간단한 시험을 받았네. 이 근처 가시멧돼지에게서 전쟁의 우상을 되찾아 오는 일이었지. 대족장께서 듀로타를 정복할 때 그 짐승들과 수도 없이 싸워 봤던 나는, 우상을 지닌 족장을 조심하라는 마티아스의 충고를 대수롭지 않게 여겼네. 전투에서 상대를 얕본 끝에 큰 부상을 입었고, 그 와중에 우상까지 실수로 파괴해 버렸지. 목숨은 건졌지만 깊은 수치심에 사로잡혔네.$B$B$N, 물론 사부님의 말을 들었어야 했지만 내가 정말 배워야 했던 교훈은 그것만이 아니었네. 자만심이 판단을 흐리게 두었고, 그건 나뿐 아니라 동료들까지 위험에 빠뜨리는 일이었지.'),
(30273, '사부님의 새 제자인가? 그런 사람을 본 지도 꽤 됐군. 그런데 이런 민감한 질문을 내게 하라고 하셨다고? 평소라면 코웃음 치며 돌려보냈겠지만, 사부님의 뜻을 거스를 수는 없지.$B$B나도 한때는 자네처럼 젊고 야심만만했네. 지나칠 정도였지. 내 검술 실력을 대단하게 생각했고, 마티아스 사부님이 나를 받아 주셨다는 사실이 그 자만을 더 키웠네. 그래서 사부님이 내게 맡긴 첫 임무가 배달이었을 때 얼마나 화가 났겠나. 배달이라니! 좋게 말해도 기가 막혔지.'),
(30274, '무슨 일이 있었나요?'),
(30275, '상자에는 약초와 물약 같은 귀중한 물건들이 가득했고, 먼지진흙 습지에 사는 은둔자에게 가져다주는 임무였네. 그리 무서운 일은 아니었지만 욕심 많은 누군가가 그 사실을 알아내고, 노인의 집에서 나를 덮치도록 도적들을 고용했지. 그 정도 산적쯤은 충분히 상대할 수 있었기에 어린 혈기에 정면으로 돌진해 눈이 뒤집힌 채 놈들을 베어 넘겼네. 산적들이 모두 죽은 줄 알고 여전히 피가 끓는 상태로 은둔자를 돌아봤는데, 그는 바닥에 죽어 있었고 상자는 사라지고 없었지. 분노에 사로잡힌 나는 무엇이 중요한지 잊었던 걸세. 전투의 흥분에 취했고, 그 대가를 다른 사람이 목숨으로 치렀지.$B$B$N, 내 무모함 때문에 한 사람이 죽었네. 우리가 걷는 전쟁의 길에서 다른 이의 목숨까지 위험에 빠뜨려서는 안 돼. 스스로 물어보게. 스스로를 지킬 수 없는 이들을 보호하기 위함이 아니라면 무엇 때문에 무기를 드는가?'),
(30276, '아, 그 늙은 사부 말이구먼. 그래, 카파이는 그분한테 많은 걸 배웠지만, 스스로 깨우친 것도 많지. 삶 자체가 훌륭한 스승 아니겠나.$B$B카파이가 절대 잊지 않는 이야기는 규율에 관한 것이네. 난 참 부주의한 트롤이었고, 지금도 왜 사부가 나를 받아 줬는지 모르겠어. 어쩌면 나보다 내 안의 가능성을 더 봤던 걸지도 모르지. 사부는 페랄라스 정글에서 꽃 하나를 가져오라고 했어. 아주 급하다고도 했지. 하지만 그때의 나는 꽃 따위에는 관심이 없었고 모자케 야영지의 전사들과 결투하는 게 훨씬 재미있었어. 한참 뒤에야 꽃을 찾으러 갔고, 막상 찾아냈을 때는 이미 시들어 있었지. 그제야 사부의 뜻을 깨닫고 시든 꽃이라도 가지고 돌아왔어. 섬으로 돌아오자 사부는 그 꽃이 제자들이 앞서 간 이들을 기리기 위해 바치는 것이라고 알려 주었지.$B$B$N, 맡은 의무를 잊지 말고 성실하게 끝내게. 자신의 욕망은 기다릴 수 있고, 또 기다려야 하네.'),
(30277, '짭짤한 바닷바람을 맞으니 언제나 기운이 나는군요. 무엇을 도와드릴까요?'),
(40049, '난 내 물건을 최고의 영웅들에게만 파네. 관중들이 자네를 충분히 좋아한다고 생각하나?\n\n그렇다면 다가오고, 아니라면 물러서게 이봐!'),
(41083, '던 아그라스 최고의 거래요 친구, 더 좋은 건 찾을 수 없을 걸. 자, 무엇을 도와줄까?'),
(41084, '와일드파우 우두머리는 위대하고 두려운 코락의 피가 당신에게서 떨어지는 것을 알아차리고 굴복하여 웅크립니다.\n\n당신이 이 캠프의 새로운 우두머리가 된 것 같습니다.'),
(41085, '<으르렁>\n\n이 놀은 당신을 이해할 만큼 지능이 높아 보이지 않습니다.'),
(41333, '한가하게 이야기할 시간이 없소, $N. 비가 오기 전에 이 다리를 다시 지어야 하거든. 나는 모든 프로젝트를 제시간에 예산 범위 내에서 끝냈고 지금 지체할 생각은 없소.'),
(41334, '그렇소. 붉은 옷을 입은 남녀 무리가 한 수레를 이끌고 이곳을 지나갔소. 우리 젊은이들 다수가 그들을 따라갔지.'),
(41335, '이 방어구를 제작하느라 정말 바쁘니, 용건만 간단히 하시오!'),
(41336, '그렇소, 우리 젊은이들이 그들과 함께 떠났다오. 그들을 탓할 수 있겠소? 이 장소를 보시오.'),
(41337, '스톰윈드 왕국의 레이크샤이어 법정에 선 이 $c(은)는 누구인가? 이 마을에 온 목적을 말하라, $R. 오크의 위협이 너무 커 한가한 대화로 시간을 낭비할 수 없다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(41338, '우리 아이들이 한밤중에 그 어리석은 십자군 광신도들과 함께 떠난 것이 유감이오! 제발 그들을 해치지 마시오. 그들을 집으로 돌려보내 주시오.'),
(41339, '당신 앞에 드워프 산악보병의 시체가 누워있습니다.'),
(41343, '반갑습니다, 손님분! 판매할 희귀한 약초가 많습니다. 둘러보세요.'),
(41344, '네 두목님, 정말 그랬습니다. 전 상인이니까요. 물건이 있으면 팝니다.'),
(41345, '북쪽으로 간 것 같아요, 그 드워프 수레의 발자국을 따라서요. 그들 중 한 명은 매복을 위해 다리 옆에서 기다릴 거라고 했습니다. 머리가 그렇게 좋아 보이지는 않던데요, 무슨 말인지 아시겠죠?'),
(41346, '농담이시죠? 적어도 다섯 명은 있었다고요!'),
(47000, '할머니한테 100골드 수표를 받았는데, 아빠가 수년 동안 불릴 수 있도록 은행에 넣어야 한다고 했어요.'),
(47001, '그거 정말 멋지구나. 아주 똑똑한 결정이야, 애야.'),
(47002, '그 수표를 화폐 시장 뮤추얼 펀드에 넣고...'),
(47003, '그런 다음 수익을 복리 이자가 붙는 외화 계좌에 재투자할 거란다...'),
(47004, '그리고~~~ 사라졌단다.'),
(47005, '어... 네?'),
(47006, '사라졌다, 전부 다 사라졌어.'),
(47007, '뭐가 다 사라졌다는 거예요?'),
(47008, '네 계좌에 있던 돈 말이다. 운이 좋지 않았어, 다 사라졌다.'),
(47009, '무슨 말씀이세요? 저-저한테 100골드가 있었는데요!'),
(47010, '더 이상은 없단다.'),
(47011, '다음 분!'),
(47012, '그분에게 제 돈을 어서 드리고 싶어요.'),
(47013, '우린 모두 부자가 될 거야.'),
(47014, '쉘코인 투 더 문!'),
(47015, '말 그대로 망할 수가 없어.'),
(47016, '그래서 내가 말해줬지 - 팔지 않으면 절대 잃는 게 아니라고!'),
(47017, '아이들이 가난 속에서 자라게 둘 수는 없습니다. 나중에 다시 올게요, 고아원 기부금을 쉘코인에 투자할 겁니다.'),
(47018, '사기가 아니었어, 저스틴. 난 곧 엄청난 부자가 될 거라고.'),
(47019, '잠시 자리 좀 비워줄래? 쉘 코인 사무실에 가서 현금을 좀 인출해야겠어.'),
(47020, '어이, 어이, 어이~~~! 일어나라 스톰윈드, 투자할 시간이다!'),
(47021, '믿음과 신념은 온 세상을 바꿀 수 있는 단 한 가지입니다. 쉘코인을 믿으세요, 당신의 세상을 바꿀 것입니다.'),
(47022, '쉘코인은 발아하여 놀라운 기회로 폭발할 씨앗입니다. 투자하여 그 씨앗을 심는 것을 도와주세요.'),
(47023, '쉘~~~~ 커넥트~~~~~!!!'),
(47025, '우리가 어떤 대우를 받고 있는지 믿어지십니까? 대족장이 우리를 스파이라고 비난하며 이곳에 가두었습니다!\n\n시민들에게 경제적 풍요를 가져다주기 위해 오그리마에 왔는데, 그 대가가 이겁니다.\n\n제발 여기서 나갈 수 있게 도와주세요. 제 고용주가 당신에게 두둑히 보상할 것입니다.'),
(47030, '어이 거기 당신, 쉘 무역 회사에 잘 오셨소!\n\n오그리마에 새로운 통화 소식이 들려왔는데, 인간들을 폭풍처럼 휩쓸고 있소. 아제로스를 영원히 바꿀 마법의 동전이지. 당신의 전리품을 투자할 절호의 기회라오, 젊은이.\n\n나를 보시오, 한때 한심한 드루이드에 이름도 없던 내가 이제는 쉘코인의 가장 큰 주주 중 한 명이라오. 일찍 투자하면 꿈도 못 꿀 수익을 거둘 것이오.'),
(47031, '들여보내 줘, 이건 우리 건물이라고!'),
(47032, '이제 더 이상은 아니다.'),
(47033, '이 재산은 대족장의 명령으로 몰수된다.'),
(47034, '이건 터무니없어. 불공평하다고!'),
(47035, '이 모든 일이 지독하게 위험해 보이는군.'),
(47036, '내 말은, 정말 우리의 모든 골드를 조개껍데기(SHELLS)에 투자하고 싶냐는 거야?'),
(47037, '전체 시장이 붕괴되어 우리 돈을 다 잃으면 어쩌지!'),
(47038, '가서 이야기를 좀 해봐야겠어...'),
(47039, '난 아무것도 못 봤어.'),
(47040, '나도야!'),
(47041, '안 돼!'),
(47042, '신이시여!'),
(47043, '안 돼, 신이시여, 제발 안 돼!'),
(47044, '안 돼! 안 돼! 안 돼애애애애!'),
(47047, '이 일은 잊지 않겠다, $n!'),
(50000, '우리는 고대정령이다. 한때 위대했던 이 숲의 수호자들이지.\n\n1만 년 전 아키몬드와 불타는 군단이 하이잘로 행진했을 때 우리의 육체적 형태는 파괴되었다.\n\n하지만 우리의 영혼은 온전히 남아있다.'),
(50041, '고장 난 물건을 고치는 것만큼 좋은 건 없지, 고깃덩어리.'),
(50580, '이번에 우리 팀이 경주를 성공적으로 마칠 확률이 일정 비율 존재합니다. 물론 제대로 배우지 못한 몇몇 고블린들과는 달리 말이죠.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(50581, '성공 확률 높음. 경쟁 팀의 승리는 거의 존재하지 않음. 결과 수용 가능. 영광과 함께 진행하라!'),
(50582, '누구? 그들? 하하하하! 정말 좋은 농담이군요! 고블린이 발명이라는 용어 자체를 알고 있는 것처럼 들리네요.'),
(50583, '어떤 기계든 성공적인 시동을 위한 확률을 계산하고 가능한 결과를 분석하는 데는 상당한 뇌 용량이 필요합니다. 노움이라면 누구든 당연히 쉽게 할 수 있는 일이죠. 쯧, 물론이죠, 우리가 무슨 녹색 코주부 사기꾼 같은 건 아니잖아요.'),
(50584, '여기서 고려해야 할 두 단어가 있습니다; 로켓과 과학. 두 가지를 모두 가진 자가 누구일까요? 정답은 바로 – 노움입니다!'),
(50585, '좋아 그럼, 얘야, 한두 걸음 물러서거라. 이게 아주 멋지게 날아갈 거라고 확신한다. 내 생각엔...'),
(50586, '흥! 이 대머리 녀석들이 계산하고 도면을 그리는 동안, 우리는 소금 한 뼘과 돌 몇 개만으로 이 저주받은 곳을 높이 날려버릴 거다 ... 어쩌구 저쩌구, 알아들었지, 얘야! 쾅!'),
(50587, '수류탄 투척!'),
(50588, '폭발에 관한 거다, 얘야! 가장 큰 쾅 소리가 최고의 가격을 가져오지!'),
(50589, '야, 가즈로가 이런 폭발을 보고 질투와 시기, 악의로 얼굴이 질려 푸르러지겠는데! 아, 잠깐만...'),
(50590, '시간은 돈인데 우리는 항상 돈이 부족하지. 터뜨려야 할 게 너무나 많고 돈은 항상 이 정도뿐이니까. 적어도 우리는 일부 "발명가들"과 달리 물건을 터뜨리는 대가로 돈을 받잖아. 하하!'),
(50591, '노움이 어쩌구... 노움이 저쩌구... 우리는 걷기 시작하기도 전에 물건을 터뜨리는 법부터 배운다고, 하!'),
(50592, '화약으로 고쳐지지 않았다면 화약을 충분히 쓰지 않은 것이다!'),
(50647, '이 신기한 계절에 품질 좋은 맥주를 찾고 있나? 제대로 찾아왔네 드워프 친구.'),
(50652, '이 겨울맞이 축제 시즌을 즐기고 계시기를 바랍니다.'),
(50877, '군단은 수많은 다른 세계를 불태웠듯 이 세계도 불태울 것이다!'),
(50878, '군단의 힘 앞에 벌벌 떨어라!'),
(50879, '%s|1이;가; 불안정해지며 곧 폭발하려 합니다.'),
(50880, '필요한 게 무엇인가요?'),
(51540, '반갑습니다. 새로운 도전을 찾는 이들에게 문양을 판매합니다. 무엇을 찾고 계신가요?'),
(51541, '반갑습니다. 새로운 도전을 찾는 이들에게 문양을 판매합니다. 무엇을 찾고 계신가요?'),
(51542, '반갑습니다. 새로운 도전을 찾는 이들에게 문양을 판매합니다. 무엇을 찾고 계신가요?'),
(51543, '반갑습니다. 새로운 도전을 찾는 이들에게 문양을 판매합니다. 무엇을 찾고 계신가요?'),
(51544, '반갑습니다. 새로운 도전을 찾는 이들에게 문양을 판매합니다. 무엇을 찾고 계신가요?'),
(51545, '반갑습니다. 새로운 도전을 찾는 이들에게 문양을 판매합니다. 무엇을 찾고 계신가요?'),
(51546, '반갑습니다. 새로운 도전을 찾는 이들에게 문양을 판매합니다. 무엇을 찾고 계신가요?'),
(51547, '반갑습니다. 새로운 도전을 찾는 이들에게 문양을 판매합니다. 무엇을 찾고 계신가요?'),
(51670, '자를 머리카락, 세어볼 동전.\n고블린의 바쁜 삶이란.'),
(51671, '엄마나 좋아할 법한 얼굴을 가지고 계시네요. 저에게 완벽한 해결책이 있습니다!'),
(51673, '시간의 동굴에 오신 것을 환영합니다, $N.\n\n당신이 한 일 또는 앞으로 할 일 덕분에 입장이 허가되었습니다.\n\n시간의 동굴은 나의 동족인 청동용군단의 고향입니다. 우리는 시간의 파수꾼이며, 따라서 우리의 고향은 시간의 흐름과 연결되어 있습니다.\n\n착각하지 마십시오 필멸자여, 이곳은 휴양지가 아닙니다. 멋대로 행동한다면 결코 나가지 못할 것입니다. 동굴에서는 우리의 규칙과 지시를 철저히 따르십시오.'),
(51674, '동굴로 가는 길은 길고 험난합니다. 당신의 짐을 줄여 동굴 더 깊은 곳으로 안내해 드릴 수 있습니다.'),
(51680, '이 드워프는 죽었을 뿐만 아니라 훼손당한 것처럼 보입니다. 턱이 사라졌군요.'),
(51681, '용기는 비어있었고, 내용물은 여전히 타오르는 것처럼 보이는 것에 부어진 것 같습니다.'),
(51682, '이제 당신은 이 드워프들을 도살한 것이 신병들이라는 것을 확신합니다.\n\n하지만 사라진 턱은 의구심을 불러일으킵니다. 다음 생각으로는 지금 있는 곳의 남쪽, 교차로에 캠프를 친 고블린에게 기름을 판 사람이 그인지 물어보는 것입니다.'),
(51683, '내가 한 일에 대해 책임을 지겠습니다. 걱정 마세요, 당신을 따라가며 바르게 행동하겠습니다.'),
(51684, '저한테 무슨 짓을 하려는 거죠? 내가 한 모든 일에 대해 정말 죄송합니다. 정말이에요.\n\n모든 것을 후회하며, 기회가 주어진다면 반드시 보상하겠습니다.'),
(51685, '제발, 절 죽이지 마세요, 제발!\n\n다른 건 아무것도 몰라요, 제발! 난 그저 집에 가고 싶을 뿐이에요.'),
(51690, '당신이 바리마트라스 군주께서 말씀하신 중요 임무를 맡은 자인가?'),
(51691, '매버릭은 깊은 잠에 빠져 있어서 그 무엇도 그를 깨울 수 없을 것 같습니다.'),
(51692, '여기 귀중한 걸 잃어버리신 분 계신가요? 대가를 지불하시면 돌려드릴 수 있습니다...'),
(51693, '당신에겐 쓰레기일지 몰라도, 나에겐 아닙니다!'),
(51694, '아 이것 좀 보세요, 전설의 쓰레기인도자 검이군요. 완벽한 상태입니다!'),
(51695, '이건 내 거야, 내 거라니까. 내 보물. 이게 쓰레기라니 무슨 소리야?! 이건 엄청난 가치가 있다고!'),
(51696, '항복하겠소, 좋소! 그에게 문제 일으키지 않겠다고 전해주시오, 교훈을 얻었으니.'),
(51697, '안부를 확인하라고? 그자가 여기서 날 통제할 수 있다고 생각하는 건가, 그리고 당신은 누구지, 보잘것없는 순경인가?'),
(52000, '너무나 많은 이들을 잃었다. 그리고 이 전투가 끝나기 전에 더 많은 이들을 잃어야 한다.'),
(52001, '로데론의 그 여관에서 마시던 드워프 에일이 그립군. 거기서 우리가 시작했던 싸움 기억나나?'),
(52002, '실례가 안 된다면, 먼저 물러가 보겠습니다. 좋은 하루 되세요, 숙녀분들.'),
(52003, '딸깝! 딸깝! 속이 좋지 않군...'),
(52004, '어떤 이들은 위대한 힘만이 악을 저지할 수 있다고 믿지만, 내가 발견한 것은 그렇지 않습니다. 어둠을 물리치는 것은 보통 사람들의 사소한 일상적 행동입니다. 친절과 사랑의 작은 행동들 말이죠.'),
(52005, '혈투의 전장에서 잠시 살았었지. 재미있었어. 정말로.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(52006, '날씨 참 좋죠?'),
(52007, '다나스가 스톰윈드의 모든 용병을 모아 네더가드에서 싸우기 위해 행진했던 때 기억나나요?'),
(52008, '검술에 소질이 있으신가요? 아시다시피, 우리는 앉아있는 동안 두려움을 만들어냅니다. 우리는 행동으로 그것들을 극복하죠. 두려움은 자연이 우리에게 바쁘게 움직이라고 경고하는 방식입니다.'),
(52009, '이 흐릿함... 이 불쾌함 속에서 한탄하며 너무 오랫동안 한가하게 앉아있었군... 되었어야 할 일들을 말이야.'),
(52010, '저 선술집들을 조심해요! 자기도 모르는 사이에 술고래가 될 테니까요.'),
(52011, '네?'),
(52012, '그녀는 내 거야 이봐!'),
(52013, '우리 모두가 훌륭한 춤꾼이 될 수는 없죠!'),
(52014, '안녕하세요 $n! 문제를 일으키러 온 게 아니길 바랍니다, 네? 저로 말할 것 같으면 이 모든 전쟁에 지쳤습니다... 완전한 깨달음이 있을 때 평화가 찾아오고 세상은 행복해질 거라 믿어요.'),
(52015, '경치 좋은 길로 가는 건가요?'),
(52016, '어쩔 수 없어요, 정말로. 여긴 너무 아름다운 곳이거든요.'),
(52017, '뭐야...'),
(52018, '어?'),
(52019, '물고기가 입질을 하는지 봅시다.'),
(52020, '만나서 반갑습니다 $n!'),
(52021, '이 세상을 구하러 오셨나요? 정화하기 위해서인가요?'),
(52022, '이곳은 처음이신가요? 마법사 티르스에게 들러보세요, 분명 신비한 물건들이 있을 겁니다.'),
(52023, '용기에 대해 말씀하시나요? 용기란 기도를 마친 두려움일 뿐입니다.'),
(52024, '전쟁이 다가오고 있습니다 $n... 언제일지, 누구와 싸우게 될지 모르지만... 오고 있습니다.'),
(52025, '아, 흠칫 놀랐잖아요! 요새 이 다람쥐들 때문에 약간 예민해진 것 같아요.'),
(52026, '반갑습니다 $n. 묵을 곳을 찾으시나요? 매의 경계초소 여관에는 분명 자고 가기 좋은 따뜻한 침대가 있을 겁니다.'),
(52027, '아, 안녕하세요. $c(이)가 고향에서 이렇게 멀리 떨어진 곳에서 무엇을 하고 계신가요?'),
(52028, '아, 시간 좀 봐! 내 초소로 돌아가야겠어... 저 위쪽으로 말이야.'),
(52029, '이 근방에서 가장 훌륭한 염장 고기를 가지고 있죠! 자 한 번 맛보세요!'),
(52030, '대단한 건 아니지만, 정직한 일입니다.'),
(52031, '쉬하고 싶어요.'),
(52032, '매의 경계초소에 오신 것을 환영합니다 $n! 즐거운 시간 보내시길 바랍니다.'),
(52033, '모두에게 술을!'),
(52034, '흠, 이쪽에 뭐가 있는지 궁금한데?'),
(52035, '이 폭죽 발사기들을 사용해 보세요. 엄청 재미있습니다!'),
(52036, '편히 쉬세요 $n.'),
(52037, '체리 파이는 아제로스 전체에서 제가 가장 좋아하는 음식이에요.'),
(52038, '날 찾는 이는 극히 드문데... 무엇을 도와드릴까요?'),
(52039, '연구로 돌아가야 합니다. 우리 땅에 무언가 이상한 일이 일어나고 있어서 원인을 알아내야 합니다.'),
(52040, '아, 거기 계셨군요!'),
(52041, '머라고 하셨나요?'),
(52042, '이 나무들 정말 장엄하지 않나요?'),
(52043, '아 안녕 $n. 고양이를 좋아하시길 바라요!'),
(52044, '군대는 배가 불러야 움직인다는 말이 있는데, 진실입니다. 어떤 공세든 성공하려면 부대가 잘 먹고 물자를 잘 공급받아야 합니다.'),
(52045, '불쌍한 타비우스의 아내에게 무슨 일이 일어났는지 들으셨나요?'),
(52046, '내가 배운 한 가지는, 배를 만들고 싶다면 사람들을 불러모아 나무를 수집하고 일을 나누고 명령을 내리지 말라는 것입니다. 대신 그들에게 광대하고 끝없는 바다를 동경하도록 가르치세요.'),
(52047, '아, 거기 계신 줄 몰랐네요!'),
(52048, '좋은 날입니다, 환영합니다 $n!'),
(52049, '삶을 견디게 해주는 섬세한 환상들도 어느 정도의 부담만을 견딜 수 있습니다. 아 미안해요, 내가 또 횡설수설했네요.'),
(52050, '밤새도록 춤추는 것만큼 좋은 건 없죠!'),
(52051, '춤춰봅시다!'),
(52052, '춤추러 오셨나요? 파트너는 있으신가요?'),
(52053, '도와드릴 일이 있나요?'),
(52054, '어디가 아프신가요, 친구여?'),
(52055, '할머니는 온 세상에서 따뜻하고 바삭하게 구운 홈메이드 체리 파이 한 조각보다 더 위대한 건 없다고 항상 말씀하셨죠.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(52056, '이런 때가 되면 난 센티멘탈해져요...'),
(52057, '기다리는 시간이 길어질수록, 내가 점쳐줄 수 있는 당신의 미래는 줄어듭니다.'),
(52058, '안녕 어린 $G신사:숙녀; 분, 춤 한 번 추실래요?'),
(52059, '이건 정말 대단한 모험이군요!'),
(52060, '자, 어디 보자... 내 생각이 맞다면, 그렇다면... 흠...'),
(52061, '스컬지는 승리하지 못할 것이다!'),
(52062, '제발 나한테 다시 말 걸지 말아 주세요. 위로받을 수 없는 상태예요.'),
(52063, '그는 의심할 여지 없이 배짱과 기지가 넘치는 사람이었소... 그의 용맹한 행적을 생각하지 않는 날이 단 하루도 없소.'),
(52066, '(킁킁) 이 냄새 나나요? 기름 냄새 정말 좋지 않나요?'),
(52067, '딸깝! 딸깝!'),
(52068, '아, 내가 또 길을 잃었네요. 죄송합니다.'),
(52069, '저 밖에는 거친 바다가 펼쳐져 있군. 바다 정령들이 불안해하는 게 틀림없어.... 딸깝!'),
(52070, '아 그래! 사주는 거라면 에일 한 잔 하지! 하하! ...딸깝!'),
(52071, '날 좀 엮어주게!'),
(52072, '저 여자 꼬리 좀 봐! 내 전盛기 때는 내-- 때문에 벽돌 윌리라고 불렸었지. 자세한 건 말하지 않겠지만 무슨 뜻인지 알겠지. 건배!'),
(52073, '네, $c?'),
(52074, '네, 알겠습니다, 보스. 문제없습니다.'),
(52075, '아 다시 젊어질 수만 있다면. 나에겐 싸워야 할 전쟁과 결혼할 여인들이 있었는데... 젊음을 누릴 기회가 없었어.'),
(52076, '여정에 행운을 빕니다, 친절한 이방인님!'),
(52077, '원하는 게 뭐야?'),
(52078, '내가 저 표적 과녁을 너로 바꾸고 준비 운동을 시작하기 전에 뭐라도 하기 시작해라!'),
(52079, '아, 저기 정말 아름다운 꽃이 있네...'),
(52080, '파이가 너무 좋아요.'),
(52081, '예?'),
(52082, '마음이 산만하군요. 나에게 무언가 숨기는 게 있나요?'),
(52083, '내가 마지막에 웃게 될 거야... 다들 보게 될 거라고! 아, 안녕 $c, 거기 계신 줄 몰랐네요.'),
(52084, '딸깝!'),
(52085, '젠장! 여기서도 물고기가 안 문다. 내 옛날 낚시터로 돌아가야겠어!'),
(52086, '봤어요? 방금 전 폭죽이 저 드워프 셔츠에 불을 붙일 뻔했어요! 하하!'),
(52087, '적에게 힘을 보여주어라, 그러면 우리가 승리하리라!'),
(52090, '이름이 무엇인가요?'),
(52091, '제발, 계속하세요.'),
(52092, '반갑습니다 여행자여. 최신 소식을 원하시면 비질 선술집으로 가보세요. 우리 대부분이 모여 이야기를 나누고 소문을 주고받는 곳입니다.'),
(52095, '신들이여, 여기가 시골이군요. 다 버리고 그냥 계속 가버릴까 하는 마음도 듭니다. 국도 위에서 당신과 나 단 둘이서, 옆에는 검을 차고, 오늘 밤 우리 침대를 따뜻하게 해줄 선술집 시녀 몇 명쯤 고용해 보는 건 어때요?'),
(52096, '예전에 한 친구가 나에게 큰 위안을 준 말을 해주었습니다. 그는 \'인생은 짧기 때문에 가치가 있는 거야! 소모되고, 사용되고, 지출되고, 삶을 살고, 느껴지도록 설계된 거지. 우리가 할 수 있는 모든 실수와 기적으로 채워넣어야 해. 그리고 나서 내보내줘야 하지.\' 라고 했죠.'),
(52097, '우리 돼지들에게 무슨 일이 일어난 거지?'),
(52100, '이걸 기억하게 젊은이, 압력은 파이프를 터뜨리거나 다이아몬드를 만들 수 있다네.'),
(52101, '냄새가 더 좋았으면 대화를 나눴을 텐데요. 향수를 뿌리면 좋겠네요.'),
(52102, '길을 잃으셨나요?'),
(52103, '물고기도 목이 마를 때가 있을까요?'),
(52104, '내 진정한 사랑이 저 밖 어딘가에 있다는 걸 알고 있어요! 의학, 법학, 경영, 공학, 이것들은 고귀한 추구이며 삶을 유지하는 데 필요하지만... 시, 아름다움, 로맨스, 사랑, 이것들이 우리가 살아가는 이유입니다.'),
(52105, '당신은 우리 모두에게 영감을 줍니다, 귀하.'),
(52106, '조심해, 친구!'),
(52107, '어라...'),
(52108, '대부분의 오우거와 달리, 난 변기가 무엇에 쓰이는지 알고 있지 - 너한테 변기물 세례를 주는 거다. 이제 꺼져라.'),
(52109, '만나서 반갑습니다 $n. 항구에서 오셨나요? 다음에 거기 가시면 시다에게 내 안부 좀 전해주세요, 그러실 거죠?'),
(52111, '*그웬나가 당신에게 짓궂게 윙크합니다.*'),
(52112, '반갑습니다, $n. 무엇을 도와드릴까요?'),
(52114, '힘든 하루였나요? 시원한 에일 한 잔이면 걱정이 싹 풀릴 겁니다.'),
(52115, '비밀 하나 알려드릴게요. 당신들의 신전에서는 가르쳐주지 않는 거죠. 신들은 우리를 부러워합니다. 우리가 필멸자이기 때문에, 매 순간이 우리의 마지막이 될 수 있기 때문에 부러워하죠. 우리가 죽을 운명이기 때문에 모든 것이 더 아름답습니다. 당신은 지금보다 더 사랑스러울 수 없을 겁니다. 우리는 다시는 이곳에 있지 않을 테니까요.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(52116, '키스해 주세요.'),
(52117, '네?'),
(52119, '원하는 게 뭐야?'),
(52125, '수다쟁이 그레타는 작은 금속 병에 대해 헛소리를 늘어놓았습니다. 그녀는 치열한 전투에서 가축을 문 나방에게 침을 좀 뱉었습니다.'),
(52128, '어떻게 지내세요?'),
(52129, '이 문양은 힘을 얻는 것보다 모험에 대한 사랑이 더 큰 이들에게 맞춰져 있습니다. 던전 외의 생물로부터 얻는 경험치가 평소의 50%로 감소하지만, 인내와 부지런함에 대한 보상으로 10레벨마다 멋진 보물을 받게 됩니다. 사망 시 전장을 제외하고 현재 레벨 경험치의 5%를 잃게 됩니다. 이 문양은 1레벨에서만 활성화할 수 있습니다.'),
(52130, '이 문양은 쉬지 않고 험난한 여정을 떠나는 것이 더 보람차다고 느끼는 이들에게 맞춰져 있습니다. 다시는 휴식 경험치가 누적되지 않지만, 그 대가로 무기 숙련도를 두 배 빠르게 익힐 수 있습니다.\n\n왜 그러시죠? 이게 어떻게 유용할 수 있는지 모르겠나요? 글쎄요, 피곤하고 지친 상태로 여정의 끝에 도달한 자들이야말로 진정으로 성과를 누릴 자격이 있다는 소문이 있습니다. 뭐, 그냥 소문일 뿐이지만요...'),
(52131, '호드와 얼라이언스 간의 휴전은 잘해봐야 위태로운 수준이며, 당신과 같은 용병과 아전투구의 모험가들은 종족이나 진영에 상관없이 원하는 누구와도 연합할 수 있지만, 1차 및 2차 대전을 기억하는 이들 사이에는 여전히 앙금이 남아있습니다. 이 문양은 당신의 전쟁 깃발을 높이 들어 올려 동족의 명예를 위해 싸울 것임을 모두에게 선포합니다. 영구적으로 PvP 상태가 되지만, 그 대가로 모든 출처로부터 경험치와 명예를 20% 더 얻게 됩니다.'),
(52132, '방랑자의 도전은 캐릭터 장비를 최소한으로 사용하는 방식에 도전하는 독특한 게임 모드입니다. 이 모드에서는 저급 및 일반 품질의 아이템만 착용할 수 있으며, 마법부여도 사용할 수 없습니다. 따라서 강력한 장비에 의존하는 대신 자신의 실력과 전략에 의지해야 하는 긴장감 넘치고 몰입도 높은 경험을 제공합니다.\r\n\r\n플레이어가 성장하여 60레벨에 도달하면 장비 제한이 해제되며, 특별한 동료인 포스원 노새를 보상으로 받습니다. 이 귀여운 은행 애완동물은 모험에 소소한 즐거움을 더해 줄 뿐 아니라, 소지품을 보관할 추가 공간까지 제공하는 유용한 조력자입니다.'),
(52133, '%s|1이;가; 마력 친화력의 힘을 빨아들이기 시작합니다.'),
(52134, '%s|1이;가; 공격에 취약해집니다.'),
(52135, '이게 뭐지?! 내 비밀을 훔치려고 내 방에 침입한 놈들이냐? 그렇다면 내가 가진 힘이 어떤 것인지 직접 보여 주마.'),
(52136, '생각보다 질긴 놈들이군. 좋아, 이제 봐주지 않겠다!'),
(60000, '반갑습니다, $N. 네, 저는 패션의 거장이며 귀하의 장비 외형을 마침내 잘 어울리도록 바꾸는 것을 도울 수 있습니다.'),
(60001, '이들 중 지혜롭게 선택하세요. 아이템당 변경 시 패션 코인 1개가 소요됩니다.'),
(60002, '놈리건 탈환 시설에 오신 것을 환영합니다! 저는 놈리건의 왕, 국왕 겔빈 메카토크입니다.\n\n드워프들의 호의에는 감사하지만, 깊은굴 지하철의 종착역은 더 이상 노움 사람들의 거처로 충분하지 않습니다. 놈리건을 탈환해야 하며, 이 오래된 공장은 노움 사람들이 탈환 작업을 수행할 수 있도록 새로운 거처로 개조되었습니다. 우리는 이 장소를 전초기지로 삼아 배신자 나병노움들로부터 놈리건을 정화하고 되찾을 수 있습니다.\n\n우리는 우리의 것을 되찾을 것입니다... 그리고 셔머플러그를 처단할 것입니다!\n\n자, 그렇게 말했으니. 무엇을 도와드릴까요?'),
(60010, '전쟁가어 정찰대의 거처에 오신 것을 환영합니다.\n\n지쳐 있으시겠군요. 호드와 우리의 전쟁 노력을 기리는 일은 목마른 작업입니다.\n\n잠시 머물며 지친 몸을 쉬어가세요.'),
(60011, '당신에게 무게감을 주는 것은 말이 아니라, 당신의 행동입니다 친구여.'),
(60012, '이곳에 배치되다니? 이보다 더 큰 영광은 없소.'),
(60014, '이곳이 우리의 영토라네. 보잘것없지만 보금자리라 부르고, 마음이 있는 곳이 바로 고향 아니겠나.'),
(60015, '반갑습니다! 사냥의 대가 암로 드 룩스, 인사드립니다.\n\n보스가 훨씬 더 흥미진진한 일을 하러 전 세상을 돌아다니는 동안, 누군가는 뒤에 남아 지루한 작업들을 처리해야 하죠.\n\n제가 무슨 일을 하냐고요? 물론 이 모든 운영을 관리하는 일이죠.'),
(60016, '어서 오세요, 지친 여행자여!\n\n이번엔 어떤 은밀한 즐거움을 찾으시나요? 술? 소문? 모험?\n\n무슨 문제라도 있으신가요?\n\n저는 마법사이고 술을 제공합니다! 아무에게도 말하지 마세요, 하지만 이게 내가 들어본 것 중 가장 쉽게 돈을 버는 방법이거든요.'),
(60017, '네?\n\n당연히 모조는 제 진짜 이름이 아닙니다... 보스만 알고 있죠.\n\n그리고 거기엔 그만한 이유가 있습니다. 이제 심문은 그만두고 다른 데 가서 노세요!'),
(60301, '우리 자치권의 큰 부분을 포기해야 하는 게 마음에 들지는 않네, 그렇고말고. 하지만 말했듯이 내 동족의 미래가 최우선이라네. 게다가, 조상들의 여신께서는 칼도레이를 잘 인도해 주셨지. 내가 감히 그들의 여신을 의심하겠나? 내 눈으로 직접 그분의 힘을 보았고, 자네도 보았지 않나. 그분이 내 동족에게 적합한 존재인지는 또 다른 문제라네. 오직 미래만이 답해줄 수 있겠지.'),
(60305, '<테그렌의 시선이 당신을 향해 고정되며 영혼까지 꿰뚫는 듯합니다.>'),
(60306, '예술 작품을 만들려면 숙련된 손길이 필요하지. 하지만 그 기술은 빛나는 정신과 함께할 때 비로소 완성되는 법이네.$B$B그렇게 아름다움이 탄생하는 거지.'),
(60312, '칼도레이가 도착해서 준비를 시작했습니다. 가셔서 진행 상황을 확인해 보시는 건 어떨까요? 황금여명회 연구소에 자리를 잡았습니다. 스톰윈드로 가는 순간이동 장치가 있는 부유 건물입니다. 완료되면 이쪽으로 돌아오세요.'),
(60313, '다시 만나 반갑네 친구, 우리 위업을 위해 자네가 해준 모든 선행에 대해 들었네. 회담을 위해 윈드러너 여사의 사절로 오신 건가?'),
(60314, '달의 샘을 정화하고 오우거들에게 응징을 내리는 것을 도와주신다면, 정화된 물을 일부 가져가셔도 좋습니다. 대사제님께 직접 당신의 입장을 전달하겠습니다.\n\n자매단과 파수대의 감독 하에, 퀘엘도레이의 일부를 다시 여신의 따뜻한 품으로 이끄는 시도를 하지 못할 이유가 없습니다. 설령 그들이 여신을 거부하더라도, 물 근처에 있는 것만으로도 결국 병을 치유하는 데 도움이 될 것입니다. 하지만 수천 년이 걸릴 수도 있습니다.\n\n퀘엘도레이는 2천 년 넘게 우리와 함께 살았지만 마법 사용을 중단하기엔 부족했다는 점을 기억하세요. 하지만 현대의 퀘엘도레이는 방황하는 우리 동족과는 다른 존재입니다. 어쨌든, 그것이 제 제안입니다.'),
(60315, '훌륭합니다! 그렇다면 달의 샘 옆에서 만나고 준비하세요, 쉬운 과업이 아닐 것입니다. 실패해서 후퇴해야 한다면, 다시 시도할 준비를 하겠습니다. 샘 옆에 신성한 물이 담긴 대접을 놓아두겠습니다. 당신이 거기 도달하면 저도 도착할 것입니다.\n\n정화 작업은 그 무지막지한 놈들의 주목을 끌 테니, 주저하지 말고 싸우세요! 놈들이 저를 부상시키면 정화도 실패합니다, 저를 안전하게 지켜주세요! 엘룬께서 우리를 인도하시기를.'),
(60350, '길네아스의 위엄 앞에 넌 죽게 될 것이다.'),
(60351, '이곳을 살아서 나가지 못할 것이다, 이방인!'),
(60352, '난 왕을 위해 싸우고, 넌 목숨을 위해 싸우는 거다!'),
(60353, '내 검은 적들의 피로 물들어 있고, 너도 곧 그들과 함께하게 될 것이다.'),
(60354, '너와 다른 반란군들은 가축처럼 사냥당할 것이다.'),
(60355, '이곳에서 자비 따윈 찾을 수 없을 거다, 오직 그레이메인의 진노뿐.'),
(60356, '왕관을 위하여!'),
(60357, '겐 그레이메인의 이름으로!'),
(60358, '빛의 이름으로!'),
(60359, '정의가 실현될 것이다.'),
(60360, '그림자 속으로 돌아가라!'),
(60428, '은빛십자군에 합류하고 싶으신가요? 그렇다면 나가서 유용한 일을 해보세요.'),
(60446, '거대한 힘이 도사리고 있고, 나는 그에 맞서 싸우려 한다. 나에게 해를 입힌 자들은 최후의 대가를 치르게 될 것이며, 나는 그들이 고통받도록 할 것이다. 당신이 나를 도와줄 사람이 될 것이고, 어쩌면 내 당신의 노고에 보상할지도 모르지.\n\n자, 편하게 있으라. 할 일도 많고 논의할 것도 많으니.'),
(60447, '물고기들을 다 겁주어 쫓아낼 작정인가요!'),
(60448, '동전 몇 개쯤 가지고 있지 않나요? 다음에 어딘가에 멈출 때 필요해서요.'),
(60449, '나는 결코 당신의 계급 따위 신경 쓰지 않는다. 나는 무엇보다 힘을 존중한다. 내 도끼에 가치 있는 사람임을 증명한다면 당신을 위해 죽겠다. 이 말을 반란으로 오해하지 마라, 당신의 명령을 존중하고 의문을 제기하지 않을 테니.'),
(60450, '어이 친구, 개리라고 하네! 동전을 쓰고 싶다면 여기가 바로 그곳이지. 운만 따라준다면 나를 통해 돈을 세 배로 늘릴 수도 있다네! 그래, 뭐라고 하겠나 해적 친구, 배짱이 좀 있나?'),
(60452, '승선을 환영하네, 우리 붉은해적단은 적어도 충성심만 있다면 서로를 잘 대해준다네.'),
(60454, '내가 늙었다고 약하다고 생각하지 마라, 알아들었냐 젊은이? 아주 잠시라도 경계를 풀었다간 올드 타이드 샘이 널 밑으로 끌어내릴 테니.'),
(60455, '배 위보다 쉬기 좋은 곳은 없죠! 파도의 흔들림이 부드럽지 않나요?')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(60459, '어이 친구, 장신구가 좀 필요한 것 같아 보이는데, 빌도가 자네에게 필요한 게 뭔지 말해주지.'),
(60460, '좋은 물건을 찾고 계신가요? 다른 곳에서는 절대 찾을 수 없을 겁니다.'),
(60465, '젊은 $r이(가) 여기까지 무슨 일로 왔나? 내 조언을 구하러 온 것이라 생각할 수밖에 없군.'),
(60470, '누구냐?! 물러가라, 여긴 내 집이다. 너희가 있을 곳이 아니다!'),
(60471, '숲의 아름다움은 비할 데가 없지요, 나무 사이로 흐르는 바람, 풍경을 수놓는 달빛. 하지만 그 아래에는 베일 속에 숨겨진 어둠이 도사리고 있습니다. 이곳은 한때 생명과 조화로 가득 차 있었지만, 이제는 세어볼 수 없을 만큼 많은 포식자가 들끓고 숲속의 우리 동맹들은 그저 돌아다니는 악당으로 변해버렸습니다.\n\n느껴지시죠, 마치 언제든 꿈에서 깨어날 수 있을 것처럼 말입니다.'),
(60472, '잿빛골짜기는 날이 갈수록 점점 더 위험해지고 있습니다.'),
(60474, '텔드라실의 최고의 보석, 다러나서스에 오신 것을 환영합니다.\n\n이 도시는 칼도레이의 심장이자 영혼 역할을 하며, 그만한 이유가 있습니다. 도사의 우아함과 아름다움은 우리 문화와 유산을 그대로 반영하고 있지요.'),
(60476, '여기 멀리까지 무슨 일인가 $R?'),
(60477, '편히 쉬게나, 여기 모닥불이 따뜻하니 자네도 따뜻해질 거야!'),
(60478, '우리 몰오그는 오랫동안 여기에 있었고, 앞으로도 오랫동안 있을 거다! 다른 놈들이 우리를 밀어붙일 수 있다고 생각한다고 해서 그게 의미가 있겠어! 크룩조그 군주님과 함께라면 우리는 섬에서 원하는 건 뭐든 할 수 있다.\n\n우리가 그놈들 모두보다 강하고, 곧 그놈들을 밀어붙일 거다!'),
(60479, '어이 거기, 난 윈싱 윌리 친구라고 해! 너에 대해 좋은 소문을 들었지, 그게 우리가 지금 대화하고 있는 유일한 이유야. 내 일은 대해에서 오는 물자들을 감독하고 다른 곳에 배분할 수 있을 때까지 보관하는 거지.'),
(60480, '낯이 익은데, 새로 온 선원 중 한 명인가?'),
(60481, '또 다른 붉은해적단인가? 여기까지 헤매다 나타나는 사람은 흔치 않은데, 돕고 싶은 게 뭔가?'),
(60483, '앞으로의 길은 달라질 것이다. 더 이상 자연에 적응하는 것이 아니라, 자연이 너에게 적응하게 될 것이다.'),
(60484, '포세이큰 사냥꾼의 길은 다른 이들과 다르다. 우리는 자연에 적응하지 않고, 자연을 꺾어 우리에게 적응하게 만든다.'),
(60485, '앞으로의 길은 달라질 것이다. 더 이상 자연에 적응하는 것이 아니라, 자연이 너에게 적응하게 될 것이다.'),
(60486, '앞으로의 길은 달라질 것이다. 더 이상 자연에 적응하는 것이 아니라, 자연이 너에게 적응하게 될 것이다.'),
(60487, '앞으로의 길은 달라질 것이다. 더 이상 자연에 적응하는 것이 아니라, 자연이 너에게 적응하게 될 것이다.'),
(60488, '이 세상의 짐승들은 언데드를 믿지 않는다. 하지만 잊혀진 그림자의 교단은 이에 대한 해결책을 가지고 있지.'),
(60495, '카르가스는 호드가 가진 가장 먼 변방 중 하나입니다.'),
(60496, '어이 친구, 자네가 붉은해적단을 위해 어떤 새로운 장을 써 내려갈지 매우 궁금하군. 당분간 캡틴의 요새를 감시하고 있겠지만, 자네가 쉬거나 혼자만의 시간을 보내러 올 때쯤이면 난 떠나고 없을 걸세.'),
(60500, '짧은 시간 동안 해야 할 일이 너무 많네, 경쟁자들은 말할 것도 없고, 저 지독한 투자개발회사 녀석들이 얼씬거리는 것도 모자라서 말이지.'),
(60502, '여기 뒤쪽까지 오는 사람은 별로 없는데, 쓸모 있는 녀석인가? 날 위해 잡일을 좀 해줄 수 있나?'),
(60503, '당신에게서 무언가가 느껴지는군요, 무언가... 다른 느낌이. 아마 다시 만나게 될지도 모르겠네요, 그때까진 날 내버려 두세요. 할 일이 많고 방해받고 싶지 않으니까요.\n\n싸움을 찾는 게 아니라면 말이죠 필멸자여, 그렇다면 마련해 줄 수도 있습니다.'),
(60504, '무법항에서 소식 들었나? 화물을 기다리는 중이거든.'),
(60507, '돌발톱 봉우리는 조화로운 장소일지 모르지만, 이를 유지하기 위해 우리는 경계를 게을리하지 말아야 합니다.'),
(60510, '낚시보다 더 위대한 건 없지!'),
(60511, '어이 친구, 자연과 함께 일하는 법을 배우고 싶나?'),
(60512, '이거 참 신선하군, 방문객이 자주 오는 편이 아닌데.'),
(60526, '희망이 가장 밝게 빛나는 곳은 바로 세상의 변두리입니다. 희미한 횃불조차 여전히 타고 있다는 사실을 결코 잊지 마세요.'),
(60527, '나는 내 고향에서 나에게 중요한 것을 지키고 있소, 미친 광신도들이든 언데드들이든 말이지. 빛의 요새는 한때 존재했던 것을 세울 것이오.'),
(60528, '내 가족은 한때 로데론을 고향이라 불렀소, 믿거나 말거나. 수년 전 우리 스톤퓨리 가문이 이름을 날렸던 광석과 보석 세공으로 가치 있는 돈을 벌었었지! 이제 내 가문의 유산에 남아있는 건 그을린 폐허와 돌 무더기, 탄 나무 조각들 뿐이오, 시체들은 말할 것도 없고!\n\n내가 무언가를 위해 싸워야 한다면, 차라리 여기서 싸우겠소.'),
(60529, '빛의 요새에 오신 것을 환영합니다, 편히 계십시오. 죽음의 역병이나 광신의 역병에 오염되지만 않았다면 말이죠.\n\n이 지역을 점령하고 있는 붉은십자군은 살아있는 자든 죽은 자든 모든 것에 대해 혈안이 되어 있습니다. 그들은 주변 세계를 적대적으로 보고 있으며, 한때 존재했던 진정한 빛이 비추려면 그들을 진압해야 합니다.'),
(60530, '반갑습니다, 이 근처의 많은 사람들은 국경 가장자리에 있을 만한 좋은 이유가 있죠. 당신의 이유도 의미가 있기를 바랄 뿐입니다.\n\n이 땅을 쥐고 있는 자들이 스컬지만큼이나 악랄할지라도, 언데드의 손길이 닿지 않은 로데론을 보는 것은 흥미롭군요.'),
(60531, '당신은 우리에게 훨씬 더 친절한 얼굴이군요, 우리 무기 동료들조차 그냥 와서 이야기하는 것을 원치 않았는데 말이죠.\n\n우리가 영웅으로 칭송받거나 적어도 열린 품으로 맞아줄 거라 생각했는데, 북쪽으로 간 십자군 원정에서 살아남은 후 불량배 취급을 받고 있으니 말입니다. 운명적인 원정으로 인해 많은 이들이 죽어갈 때 상황이 이렇게 무너졌다는 걸 생각하면 환멸이 납니다.\n\n어쨌든, 무례했다면 사과드립니다. 저는 붉은함대의 앰버타이드호 캡틴 해롤드슨입니다, 혹은 그 지독한 원정 이후에 남아있는 잔재일 뿐이죠.'),
(60532, '돌아온 모든 배들 중에서 살아남은 건 우리뿐이었어, 이게 운이라고 믿어?... 딸깝!\n\n나보다 훨씬 뛰어난 사람들이 많았는데, 솔직히 북쪽에서 일어난 모든 일을 겪고 난 후엔 여기 있고 싶지도 않아. 그냥 날 물속에 던져버려.'),
(60538, '저는 노련한 와이번 조련사입니다, $c. 타우렌과 오크들이 돌발톱의 하피들로부터 와이번을 해방시킨 게 바로 어제 같군요. 그 이후로 그들은 호드에게 충성스러운 친구가 되어왔습니다.'),
(60539, '브리스틀퍼는 당신을 보자마자 으르렁거리지만 공격하진 않습니다. 이 짐승은 바닥에서 매우 지루해 보이는군요. 간식을 좀 주면 당신을 태우고 비행하도록 설득할 수 있을지도 모릅니다.'),
(60540, '외지인을 자주 보진 못하는데요! 어서 오세요 몸을 피하세요, 겨울이 정말 가혹해질 수 있거든요!'),
(60541, '와, 당신은 누구인가요? 인웅쿠아크가 남쪽 땅에서 만나러 가려던 사람들 중 한 명인가요?!\n\n여기 오신 건 운이 좋네요, 많은 이들이 하늘을 날아다니는 거대하고 반짝이는 정령을 보기 위해 카넥눈으로 여행해 오거든요. 어쩌면 당신도 보게 될지도 몰라요!'),
(60542, '카넥눈에 오신 것을 환영합니다. 내가 본 그 어떤 것과도 많이 달라 보이지만, 친절하게 대하는 한 환영합니다. 저는 이곳의 장로 파누쿠키입니다. 질문이 있으시면 언제든 저에게 가져오세요.'),
(60543, '여기 물고기들은 항상 입질을 하죠.'),
(60549, '반갑습니다 여행자여. 서쪽에 있는 우리의 고대 고향인 칼림도어에 도달하고 싶다면 배를 타고 가야 합니다. 아우버다인에서 출발하는 우리 배 중 한 대가 이곳 스톰윈드에 정기적으로 정박합니다.\n\n배가 여기에 없다고 걱정하지 마세요. 제때 도착할 테니까요.'),
(60606, '카라잔 주변에서 증가하는 마법 에너지들은 키린 토 내부에서 큰 우려를 자아냈습니다. 시간이 지날수록 더욱 대담해지는 것 같은 신비함을 연구하고자 내 의지로 이곳에 왔습니다. 대의를 위해 알 수 없는 것들을 밝혀내는 데 키린 토를 도울 용의가 있으신가요?'),
(60607, '강하게 불타오르는 위대한 마법을 찾아 멀리서 찾아왔습니다. 오그리마에서부터 그 힘을 느꼈고, 더 많이 알아내야 합니다.\n\n의심할 여지 없이 근처의 카라잔 탑에서 나오는 것입니다. 그 안에 도사리고 있는 것은 모두에게 미스터리이며 밝혀져야만 합니다. 당신의 도움이 필요합니다, 도움을 주실 용의가 있으신가요?'),
(60611, '정말 멋진 곳이지 않나요?'),
(60621, '우리는 대해 너머 동부 왕국 동쪽에 위치한 많은 동맹을 두고 있습니다. 이 선착장에 도착하는 배는 얼라이언스의 심장부인 인간들의 도시 스톰윈드 항구로 향합니다.\n\n배가 없다면 느긋하게 기다리세요. 곧 도착할 것입니다.'),
(60622, '필멸자가 이 홀을 거닌 지 오래되었습니다. 당신들 모두에게 불만이 많지만, 당신들의 도움이 필요하다는 것은 이해합니다.'),
(60623, '이 배는 듀로타의 스파크워터 항구까지 연결해 줍니다. 고블린들은 우리에게 온갖 종류의 물건을 필요로 하고, 우리는 무기의 대가로 그것들을 공급해 주는 것을 매우 기쁘게 생각합니다.'),
(60624, '나와 내 형제 티작이 이 비행선 항로를 운영하고 있지! 조만간 기계를 수리할 새 부품이 필요하겠지만, 황탄지대를 거쳐 여행하는 건 정말 스트레스였습니다! 이 비행선은 호드의 심장부인 오그리마까지 연결됩니다.\n\n비행선이 들어올 때 조심하세요, 아슬아슬할 수 있으니까요!')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(60625, '헤, 이 늙은 고물상 상자는 조종이 제일 좋지 않소. 황탄지대의 거친 험준한 지형을 통과하는 게 지독하게 힘들지만, 지금까지 잘 버텨왔소! 카르가스로 가는 급행 티켓을 찾고 있다면 이 늙은 여성보다 더 좋은 항로는 없소, 비행선은 확실히 충직하니까요!\n\n아, 덜컹거리는 탑승감은 신경 쓰지 마시오. 새 부품이 좀 필요하고, 제대로 멈추지도 않거든.'),
(60626, '어이 거기, 썬더 블러프의 광대한 평원으로 향하고 싶으신가요? 그렇다면 운이 좋으시군요. 오그리마에서 썬더 블러프까지 새로운 항로를 개설했거든요. 아주 경치가 좋으니 한번 이용해 보세요.'),
(60627, '듀로타는 덥고 무더운 곳이죠, 확신합니다. 시원한 바람과 아름다운 풍경이 있는 이곳 썬더 블러프에 배치되어 기쁩니다!\n\n오그리마로 가고 싶다면 이 비행선이 도시 바로 밖에 정차합니다.'),
(60628, '왜 그러시죠, 도와드릴 일이 있나요? 비전 마법에 관한 지식을 구하는 게 아니라면 도움이 되지 않을 수도 있습니다.'),
(60629, '우리 드워프 마법사들은 푸른돌 결사단 소속이라네. 오랜 옛날 아이언포지의 동굴에서 광산을 캐던 중, 오래되고 마법의 힘이 강력한 돌을 발견했지. 이 돌은 달라란의 마법사들에 의해 연구되었고, 바로 그날 이후로 우리 손에 보관되어 왔다네.\n\n많은 최초의 드워프 마법사들이 비전의 영역에 발을 들여놓게 된 것은 바로 이 돌 덕분이었지. 자연적으로 마법에 재능이 있는 우리 동족을 본다면 이곳으로 안내하게나.'),
(60631, '<엔리비가 당신의 영혼을 깊이 노려봅니다>.'),
(60636, '남부성난 무역 회사에 오신 것을 환영합니다, 친구여! 사업차 오셨나요? 화물을 보낼 필요가 있다면 최고의 상단원들이 준비되어 있습니다.\n\n아니면 동전을 너무 많이 가지고 다녀서 건달들이 따라올까 봐 걱정되시나요? 문제없습니다, 당신의 어여쁜 엉덩이를 보호할 잘 훈련된 근육들이 있으니까요! 아니면 남해의 희귀한 물건들을 찾고 계신가요? 돈으로 살 수 있다면 반드시 구해다 드립니다, 약속하죠!\n\n남부성난 무역 회사 - 돈이 있으시다면 저희가 가져가겠습니다!'),
(60640, '분노의 손길은 집행관 로트하트가 이끄는 군사 부대입니다. 적들을 짓밟는 호드의 철권이죠. 손길은 대족장과 호드 종족의 지도자들을 섬깁니다.\n\n전쟁의 화염 속에서 호드의 모든 종족 간의 형제애를 다지기 위해 어둠의 여왕의 명령으로 포세이큰 전위대에서 설립되었습니다. 합류하고 싶거나 사업이 있으시다면 터널 바로 아래로 내려가시면 장교들이 있습니다. 아니라면 내 시간 낭비하지 마세요.'),
(60643, '내 수확물에 손대지 마 이봐!'),
(60644, '나는 셰난드랄라의 지식을 품고 있다, 나는 엘드레탈라스의 명가이며 우리 세계에 대해 아주 많이 알고 있다. 당신이 내가 더 많은 지식을 얻도록 도와줄 수 있으니 기꺼이 당신을 섬기겠다, 선장.'),
(60645, '황금달 서커스에 오신 것을 환영합니다, 황금달 유랑극단의 거처죠.\n\n마법 같은 연기와 속임수로 당신을 즐겁게 해드릴 테니 즐거운 시간 보내세요 - 하지만 화상, 질식, 익사, 금전 손실, 신체 손실 또는 정신 상실이 발생하든 안 하든 저희는 책임을 지지 않습니다.\n\n양해해 주셔서 감사하며 즐거운 하루 보내세요.'),
(60648, '반갑습니다.\n\n이 영역에서 나는 차원 사이의 낚시꾼 올롬으로 알려져 있다. 당신은 새로운 얼굴이군... 아마도?\n\n젊은 오크 시절 악마 주인에게서 벗어났기에, 수년이 지난 후 군단에 맞선 다른 이들이 있다는 것을 마침내 알게 되었을 때 매우 기뻤다. 새로운 시대와 스타일의 흑마법사가 성장하고 있다는 사실에 마음이 기쁘다.\n\n여기 핍남이 많은 악이 도사리고 있다고 보고했다. 그래서 우리 이름이 암시하듯 최악의 상황에 대비해야 한다.\n\n우리는 에레드 루인. 파멸의 수호자다.\n\n환영한다.'),
(60656, '내 모든 것: 분노, 잔혹함, 복수, 죽음과 부패 - 언데드의 차가운 품을 환영하는 자들에게 부여하노라.\n\n이제 우리 앞에 놓인 땅을 바라보라.\n\n붉은십자군은 내 업적을 되돌리려 허둥대고, 빛의 희망 예배당은 우리에게 대항하여 거만하게 서 있다 - 동부 역병지대의 흠집에 불과한 놈들이.\n\n놈들 모두에게 반역의 대가를 보여주어야 한다.\n\n네가 밟는 곳마다 역병이 따를 것이다.\n\n이제 가서 넬쥴과 리치 왕의 이름으로 이 땅을 차지하라. 모두. 죽어야. 한다!'),
(60660, '학원이 항상 퀘엘도레이의 것은 아니었답니다, 그 기원은 순찰대장 드래곤스트라이더가 알던 것보다 훨씬 더 고대이죠. 고대의 전쟁 이후, 엘룬의 낫에서 불운하게 풀려난 후 많은 워겐들이 여전히 칼림도어의 숲을 떠돌았습니다. 악마와 사티로스들도 날뛰었고 무고한 이들이 끊임없이 살해당했습니다. 용맹한 파수꾼들과 명가 마법사들은 서로의 차이점을 제쳐두고 밤을 기어 다니는 포악한 괴물들을 소탕하기 위해 새로운 전사 단체를 만들었습니다. 당신들의 언어로 "테로아니르" 또는 "용매"는 적들의 사나움에 맞서기 위해 용의 피가 주입되었습니다.\n\n슬프게도, 원래 테로아니르 중 남아있는 건 시다스와 나뿐입니다. 순찰대장 블레이드송의 단체 부활과 함께 학원이 다시 절정에 달하길 바랄 뿐입니다.'),
(60661, '친구여 환영합니다!\n\n이 신성한 장소는 아제로스의 마크로켈리스의 거처이자, 호드와 얼라이언스의 수호자들, 정령 집행자들, 용 사냥꾼들, 신 도살자들의 거처입니다.\n\n이곳이 우리의 고향이며, 마음이 있는 곳이 바로 고향입니다.'),
(60662, '뭐라고? 이 검은 깃발들을 모른다고? 내가 살아있었을 때조차 이빨들을 두려워했어! 웃음은 진짜 대족장 블랙핸드를 섬긴다. 그는 우리를 보내 스톰윈드에 맞서 새로운 전선을 열게 했지. 루아그 두목은 모든 검이, 심지어 어둠의 호드의 검이라도 늪지대에서 필요하다는 걸 알고 있어. 평화대장의 자존심이 듀로타에서 으뜸일지 몰라도, 넌 지금 아제로스의 겨드랑이에 들어와 있는 거다, 꼬맹이. 그리고 우린 늪보다 더 악랄하지. 집에 돌아가면 우리 얘긴 꺼내지도 마라, 알겠어?\n\n<그는 이제 혼잣말을 하는 것처럼 보입니다.>\n\n그냥 날 죽게 내버려 두질 않는군...'),
(60668, '록타르 오가르!\n\n이 캠프에서는 어떤 부족 출신이든 서로 피를 흘리지 않는다. 여기서 상처를 치료하고 휴식을 취한다.\n\n분홍 피부 놈들에 맞서 다음 전투를 준비하기 위해.\n\n피와 불과 죽음을 통해!'),
(60670, '함께하게 되어 기쁩니다! 샤란디스에서 무엇이 기다리고 있을지 알 수 없지만, 새로운 동맹을 실망시킬 수는 없습니다.'),
(60700, '지난 전쟁의 부상 이후 최고의 식사를 준비하는 데서 내 소명을 찾았습니다.\n\n일하러 돌아가기 전에 마음껏 드세요!'),
(60702, '모두가 내 맥주의 비결을 알고 싶어 하지만, 내가 가르쳐줄 수 없는 것입니다.\n\n몇 년 전 거북이를 탄 엉뚱한 남성에게서 배웠거든요.'),
(60703, '매일 여기 와서 밥 먹는 게 참 불편한데, 사른의 맥주를 끊을 수가 없어.\n\n난타이가 일하는 거 봤어? 하루 종일 보고 있을 수도 있을 것 같아.'),
(60704, '<그녀는 들떠서 당신의 얼굴 앞에서 손뼉을 치며 미친 듯이 킥킥거립니다.>\n\n이 영지 주변을 조심히 걸으세요! 의심스러운 자들이 주변에 많아서 꽃들조차 두려워하고 있어요!\n\n그 소리가 들리나요?!'),
(60710, '이 땅에 더러운 어둠이 침범해 점점 더 강력해지고 있습니다. 악마의 오염을 막는 것은 우리에게 달려 있습니다.\n\n악마를 추적하고 세상에서 제거할 자격이 있으신가요?'),
(60727, '테라모어에 오신 것을 환영합니다, 편히 계세요. 저는 테라모어 방어 사령관 브린 대령입니다.\n\n우리는 항상 용감한 손길을 찾고 있습니다. 일거리를 찾으신다면 테라모어 경비대를 도와주실 수 있습니다.'),
(60728, '누군가는 이 등대를 계속 가동해야 하고, 그 누군가가 나라고 생각합니다.\n\n할 일이 많은데, 필요한 게 있으신가요?'),
(60729, '이 밖은 위험해요, 의심할 여지없이 말이죠! 특히 주변에 도사리고 있는 모든 야생 동물들 때문에요.'),
(60730, '국경에서 할 일이 많으니, 도우러 온 게 아니라면 일하게 내버려 두세요.'),
(60731, '우리는 칼림도어 내에서 마주친 많은 것들을 장으로 만든 온갖 종류의 책을 보관하고 있습니다. 희귀한 지식을 구하신다면 제대로 찾아오셨습니다.'),
(60732, '최근 해안가가 점점 더 우려스러워지고 있으니, 상황이 더 악화되지 않기를 기도합시다.'),
(60733, '부두는 내 영역입니다, 보낼 것이나 배달할 것이 있다면 알려주세요.'),
(60748, '어디를 걷고 있는지 아느냐 필멸자여? 이곳은 너희 종족이 존재하기 훨씬 전부터 여기에 있었다. 에메랄드 안식처는 신성한 땅이다. 싱그러운 풀밭을 밟는 너의 발걸음 자체가 이곳의 아름다움을 더럽힌다. 너의 더러운 냄새가 공기 중에 떠돌고 있구나.\n\n너는 떠나야 한다, 나머지 녹색용군단이 깨어날 때까지 오래 걸리지 않을 것이다.\n\n우리의 영원한 의무가 도달했고, 깨우는 자로서 나는 잠에 빠진 자들을 뒤흔들기 위해 부름을 보냈다. 그들은 도착할 것이다, 이제 시간문제일 뿐이며, 너는 길을 막지 못할 것이다, $r.\n\n어둠이 넘실대며 잠들지 못하는 영역에 번지고 있으니, 내가 그것을 끝낼 것이다.'),
(60749, '그래서, 호드에서 오셨나요, 그렇죠?\n\n내 이름은 타자고입니다. 한때 우코르즈 샌드스칼프 밑에서 그의 영웅으로 싸웠지만, 그 시절은 오래 전에 지났습니다 친구여.\n\n파르라기 부족은 흩어지고 환상이 깨졌습니다. 우리 전후로 다른 이들이 떠났고, 줄파락이 그 도시에서 일어난 모든 악하고 저주받은 일들 때문에 버려진 폐허로 남을 때까지 오래 걸리지 않을 것입니다.\n\n어쩌면 당신이 우리를 도울 수 있을지도 모릅니다, 도움이 필요하거든요.'),
(60750, '무서워하지 마세요, 바이스클로는 내가 시키지 않는 한 아무도 꼬집지 않으니까요!'),
(60751, '어이 친구, 이 마을엔 방문객이 많지 않아. 난 여기서 가죽 일을 하는데, 특별히 찾는 게 있나?'),
(60752, '조상님들께서 옛 도시에서의 우리 행동 때문에 노하셨다. 구원을 얻고 파르라기 악의 오염에서 벗어나 새로운 운명으로 우리를 이끌 지침을 구하고 있다.'),
(60753, '샌드문 마을에 오신 것을 환영합니다, 이곳은 타자고가 이끌고 있습니다. 그는 이곳의 리더이고, 이 세상 끝까지 믿고 따를 사람입니다 친구여.\n\n우리의 잃어버린 명예를 되찾을 수 있는 사람이 있다면, 바로 그일 것입니다.'),
(60754, '타나리스에서는 조심하세요, 물이 없어 외지인들에게는 가혹한 곳입니다.\n\n태양 자체가 우리 종족 중 가장 강한 자들조차 메마르게 만들었으니, 더위에 불사신이라고 생각하지 마세요.'),
(60759, '이곳에서의 우리 임무는 지극히 중요합니다. 어둠의 문이 지옥 에너지로 일렁이고 있으니, 여전히 활성화되어 있는지 누군들 알겠습니까.'),
(60760, '난 오우거가 싫어.'),
(60761, '난 타이무의 아들 자이무다. 필요한 게 뭔가 친구?'),
(60762, '나는 옛 방식으로 제작하는 데 정통하니, 수리를 받아서 내 기술을 연마하게 해줄 수도 있겠지.'),
(60763, '어둠의 마법은 전투에서 우리를 돕고 영혼을 강화한다. 우리 혈관에 흐르는 피의 분노는 이용할 수 있는 자원이며, 내가 불러낼 수 있는 힘에 의해 도움을 받을 수 있다.'),
(60764, '언제나 더 어두운 힘이 작용하고 있으니, 그들의 속임수를 피할 만큼 똑똑하다고 생각하지 마라. 경계하라, 누구 혹은 무엇이 지켜보고 있는지 결코 알 수 없으니.'),
(60765, '많은 전장을 누비며 수많은 적을 베었지만, 이제야 앞에 놓인 일에 주의를 기울이게 되는군. 카르팡을 내 피 한 방울까지 신뢰하지만, 온 세상을 무대로 하는 이 \'새로운 호드\'와 같은 가치를 공유하고 있는지는 모르겠다.\n\n어쩌면 정말 최선일 수도 있고, 어쩌면 우리의 몰락일 수도 있으니, 시간이 지나면 알게 되겠지.'),
(60766, '뭘 찾고 있나 외지인?'),
(60769, '원하는 게 뭐야, 바쁜 거 안 보여 꼬맹이?'),
(60770, '내 이름은 카르팡이다, 이곳의 리더지.\n\n네가 모욕하거나 너무 괴롭히지 않는 한, 내 동족은 너를 해치지 않을 것이다. 이 세상에서 우리의 자리를 확보하기 위해 논의할 것도 많고 해야 할 일도 많다.\n\n검은바위 부족은 더 큰 세력에 의해 조종당하고 있음을 깨달았다. 옛 호드는 한때의 껍데기에 불과하며, 내 동족이 그들을 따라 광기로 들어가는 것을 좌시하지 않을 것이다.'),
(60772, '나는 카르팡의 고문이다. 대내외의 모든 문제에 대해 그에게 조언하지.\n\n이 타버린 골짜기 너머에서 소식을 가져왔나?'),
(60773, '필요하다면 에일이 있고, 필요하다면 음식이 있소, 뭘로 하겠소?'),
(60774, '우리가 사이가 좋아서 다행인 줄 알아라 외지인, 혀와 나쁜 말을 삼가라. 부족 외의 자들을 죽이는 데 익숙하니까.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(60775, '나는 사냥, 살상, 배회를 위해 바르그를 훈련시키는 사람이다.\n\n나는 우리의 가장 훌륭한 표본들과 가장 유용한 동맹들을 책임지고 있다. 자, 원하는 게 뭐냐 외지인?'),
(60778, '쥐어쥔 주먹이 백 가지 말보다 더 크게 말한다.'),
(60780, '아 안녕, 리빙스턴 농장에 오신 것을 환영합니다, 편히 계세요. 한 가지 부탁드릴 건 들어오기 전에 밖에서 발을 털어주세요!'),
(60781, '이 주변에 지독한 생물들이 너무 많아서 농작물을 계속 어지럽히고 우리 삶을 필요 이상으로 힘들게 만드네요...\n\n아, 미안해요, 무엇을 도와드릴까요?'),
(60782, '이 모든 작업이 진행되고 있다니 신나는군요, 도시 전체가 완성되는 걸 어서 보고 싶어요!'),
(60784, '아제로스는 참 신비로운 곳입니다, 많이 읽을수록 더 많이 알게 되죠.'),
(60786, '스트롬가드 기병대의 말들을 많이 돌보고 있습니다, 주변에서 보셨을 테죠. 그들은 이곳과 임시 거처 지점 사이의 주 도로를 가능한 한 안전하게 유지하곤 합니다.'),
(60787, '상황이 훨씬 나아지는 것은 시간문제일 뿐입니다.'),
(60788, '용감한 광장에 오신 것을 환영합니다, 도시의 우리 구역이죠. 경계를 풀지 마세요, 우리가 이루고 있는 발전만큼이나 몇 분 만에 모두 파괴될 수도 있으니까요.\n\n오우거들과 신디케이트가 여전히 도시 다른 부분에 도사리고 있어서 우리에게 큰 방해가 되고 있으니, 들어오고 나가는 길에 정신을 똑바로 차리세요.\n\n자, 무엇을 도와드릴까요?'),
(60789, '수줍어하지 말고 이리 오세요! 온갖 종류의 마법 용품과 물건을 팝니다, 어쩌면 제가 파는 걸 찾고 계실지도 모르겠네요!'),
(60790, '수줍어할 필요 없습니다, 둘러보고 필요한 걸 사 가세요.'),
(60791, '환영합니다, 이 지옥 같은 곳에서 휴식을 찾으시길 바랍니다.\n\n이곳은 네더가드 요새로, 오랫동안 어둠의 문이 열리고 1차 대전이 시작되었을 때 세워졌습니다. 우리는 이곳을 감시하고 마법 이상 현상이 발생하면 보고하도록 배치되었습니다.\n\n이상한 점을 발견하시면 알려주세요.'),
(60792, '우리는 오우거부터 오크, 악마까지 저 밖에서 온갖 적들을 보았습니다. 놈들이 대담해져서 우리를 공격하는 건 시간문제일 뿐입니다.\n\n놈들이 그런 행동을 할 때 우리는 충분히 준비되어 있을 것입니다.'),
(60793, '여기서 문제를 일으키지 않도록 하세요, 황무지에 도사리고 있는 모든 지옥 변형 짐승들만으로도 문제가 넘쳐나니까요.\n\n아니면 도움을 주기 위해 이 국경에 오신 건가요.'),
(60794, '마법의 변동이 너무 많고, 유전자의 변형이 너무 많아서, 그 모든 가능성에 노움의 머리가 어지러울 지경입니다!\n\n할 연구가 있습니다 $R, 연구가 있습니다!\n\n아, 맞다. 저는 네더가드의 수석 분석가 위글스팁이라고 합니다, 만나서 반갑습니다.'),
(60795, '이 저주받은 돌벽 뒤에서 안절부절못하고 있소, 여기서 썩어가기엔 너무 많은 악마 해골을 부숴버렸거든.\n\n이름은 하구프요, 여기 오래 있었는데, 무엇을 도와줄까?'),
(60799, '우리가 여기서 무엇을 하고 있는지 궁금하실 겁니다.\n\n나를 정확히 이해해 주세요, 우리는 전쟁을 좋아하지 않습니다.\n\n우리는 자존심이나 명예를 위해 전투에 임하지 않습니다. 얼라이언스와 호드 사이의 싸움 따위엔 관심이 없습니다.\n\n각 진영에는 아이들이 있고, 모든 아이는 행복하게 자랄 수 있어야 합니다.\n\n여단은 이 세상을 보존하고 자신들의 아이들을 보호하고 싶어 합니다.\n\n자, 이제 결정하는 것은 당신에게 달려 있습니다. 우리에 합류하고 싶다면 이 나비를 가지세요. 당신의 마음과 휘장 위에 앉을 것입니다. 그러면 이해하기 시작할 것입니다.'),
(60802, '반갑소, 군인. 사악한 검은용군단을 퇴치하러 왔소? 공기 중에 긴장감이 감도는구려... 느껴집니다. 용군단의 새로운 지도자들을 쓰러뜨리는 데 가까워질수록, 다시 안전함을 느끼는 데 가까워집니다.'),
(60806, '마음속에서 분노를 털어내지 않는 한, 당신의 성장은 영원히 저해될 것입니다.'),
(60813, '당신의 여정이 흥미로운 곳으로 안내하기를 바랍니다, 무엇을 도와드릴까요?'),
(60816, '붉은구름 보금자리에 오신 것을 환영합니다. 이곳에서 우리는 새로 태어난 어린 와이번들이 호드의 충직한 동반자로 살아가도록 준비시킵니다. 제대로 훈련받지 않으면 다루기 힘들어지고 야만적이 될 수 있거든요.\n\n와이번들이 얼마나 포악해질 수 있는지 알고 싶다면 돌발톱 산맥 안에서 길들여지지 않은 많은 와이번을 발견할 수 있을 것입니다.'),
(60817, '저는 한동안 여기서 와이번들을 훈련시켜 왔으며, 와이번들이 원시적 본능을 제대로 제어할 수 있도록 하고 있습니다.'),
(60818, '이곳에 새로 온 것은 확실히 장단점이 있지만, 적어도 최고로부터 배웁니다.'),
(60822, '이 지독한 가시돼지들은 내가 예상했던 것보다 항상 강하군요, 절대로 적을 과소평가하지 마세요.'),
(60823, '영혼들이 저세상으로 잘 전환되도록 하는 것이 우리에게 달려 있습니다. 우리는 그들을 지켜보고, 그들의 기억과 경험이 세대에서 세대로 전해지도록 해야 합니다. 어떤 면에서 우리는 과거와 현재의 파수꾼입니다.'),
(60824, '어디에 있든 영혼들을 항상 느낄 수 있습니다. 조상님들이 앞길을 인도해주실 것임을 알고 위안을 얻으세요.'),
(60825, '보는 것이 믿는 것입니다.'),
(60826, '다음에 올 것을 두려워하지 마세요, 주변 이들과 함께 이 경험을 공유하는 것을 기뻐하세요.'),
(60827, '아라소르는 오랫동안 트롤들과 전쟁을 벌여왔고, 우리가 그것을 끝낼 자들이 될 것입니다.'),
(60832, '어둠철퇴 안에서 많은 노력을 기울였는데, 그 모든 게 아무 의미도 없었다고 생각하니.'),
(60833, '추방당했다고, 그게 믿어져?!\n\n난 어둠철퇴 광부 조합을 보살피던 반장이었어. 수년 동안 도시 자체의 터널을 파냈는데 받은 대가가 이거야? 내 실패에서 살아남은 걸 다행으로 여기라더군. 의심할 여지 없이 나와 내 무리가 검은바위 쓰레기들에게 그냥 죽길 바랐겠지.\n\n대가르 치르게 될 거다.'),
(60834, '아, 평생 늙은 오르박에게 충성했는데, 놈들은 나를 다른 사람들과 함께 쫓아냈고, 남은 건 우리뿐이야.'),
(60846, '메에에!'),
(60850, '배울 것도 많고 전해줄 지혜도 많습니다.\n\n우리 추방자들은 이 세상의 다른 종족들에게 가르쳐줄 것이 많습니다.'),
(60851, '호기심 어린 얼굴을 보니 우리가 누구이고 무슨 일을 하는지 알고 싶어 하는군요...\n\n<마법기술자 보르탈이 답답한 듯 한숨을 쉽니다.>\n\n우리는 탈라시안 얼라이언스입니다. 난민들과 내 동족인 하이 엘프들을 돕고, 당연히 새로운 얼라이언스 동맹들이 무엇을 하든 지원하는 고귀한 목표를 가진 단체이죠.\n\n자, 실례가 안 된다면 이 지독한 보주를 고쳐야 하니, 당신이 지맥이나 마나 전류의 전문가가 아니라면 다른 데 가서 놀고 내 시간 좀 뺏지 마세요!'),
(60854, '내 오두막에서 나가.'),
(60855, '조심해라, 주둔지 무기고가 점령당했다.'),
(60856, '타나리스의 울부짖는 바람이 나에게 무언가를 속삭이는데, 되돌려 말할 수가 없군요... 이렇게 길을 잃다니 기묘한 일입니다.'),
(60857, '이곳에 온 것을 환영합니다, 할 일이 많아요!'),
(60858, '몰티모어 가트사이드'),
(60859, '나 바빠, 친구.'),
(60860, '안녕 동지. 너처럼 에너지가 넘치고 의욕적인 사람을 보니 기쁘군. 한때 나도 살아있음을 느꼈지만, 지금은 폐허에 불과하고 내가 왜 아직 여기 있는지 모르겠어. 이 세상에 몇 번이고 환생한 듯한 기분이 들어...\n\n희미한 기억이 떠오른다... 상자? 조심해! 함정으로 가득 차 있어, 자살행위야!... 숨이 막혀, 다음 생엔 수영하는 법을 배워야겠어...\n\n우후, 그게 뭐였는지 모르겠지만 기억하니 오싹하군. 명심하는 게 좋을 거야.'),
(60862, '<시체가 움직이지 않고 누워있습니다.>'),
(60863, '<조상님들의 시선이 당신을 향하는 것이 느껴집니다>.'),
(60864, '<조상님들의 시선이 당신을 향하는 것이 느껴집니다>.'),
(60865, '<조상님들의 시선이 당신을 향하는 것이 느껴집니다>.'),
(60869, '여기 외곽에 배치된 건 모욕에 가깝지, 잘못된 일 하나 했다고 문제를 처리하러 변방으로 보내지다니...\n\n누군가는 손에 흙을 묻혀야겠지.\n\n일거리를 찾고 있나, 도움이 필요한데.'),
(60870, '산등성이 주변에서 온갖 일들이 일어나고 있으니 눈을 크게 뜨게, 검은무쇠 부족이 보일 테니.\n\n난 놈들이 무슨 짓을 하는지 알아내러 여기 있네.'),
(60872, '아이언포지도 좋지만 놈리건이 좀 그립군요, 그냥 아늑하고 여러 분야에서 온갖 발전의 가능성을 제공했잖아요, 그렇죠?\n\n뭐, 아닐 수도 있지만 어쨌든 다 나쁜 건 아니에요, 여전히 알아낼 것들과 풀어야 할 미스터리들이 있으니까요.'),
(60873, '늑대가 두려움에 찬 눈빛으로 당신을 바라봅니다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(60874, '잘 지내고 계시길 바랍니다, 필요한 게 있으신가요?'),
(60875, '2 더하기 3 곱하기 4는... 원하는 게 뭐야?'),
(60877, '빛이 모두를 보살피신다, 그걸 잊지 말아라.'),
(60879, '원하는 게 뭐야? 나 바쁘니까 얼른 지나가.'),
(60880, '그롬마쉬 헬스크림의 죽음 이후, 우리 부족은 잿빛골짜기에서 버섯구름 봉우리까지 칼림도어 전역에 흩어졌다.\n\n요즘엔 전쟁가어 정찰대의 가장 사나운 지도자들만이 목소리를 낸다. 하지만 언젠가, 조만간... 새로운 대족장이 일어날 것이다! 며칠 만에 오그리마를 세운 것은 우리다. 모든 시민들이 진짜 호드의 아들들이 해낸 일을 목격하고 있다!\n\n우리는 저 지독한 나이트 엘프들이 터무니없는 방해 공작을 계속하도록 내버려 두지 않을 것이다.\n\n전쟁 노력에는 끝이 없다. 영원한 유목 생활이 칼림도어 전체를 누비는 한.'),
(60884, '벽에 난 이 구멍 같은 곳으로 들어온 자가 누구인지 보게나! 우리 숨어있는 곳을 찾아냈군, 빡세게 일해서 부자가 되거나 죽으려는 자들의 아지트라네. 동전이 있나? 받아주지. 목이 말라? 안에 통이 수두룩하네.\n\n기술을 좀 연마하든, 벽을 멍하니 바라보든, 우린 신경 안 쓰네. 놈들이 널 찾는 걸 멈출 때까지 몸을 사리고 쉬다가, 다시 나가서 부를 찾게나!'),
(60888, '어이 거기! 부발톱 기지에 오신 것을 환영하네! 이름은 헤로드와투스라 하고, 길드의 역사학자라네. 길드의 역사에 대해 전부 알고 있지! 부발톱의 목적은 스컬지와 불타는 군단에 충성하는 모든 자들을 사냥하는 것이라네. 니콜라스 오스마부터 마지막이자 지금은 사망한 라그나르 망누스까지, 모든 지도자들이 이 목적을 따랐지.\n\n하지만 말해주겠네, 쓰러진 지도자들도 부발톱이 아제로스의 모든 스컬지 짐승들과 악마들을 사냥하는 것을 막지 못할 걸세! 이제 부발톱은 아네스트가 이끌고 있다네. 멍청하지만 배울 걸세! 두고 보게나.'),
(60893, '은빛십자군에 합류하고 싶으신가요? 그렇다면 나가서 유용한 일을 해보세요.'),
(60899, '하필이면 닻의 모퉁이까지 당신을 이끈 것은 무엇인가요?'),
(60900, '깊은파도호는 수년 동안 쿨 티라스에 충직한 함선이었습니다.'),
(60901, '우리의 여정은 예상보다 훨씬 오래 걸렸습니다. 이제 호드에 맞서 우리의 노력을 기울여야 할 때입니다.'),
(60902, '빛에 대한 신념을 유지하면 모든 것이 드러날 것입니다.'),
(60916, '누군가가 이곳에 발을 들여놓은 지 오래되었습니다.'),
(60917, '내 왕국은 먼지로 무너졌고, 내 백성들은 오래전에 사라졌으며, 내 기억은 희미해져 가오. 하지만 난 여전히 여기에 남아 한때 위대했던 과거를 상기시키는 유령으로 서 있소. 잊혀진 내 영토에 온 목적이 무엇이오?'),
(60924, '우리 레드브랜드는 아주 오래전 세 망치 전쟁에서 국왕의 편에 서서 싸웠습니다. 우리는 자랑스러운 유산을 지니고 있으니 가볍게 판단받아서는 안 됩니다.'),
(60925, '내 이름은 나즈그림 레드브랜드, 고귀한 레드브랜드 가문의 영주요. 레드브랜드 가문은 최근 우리 이름을 딴 가문이 무너지면서 많은 비극을 겪었소. 내 가문의 유산이 불운으로 더러워지는 것을 좌시하지 않을 것이오.\n\n드워프의 평판은 이곳 카즈 모단에서 큰 의미를 가지며, 내가 레드브랜드 가문의 수장으로 서 있는 한 가문의 명예가 회복되는 것을 보고야 말겠소.'),
(60926, '내 일은 적을 이해하고 적의 약점을 찾는 것이다.\n\n스톰윈드의 많은 결점에 대해 말할 수도 있지만, 내가 여기 있는 이유는 그것 때문이 아니다.\n\n내가 당신을 위해 할 수 있는 일이 무엇인가 $R?'),
(60927, '스톰윈드는 우리에게 숙소와 대사관을 둘 장소를 제공할 만큼 친절했습니다. 두 왕국이 뜻을 모아 함께 서기까지는 시간이 좀 걸릴 것 같습니다.'),
(60928, '이 항구는 낚시하기에 그다지 나쁘지 않네요!'),
(60929, '선원들의 하층민들과 그들과 해병대 사이의 적대감을 통제하는 것은 어려울 수 있습니다.\n\n나 같은 하사관들이 나서는 이유가 바로 그 때문이죠.'),
(60930, '쿨 티라스 국가에는 충성스러운 백성들과 충성을 맹세하는 자들에게 관대합니다.\n\n우리의 충성심과 헌신은 로데론 왕국과 옛 얼라이언스에 있습니다.\n\n당신의 충성심은 어디에 있습니까?'),
(60931, '스톰윈드는 보랄러스에 있는 사람들이 말하는 것처럼 나쁘지 않아요.'),
(60932, '그렇게 긴 원정을 마친 후 마른 땅에서 다리를 펼 수 있는 순수한 즐거움을 당신은 모를 겁니다.'),
(60933, '육지 사람이여, 무엇을 도와드릴까요?'),
(60934, '저는 제독님을 대신해 남쪽 이웃들과 외교를 하기 위해 파견되었습니다.\n\n이곳의 귀족들이 옛 방식을 고수하고 있는지, 그리고 북쪽에 쓰러진 자매 왕국들에 대해 어떤 존중을 표하는지 보고 싶었습니다.\n\n쿨 티라스와 스톰윈드가 함께 서려면 가혹한 진실들이 솔직하게 펼쳐져 모두가 이해해야 합니다.\n\n검은피들과는 휴전이 없을 것이며, 한때 존재했던 것을 파괴한 자들 곁에 서서 명예를 얻을 수는 없습니다.'),
(60935, '육지 사람과 대화할 기회는 흔치 않네요.'),
(60936, '바다는 가혹하고 비밀로 가득 차 있습니다. 우리가 탐험할 수 있는 것들이 저 밖에 아직 더 많이 있고, 원정대가 지도에 그릴 것들이 더 있습니다.\n\n이 세상의 공개되지 않은 장소들을 우리가 찾아낼 것이라 믿어도 좋습니다.'),
(60937, '스톰윈드에 오랫동안 오지 못했어요. 얼마나 많이 변했는지 보니 좋네요.'),
(60938, '당신은 쿨 티라스의 배인 올드 타이드호 위에 서 있고, 나는 이곳의 수석 관리자요.\n\n배 위에서 문제를 일으키지 마시오, $C.'),
(60939, '교환할 퀘스트 보상을 선택하세요.'),
(60945, '<새끼용이 호기심 어린 눈빛으로 당신을 바라봅니다.>'),
(60946, '음름글?'),
(60949, '우리는 경계를 서고 있다.'),
(60950, '아, 달라란 레드 한 병을 위해서라면 무슨 짓이든 할 텐데...'),
(60951, '이 늪이 싫어.'),
(60955, '사막에는 기회가 풍부하고 동전을 좀 벌 수 있는 기회가 많다네. 나는 희귀하고 독특한 물건들을 찾는 바다 너머의 이익 단체들을 대표하고 있지.\n\n서로 도와줄 수 있을지도 모르지, 그렇지?\n\n아, 그리고 혹시 체다 치즈를 찾고 있다면 내가 아주 많이 가지고 있다네, 내 편지를 너무 진지하게 받아들였더라고.'),
(60956, '어서 오세요, 스팀휘들 미술관에 오신 것을 환영합니다. 편히 계시고 커뮤니티의 훌륭한 작품들을 즐겨보세요.'),
(60960, '운도 없지, 이 동네에서 가동되던 유일한 분쇄기 두 대가 모두 고장 나버렸지 뭐야!\n\n이제 부품도 거의 없는 상태에서 여기서 수리하느라 갇혀버렸네.'),
(60961, '이곳을 보살피기 위해 스파크워터에서 파견되었습니다. 여기저기 진행 중인 프로젝트가 많고, 저희 기술자들은 모든 부품이 제대로 작동하도록 유지하고 있죠.\n\n어쨌든, 무엇을 도와드릴까요?'),
(60962, '이봐 친구, 이렇게 장엄하고 아름다운 걸 본 적이 있나? 이 녀석은 우리가 이 도화선에 불을 붙이는 곳 어디든 스파크워터 크기의 구덩이를 날려버릴 수 있고, 스스로를 산산조각 내지 않도록 보장하는 게 내 일이라네!\n\n아, 나즈가 이 물건을 사용하는 걸 승인할 날을 기다리고 있어, 아제로스에서 본 최고의 폭발이 될 거야!'),
(60964, '여기가 내가 올 거라고 생각했던 마지막 장소야, 날 믿어. 하지만 고블린들은 돈을 잘 쓰고 난 여기서 할 사업이 있어.'),
(60967, '날 화나게 하기 전에 어서 가라 이봐.'),
(60968, '마을을 즐기고 있길 바라, 투자개발회사 녀석들보다는 듀로타 노동조합과 일하는 게 훨씬 낫지.'),
(60969, '파우더 타운에 오신 것을 환영합니다, 여기서 찾고 있는 것을 찾으시거나 그냥 도우러 오셨기를 바랍니다, 편하게 계세요.'),
(60970, '아 안녕, 고쳐야 할 문제들이 있는데 당신은 문제를 해결할 수 있는 사람처럼 보이는군요.\n\n어쩌면 우리가 서로 도와줄 수 있는 게 있지 않을까요 그쵸?'),
(60972, '당신 우리 도와-도와줄 거지 응? 보그파우는 당신이 우리의 많은 문제-문제를 도와줄 거라 본다!'),
(60973, '문제 일으-일으키지 마라 안 그러면 벤다!\n\n나 잘 벤다, 제일 잘 벤다!'),
(60976, '거기 당신, 그래 그래, 나는 습지대라고 불리는 늪에서 왔다, 들어봤지 그래 그래?\n\n위대한 리더 가울팽이 여기 머물렀었다, 도움 도움을 찾아서, 하지만 지금은 이끼가죽의 리더가 되기 위해 싸우고 있다!\n\n나는 사람들을 그에게 안내하기 위해 여기 있다.'),
(60990, '모험은 언제나 존재하지, 특히 저 먼 변방에서는 말이야.'),
(60991, '어서 오세요! 편히 계세요. 휴식이 필요하다면 에일과 숙소가 풍족하게 준비되어 있습니다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(60993, '아이언포지를 섬기던 시절부터 화이트피크를 알고 지냈지.\n\n특히 고향에서 멀리 떨어진 이곳에서 그가 내 경험과 전문 지식을 활용할 수 있을 거라 확신하네.'),
(60994, '우리는 적대적인 영토 깊숙이 있고 사실상 적들에게 둘러싸여 있습니다. 정신을 똑바로 차리고 싸울 준비를 하는 것이 가장 좋습니다.\n\n이곳 바엘 하르둘에서 우리를 도와주고 싶으신가요?'),
(60996, '칼림도어에는 동부 왕국에서 자주 보지 못하는 풍부하고 희귀한 광물이 가득할 것이라 확신합니다. 원하는 것을 찾기만 하면 됩니다, 그게 전부예요.'),
(60997, '바엘 하르둘에 오신 것을 환영합니다, 이곳은 3차 대전 시절부터 남아있는 곳입니다.\n\n우리 드워프들은 그 시절 얼라이언스를 돕기 위해 연합과 하이잘 산 전투 때까지 오크 및 악마와 맞서 싸웠습니다.\n\n이곳은 버려져 있었지만, 최근에서야 미래의 원정을 위한 고향으로 삼기 위해 도착했습니다.\n\n도움을 제공할 의향이 있으시다면 언제든 도움을 받을 수 있습니다.'),
(60998, '저는 돌발톱 봉우리에서 온 사절이며, 화이트피크와 그의 동족이 자연의 질서를 어지럽히지 않고 이 땅을 횡단할 수 있도록 돕는 가이드 같은 역할을 하고 있습니다.'),
(60999, '이렇게 먼 서쪽까지 와본 적이 없어요! 정밀 조사에서 벗어났으니 오랫동안 미뤄왔던 실험을 시도해 보고 싶어서 안달이 났습니다.'),
(61000, '엔지니어의 삶이란, 발명을 하고 있을 줄 알았는데 고장 난 장치와 기계를 고치는 데 전념하는 정비사가 되었군요.\n\n뭐 어쨌든, 적어도 공구를 만지고 있으니까요.'),
(61001, '저 농장을 비료로 가꾸는 데 얼마나 걸렸는지 아시오?!\n\n<드워프가 눈에 띄게 화가 난 모습입니다.>\n\n독수리 몇 마리가 와서 모든 걸 망치려고 그 모든 준비를 했다니.'),
(61004, '탐험가 연맹은 항상 도움을 찾고 있습니다, 우리의 동기와 목표를 수행하기에 인력이 모자랄 때가 많거든요.'),
(61006, '하늘이 내 이름을 부르고 있는데 응답할 수가 없군요!\n\n지독한 비행 기계가 고장 나는 바람에 다른 평민들처럼 지상에 갇혀버렸습니다.\n\n자이로크랭크 피즈워블 엔진에 대해 좀 아시나요?'),
(61008, '아 안녕. 무엇을 도와드릴까요?'),
(61009, '내가 너라면 레드브랜드 건드리지 않을 거야.'),
(61010, '우리의 역사는 훌륭하고 뛰어남과 명예로 가득 차 있소. 한때 브론즈비어드의 오른팔 역할을 했지만, 지난 몇 세대 동안 유감스러운 사건들이 많았지.\n\n잃어버린 수많은 기록들을 수집하는 데 도움을 구하고 있었소. 도와줄 수 있겠소?'),
(61011, '나는 레드브랜드의 영웅으로 선택받아 그들의 동족을 지키고 대리해 싸우고 있소.\n\n그들과 등지지 않는 것을 추천하오, $C.'),
(61012, '내 군주님의 이익을 지키겠다고 장엄하게 맹세했소.'),
(61013, '남쪽도 그렇게 나쁘진 않군요. 좋은 에일과 긴 여정으로 지친 바다 다리를 풀 수 있는 기회가 있으니까요.\n\n육지 사람이여, 무엇을 도와드릴까요?'),
(61014, '<선원 케이프윈드가 호기심 어린 눈빛으로 당신을 살핍니다.>\n\n필요한 게 있으신가요, 아니면 그냥 휘장에 호기심이 생긴 건가요?\n\n섬사람을 본 적이 없으신가요?'),
(61015, '모아둔 돈이 이만큼이나 되는데, 지금 당장 쓰는 것보다 더 좋은 때가 어디 있겠어, 안 그래?"\n\n<선원 브루엔이 웃습니다.>'),
(61016, '문제가 생기기 전에 물러서는 게 좋을 거야, 알아들었어?'),
(61017, '쿨 티라스의 야망과 욕망은 복잡한 문제입니다. 여기서 우리의 목표는 이 남부인들의 진정한 가치를 판단하고 육지 사람들을 믿을 수 있는지 확인하는 것입니다.\n\n스톰윈드의 귀족들이 옛 방식과 옛 명분에 충성함을 증명한다면 협력의 미래가 있을 지도 모릅니다.\n\n스톰윈드의 마음이 올바른 곳에 있는지 지켜봅시다.'),
(61019, '현실을 오락가락하고 있어서 오래 머물지 못할까 봐 두렵습니다, 영영 떠나기 전에 저를 도와주셔야 합니다.'),
(61024, '게으름뱅이들! 죄다 게으름뱅이야! 내가 일하던 시절엔 그런 막강한 화력과 함께 일하는 게 특권이었지. 요새 젊은것들은-\n\n<나즈가 당신에게 시선을 돌립니다.>\n\n어이 꼬맹이. 파우더 타운에 온 걸 환영한다! 쉬러 왔냐? 그럼 전율을 즐겨라! 너트가 제공한 이 멍청한 "엔지니어들" 때문에 언제 터질지 모른다고!\n\n어쨌든 돈을 위해 손에 흙을 묻히는 걸 좋아한다면 할 일거리가 좀 있다. 그렇지 않다면 파우더 타운엔 왜 왔겠냐?!\n\n아, 쓸모 있게 되는 것에 대해선 걱정 말고 그냥 방문이나 해라. 첫 번째 손님도 아니니까.\n\n이제 꺼져라!'),
(61026, '물이 해안선에 부딪히고 전투가 다가오고 있으니, 공기 중에서 느껴지지 않느냐 어린 자여?\n\n우리의 적은 감히 힘을 다잡고 호드의 위엄에 정면으로 도전하려 한다.\n\n전쟁이 우리를 부르고 있고, 도끼를 들고 고향을 지키는 것은 호드의 모든 구성원의 의무이다, 도끼를 들고 고향을 지키겠느냐?'),
(61040, '<켄타우로스 여성이 팔짱을 끼고 꼬리를 휙휙 저으며 위협적으로 노려봅니다.>\n\n나한테 말을 거는 넌 누구냐? 와루그가 보낸 거냐?'),
(61041, '<덱샤르가 사나운 눈빛으로 노려봅니다.>'),
(61044, '<늙은 켄타우로스가 당신에게 말을 건네기 위해 고개를 듭니다.>\n\n너는 우리 부족이 아닌데 우리 사이를 거니는구나. 무슨 일로 왔느냐?'),
(61045, '우리는 항상 전쟁의 위협에 시달리고 있으니, 이전의 많은 부족처럼 짓밟히지 않으려면 충돌에 대비해 자신을 단련해야 합니다.'),
(61050, '<다론이 당신의 존재에 약간 혼란스러워 보입니다.>\n\n외지인이 오는 건 흔치 않은 일인데, 정말 몇 년 만이군요.\n\n어쨌든 환영합니다, 필요한 게 있으신가요?'),
(61051, '무엇을 도와드릴까요 $R?'),
(61052, '조심해라 친구.\n\n원하는 게 뭐야?'),
(61053, '너는 눈을 뜨고 걷고 있구나, $r, 하지만 진정으로 보고 있느냐? 최근에 주변 세계를 감상해 본 적이 있느냐?\n\n바람에 날리는 나뭇잎들, 바다의 격렬한 파도, 도시의 바쁜 걸음걸이. 전쟁 중이라 할지라도 당신 주변에는 위엄이 있고, 언제나 감상할 것들이 존재한다.\n\n자... 술 한 잔 어떠냐?'),
(61057, '글쎄요, 확실히 항로를 벗어났네요, 잘못 돌아서 여기로 오게 되었어요.'),
(61060, '기진은 방향 감각이 별로 없어서...'),
(61063, '자연의 유익함 안에서는 언제나 치러야 할 전투가 존재하며, 그 전투를 위해 싸우는 것은 우리 모두에게 달려 있습니다.'),
(61064, '반갑습니다, 키린 토는 비전에 대한 지식을 넓히고자 하는 모든 이를 환영합니다.\n\n무엇을 도와드릴까요?'),
(61065, '언제나 할 일이 있습니다, 달라란이 완전히 복원될 날을 고대합니다.'),
(61070, '안녕 귀여운 친구, 힘든 하루를 보낸 것 같아 보이는데 민트 사탕 하나 어때요? 입냄새가 나니까요!\n\n어서요, 잠시 머물면서 도로테아에게 전부 말해보세요.'),
(61100, '흠, 뿌리와 섞을 잔여물이 조금만 더 있으면 잠재적으로... 어쩌면 나무 자체의 성장을 바꾸는 것도-\n\n좀 바쁜 거 안 보이시나요, 엄청난 돌파구 직전에 와있단 말입니다 안 보여요?\n\n거대한 바나나의 비밀이 내 손끝에 있으니, 도우러 온 게 아니라면 어서 지나가세요.'),
(61101, '정말 멀리 오셨군요, 파견되어 오셨다면 죄송하고 스스로 오셨다면 환영합니다!\n\n제 이름은 빅슬이고, 한동안 이 창고를 관리해 오고 있습니다. 얼마 전까지만 해도 바나나 수집의 주요 장소 중 하나였는데, 지금은 완전히 망가졌습니다.\n\n유인원, 원숭이, 뱀들이 온갖 문제를 일으키고 있지만, 제가 말해줄 필요는 없겠죠, 이미 보셨을 테니까요!\n\n이 주변의 일들을 좀 도와주실 수 있다면 정말 큰 도움이 될 것입니다.'),
(61102, '당신이 그 모험가들 중 한 명인가요? 그렇다면 내가 딱 찾던 사람입니다. 문제가 너무 많아서 모든 게 무너졌습니다. 바나나보다 죽은 직원이 더 많다고요, 이해가 돼요?!\n\n<텔라즈 남작이 잠시 목을 가다듬습니다.>\n\n미안합니다, 고블린은 많은 자본과 골드의 손실에 대해 काफी 화가 날 수 있거든요. 시간은 돈이지만, 텔아빔에서 시간은 돈을 잃는 것입니다.\n\n이러한 재앙은 여기 있는 모든 투자금이 무로 돌아가기 전에 되돌려져야 합니다. 말해두지만, 고블린은 그의 골드만큼 가치가 있고, 나는 주머니에 바나나 몇 개만 차고 케잔으로 돌아가지 않을 것입니다.'),
(61105, '이 주변에서 문제를 일으키지 마세요, 최근에 원숭이들이 사방에서 날뛰는 것만으로도 충분히 머리가 아프니까요.'),
(61106, '베이스캠프에서 정말 멀리 오셨네요 친구, 요즘은 모두가 창고까지 오는 건 아니거든요.\n\n이 거대한 똥더미에 배치된 게 아니길 바랍니다.'),
(61108, '고블린 기계 장치, 정교한 부품과 엉성한 설계. 당연히 대단한 고장으로 이어지고, 그게 나 같은 엔지니어들이 계속 장사할 수 있게 해주는 것이죠.\n\n자, 뭘 원하시나요?\n\n분쇄기 수리하러 온 건 아니겠죠.'),
(61109, '태양이 정말 덥죠, 그렇죠? 저는 이 주변의 물과 음료를 담당하고 있으니 얌전히 행동하시는 게 좋을 겁니다. 알아들었나요?\n\n안 그러면 바다에서 물을 마셔야 할 테니까요!'),
(61110, '텔 무역 회사 베이스캠프 여관에 오신 것을 환영합니다, 저희는 원숭이가 없고 매우 저렴합니다. 부디 편히 계세요.\n\n그리고 떠돌아다니는 소문을 일축하고 싶네요. 이 업소에는 원숭이 공격이 없었습니다. 전혀 없었습니다. 원숭이 무리가 한밤중에 침입해서 난동을 부리고 무고한 손님들을 공격하는 일 따위는 없었습니다.\n\n만약 그런 일이 일어난다면 무료 숙박권을 제공합니다.'),
(61111, '노크롯은 자기가 특별하다고 생각하지만, 그가 흔들어대는 물을 제공하는 건 바로 나라고.'),
(61112, '이봐 친구 들어요, 때로는 틀 밖에서 생각할 필요가 있어. 나는 톱니항에서 지루한 타조 고기를 만지며 수많은 날을 보냈고, 케잔에서 큰 이름으로 대박을 치고 싶다면 혁신이 필요해.\n\n고블린의 가장 좋은 특성은 교활함과 생각하는 것이지, 알겠어? 큰 뇌에는 큰 아이디어가 필요하고 텔아빔보다 틀 밖에서 생각하기 더 좋은 곳이 어디 있겠어? 바나나가 비밀이야 꼬맹이, 말해주는데, 딱 적절한 양념과 적절한 재료만 있으면 대박을 칠 거야.'),
(61113, '이 유인원들은 규율 교육이 필요해, 이제 우리가 강하게 맞받아칠 때가 되었어. 몽땅 때려부수는 것만이 전부는 아니야, 때로는 전략이 필요하고, 전략이 안 통할 땐 오곤이 확실히 도움이 되지.'),
(61116, '원하는 게 뭐야? 내가 너라면 상관없는 일에 코를 들이밀지 않을 텐데.'),
(61117, '이봐 $r, 발밑에 무엇이 숨겨져 있는지 궁금했던 적 없어? 잃어버린 문화로부터 우리가 어떤 포상금을 차지할 수 있을지? 어쩌면 함께 알아낼 수 있을지도 모르지.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(61121, '아이스포 마을에 오신 것을 환영합니다. 다른 이들이 이 땅에서 당신을 친절하게 대해줄 것입니다.\n\n함께 겨울맞이 축제를 즐기고 외국의 음식을 나누어 먹는 건 어떨까요, 네?'),
(61122, '눈은 신선하고 공기는 시원합니다. 우리 아이스포 부족에게는 축제를 시작하고 또 다른 한 해의 끝을 축하할 시간이 시작됩니다.'),
(61125, '다른 이들이 내 선물을 마음에 들어했으면 좋겠어요!'),
(61126, '너 원숭이랑 친구냐, 너 에부랑 친구냐? 에부는 친구 좋아한다, 너 도와줄 거냐, 응?'),
(61136, '난 그렇게 무섭지 않아요. 안녕이라고 말하는 걸 두려워하지 마세요. 다른 예티들이 우리 평판을 나쁘게 만들고 있어요.'),
(61137, '솔직히 손님이 올 줄은 몰랐군요. 사실 그런 이유로 여기서 살기로 결정했습니다, 요즘은 혼자 있는 걸 즐기거든요, 많은 것을 보았으니까요. 산속에 숨겨진 제 외로운 영지에 누군가 방문해 준 지 꽤 되었는데, 무슨 일로 오셨나요?\n\n동전을 요구하러 오셨다면 미리 사과드립니다, 가진 게 없거든요.'),
(61142, '숲의 노래에서 긴장감이 커지고 있으니, 감당할 수 없을 정도로 악화되는 건 시간문제인 것 같습니다.'),
(61143, '아 안녕 외지인, 숲의 노래에 오신 것을 환영합니다.\n\n이곳은 한때 우리 과거의 평화로운 글레이드였지만, 지금은 그저 폐허일 뿐입니다. 우리는 이곳 구역을 유지하고, 우리 신성한 숲 안에서 전쟁가어 부족이 입지를 더 넓히지 못하도록 막는 역할을 하고 있습니다. 그들은 집요함과 활력이 넘치며, 특히 녹색 피부 놈들은 소탕되어야 합니다.\n\n우리에겐 안팎으로 많은 문제가 있으니 우리를 도와주실 수 있을지도 모릅니다.'),
(61145, '이 신성한 숲은 뿌리를 갉아먹는 외부 세력으로부터의 휴식을 갈망하고 있습니다.'),
(61146, '칼도레이가 저에게 안식처를 제공해 주었습니다, 오랫동안 여기서 살았고 자연의 다른 부분으로부터 받는 추가적인 보호는 따뜻한 환영입니다.'),
(61147, '외지인이군요, 아 안녕.\n\n이 글레이드는 3차 대전 이전 많은 드루이드들에게 숭배받던 곳으로, 이곳에서 자연 및 숲 자체의 정령들과 교감했습니다. 최근 오크들이 이 안식처를 어지럽혔고, 이 장소를 복원하는 짐이 이제 우리 어깨에 지워졌습니다.\n\n파수꾼들이 돌아다니는 것을 보셨을 텐데, 그들 역시 최근 숲의 노래의 두통거리를 더해주고 있습니다.'),
(61149, '당신은 숲의 위대한 영웅 앞에 서 있습니다 친구여, 당신이 걷는 이 땅을 불경하게 대하지 마세요. 우리 앞에 있는 나무정령 에스위어는 악령의 숲의 대의를 위해 자신을 희생했습니다. 주변의 녹음과 생명을 보실 수 있을 겁니다, 이 저주받은 땅에서 특히나 기적 같은 일이죠.\n\n어쩌면 그의 비밀에 대해 더 많이 배우고 숲 자체의 정화를 밝혀낼 수 있을지도 모릅니다, 그게 제가 여기 있는 이유입니다.'),
(61150, '이 땅이 항상 이러지는 않았습니다, 숲 주변에는 많은 자치구와 마을들이 있었죠.\n\n이곳이 어떻게 되었는지 보는 것은 안타까운 일입니다, 얼마 전 악마 침공의 오염이 이 땅에 흉터를 남겼으니, 우리는 이에 맞서 최선을 다해야 합니다.'),
(61151, '야생은 매혹적이지 않나요? 자연은 언제나 신비로운 수호자였으며, 우리가 밝혀내고 보호해야 할 많은 비밀을 가지고 있습니다.\n\n제 이름은 칼라란입니다, 이곳에서 찾으시는 게 무엇인가요 친구여?'),
(61157, '니부가 호기심 어린 눈빛으로 당신을 바라봅니다.'),
(61158, '원장님이 겨울 할아버지 무릎에 앉아서 선물을 물어봐도 된다고 하셨어요! 전 정말 엄마를 되찾고 싶어요.'),
(61159, '큰 메이스를 달라고 할 거예요! 원장님이 로데론에 있던 위대한 성기사였던 왕자에 대한 이야기를 해주셨는데, 그 사람처럼 되고 싶어요!'),
(61160, '겨울 할아버지에게 토템을 달라고 할 거예요. 우리 대족장님처럼 주술사가 되고 싶거든요. 호드를 위하여!'),
(61161, '록타르! 호드 최고의 전사 조키가 당신을 환영합니다!'),
(61168, '정령이 당신의 영혼을 오랫동안 깊이 바라봅니다, 차갑고 흔들림 없이.'),
(61169, '거대한 고대정령이 당신을 바라보며 삐걱거립니다. 나무 덩어리 안에 자상한 영혼이 들어앉아 있음을 느낍니다. 임무가 있는 듯 계속 움직이라고 재촉합니다.'),
(61170, '<곰 아버지가 잠시 당신을 돌아본 후 입을 열어 말합니다.>\n\n어린 자여, 지금은 비참한 시기이지만 어둠 속에도 언제나 희망이 있음을 기억하라. 내가 많은 곰들에게 구원을 가져다주었지만 여전히 너무나 많은 곰들이 타락에 굴복했다. 이 땅에서 조심하거라.'),
(61171, '겨울 할아버지가 고마운 눈빛으로 당신을 바라보지만, 마음은 분명 다른 것에 집중되어 있습니다. 친절한 아버지 같은 눈빛으로 계속 지나가라고 재촉합니다.'),
(61172, '<거대한 코도가 잠시 당신을 바라본 후 친절한 아버지 같은 톤으로 말합니다.>\n\n겨울이 오고 있단다 어린 자여, 따뜻한 곳을 찾는 게 좋을 거다. 나는 세대 동안 부족들을 인도해 왔고 앞으로도 계속해야 한다. 이제 떠나야겠구나, 어둠 속에서 구원을 찾길 바라며, 대지의 어머니께서 더 푸른 초원으로 이끄시기를.'),
(61173, '록타르! 어린 $G꼬마야:꼬마야;, 즐거운 겨울맞이 축제 보내거라!\n\n굴뚝나무 목술샘에서 제공하는 공짜 음식과 많은 즐거움이 마련되어 있다!\n\n즐거운 시간 보내도록 해라... 아 그리고 내 무릎에는 앉을 수 없단다.'),
(61174, '놀라지 마라 친구. 모든 서리갈기 부족이 정복의 길에 있는 건 아니다, 우리는 축하하러 왔다.\n\n우리 중 일부는 평화를 원한다. 우리 부족은 많은 고통을 겪었으니, 그저 위대한 겨울 정령의 풍요를 축하하러 왔을 뿐이다.'),
(61175, '놀라지 마라 친구. 모든 서리갈기 부족이 정복의 길에 있는 건 아니다, 우리는 축하하러 왔다.\n\n우리 중 일부는 평화를 원한다. 우리 부족은 많은 고통을 겪었으니, 그저 위대한 겨울 정령의 풍요를 축하하러 왔을 뿐이다.'),
(61177, '반갑다 친구, 위대한 겨울 정령에 대해 듣고 싶나? 그분이 계절을 안내하고, 우리 계절의 시간을 가져오는 분이다. 사냥의 시간, 수집의 시간.\n\n계절이 오면 우리는 축제를 연다. 희생 의식, 춤, 의식, 그리고 성대한 잔치. 우리는 생존과 계절의 변화, 그리고 이 세상에서의 또 다른 한 해의 끝을 축하한다 친구여.'),
(61178, '겨울 할아버지에 대해 알고 싶으신가요? 아 사과드립니다, 아마 이야기꾼 틸레키나와 이야기해 보셔야 할 겁니다. 이 전설들은 내 동족이 지난 일들이고, 이 전통에 얽힌 조상들의信仰에 대해 내가 아는 얼마 되지 않는 지식은 그녀에게서 나온 것입니다. 저는 그저 즐겁게 놀고 이야기를 나누러 왔을 뿐입니다.'),
(61179, '"겨울맞이"라는 용어는 겨울 할아버지로 알려진 조상 인물에서 유래했다고 합니다. 늦은 계절에 그가 이 땅을 거닐 때 겨울 자체가 그의 나부끼는 망토가 되었죠. 그의 자취에는 온 땅을 눈으로 덮었기에, 겨울 할아버지가 이 땅에 겨울의 베일을 던졌다고 전해집니다.\n\n겨울 할아버지가 이 땅을 거닐 때, 그의 존재를 환영하는 자들에게 풍요를 가져다주었다고 합니다. 아제로스의 일부는 눈에 덮여 있을지라도 이 땅에 재탄생과 쇄신의 시간을 제공합니다. 따라서 겨울맞이 동안 잔치를 벌이는 생각은 공동체가 각자 가진 것을 나누며 함께 모이도록 만들었습니다. 일반적으로 하루 동안의 즐거움과 잔치가 변화를 환영하며 이 땅의 쇄신을 고대했습니다.'),
(61180, '겨울 할아버지 전설에 대한 우리식 해석을 알고 싶나, 어?\n\n뭐 별로 할 말은 없다, 우리는 그가 선물을 전달하는 친절한 늙은 신사라고 믿는다. 다른 종족들처럼 문화적 전설이었던 적은 없지만 흥겨움을 함께 나눈다. 게다가 군대에 있을 때 들은 좋은 이야기들도 있고.'),
(61181, '음 겨울 할아버지에 대해 알고 싶나? 글쎄, 우리 문화에는... 아무것도 없다. 알다시피 우리 오크들은 다른 세계에서 왔기에 이에 상응하는 고유한 이야기가 없다.\n\n우리가 아는 건 아이들을 즐겁게 해주는 겨울 할아버지뿐이다. 그렉로르가 그 역할을 잘 맡아주었다. 아 하지만 그 사람 앞에서 그의 이름을 쓰지 마라, 모든 아이들이 그가 겨울 할아버지라고 믿고 있고 그래야 마땅하니까. 대신 드레노어에서 가져온 교환할 만한 좋은 이야기들은 몇 개 있다.'),
(61182, '아, 겨울의 고대정령에 대해 듣고 싶으신가요? 저는 여윈눈에 위치한 별빛마을 출신입니다. 지독하게 춥고 다른 이들과 고립되어 있죠. 이토록 추운 곳에서도 이 땅의 정령들과 교감해야 하는 잠자는 드루이드들을 보살피는 것이 우리의 의무입니다. 겨울 동안 이 땅은 우리조차 견디기 힘들 정도로 춥고 가혹해집니다.\n\n그때 위대한 고대정령이 찾아옵니다. 고대정령은 드루이드들의 꿈속에서 이야기하며 우리가 살아남는 데 필요한 것을 찾도록 도와줍니다. 그 대가로 우리는 축제와 잔치로 고대정령을 기립니다. 고대정령 덕분에 드루이드들이 안전하게 보호받고, 추운 겨울 달이 지난 후 위대한 쇄신의 시간이 찾아옵니다.'),
(61183, '얼음 로아에 대해 알고 싶나? 그래, 트롤들이 참여하는 이유가 뭔지? 그럼 서리갈기 부족에게 물어봐라. 우리는 따뜻한 땅에서 와서 서로 다른 로아를 섬기고 각 부족마다 고유한 전통이 있다.\n\n우리는 모든 로아를 존중하므로, 나도 경의를 표하고 잔치와 이야기를 즐기러 여기 왔다.'),
(61184, '우리 가장 오래된 이야기 중 하나는 대지의 어머니의 첫째 아들인 겨울 족장에 관해 말한다. 나뭇잎이 떨어지고 해가 짧아지면 그가 도착한다. 그는 위대한 사냥감 무리를 이끌고 오지만, 그 대가로 추위와 긴 밤도 가져온다.\n\n우리 부족들은 이 시기를 모닥불 주변에 모여 잔치를 벌이며 조상들의 이야기를 나누며 보낸다. 이 시기에는 사냥감을 잡기 어렵기 때문에 우리는 항상 살아남을 수 있도록 족장에게 축복을 기도한다. 추위와 어둠이 봄에게 자리를 내주면 족장은 떠나고, 이 땅이 우리에게 제공할 수 있게 됨에 따라 다시 잠으로 돌아간다. 오직 그가 다시 필요할 때만 깨어난다.'),
(61185, '당신의 흥미를 끌 만한 이야기는 없습니다. 브랜드에게 물어보세요.'),
(61186, '추워지면 혼자 있고 배가 고픈 건 좀 그렇지, 안 그래? 친구들과 시간을 보내는 건 어때!\n\n겨울 할아버지가 해결책을 가지고 있지. 굴뚝나무 목술샘과의 협력으로, 적은 요금으로 훌륭한 선물과 음식을 가져다줄 거야, 안 그래? 그러니 일 년 중 아주 즐거운 시기지. 눈 속에서 놀고 난 후 이국적인 장난감, 선물, 맛있는 음식으로 서로를 마음껏 즐겁게 해주고 놀라게 해주라고!'),
(61187, '흠... 땅에 추위가 찾아오면 곰 아버지가 도착하여 위대한 잠을 안내한다고 합니다. 식량은 부족해지고 밤은 길어지며 추위가 기승을 부리죠.\n\n곰 아버지의 도착은 성대한 잔치로 절정에 달하며, 그 후 우리 중 많은 이들이 깊은 잠에 빠져들고, 곰 아버지가 떠난다고 전해지는 겨울이 끝날 때에야 깨어납니다. 숲과 땅은 생명으로 만발하고 식량은 풍부해지며 새로운 쇄신이 찾아옵니다. 그리하여 우리는 잠들기 전에 이 계절을 축하하고 잔치를 벌입니다.'),
(61188, '겨울 할아버지에 대해 알고 싶나? 헤, 우리 이야기도 드워프들의 이야기와 비슷하지만 그분은 미사일로 무장한 거대한 자이로콥터가 이끄는 썰매를 타고 다닌다네! 자세한 내용은 헤닝에게 물어보는 게 좋겠지만 기억하게! 진짜 겨울 할아버지는 미사일이 달린 자이로콥터가 이끄는 썰매를 탄다네!.'),
(61189, '안녕 $r! 나는 이 축제들을 둘러싼 전설을 연구하도록 임무를 받은 학자라네. 서로 다른 수많은 문화들이 유사한 인물을 가지고 있다는 게 기묘하지 않은가?'),
(61190, '남해 너머에서 온 물건들을 찾고 계신가요?'),
(61191, '하지만 국왕님, 그들은 죄수들입니다.'),
(61192, '인류가 위기에 처했습니다! 어둠의 물결이 다시 찾아왔고 전 세계가 전쟁의 벼랑 끝에 서 있습니다.'),
(61193, '내 말을 들으시오! 당신들 백성의 유일한 희망은 서쪽, 잊혀진 칼림도어의 땅으로 여행하는 것뿐이오!'),
(61194, '이 땅의 죽은 자들이 당분간 가만히 있을지 몰라도 속지 마시오. 당신의 젊은 왕자는 추운 북쪽에서 죽음만을 찾게 될 것이오.'),
(61195, '칭찬할 만하지만 그 열정이 그의 파멸이 될 것이오. 어린 여마법사여, 이제 당신에게 달렸소.'),
(61196, '당신은 백성들을 이끌고 서쪽, 고대의 칼림도어 땅으로 가야 하오. 오직 거기서만 그림자에 맞서 싸우고 화염으로부터 이 세상을 구할 수 있소.'),
(61197, '어린 대족장이여, 당신과 당신 백성에 대해 많은 것을 알고 있소. 지금 내 정체는 중요하지 않소. 중요한 것은 당신이 백성들을 모아 즉시 이 해안을 떠나는 것이오.'),
(61198, '인간이라고? 난 오랫동안 내 인간성을 버렸다. 난 이제 다른 무언가다.'),
(61199, '미래를 보았고 이 세상을 삼키러 오는 불타는 거대한 그림자를 목격했음을 알아라. 당신도 느끼고 있지 않은가?')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(61200, '내가 군단이 돌아온 이유다.'),
(61201, '수년 전, 내가 오크들을 이 세상으로 데려왔고 그로 인해 악마들의 길을 열어주었다. 내 죄로 인해 내가 가장 아끼던 이들에게 살해당했지.'),
(61202, '내 죽음에도 불구하고, 긴 세월 동안 동쪽 땅 전역에 전쟁이 몰아쳤고 그 자리에 왕국 전체가 황폐해졌다.'),
(61203, '이제 마침내 내가 상황을 바로잡으러 돌아왔다. 나는 마지막 수호자, 메디브다.'),
(61214, '이슈누 알라, 몽상가여, 은폐된 우리의 자치구에 오신 것을 환영합니다. 에메랄드의 악몽 속으로 들어가는 긴 여정에 약간의 안식처가 되기를 바랍니다.'),
(61216, '에메랄드의 꿈이 우리 손에 닿을 곳에 있습니다, 몽상가여.'),
(61217, '네에?'),
(61254, '아 안녕, 오페라 홀에서 손님을 받는 건 자주 없는 일인데말이죠.\n\n음악이라도 듣고 싶으신가요? 사람이 없어서 이 장소에서 내 실력을 시험해 본 지 오래되었거든요. 장담하건대 훌륭할 겁니다, 난 유명한 음악가니까요.'),
(61255, '아 안녕, 축제에 오신 것을 환영합니다. 다른 손님들이 제대로 된 예의로 대해주지 않은 점 사과드립니다. 요즘 들어 다들 bastante... 탐욕스러워진 것 같네요.\n\n저는 다크샤이어의 에본로크 주공입니다. 제 의지로 여기 여행을 왔고 그 이후로 돌아가지 못했죠. 탑 안에서의 내 현재 상태를 아주 잘 알고 있습니다, 죽은 지 꽤 되었으니까요. 슬프게도 여기 감도는 대부분의 다른 이들은 그렇게 예리하지 못합니다. 매우 운 좋은 무언가가 이 영원한 갇힘에서 나를 풀어줄 때까지 이 홀을 떠돌도록 저주받은 것 같군요.\n\n어쩌면 우리가 서로 도울 수 있을지도 모릅니다. 여기 묶여 있는 동안 몇 가지를 배우게 되었고 나와 비슷한 상황에 처한 다른 이들을 만나게 되었으니까요.'),
(61256, '<환영이 생각에 잠겨, 시간 속에 머물러 있는 것처럼 보입니다.>'),
(61257, '길네아스의 왕좌에 앉는 자는 항상 그레이메인이 될 것이다. 다시 한번 그렇게 되는 것이 내 군주님의 뜻이다.\n\n인정하건대 외지인들을 신뢰하지 않지만, 그런 태도가 우리가 살고 있는 이 시대로 우리를 몰아넣었다는 것을 깨달았다.'),
(61258, '내 등대에 오신 것을 환영합니다.\n\n경고하건대, 손님을 맞이하기에 가장 좋은 숙소를 갖추지 못했을 수도 있습니다. 나는 단순히 배들이 여울에 부딪히지 않도록 불을 태우고 있을 뿐이거든요.\n\n어쨌든 무슨 일로 오셨나요?'),
(61259, '길네아스는 더 어두운 날들을 보았습니다. 하지만 당신과 같은 새로운 동맹들과 함께 희망은 남아있습니다. 얼라이언스가 우리를 버렸을까 봐 두려웠지만 우리는 여기 서 있습니다. 이 알터랙 쓰레기들에게 무릎 꿇지 않을 것입니다.\n\n우리는 승리할 것입니다.'),
(61260, '키린 토는 아루갈을 싸구려 눈속임으로 마법사 행세를 하는 사기꾼이라 불렀지. 그들이 그의 천재성과 나의 천재성을 알아보기만 했더라면.$B$B소위 늑대인간의 저주라는 것은 축복이다. 아루갈의 연구를 이용하면 우리는 불멸을 얻을 수 있어. 다시는 질병이나 쇠약을 두려워하지 않아도 되고, 인간의 이해를 뛰어넘는 힘을 손에 넣게 되지.$B$B아직 인간과 드워프 이외의 종족에게 이 저주를 시험해 보지는 않았다. 하지만 우리도 원치 않는 자에게 억지로 강요할 만큼 타락하지는 않았어.'),
(61265, '길니아스 여단이 마침내 고향으로 돌아왔다. 우리는 그레이메인의 이름으로 이 땅을 되찾기 위해 왔다.'),
(61269, '아, 안녕하시오. 레이븐샤이어에 온 것을 환영하오!$B$B유서 깊은 이 마을은 길니아스에서 가장 오래된 곳 중 하나로, 오랫동안 레이븐우드 성채의 영주들에게 충성을 바쳐 왔소.$B$B성에 암운이 드리운 뒤 레이븐우드 경께서는 이곳으로 궁정을 옮기셨지. 그러니 바로 우리 눈앞에서 역사가 새로 쓰이고 있는 셈이오!$B$B우리의 흥미로운 과거를 더 알고 싶다면 말만 하시오. 역사 기록과 학술 논문에서부터 손에 땀을 쥐게 하는 민담과 우화까지, 제법 훌륭한 장서를 갖추고 있으니.'),
(61270, '솔직히 말해, 길니아스 시에 있지 않다는 게 아직도 이상하군. 특히 이렇게 혼란스러운 때에는 말이야. 한때는 국왕의 평의회에 몸담았는데, 이제는 하필 레이븐샤이어에서 이런 신세라니.$B$B<치안판사가 한숨을 내쉰다.>$B$B이 분쟁이 끝나고 땅이 다시 아물기 시작한다면, 결국 이 모든 일에도 의미가 있었겠지.'),
(61271, '그레이메인께서 키린 토를 그토록 못마땅해하셨으니, 내가 길니아스에 와서 백성을 돕게 될 줄은 상상도 못 했소.$B$B기이한 사건으로 가득한 기이한 시대요. 나는 도움을 제공하고 달라란 도시국가의 사절 역할을 하기 위해 이곳에 왔소.$B$B키린 토에 볼일이라도 있소?'),
(61272, '분명 찾고 있던 물건이 있을 거요.'),
(61273, '장담하건대, 길니아스의 장인 솜씨는 알아주는 편이지.'),
(61274, '레이븐샤이어는 오래전부터 물고기에 의지해 왔지. 바다는 언제나 우리를 먹여 살릴 만큼 넉넉하거든.'),
(61275, '뭘 원하는 거냐, 외지인?'),
(61276, '아버지는 내가 어릴 때부터 평생 갑옷을 만들고 수리하는 법을 가르쳐 주셨어요. 뭐라도 배우고 싶다면 아버지께 말씀드려 보세요. 정말 최고시거든요.'),
(61277, '내 아들이 좀 과장하긴 해도 성실한 녀석이오. 뛰어난 대장장이가 되고 싶다면, 성공할 때까지 부지런히 망치질해야 하지.'),
(61278, '나도, 내 아버지도 평생 이 근방의 들짐승을 사냥해 왔소. 정직한 일이지만 때로는 꽤 위험하지.'),
(61279, '우리 아빠는 엄청난 사냥꾼이에요! 커다란 늑대도 잡아서 먹을 걸로 만들 수 있다니까요!'),
(61281, '살아생전 나는 이 교회를 돌보았소. 그러나 이 왕국의 문장을 단 자들에게 냉혹하게 살해당했지. 이제 새로운 목적을 위해 잠에서 깨어난 듯하니, 그 목적을 다하겠소.$B$B여기서는 적의를 찾지 못할 것이오. 나는 길니아스인이지만, 이 교구의 벽 안에서 누구든 안식을 찾을 기회를 주겠소.$B$B쉬어야 한다면 거리낌 없이 말하시오.'),
(61282, '우리는 길니아스의 상황을 감시하라는 명을 받고 왔소. 이곳은... 내가 생각했던 것보다 훨씬 흥미롭군.$B$B어쩌면 앞으로 펼쳐질 역사에서 우리도 좀 더 중요한 역할을 할 수 있겠어.'),
(61283, '길니아스의 땅이 상처 입고 흉터투성이인 건 분명하지만, 티리스팔처럼 속까지 썩어 문드러진 곳은 아니오. 이곳까지 우리의 영향력을 넓히려면 상당한 노력이 필요하겠군.'),
(61284, '뭘 그렇게 쳐다보나? 병사는 처음 보나?'),
(61285, '어둠의 마력이 내 혈관을 흐르며 다시 일어설 힘을 주는군. 내 삶은 기만과 고통, 살인으로 얼룩졌지. 어쩌면 이제 나를 일찍 무덤으로 몰아넣은 자들에게 그 비참함을 돌려줄 수 있겠어.'),
(61286, '믿어지나? 길니아스에 스컬지가 있다니! 어디를 가든 놈들의 오염이 따라붙는 것 같군.$B$B그레이메인 성벽은 오래전에 한 번 뚫린 적이 있소. 내가 조사한 바로는 과거 스컬지 침공의 잔재들이지. 이런 기회를 허비하는 건 어리석은 짓이오. 이 땅에서 아직 배울 것이 많으니, 기회가 있을 때 가능한 모든 것을 밝혀내야 하오.'),
(61287, '사람 뒤에서 그렇게 불쑥 나타나면 안 된다는 것쯤은 알잖아?! 하마터면 나를 두 번째 무덤으로 보낼 뻔했군.$B$B내가 지금 바쁜 게 안 보여? 바쁘고, 손이 묶였고, 정신없고, 딴 데 신경 쓸 겨를 없고, 몰두했고, 푹 빠졌고, 일하는 중이라고!$B$B도대체 몇 가지 표현을 더 써야 알아듣겠나?'),
(61288, '뭐 찾는 거라도 있나? 있으면 빨리 말해.'),
(61289, '성벽 너머가 어떤 곳인지 늘 궁금했지... 막상 가 보니 솔직히 실망이더군. 왕국 하나 보고 나면 다른 왕국도 다 거기서 거긴가 봐.$B$B여기서 일거리라도 찾는 건가, 아니면 풍경 구경이나 하러 왔나?'),
(61290, '빌어먹을 해충들 같으니! 내 농장 문제조차 혼자 해결하지 못해서야 어떻게 다시 일어서겠나? 에본미어 가문은 한때 길니아스의 부유한 집안이었는데, 이제 꼴을 보게. 잡초만 무성하고 썩어 들어가고 있잖아.'),
(61291, '뭐 고칠 게 있나? 이 새 삶에서 내가 쓸모 있는 건 그것뿐인 모양이군.'),
(61293, '그러니까 말이야, 내가 실리더스 사막 한복판에 있었어. 문명에서 수백 마일이나 떨어진 곳이지. 먹을 것도, 마실 물도 없었어. 하지만 나, SQUAD의 성기사 바수테이는 예언을 이루기 위해 계속 나아가야만 했지... 젠장, 이 언덕 진짜 죽여주게 빡세네!'),
(61298, '와타메는 아무 잘못도 하지 않았어!'),
(61303, '아, 어서 오시오, 지친 여행자여! 썬더혼 봉우리에서 그대를 만나니 반갑군. 아제로스에는 악이 꿈틀대고 앞으로 닥칠 시대도 험난하겠지만, 용감한 모험가들의 활약은 병든 대지모신을 돕고 그 고통을 달래 줄 것이오. 바우섀도 대사 또한 얼라이언스의 새 일원들이 이곳에서 자리를 잡을 수 있도록 부단히 애쓰고 있소. 대지모신을 치유하고자 하는 자라면 누구든 환영하오.'),
(61307, '이곳에는 쓰러진 아제로스의 필멸자 영웅들이 잠들어 있다. 그 영혼에 평온이 함께하기를.'),
(61313, '<웅얼거리는 목소리.>'),
(61320, '이 어두운 복도에는 눈에 보이는 것보다 훨씬 많은 것이 숨어 있소. 정신을 바짝 차리시오. 영원히 이곳을 떠도는 신세가 되고 싶지 않다면 말이오.'),
(61321, '살아생전 나는 정의라는 명분 아래 온갖 죄악을 저질렀소. 뇌물을 받고, 국고를 통해 금화를 세탁했으며, 지위를 얻기 위해 수많은 악행을 벌였지.$B$B다시 시작할 수 있다면 그러고 싶소. 하지만 이제는 짧은 생에서 내가 무엇이 될 수 있었는지, 또 얼마나 잘못된 길을 걸었는지를 영원히 되새길 수밖에 없군.'),
(61322, '들리지 않나, 저 끊임없이 울어 대는 바람 소리 말이야? 누가 창문이라도 열어 둔 건가?!$B$B당장 하인을 불러 이 빌어먹을 소음을 멈추게 해!'),
(61323, '떠도는 영혼으로 산다는 것의 가장 큰 비애가 뭔지 아나?$B$B난 훌륭한 음식과 술을 맛볼 수 없다는 점을 꼽겠네. 함께할 벗이 부족한 것도 문제고. 어쩌면 자네가 이곳 분위기를 좀 바꿔 줄 수 있겠군.'),
(61325, '에메랄드의 꿈과 놀드랏실은 서로 이어져 있으며, 이 땅 자체가 그 세계의 마력에 물들어 있소. 꿈의 파편이 바로 그 증거지. 순수한 에메랄드 마력이 응축된 강력한 물질로, 이곳 하이잘에서만 찾을 수 있소.$B$B작은 꿈의 파편을 조율해 빛나는 꿈의 파편으로 만드는 것이 내 임무요. 여행 중에 발견한다면 나를 찾아오시오.'),
(61326, '장막 아래, 꿈속에는 거대한 그림자가 숨어 있소. 이미 우리 종족의 많은 이들이 그 존재로 인해 동요하기 시작했지.$B$B그대는 모르겠지만, 각성이 시작되었소.$B$B우리 동족의 고대 의식이 우리를 꿈에서 끌어내려 하고 있소. 나는 이미 그 유혹을 견뎌냈지만, 모두의 의지가 나만큼 강한 것은 아니오.'),
(61327, '악마들이 날마다 하이잘을 잠식해 오고 있으니, 우리는 언제나 비축 물자를 준비해 두어야 하오. 놈들의 목적이 놀드랏실을 타락시키는 것이라면, 반드시 막아낼 준비가 되어 있어야 하지.$B$B무엇을 도와드릴까, $c?'),
(61355, '놀드랏실 아래에서 안식을 찾으러 온 것이길 바라오. 이 땅의 모든 야생 생물이 우리처럼 운이 좋은 것은 아니니.$B$B제3차 대전쟁 이후 이 땅을 위협해 온 어둠은 아직 사라지지 않았소. 세계수의 아름다움에 눈이 멀어 그 사실을 잊어서는 안 되오.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(61368, '수리나 대장장이 물품이 필요한가? 그렇다면 내가 딱 맞는 사람이지... 물론 돈은 받아야 하고.'),
(61369, '우릴 도와주고 있으니 자네가 물자를 채우는 걸 나도 도와주지. 물론 공짜는 없어. 여긴 자선단체가 아니라고.'),
(61371, '이봐, 다들 먹고는 살아야 하잖아? 그렇지? 뭐, 살아 있는 녀석들 말이지만. 아무튼 배고프면 우리 비축분을 조금 내줄 수 있어. 대신 금화는 꼭 챙겨 왔겠지?'),
(61373, '외지인이라, 그래? 이런 사람은 정말 오랜만이군. 그레이메인 성벽이 닫힌 뒤로는 왕국 밖에서 무슨 일이 벌어지는지 거의 듣지 못했지.$B$B언젠가 시간 나면 바깥 세상 이야기를 한두 가지 들려주게.'),
(61374, '어둠의 여왕께 영광을, $c. 무슨 일이지?'),
(61375, '마침내 어둠의 여왕께서 쓸 만한 지원군을 보내셨군. 내 모습에 그리 놀라지 마시오. 그래, 이 육신은 살아 있지만 나는 호드와 어둠의 여왕께 온전히 충성하고 있소.'),
(61376, '대장이 자네를 쓸 만하다고 했다면 내가 뭐라고 판단하겠나? 난 이 땅이 영 마음에 들지 않아. 그러니 볼일만 끝내고 가능한 한 빨리 여기서 뜨는 편이 좋겠군.'),
(61377, '지난 4년 동안 별꼴을 다 봤지. 전리품만 두둑하다면 누구 밑에서 일하든 상관없어. 그래서, 대장한테 도움이 되러 온 건가 아니면 뭐야?'),
(61378, '이야, 길니아스에서 보내기 참 좋은 날 아닌가? 마을 밖으로 나갈 땐 조심하게, 알겠지?'),
(61379, '이야, 길니아스에서 보내기 참 좋은 날 아닌가? 마을 밖으로 나갈 땐 조심하게, 알겠지?'),
(61381, '셰이드모어 가문에서 정말 아낌없이 지원해 주고 있지만, 솔직히 말해 내 걱정은 조금도 가라앉지 않는군.'),
(61382, '길니아스 요리는 세계에서도 손꼽히는 수준이지. 다만 우리가 쓰는 재료를 모두가 좋아하는 건 아니지만.'),
(61383, '살면서 옳고 그름을 분별하기에 충분한 일을 겪었소. 내 생각에는 국왕께서 이 일을 너무 멀리 끌고 가셨소.$B$B나도 한때 그레이메인의 대의에 몸담았지. 하지만 이제야 내가 들었던 말들이 거짓이었다는 걸 알게 되었소.'),
(61384, '하필 이런 때 바퀴가 빠지다니, 안 그런가? 정말이지 자네를 보니 살 것 같군.'),
(61385, '아, 어서 오시오. 셰이드모어 선술집에 온 걸 환영하오. 요즘은 손님이 뜸하지만 그래도 찾아와 주니 기쁘군.$B$B편하게 쉬시오. 필요한 게 있으면 나를 찾아오고.'),
(61386, '요즘처럼 사람들 마음이 어지러운 때에는 빛의 말씀을 전하기가 쉽지 않소.$B$B그래도 이런 힘든 시절도 머지않아 지나가리라 믿소.'),
(61387, '나는 붉은십자군을 대표해 내 몫을 다하러 이곳에 왔소.$B$B죽음과 사악한 오염의 손아귀에서 로데론을 되찾을 의지가 있다면 내게 말하시오. 어쩌면 그대가 쓸모 있는 일을 맡을 수도 있으니.'),
(61410, '정령이 그대와 함께하기를, 낯선 이여. 무엇을 도와드릴까?'),
(61411, '거리를 두어라, 외지인.'),
(61412, '행실 똑바로 하게.'),
(61413, '지켜보고 있다, 외지인.'),
(61414, '구해 줘서 고맙소. 이 은혜는 잊지 않겠소.'),
(61416, '오, 안녕하신가! 곤경에 처한 드워프 하나 좀 도와주는 게 어떻겠나?'),
(61428, '여긴 할 일이 산더미야. 이러다 머리가 터져 버리겠다고!'),
(61429, '놈리건의 고향을 되찾으려면 아직 해야 할 일이 산더미처럼 남아 있어요. 그래도 탈환 작전에 힘을 보탤 수 있다는 건 영광이죠!'),
(61430, '오, 안녕하세요! 노움 공학의 경이로움을 보러 오셨나요? 아니면 최신이자 최고의 기술 발전을 직접 목격하러 오신 건가요?'),
(61433, '뭐라고요? 여기 지원하러 보낸 새 화학자입니까?$B$B열에너지와 독성 화학물질 저감에 대해 아는 게 없다면 그냥 지나가 주시죠.'),
(61434, '수소를 조금만 더 넣으면 훨씬 안정적인...$B$B으앗, 깜짝 놀랐잖아요! 그런데 여기서 뭘 하는 겁니까? 내 영업 비밀이라도 훔치려는 거예요?!'),
(61435, '놈리건이 무너진 뒤 오랫동안 세계 곳곳을 돌아다녔습니다.$B$B이 시설 이야기가 여기저기서 들려오기에, 필요한 곳에 힘을 보태려고 돌아왔죠.'),
(61436, '여기서 엄청난 진전을 이루고 있어요! 마침 새로운 화학 정화 공정에서 돌파구를 눈앞에 두고 있죠. 방사능을 던 모로로 퍼뜨리지 않고 걸러낼 수 있게 해 줄 겁니다.$B$B이런 획기적인 정제 공정을 생각하기만 해도 흥분돼요! 응용할 수 있는 분야가 얼마나 많을지 상상해 보세요! 다만 공식에서 아직 몇 조각이 빠져 있긴 하지만요...'),
(61437, '이 탈환 시설의 장비와 기반 설비 전반을 내가 책임지고 있소. 이 벽 안으로 지나가는 마지막 전선 하나, 배관 하나까지 정확히 어디에 있고 무슨 역할을 하는지 알고 있지.$B$B내가 없으면 이곳은 통째로 무너질 거요! 여기서 나 말고 누가 계기 장비를 정비하고 제어판을 제대로 다룰 줄 안단 말이오?!'),
(61438, '공학은 노움 사회의 핵심 토대예요. 공학이 없었다면 우리가 어디쯤 있었을지 상상이 되나요?$B$B아마 트로그들처럼 아직도 막대기나 서로 두드리고 있었겠죠!'),
(61440, '특별히 찾는 물건이라도 있나요? 여기가 조금 정신없긴 하지만, 필요한 건 분명 있을 겁니다.'),
(61441, '요즘 정비할 게 정말 많군요. 이 낡은 기계들은 오랫동안 멈춰 있다가 최근에야 다시 가동됐거든요!$B$B놈리건 사태가 터지기 전에는 내가 이 시설 장비를 정기적으로 점검하곤 했죠.$B$B<위잔이 작게 웃음을 터뜨린다.>$B$B그때 해 두길 정말 잘했어요! 만일을 생각해서 이 모든 걸 예비 시설로 만들어 둔 것도 다행이고요!'),
(61442, '훌륭한 노움의 기발함으로 고치지 못할 건 없지. 머지않아 다시 놈리건으로 돌아가게 될 거야.'),
(61444, '오늘 대량으로 살 생각이라면 여분 물자를 따로 비축해 두었으니 걱정 마세요!'),
(61445, '고블린들은 폭발시키는 일이라면 자기들이 최고라고 떠들지만, 난 동의하지 않아요.$B$B정교하고 섬세한 부품이 정확히 맞물리지 않으면 집중된 동력을 원하는 방향으로 정확하게 보낼 수 없죠. 정밀하지도 않은 폭발이 무슨 재미가 있겠어요?'),
(61446, '어머, 혹시 여분의 스패너 하나 있나요? 내 걸 어디에 뒀는지 도무지 보이지 않아서요.'),
(61447, '많은 이들은 늑대인간의 저주를 끔찍한 병으로 여기지만, 우리는 기꺼이 받아들였소. 우리를 더 강하고, 더 빠르고, 더 오래 살게 해 주는 축복이니까! 그녀의 이름은 로젠버그요. 그녀가 우리를 따분하고 평범한 삶에서 구해 냈지.'),
(61448, '펠라에 대해서는 아직 알아내야 할 것이 많소. 전에는 전설에 불과하다고 여겼지만, 이제 그들이 실재한다는 사실이 증명됐지. 어쩌면 그들은 우리가 존재조차 몰랐던 길니아스의 뿌리일지도 모르오. 이 나라의 유산을 지켜야 하는 사람으로서, 나는 그들에게서 배울 수 있는 모든 것을 알아내야 하오.'),
(61449, '장비 수리가 필요하면 말하게. 웬만큼 망가진 건 내가 다 고칠 줄 아니까. 아니면 자네 잡동사니를 늙은 머스탱에게 팔아도 되고.'),
(61450, '늑대뱀께서는 나를 통해 보고, 나를 통해 듣고, 나를 통해 느끼신다. 나는 그분의 목소리인 천둥이며, 그분의 심판을 행하는 도구다.$B$B늑대숲에 머무르는 동안에는 내 말을 따라야 할 것이다.'),
(61452, '우리는 펠라다. 이 땅과 그 자손들을 수호하는 충실한 수호자들의 결사. 치유자이자 목자이며 스승이지.$B$B우리는 정치라는 신기루 너머를 바라보며 옛 삶의 방식에서 안식을 찾는 길니아스인들을 돕는다. 농부와 사냥꾼, 돌로 된 숲에서도 참된 자신을 잃지 않은 소박한 사람들을.$B$B우리와 함께하라. 그대의 뿌리로 돌아오라.'),
(61454, '동전 있나, 금화 있나? 구리 한 닢, 은화 한 닢이면 뿌리와 꽃, 꽃송이와 버섯, 골짜기에서 캐 온 알뿌리까지 기꺼이 팔아 드리지.'),
(61455, '<남자가 매서운 눈빛으로 당신을 응시한다.>'),
(61457, '나를 붙드는 것은 자유의 부재가 아니오, 낯선 이여. 내 죄책감이라는 무거운 짐이지. 이단자들의 손에 이 땅이 썩어 가는 모습을 보며 내 영혼에도 오점이 남았소. 나는 부모와 작위, 자유까지 잃었지. 이 어둠을 짊어진 채로도 여동생과 동포들, 그리고 이제는 그대에게서 희망을 찾고 있소.'),
(61458, '그대는 내 자유를 되찾아 주었고, 그와 함께 앞으로 나아갈 희망도 돌려주었소. 나도 바보가 아니며, 우리의 대의에 충성을 지키는 이들도 마찬가지요. 언젠가 내가 우리 앞날을 지켜내야 하는 날이 오더라도, 반드시 해낼 테니 염려 마시오.'),
(61459, '또 목적도 없이 여기까지 흘러든 외지인이군. 대체 뭘 찾으려는 건지 궁금하군.'),
(61460, '우르의 연구가 완성된 모습을 나도 꼭 보고 싶지만, 안타깝게도 그의 마지막 저서들은 우리 수중에 없소. 대신 뒤죽박죽인 미완성 발상과 기록으로 만족해야 하지. 지금은 그의 연구가 거의 이해되지 않을지 몰라도, 모란나라면 우리가 보지 못하는 것을 알아낼 수도 있소.$B$B그동안 우리는 도움이 필요한 자들에게 할 수 있는 만큼 손을 내밀 것이오. 그녀가 우리, 루핀 결사단에게 그랬던 것처럼.'),
(61467, '노움 종족의 노력과 눈부신 재능 덕분에 새로운 시대가 열렸습니다! 한때 땜장이 마을에 살던 우리 중 많은 이들이 다시 놈리건 쪽으로 모여들기 시작했죠. 정확히는 탈환 시설로 말이에요. 방사능에 오염된 고향을 되찾기 위한 새로운 사업입니다.$B$B이 시설은 텔마플러그의 배신 이전에 건설되었고, 지금은 도시의 유독 가스를 정화하는 데 사용되고 있어요. 정말 흥미롭지 않습니까?!$B$B노움 지도부를 찾는다면 그곳에서 만날 수 있습니다. 아이언포지에서 서쪽으로 가 놈리건 입구 쪽으로 향하세요. 입구는 어렵지 않게 찾을 수 있을 겁니다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(61468, '이웃들과 강대 세력과 우호적인 관계를 유지하는 것은 무엇보다 중요하오. 왕자의 광기로 우리는 이미 너무 많은 것을 잃었소. 살아남으려면 친구를 만들어야 하오. 그대의 도움을 기대해도 좋기를 바라오.'),
(61469, '이곳을 그럴듯하게 꾸미기 위해 할 수 있는 건 다 했지만, 난 이런 일을 하도록 태어난 사람이 아니오. 나는 높은 신분의 귀족인데도 여기서 평민처럼 고생하며 야만인들 시중이나 들고 있지. 토린은 이제 내 쪽은 쳐다보지도 않고, 내 예복까지 더러워졌다고!$B$B...실례했소. 귀족이 이렇게 감정을 터뜨리는 건 품위 없는 일이었군. 모두에게 힘든 시절이니. 자, 무엇을 도와드릴까?'),
(61470, '우리는 보관소와 도서관을 뒤로하고 떠나면서 가진 것을 모두 잃었소. 하지만 왕자의 광기에 맞서다 죽음을 무릅쓰느니 물질적인 것을 희생하는 편이 나았지. 이미 기억나는 많은 내용을 옮겨 적었지만, 잊힌 연대기를 찾아내는 일에는 언제나 도움이 필요하오.'),
(61471, '나는 우리의 마법 장비와 비전 수호자들을 제작하고 유지하는 일을 맡고 있소. 쉬운 일은 아니지만, 시간이 지나 내 노력이 샤니라의 삶을 조금이라도 견딜 만하게 해 주기를 바라고 있지. 물론 이 일에 도움을 준다면 고맙게 받겠소.'),
(61472, '반갑소, $r. 우리의 능력을 의심하는 눈치군. 하지만 분명히 알아두시오. 로네탈라스는 언젠가 우리 모두가 자랑스러워할 안식처가 될 것이오. 도움을 맹세하는 자는 보상을 받을 것이며, 아즈토르딘이 그대를 믿는다면 나 역시 믿겠소.'),
(61473, '내가 젊었을 때와 별들의 위치는 달라졌지만, 그 별들은 여전히 오늘날 우리가 보는 세상에 영향을 미치는 수많은 비밀을 품고 있소. 나는 그 힘을 우리에게 유리하게 쓸 수 있다고 믿소. 어쩌면 토린도 내 노력을 알아봐 줄지 모르지.'),
(61474, '이 엘프들이 얼마나 강대한지 감히 짐작이나 되나, $r? 그들의 힘은 지식에 있소. 나 개인에게도, 포세이큰 전체에게도 엄청난 도움이 될 지식이지.$B$B아직 그들과 같은 숨을 쉬는 몸이었다면 흥분으로 숨이 멎을 지경이었을 거요. 그런데도 엘프의 본성을 지닌 탓인지 그들의 힘을 내 것으로 만들고 싶은 충동이 드는군. 그들을 돕는 것이 곧 우리 자신을 돕는 일이오. 자, 그들에게 필요한 걸 살펴보세.'),
(61475, '정말 놀라워! 내 조상이 이들과 이어져 있고 셴드랄라가 내 동족이라니! 이들은 세상이 잃어버린 수많은 지식을 너무도 당연하게 여기고 있어. 우리는 셴드랄라에게서 엄청나게 많은 것을 배울 수 있어. 반드시 그들의 호의를 잃지 말고, 그들이 원하는 도움은 무엇이든 제공해야 해.$B$B그들의 지식이 내 백성을 구할 거야. 난 알아.'),
(61476, '아, 친구여. 여기서 만나니 반갑군. 보다시피 우리 백성을 위한 새 보금자리의 씨앗이 뿌려졌네. 솔직히 말하면 앞으로 무슨 일이 기다릴지 두렵기도 하네. 남은 이가 너무 적고, 앞으로 몇 해를 살아남을 수 있다는 보장도 없으니까.$B$B그래도 우리는 여기까지 왔네. 내가 감히 바라던 것보다 훨씬 멀리 말이지. 그동안 겪어 온 모든 일을 생각하면, 내 백성이 파멸하는 운명 따위에 순순히 굴복할 수 없고, 결코 그러지도 않을 걸세.'),
(61480, '엘룬의 빛 속에서 인사드리오. 달의 여신의 은총으로 태어난 안식처, 다르나서스에 온 것을 환영하오.$B$B이 성스러운 곳은 하이잘 산 전투 이후 우리에게 주어진 피난처요. 우리 백성이 평안과 새 삶을 찾아야 했던 곳이지.$B$B하지만 안타깝게도 우리의 단결은 산산이 부서졌고, 어떤 세계수도 이 깊은 상처를 치유할 수 없소.$B$B배신이라는 병은 전장에서 맞섰던 어떤 적보다도 음흉하게 우리 백성의 심장 속에서 곪아 가고 있소.$B$B역병처럼 번져 가는 이 병의 원흉은 바로 이 도시의 벽 안에서 편안히 지내고 있지.'),
(61481, '내 안에는 대지 그 자체가 있다. 우리는 하나다. 나는 대지의 일부이고, 대지는 나의 일부다. 나는 산의 응답에 귀를 기울인다.'),
(61482, '안두인은 지금은 어린아이일 뿐이지만 언젠가 위대한 지도자가 될 것이오. 그 아이의 마음은 순수하고 빛으로 가득하지. 아버지가 자리를 비운 지금, 그가 성년이 될 때까지 내가 가르치고 왕국을 다스릴 책임이 있소.'),
(61483, '엘드레탈라스에서 가져올 수 있었던 것은 얼마 되지 않지만, 우리의 마법만큼은 잃지 않았소. 창조술을 이용해 주로 음식과 물자를 비롯한 여러 물건을 만들어 내고 있지. 내 힘을 필요로 하는 곳이 많고, 나는 내 백성을 위해 해야 할 일을 할 뿐이오.'),
(61484, '로네탈라스는 대분열 이전 엘드레탈라스의 상류층과 밀접하게 연결된 학원이었소. 우리 중 많은 이들이 전성기의 이곳에서 공부하기도 했지.$B$B대분열로 많은 것이 파괴되었지만, 상당수의 방호 마법과 마력 저장고는 지금까지도 작동하고 있소. 이곳에 남은 마력을 재구성하고 끌어내어 우리에게 도움이 되게 만드는 것이 내 일이오.'),
(61485, '놀드랏실의 축복 아래에서 수고한 대가를 받고 싶은가? 그렇다면 제대로 찾아왔군.'),
(61486, '시간은 금이라고, 친구. 그리고 내 시간은 아주 비싸지.$B$B우리 둘 다 더 중요한 일이 있을 테니, 여기 무슨 볼일로 왔는지 빨리 말해 보는 게 어때? 금화에는 눈독 들이지 말고. 알겠나?'),
(61491, '꿈강철의 비밀은 가장 뛰어난 대장장이조차 쉽게 헤아릴 수 없소. 그토록 정밀한 기술과 솜씨를 다룰 잠재력이 그대에게 있소?'),
(61492, '마음을 비우고 손을 안정시키시오. 꿈실로 직조를 시작하려면 반드시 익혀야 할 솜씨가 있소. 이 재료의 성질은 지극히 독특하면서도, 다루다 보면 이상하리만치 마음이 평온해지지.$B$B설마 나를 방해하러 온 것뿐은 아니겠지. 무엇이 필요하오?'),
(61493, '내가 꿈가죽을 다루는 걸 보러 왔나? 미리 경고하지. 이 재료는 겁 많은 이가 손댈 물건이 아니야. 최고의 가죽세공사들조차 이 종잡기 어려운 가죽을 다루려다 실패했지.$B$B어쩌면 자네에게는 이 재료를 익힐 만한 끈기와 집중력이 있을지도 모르겠군.'),
(61494, '내 마음은 꿈으로 돌아가길 갈망하오. 꿈이 나를 부르고 내 존재를 원하지만, 나는 랄라티우스의 충실한 종이오. 하이잘에서 맡은 임무가 끝날 때까지 봉사해야 하지.$B$B그나저나 나 혼자 가서 뭘 하겠소? 나 좀 보시오, 이렇게 작은데!'),
(61496, '별똥별 마을에 있으면 언제나 마음이 편안해져요.'),
(61497, '세계수 아래까지 무엇을 찾아온 것이오? 지식? 힘?'),
(61505, '나는 희귀한 물약과 비약의 비축분을 관리하고 있소.$B$B수년 전 가장 뛰어난 드루이드 연금술사에게 가르침을 받았고, 지금도 그의 방대한 연구를 이어 가고 있지.'),
(61506, '나무껍질 부족은 공격성에 사로잡혀 길을 잃었소. 하이잘의 타락이 우리 백성에게 큰 대가를 치르게 했고, 이곳에 남은 것은 우리뿐이오. 슬프고 비극적인 몰락이 다른 부족들에게도 흔한 일이 되어 버린 듯하군.'),
(61507, '나르그 충성한다! 나르그 강하다!$B$B너 나무턱 장로 위협하면, 나르그 너 위협한다! 너 나무턱 장로 다치게 하면, 나르그 너 다치게 한다!'),
(61509, '나무껍질 부족의 몰락은 우리 펄볼그에게 참담한 손실이오. 시간이 흐를수록 커지는 타락을 견뎌낼 부족이 우리뿐이 될까 두렵군.$B$B나는 나무구렁을 대표해 타락하지 않은 모든 이들을 우리 품으로 받아들이고자 왔소. 그것이 불가능하다면, 광기가 걷잡을 수 없이 번지는 것만이라도 막도록 조언을 건넬 것이오.'),
(61512, '불타는 군단이 남긴 참화에서 세계수의 뿌리가 회복되도록 지키는 것이 내 임무요. 그들의 우두머리가 말퓨리온 스톰레이지에게 패한 지도 몇 해가 지났지만, 악마들은 아직도 이곳에 남아 있소.$B$B그대가 악마의 적으로 남는 한, 놀드랏실 숲에서는 언제나 환영받을 것이오.'),
(61513, '누구...? 누구냐?'),
(61519, '인장 조율은 이제 잊혀진 기술이오. 세상에 남은 우리도 손에 꼽을 정도지. 전해지는 말로는 오래전 명가 동족들이 지맥의 마력을 강력한 마법부여에 불어넣기 위한 방법으로 이 고대 전통을 처음 시작했다고 하오.'),
(61520, '느껴지시오? 하이잘의 공기 속에 불길한 무언가가 떠돌고 있소.'),
(61521, '바로 이 숲에서 얼라이언스와 호드가 하나로 힘을 합쳐 불타는 군단을 물리쳤소.$B$B정치와 오래된 원한을 내려놓고 세계를 위해 힘을 합칠 때 얼마나 강대한 힘을 낼 수 있는지를 보여 준 일이었지.'),
(61522, '하이잘 산은 성스러운 곳이오. 반드시 경의를 갖추시오.'),
(61528, '이 숲은 신성한 땅이오. 내 마지막 순간까지 이곳을 지켜보고 수호하는 것이 내 임무요.'),
(61529, '활을 이용한 원거리 사격의 달인에 대한 전문 지식을 원하신다면, 바로 이곳 $c에 잘 찾아오셨습니다.'),
(61530, '편히 쉬세요.$B$B 놀드랏실 그늘 아래에는 더할 나위 없이 조화로운 분위기가 있습니다.'),
(61531, '에메랄드의 꿈의 매력은 강렬하다. 각성의 기운은 목표에 집중하기를 더욱 어렵게 만든다.'),
(61534, '이 길을 걸을 때는 조심하십시오. 길니아스에 암흑기가 도래했습니다. 오직 경계를 통해서만 길니아스를 회복할 수 있습니다.'),
(61535, '길니아스가 우리 난민들에게 안전한 피난처가 될 거라고 예상했어. 실버파인 숲처럼 끔찍할 줄은 상상도 못 했지.'),
(61536, '제한된 양의 음식으로 많은 사람들을 먹여 살리려면 많은 생각을 해야 합니다.$B$B 톱밥은 음식을 걸쭉하게 만들거나 양을 늘리는 데 사용할 수 있습니다.'),
(61537, '들었어?!'),
(61539, '레이븐셔에 오신 것을 환영합니다. 저희는 그레이메인의 폭정에 시달리는 자들을 보살피고 있습니다.'),
(61540, '우리는 한때 길니아스를 위해 큰 자부심을 가지고 봉사했습니다. 이제 길니아스를 인질로 잡고 있는 세력과 싸우고 있다는 것이 묘한 기분입니다.'),
(61559, '그 유령은 시간 속에 갇힌 듯 보인다.'),
(61560, '나는 하이잘을 도사리고 있는 악으로부터 지켜낼 의무가 있다.'),
(61561, '하이잘 산 정상은 정말 장관입니다.'),
(61562, '우리는 하이잘에 만연한 부패와 싸우는 데 각자의 역할을 다해야 합니다.'),
(61563, '최근 노르다나르 산으로 오르는 것이 더욱 위험해졌습니다. 주의를 기울이시기 바랍니다.'),
(61568, '무엇이 필요하신가요?'),
(61570, '죄송하지만 지금은 손님을 맞이할 수 없습니다. 학업 때문에 매우 바쁩니다.'),
(61571, '$B$B카라잔에 오신 것을 환영합니다! 탑의 주인은 현재 출장 중이어서 당분간 돌아오지 않을 예정입니다. 부디 편히 쉬시고 저희의 환대를 즐겨주세요.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(61572, '저는 이 암흑의 땅에 도움을 드리러 왔습니다. 하지만 이곳에는 뒤틀리고 부패한 악만이 가득할 뿐입니다.'),
(61574, '싸움은 이제 지긋지긋해, 폭력은 싫어.$B$B싸움은 싫어, 난 팔아버릴 거야!'),
(61576, '이 세상에는 배우고 발견할 것이 많습니다. 눈과 귀를 활짝 열어두세요.'),
(61577, '안녕하십니까, $r님. 저는 붉은용군단의 아네사스트라자입니다. 세계수를 악용하려는 자들로부터 세계수를 지키기 위해 이곳에 파견되었습니다. 아르키몬드가 패배했을 때 놀드랏실의 에너지 대부분이 소모되었지만, 아직 남아 있습니다.$B$B 아르키몬드 군대의 잔당들이 세계수를 점령하려는 음모를 꾸미며 계속해서 산에 침입하고 있습니다. 우리 종족은 생명의 수호자이며, 세계수가 악마의 손에 넘어간다면 모두에게 재앙이 될 것입니다. 심지어 불타는 군단이 다시 돌아올지도 모릅니다. 이와 관련된 정보를 얻게 되면 저에게 알려주십시오.'),
(61578, '나는 섀도우투스 부족의 섀도우헌터, 트라크날이다. 이 어려운 시기에도 조상의 땅을 지켜야 할 나의 의무는 변함없다. 이 악마들은 물론이고, 산을 위협하는 자들도 내 칼날에 쓰러질 것이다. 자네는 그저 살육을 미루고 있을 뿐이군. 대체 무엇을 원하는 건가?'),
(61579, '안녕하세요! 조용히 해 주세요. 악마들이 저를 눈치채지 못하게 하는 게 중요해요. 악마들을 감시하는 게 제 임무거든요. 무슨 일로 오셨나요?'),
(61580, '안녕하세요! $r님, 아주 유능해 보이시네요! 하이잘에 오신 것을 환영합니다! 산의 상태가 더 좋았으면 좋겠지만, 저희는 최선을 다하고 있습니다. 이곳에 있는 동안에는 예의를 갖춰주세요, 알겠죠? 제가 당신을 죽여야 한다면 곤란할 테니까요.'),
(61581, '산지기들은 쇠락해가는 계급이며, 전성기는 이미 지났다. 하지만 그렇다고 해서 내가 내 의무를 다하는 것을 막을 수는 없다. 이 얼간이들이 우리의 신성한 산을 침범하고 더럽히고 있다. 이 죄악에 대한 처벌은 사형이며, 나는 누구의 도움을 받든 받지 않든 그 형벌을 집행할 것이다. 자, 이제 무엇을 원하는가?'),
(61583, '낯선 자가 다가온다.$B$B "탈라나르에 오신 것을 환영합니다.$B$B 저는 아나샤 스타폴 사령관입니다. 저는 상관께서 불복종이라고 여기신 일로 추방당했습니다. 하지만 상관께서는 제 부대의 충성심을 과소평가하셨죠. 이제 우리는 이곳에 갇혔습니다. 진정으로 중요한 것, 즉 우리 백성의 안전과 조상의 유산을 지키는 것을 잊어버린 지도자들에게 버림받은 것입니다.$B$B 수천 년 동안 나이트 엘프는 이 땅을 지배해 왔으며, 세상 끝날까지 그럴 것입니다. 제 말 알아듣겠습니까?$B$B" "좋습니다. 계속 진행하시죠."'),
(61584, '비할 데 없는 아름다움을 자랑하는 페랄라스는 칼림도어 남부에서 길들여지지 않은 자연의 마지막 보루 중 하나입니다. 오셔서 그 장엄함에 흠뻑 빠져 우리 혈통의 고대 이야기를 느껴보세요.$B$B 아아, 이 땅은 너무 오랫동안 버려져 이제 우리의 유산을 말살하고 잊히게 하려는 자들의 손에 넘어갔습니다.$B$B 저는 우리에게 마땅히 속한 것을 되찾기 위해 이곳에 소환되었으며, 그것을 이룰 때까지 결코 쉬지 않을 것입니다. 어쩌면 운명이 당신을 이 숭고한 대의를 돕도록 인도할지도 모릅니다.'),
(61585, '안녕하십니까, $r. 이렇게 좋지 않은 상황에서 만나게 되어 유감입니다. 이곳은 결코 사람이 살기 좋은 곳이 아니며, 드루이드들이 뭐라고 하든 저는 이 길들여지지 않은 정글의 끊임없는 폭우나 버섯구름 봉우리의 메마른 바람보다는 잿빛 골짜기의 아름다운 새소리가 훨씬 더 좋습니다.$B$B무슨 일로 이곳에 오셨는지 여쭤봐도 될까요? 만약 우리의 현재 상황에 대해 논의하고 싶으시다면, 삼가 주시기 바랍니다. 이 문제는 오직 파수꾼들만의 문제이며, 파수꾼들만이 다룰 것입니다.'),
(61586, '문명의 속박에서 아무리 멀리 벗어나도, 문명의 손아귀는 끈질기고 집요하게 나를 쫓는 것 같다.$B$B 네 생각을 말하고, 다시는 돌아오지 마라.'),
(61587, '잘 들어라, 여행자여. 내 동생은 판드랄의 계략에 이용당할지 모르지만, 나는 대드루이드의 꼭두각시가 아니다. 나는 어린 동생들을 어떤 위험으로부터든 지키고, 항상 감시하는 파수꾼들의 시선으로부터 보호하기 위해 이 땅에 왔다.$B$B (베텔론은 킥킥 웃으며 근처에 있는 파수꾼 중 한 명에게 장난스럽게 윙크를 했다. 파수꾼은 얼굴을 붉히며 황급히 시선을 돌렸다.) 하지만 그들에 대한 이야기는 이쯤 하고.$B$B 이것만은 알아두어라. 나는 정치에 관심이 없고, 솔직히 말해서 그 음모에 진절머리가 난다. 나의 가장 중요한 충성은 자연 세계에 있으며, 나는 기꺼이 자연의 하인이 될 것이다.'),
(61588, '안녕, 지친 여행자여. 먼 길을 헤쳐 이 외딴 골짜기에 도착했구나. 이곳이 황량하고 폐허처럼 보일지라도 속지 마라. 이 골짜기는 한때 우리 백성을 지키는 중요한 요새이자 매우 중요한 곳이었다.$B$B 이제 나의 막중한 임무는 이곳을 옛 영광으로 되돌리고, 무너져가는 기념물에 새 생명을 불어넣고, 칼림도어 백성을 지킬 새로운 세대의 키메라를 훈련시키는 것이다.$B$B 하지만 나 혼자서는 할 수 없다.'),
(61590, '경험이 풍부한 멘토의 지도 아래 훈련받는 것은 정말 신나는 일입니다. 때로는 엄격해 보일지라도, 그것은 그가 가르치는 교훈이 얼마나 중요한지 알기 때문입니다. 키메라는 사나운 생물이고, 단 한 번의 실수로 생사가 갈릴 수 있습니다.'),
(61591, '이 땅들은 불타는 군단이 우리 세계에 발판을 마련하게 된다면 어떤 일이 벌어질지 극명하게 보여주는 증거입니다.'),
(61592, '판드랄 스태그헬름의 명령으로 에트위르의 희생을 조사하고 연구하기 위해 이곳에 왔습니다. 이곳에서 일어난 일은 악령의 숲뿐 아니라 그 너머의 땅에도 희망을 가져다줄 것입니다.$B$B 만약 우리가 펠 이끼의 영향을 막을 방법을 찾아낼 수 있다면, 칼도레이의 미래는 그 어느 때보다 밝을 것입니다. 제 말을 끊지 마십시오. 만약 그렇게 한다면 심각한 결과를 초래할 것입니다.'),
(61607, '제 임무는 무기고의 안전을 확보하는 것입니다. 또한, 이곳에서 큰 도움을 준 사람들에게는 강력한 갑옷과 무기를 보상으로 줄 수도 있습니다.'),
(61610, '이 교회와 교회가 자리한 땅을 지키는 것이 나의 의무입니다.$B$B 하지만 경고하건대, 지하실에는 가까이 가지 마십시오. 그곳은 짙은 어둠에 휩싸였습니다.'),
(61611, '도와드릴 일이 있을까요?'),
(61612, '무슨 편지라도 받았어?'),
(61614, '저는 스톰윈드 귀족들의 지원을 구하기 위해 이곳에 왔습니다. 하지만 예상했던 것보다 훨씬 어려운 일입니다.'),
(61616, '이름을 알리고 싶다면 블러드 링이 바로 그곳입니다.'),
(61621, '버클 업에 오신 것을 환영합니다! 가게가 좀 어수선한 점 양해 부탁드립니다. 갑옷 가게를 벨트 버클 전문점으로 바꾸는 중이거든요! 세상에 하나뿐인 나만의 아이템을 만들고 싶다면 바로 이곳입니다.'),
(61622, '거기 계신 분, 사람들 속에서 돋보이고 싶으신가요? 제가 벨트 버클 제작 계획을 세웠는데요. 이걸 착용하시면 전에 없던 특별함을 느끼실 수 있을 겁니다.$B$B <타노반이 한숨을 내쉰다.$B$B> 저기, 저 좀 도와주세요. 은이 좀 필요하거든요.'),
(61623, '칼림도어의 하늘은 그 땅만큼이나 거칠고 험준합니다. 어디로 날아가고 싶으신가요?'),
(61624, '전에 석궁을 만져본 적 있어요? 쏴본 건 더더욱요. 반동이 꽤 심하더라고요.'),
(61625, '안녕하세요, 무엇을 도와드릴까요?'),
(61626, '활 솜씨는 생존과 죽음을 가르는 중요한 요소가 될 수 있습니다.$B$B 모든 것을 다 안다고 생각될 때조차도 꾸준히 연습하는 것을 잊지 마세요.'),
(61627, '길들여지지 않은 야생은 마치 도발하는 적처럼 보일 수 있습니다. 하지만 일단 그 습성을 속속들이 파악하게 되면, 그것은 그저 또 다른 잠재적 적일 뿐입니다.'),
(61628, '저는 스톰윈드 경비대 신병들에게 활과 석궁 사용법을 가르치는 일을 자주 맡습니다. 도시 방어를 위해서든, 전투에서 사용하기 위해서든 말이죠.$B$B 솔직히 말씀드리면, 제가 가장 싫어하는 일 중 하나입니다.'),
(61629, '자연과 하나가 되고, 짐승들을 길들이는 것은 배워볼 만한 가치가 있는 기술이다.'),
(61632, '나는 어린 트롤들에게 새로운 종류의 부두술을 가르치러 왔다. 너희들은 배우고 싶어하는 것 같군.'),
(61633, '넌 훈련이 많이 필요해. 배울 게 많잖아.'),
(61634, '정말 이상한 곳이네, 친구. 난 여기보다는 줄아만의 성벽이 훨씬 좋아. $B$B훈련이 필요하면 언제든 말해.'),
(61635, '우리 파라키족은 볼진의 도움으로 구원받았습니다. 이제 우리가 은혜를 갚을 차례입니다.$B$B 가까이 오십시오. 우리의 마법을 보여드리겠습니다.'),
(61636, '우리가 휘두르는 어둠의 주술은 종종 타인들에게 간과되곤 한다. 그들은 크게 착각하고 있는 것이다.'),
(61637, '저는 악마들을 위한 마법서 모음을 판매합니다. 조심하세요, 그 안에 담긴 지식은 치명적일 수 있습니다.'),
(61638, '무엇이 필요하세요?'),
(61639, '경기장에서 실력을 증명하고 싶으신가요?'),
(61641, '친구야! 내 스튜디오에 온 걸 환영해! 좀 좁긴 하지만, 그래도 괜찮아.$B$B 즈즈즈브르즈즈 여러분이 가장 좋아하는 방송 DJ, 눈망루 마을에서 생방송으로 진행하는 자포 잽블라스트입니다! 제 방송도 한번 들어보세요, 알았죠?'),
(61644, '놈리건 복구 시설에 오신 것을 환영합니다! 차가운 눈을 피해 쉴 곳을 찾고 있다면, 이곳보다 더 좋은 곳은 없습니다.'),
(61653, '울프스컬 클랜은 점점 짙어지는 어둠에 맞서 싸우는 하나의 무리라는 위대한 비전에서 탄생했습니다. 호드 안에 있는 늑대 무리, 명예와 전통, 그리고 용서를 기반으로 세워진 무리입니다. 나와 수많은 이들이 잔혹하게 우리에게 가져온 타락을, 그롬의 죽음과 우리의 미래에서 보여주듯이 이제는 거부합니다. 옛 오크의 고향이 더 밝았던 시절, 희미하게나마 기억해낼 수 있는 그 날들이 떠오릅니다. $B$B 어쩌면 대지모신의 눈이 감기고 세상의 마지막 어둠이 찾아오기 전에, 당신도 우리의 사냥에 동참할지도 모릅니다.'),
(61720, '고블린으로 크게 성공하는 유일한 방법은 광물을 캐는 것입니다. 충분히 성공해서 부자가 될 수 있어요!'),
(61721, '좋은 상품을 찾고 계신가요? 그렇다면 잘 찾아오셨습니다. 제 모든 상품은 완벽한 가격으로 준비되어 있습니다.'),
(61724, '러스트게이트 리지에 오신 것을 환영합니다. 최고 관리자이신 분의 친구분들이시겠죠? 그분은 아무나 탑에 거주하도록 허락하지 않으시니까요.$B$B 혹시 그분을 만나기를 기다리고 계신다면, 자리에 앉아 따뜻한 음식을 드시는 게 좋겠습니다. 최근 그분께서 매우 바쁘시거든요. 게다가 성격도 굉장히 급하시고요.'),
(61725, '뭘 원하는 거야? 여기 얼마나 많은 일이 필요한지 알아?! 나한테 중요한 할 말이나 좋은 소식이 있는 게 아니라면, 당장 나가.'),
(61726, '여기선 정말 조심해야 해요! 마치 온 자연이 성실하게 일하는 고블린이 돈 좀 버는 걸 막으려고 작정한 것 같아요. 원하시면 붕대 만드는 법을 알려드릴 수도 있어요. 야생에서 끔찍한 짐승에게 상처 입었을 때 정말 유용하거든요.$B$B 정말 돈값을 하는 거예요.'),
(61728, '삶에 활력을 불어넣고 싶으신가요? 저 아래 탄광 광부들은 흙만 먹고 살지만, 우리는 이 탑에서 왕처럼 먹습니다. 제게서 이것저것 배워보면, 당신도 왕처럼 먹을 수 있게 될지도 몰라요.'),
(61729, '쳇, 저것 좀 봐. 빈둥거리면서 손가락만 꼼지락거리고 있잖아. 나처럼 착하고 정직한 고블린이 이런 환경에서 어떻게 조금이라도 이윤을 남기겠어? 팔 없는 노움 무리가 저것들보다 훨씬 생산적이겠네. 아니, 팔 달린 노움 무리가 해도 저것보다는 나을 거야. $B$B 블래스텐톰은 내가 사업 성공 보고서를 가져올 거라고 믿는다면 완전 얼간이에 아마추어잖아. 당장 꺼져! 안 그러면 내 시간과 돈을 낭비한 대가로 내가 너를 땅속으로 떨어뜨려 버릴 테니까.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(61730, '어떡하지? 택슬로가 보냈어?$B$B (맥슬로는 한숨을 내쉰다.$B$B) 형치고는 좀 지나치게 간섭하네. 여기 물자 관리는 내가 맡고 있는데, 물자는 넉넉하지만 함부로 쓰면 금방 바닥날 수 있어.'),
(61732, '크고 수익성 좋은 물고기를 낚고 싶다면 도움이 절실히 필요할 겁니다. 제 상품들을 살펴보시면 필요한 것을 찾으실 수 있을 거예요.'),
(61733, '인력 부족으로 인해 작업량과 일정이 상향 조정되었습니다. 계속 그만두는 직원들의 빈자리를 메우기 위해 모든 직원들이 더욱 긴 시간 동안 근무하고 있습니다!'),
(61737, '여기엔 게으른 직원들이 너무 많아. 이런 기준과 관행은 투자개발회사에서는 절대 용납되지 않을 거야. 듀로타 노동조합이 이런 좋은 근무 조건을 허용한다는 게 믿기지 않아.'),
(61738, '우리 고블린들이 손가락이 네 개밖에 없는 좋은 점은 손가락 한두 개가 없어도 대부분의 사람들이 눈치채지 못한다는 거야. 신기하지 않아?'),
(61739, '좀 더 튼튼한 약초들을 채집하는 방법을 알고 싶다면, 돈을 내셔야 합니다. 이런 상황에서 공짜로 해줄 리가 없잖아요!'),
(61740, '재료가 부족하면 임기응변으로 해결해야지! 약초는 좀 쓰고, 신체 부위는 좀 써서라도 광고만 잘하면 누군가는 꼭 사줄 거야.'),
(61741, '정말 할 일이 산더미 같네요!$B$B 잘못 계산된 퓨즈와 불량 전선 때문에 로봇들이 전부 오작동을 일으키고 있어요!'),
(61742, '괜찮은 무기나 제대로 된 호신용품을 찾고 계신다면, 잘 찾아오셨습니다.'),
(61744, '저는 여기서 중요한 일을 맡고 있습니다. 블랙스톤에 물을 공급하는 건 정말 중요한 일이죠. 이 펌프가 고장 나거나 제가 자리를 비우면 완전히 아수라장이 될 겁니다. 펌프가 작동하지 않으면 러스트게이트와 그의 부하들은 마실 물을 구할 수 없게 되니까요.$B$B (이런 젠장) 제가 좀 더 많은 돈을 받아야 할 것 같군요.'),
(61746, '제 생각엔 러스트게이트 리지에서 물 부족 문제에 대해 문의하러 오신 것 같네요?'),
(61747, '이 주변은 사람들이 많이 다니지 않아요.$B$B 혹시 투자개발회사 관계자분들 중 한 분이신가요?'),
(61748, '안녕하세요.$B$B 제 작업실에 오신 것을 환영합니다. 저는 시간이 날 때마다 여기서 온갖 손재주 좋은 프로젝트를 하고 있어요. 요즘은 주로 러스트게이트 리지에서 가져온 것들을 고치는 데 시간을 쏟고 있습니다.$B$B 거기선 파쇄기조차 제대로 작동시키지 못하는 것 같아요. 녹슨 볼트, 찢어진 배선, 금이 간 프레임, 정말 엉망진창이에요.'),
(61749, '혹시 여분의 나사가 있으신가요?'),
(61754, '이건 정말 재앙이야, 이제 우리는 어떻게 돈을 벌어야 하지?'),
(61755, '제가 여기 서 있는 게 운이 좋다고 생각하실지도 모르겠지만, 사실은 그 배에 금이 엄청 많았는데 전부 바다 밑바닥으로 가라앉았어요... 차라리 죽는 게 나을지도 모르겠네요.'),
(61756, '우리 썬더포지 장인들은 와일드해머 대장장이 기술로 만들어낼 수 있는 최고의 장인 정신을 자랑한다! 피와 땀과 눈물이 바로 우리만의 독보적인 기술을 만들어내는 비결이다!'),
(61757, '아이언포지의 청동수염 드워프들은 자신들의 기술에 자부심을 가질지 모르지만, 와일드해머 드워프들이 수년간 갈고닦은 정교한 기술에 비하면 보잘것없어.'),
(61758, '내 아들들은 재능 덩어리지만, 잘 통제해야 해. 하루만이라도 싸우지 않고 가만히 있어 준다면, 가문의 전통을 물려주는 게 그렇게 힘들진 않을 텐데!'),
(61760, '이 주변은 거의 모든 게 엉망진창이에요. 가치크는 시간이 날 때마다 도와주려고 애쓰죠.'),
(61761, '그 망할 머드포우 놈 때문에 광산에서 쫓겨났어. 일정이 완전히 엉망이 됐어!'),
(61772, '탐욕의 저주를 받아 이제 우리는 파멸 직전에 서 있습니다. 폐허와 동족의 쓸모없는 오물 속에서 산산이 조각나고 부서지고 비참하게 서 있는 우리의 모습을 보십시오. 그들은 우리가 갈망할 수도 없는 구원을 자신들이 찾겠다고 주장하며 우리를 버렸습니다.'),
(61799, '한때 자랑스러웠던 우리 왕국의 잿더미 속에서, 우리는 모든 것을 빼앗아간 배신으로 인해 텅 비고 상처 입은 우리 자신을 발견합니다.$B$B 하지만 이 황량함 속에서 쓰라린 결의가 뿌리내립니다. 우리는 패배한 잔해가 아니라, 하나의 목적을 위해 새롭게 단련된 단결된 세력으로 서 있습니다. 한때 배신자 군주의 변덕에 좌우되었던 미래는 이제 우리 앞에 활짝 열려 있습니다. 우리가 스스로 운명을 써 내려갈 수 있는 백지 같은 캔버스입니다.'),
(61800, '우리 민족의 운명에 대한 끝없는 논쟁 속에서, 해답은 우리 눈앞에 명백히 드러나 있습니다. 소중한 자원인 시간을 끝없는 숙고에 낭비하는 대신, 우리의 마음을 하나로 묶는 단 하나의 확고한 목적에 집중해야 합니다. 우리는 어떤 수단을 동원해서라도 쿠엘탈라스를 스컬지의 손아귀에서 되찾아 조국을 다시 품에 안아야 합니다.'),
(61801, '이제는 아득한 환상처럼 느껴지는 어느 시절, 나는 순찰대 사령관의 자리를 꿈꿨다. 야망으로 가득 찬 생생한 색채의 그림이 내 눈앞에 펼쳐졌다. 하지만 세월은 다른 그림을 그려냈고, 냉혹한 현실의 붓질이 더해졌다.$B$B 한때 성취의 상징이었던 그토록 갈망하던 칭호는 이제 내 험난한 어깨를 짓누르는 무거운 짐이 되었다.'),
(61802, '베레사에게 이런 말을 해야 한다는 것이 정말 유감스럽지만, 그녀가 최선을 다했음에도 불구하고 혼자서는 책임을 다할 수 없는 것 같습니다. 우리 백성을 위해 우리는 다른 지도자를 찾아야 합니다.$B$B 안타깝게도 이곳에는 과거에 집착하여 우리의 발전을 가로막는 사람들이 있습니다. 어쩌면 이런 상황에서 왕위의 책임은 한 사람이 감당하기에는 너무 벅찬 것일지도 모르지만, 변화에 대한 두려움은 언제나 거부감을 동반합니다.$B$B 우리는 백성을 최우선으로 생각하고 낡은 충성심을 버리고 새롭고 더 나은 시대를 열어야 합니다.'),
(61803, '베레사가 쿠엘탈라스를 되찾기 위해 얼라이언스 병력을 규합하는 데 보여준 무능함은 더 이상 참을 수 없다. 자랑스러운 우리 종족이 스톰윈드의 꼭두각시 국가로 전락하는 것을 더 이상 두고 볼 수 없다. 얼라이언스 군대에 의존하는 우리는 스컬지와 부활한 아마니 부족의 위협에 무방비 상태다.$B$B 머지않아 다른 이들이 나의 정당한 지도력을 인정할 것이다. 태양의 맹세 왕조가 부활할 것이며, 나의 통치 아래 우리는 수많은 세월 동안 존속할 것이다. 취약하고 예속적인 시대는 끝났다. 쿠엘도레이의 지배권이 외부의 위협에 굴복하지 않고 다시 확립될 것이다.'),
(61804, '지나간 시대, 나는 켈타스 왕자의 가장 가까운 조언자이자 충신으로서, 그가 사악한 군단의 유혹에 넘어가 우리를 버리는 모습을 슬픔에 잠겨 지켜보았다.$B$B 비록 그의 귀환을 간절히 바라지만, 내 고대 감각을 어루만지는 예지력은 불확실한 길을 보여준다.$B$B 희망은 아직 남아 있지만, 나는 어리석지 않다. 왕자가 없는 지금, 우리는 냉혹한 현실에 직면하여 이 격동의 시대를 헤쳐나갈 임시 지도자를 선택해야 한다.'),
(61805, '흠? 오, 발라 대시, 친구. 무슨 일로 오셨나 보군요. 보시다시피, 저희는 지금 꽤 곤란한 상황에 처해 있습니다.$B$B 왕좌가 걸린 문제이니만큼, 상당히 격렬한 논쟁이 벌어질 것 같군요. 적어도 쿠엘도레이족이 열정적인 민족이라는 사실은 누구도 부인할 수 없을 겁니다.$B$B 자네는 이 대결에서 누구를 지지하겠나 궁금하군.'),
(61807, '브린틸리엔에 오신 것을 환영합니다. 여정이 너무 힘들지 않았기를 바랍니다.'),
(61822, '매혹시키는 것은 고귀한 예술입니다. 당신은 그것을 감당할 수 있습니까?'),
(61831, '지친 나그네여, 쉴지어다. 너의 짐은 무겁구나. 이 새로운 안식처, 우리 모두의 피난처에서 우리는 닥쳐온 시련에 맞서 굳건히 버텨낼 것이다.'),
(61832, '브린틸리엔에 오신 것을 환영합니다. 여정이 너무 힘들지는 않았기를 바랍니다.'),
(61836, '한때 우리의 정교한 솜씨로 만들어졌던 비단은 이제 실버문 폐허 속에서 갈기갈기 찢어지고 훼손되었습니다. 이제 우리, 하이 엘프 장인들이 그 비단을 다시 짜서 마땅히 우리에게 속한 찬란한 영광을 되찾아야 할 때입니다.'),
(61837, '쿠엘탈라스가 함락되기 전, 저는 존경받는 레이 기술자 펜로스의 제자로 있었습니다. 그의 불행한 죽음으로, 이제 이 귀중한 지식을 계승하고 다음 세대에 전수해야 할 책임이 저에게만 남았습니다.'),
(61840, '나는 알라탈라스 최고의 가죽 세공 장인이다. 그리고 내 지식을 기꺼이 나눠주겠다.'),
(61841, '저는 우리의 목표가 섭정위원회의 도덕적 지침에 얽매여서는 안 된다고 굳게 믿습니다. 신비는 우리가 현재 이해할 수 없는 실타래로 엮인 거대한 태피스트리와 같으며, 저는 그 숨겨진 비밀을 밝혀내기로 결심했습니다.'),
(61842, '아, 또 한 명의 젊은 제자가 자연의 비밀을 배우러 내게 왔군.'),
(61846, '저는 낚시를 좋아합니다. 이곳에 새로운 어종이 있는지 알아보려고 왔는데, 이 물가는 저를 실망시키지 않았습니다.'),
(61849, '윈드러너 여사님의 말씀은 진실이며, 그분의 지휘 아래 우리 백성은 번영했습니다. 섭정 위원회의 배신은 결코 우리 같은 전사들을 굴복시킬 수 없습니다. 우리의 충성은 오직 윈드러너 여사님께만 있습니다.$B$B 우리는 동족을 배신하는 자들의 음모에 굴복하지 않고, 그분의 뜻을 따를 것입니다. 치열한 전투 속에서도 우리는 윈드러너 여사님의 깃발 아래 뭉쳐, 진정한 지도력을 알아보는 전사들의 불굴의 힘으로 우리의 길을 개척해 나갈 것입니다.'),
(61851, '브린틸리엔에 오신 것을 환영합니다, 젊은 $c님. 영원한 태양이 당신을 비추기를 바랍니다.'),
(61861, '파우더 타운에 오신 이유가 무엇인가요? 행운을 찾으러 오셨나요, 아니면 삶에 약간의 위험을 더하고 싶어서인가요?'),
(61887, '돌발톱 산맥은 예전부터 그런 자연의 아름다움을 간직해 왔습니다.'),
(61894, '우리의 연구는 상당히 광범위한 것으로 드러나고 있습니다. 우리의 본질을 규정하는 신비에 대한 강렬한 욕망을 치유하는 방법을 찾는 것은 엄청난 과제입니다. 오직 우리 엘프만이 그 해법을 찾아낼 자격이 있을지도 모릅니다.'),
(61896, '어서 오세요, 아가씨! 새 옷 하나 장만하고 싶으세요? 제가 줄자를 가져올게요...'),
(61902, '패셔니스타라면 알아야 할 몇 가지가 있어요. 명품 브랜드나 최신 유행 의상을 입지 않으면 패셔너블하다고 할 수 없죠. 정말 간단해요. $B$BI가 준비한 상품들을 한 번만 봐도 그 품질에 감탄하실 거예요!'),
(61903, '축제 분위기를 만끽하는 가장 좋은 방법은 그에 맞는 옷을 입는 것이죠!'),
(61904, '눈은 언제나 내게 축제 분위기를 선사해. 내 차갑고 어두운 영혼조차도 말이야.'),
(61905, '환불받고 싶은 품목을 선택하세요.'),
(61906, '이 상품을 환불하시겠습니까?')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(61907, '우리 가문은 장사로 스톰윈드에서 명성이 높습니다. 왕국 전역의 귀족들에게 의뢰를 받아 최고급 보석 장신구를 만들어 왔지요.'),
(61908, '무엇을 도와드릴까요?'),
(61910, '제 증조부는 위대한 도시 그림 바톨의 보석세공사였습니다. 저도 그분만큼 뛰어난 장인이 되는 것이 꿈입니다.'),
(61911, '훌륭한 보석세공에 뭐가 필요한지 알지? 손도 침착하게, 정신도 침착하게 유지하면 진짜 예술품이 나오는 법이야.$B$B<토르바그가 걷잡을 수 없이 웃기 시작합니다.>$B$B내 이름은 토르바그야! 지나가다 나를 보면 편하게 인사해. 어쩌면 함께 정말 아름다운 걸 만들 수도 있잖아.'),
(61912, '토르바그 말은 너무 신경 쓰지 마세요. 열정이 지나치고 조금 별난 구석은 있지만, 자기 일에만큼은 정말 진심이거든요.$B$B보석세공의 고급 기법을 배우고 싶다면 제가 딱 맞는 노움이에요!'),
(61913, '금의 성질은 별루비와 아주 잘 어울려 눈부시고 화려한 장신구를 만들어 내는군. 모양과 비율을 조금만 더 조정하면...$B$B<팬지가 문득 정신을 차립니다.>$B$B이봐요, 여기서 뭐 하는 거죠? 내가 연구에 푹 빠져 있는 게 안 보여요?$B$B아, 고급 보석세공을 배우러 왔다고요? 그렇다면 내가 가르칠 생각이라도 해 보기 전에, 방대하고 복잡한 보석세공의 원리를 제대로 이해하고 있어야 할 겁니다.'),
(61916, '보석세공의 섬세하고 복잡한 성질은 엘프의 취향과 아주 잘 맞습니다.'),
(61917, '비전 마력을 집중할 수 있는 곳은 많습니다. 저는 예술, 그중에서도 섬세한 아름다움을 빚어내는 일에서 안식을 찾았지요. 주로 몸에 걸치는 금과 은 장신구의 형태로 말입니다.$B$B그 안에는 우아함이 있지 않습니까?'),
(61918, '아소란의 보석상에 오신 걸 환영합니다... 네, 알아요. 예전에는 여기서 다른 걸 팔았지만 이번엔 새 사업을 시작한 겁니다.$B$B뭔가 배우러 오셨나요?'),
(61919, '인간들과의 전쟁이 끝나고 나니 다른 일에도 눈을 돌릴 때가 됐지요. 전 예전부터 반짝이는 물건이나 빛나는 수정에 유난히 눈이 갔거든요.'),
(61921, '차갑고 감각도 없는 손가락으로 이런 섬세한 작업을 하려니 쉽지가 않군!'),
(61923, '장신구는 언제나 사람을 돋보이게 해 주는 물건이었지요. 이제 몸이 썩어 가고 있으니 오히려 더 의지하게 될지도 모르겠군요. 죽어서도 가장 멋진 모습은 유지해야 하지 않겠습니까.'),
(61924, '우리 가문은 대대로 보석세공사였습니다. 한때 스트라솔름에 가게를 두고 아제로스 최고의 목걸이들을 만들어 냈지요.$B$B아버지의 작품 몇 점을 경외심에 바라보던 기억이 아직도 생생합니다.'),
(61925, '장신구는 누구에게나 필요하지. 특히 고블린 사회에선 더 그래! 돈 많은 걸 동료들에게 과시하려면 달리 무슨 방법이 있겠어?$B$B사회적 지위도 올려 준다고. 은반지 두어 개만 끼면 여자들이 줄을 설걸.'),
(61927, '잘 들어, 친구. 진짜 돈 버는 법을 알고 싶다면 내가 비법을 알려 주지. 금이 비싸다고 생각해? 그걸 고급 장신구로 만들어 봐!$B$B내 작품 중에는 경매에서 터무니없는 이익을 남긴 것도 있어. 너도 똑같이 할 수 있다고. 내 쉬운 방법만 따라 하면 너도 보석세공으로 대박을 터뜨릴 수 있어!'),
(61930, '어서 오십시오, 지친 여행자여. 혹시... 착하고 정직한 거래를 하러 오셨습니까?'),
(61931, '<그의 눈빛이 위압적입니다.>'),
(61973, '흠, 목숨이 아깝다면 남의 일에 함부로 코를 들이밀지 않는 게 좋을 거야...'),
(61977, '왜 나는 되는 일이 하나도 없는 거야.'),
(61979, '당신이 누군데요? 남의 일에 끼어들지 좀 마시죠?'),
(61988, '유령 같은 형상이 서로 다른 두 존재의 차원 사이를 오가듯 희미해졌다가 다시 나타납니다.'),
(61990, '큰 양초 봤어? 나 큰 양초 찾는다!'),
(61991, '꺼져, 멍청아. 술이나 마시게 내버려 둬.'),
(61992, '먼지도 너무 많고 같이 있는 놈들도 끔찍하군. 여기도 한때는 더 나았는데.'),
(61996, '우리의 영원한 감시는 신성한 의무입니다. 카라잔의 비밀이 사악한 자들의 눈에 드러나지 않게 하려면 굳은 결의를 지켜야 합니다.'),
(61997, '여긴 완전히 엉망이에요. 모든 게 뒤죽박죽이죠. 내놓는 음식은 턱없이 부족하고, 함께 있는 사람들도 영 미덥지 못한 데다가 물건까지 자꾸 멋대로 사라져요! 반지를 몇 시간째 찾고 있다고요! 메디브에게 대체 무슨 일이 생긴 건지는 모르겠지만, 손님을 이런 식으로 대하는 건 절대로 아니죠.'),
(61998, '<젊은 여인이 토라진 채 우울해 보입니다.>'),
(61999, '주인님은 이 마력 수정을 언제나 가동해 두라고 하셨는데, 누군가 시동 열쇠를 훔쳐 간 뒤로는 작동시킬 수가 없습니다. 주인님이 돌아오기 전에 반드시 고쳐야 해요!'),
(62000, '아, 여기 이렇게 혼란스러워서 당신이 온 줄도 몰랐네요. 주인님이 곧 돌아오시는데 좋아하시는 바나나가 과일 그릇 어디에도 없어요! 큰일이에요!'),
(62001, '수호자의 책이 이렇게 깨알 같은 글씨로 쓰였을 줄 누가 알았겠어요? 머리가 깨질 것 같아요!'),
(62002, '아무리 오래 불 앞에 서 있어도 전혀 따뜻해지질 않아! 유령으로 사는 건 가끔 정말 성가시다니까.'),
(62003, '좋은 날입니다! 이 경치 정말 대단하지 않나요? 메디브의 웅장한 탑에 견줄 만한 건 없을 것 같아요. 이 탑이 지맥의 중심점 위에 세워졌다는 사실을 알고 있었나요? 놀랍죠? 자, 친구여, 그걸 기념해 한잔합시다!'),
(62007, '밤에는 달이 길을 비춰 주고, 낮에는 태양이 그대의 뼈를 따뜻하게 해 주기를.'),
(62030, '이곳의 복잡한 마법은 이용되기를 기다리고 있군... 이 탑을 충분히 탐험하고 숨어 있는 악을 몰아낸다면, 내 균열 이동술로 그대를 옮겨 줄 수 있네.'),
(62031, '나는 아제로스에서 살아온 세월 동안 무기의 달인이 되는 데 온 힘을 바쳤네. 이제 여러 종족에게서 배울 수 있는 것은 모두 배웠으니, 시간 속에 잊힌 기술을 찾기 위해 과거를 살펴보고 있지. 이 희귀한 유물들을 찾는 데 도와준다면 내가 터득한 지식을 나눠 주겠네.$B$B아제로스의 위험한 지역들에서 \'고대 전쟁 문서\'를 찾을 수 있을 걸세. 이 문서에는 옛날의 전투와 전쟁, 일대일 결투 방식이 기록되어 있어 지금은 알려지지 않은 전투 기술을 되살릴 가능성이 있지.'),
(62032, '마티아스는 자신의 일에 온 마음과 영혼을 바쳤습니다. 그 모습에 감명받아 저도 그의 발자취를 따르기로 했지요. 아주 먼 훗날에는 제가 그의 자리를 이어 이 일을 계속하게 될지도 모르겠습니다.'),
(62033, '이 섬에서 벌어지는 온갖 싸움은 배가 금방 꺼지게 하지. 먹을 게 필요하면 말해.'),
(62034, '안녕하세요! 제 이름은 노라예요. 마티아스의 좋은 친구라 이곳에 왔죠. 여기 있는 오래된 문서들을 해독하는 게 제 일이에요! 오래된 룬이나 문양으로 적힌 것도 있어서 제대로 된 지식 없이는 도저히 번역할 수 없답니다.'),
(62063, '이 모래는 자비도 타협도 없어. 훈련하기에는 완벽한 곳이지.'),
(64000, '알을 찾는 건 제 특기입니다. 아제로스 전역 구석구석을 샅샅이 뒤지죠. 혹시 알 속에서 뭔가를 발견하고 기분이 우울해지셨다면, 제가 대신 해결해 드릴 수도 있습니다... 물론, 소정의 금액은 있습니다.'),
(65003, '단순한 잡담을 하러 온 건 아니겠지. 푹 쉬고, 돈이나 쓰시고, 날 내버려 두시오, 필멸자여.'),
(65013, '이곳은 좀 이해하기 어렵지만, 장사가 아주 잘 돼요!'),
(66004, '섬뜩한 시선이 당신의 영혼을 꿰뚫는다.'),
(66100, '아이고! 난 어린애인 게 너무 싫어!'),
(66101, '내가 박살낼 거야! 넌 죽을 거야!'),
(66102, '위대한 자가 너를 박살낼 것이다!'),
(66103, '왜... 사장님이... 우리를... 배신하신 거죠...?'),
(66104, '원하시는 대로 해드리겠습니다...'),
(66105, '당신은 다른 사람들보다 훨씬 멀리까지 왔습니다. 이제 당신은 우리와 함께 이 지하 묘지로 들어가게 될 것입니다!'),
(66106, '또 하나의… 시체가… 더미에 추가되었다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66107, '그의 손아귀에서 더 이상 나를 놓지 않아... 룬을 찾아서 우리를 자유롭게 해 줘...'),
(66108, '납골당 전체에 삐걱거리는 소리가 크게 울려 퍼진다...'),
(66109, '쓰러진 자들의 영혼은 복수를 갈망한다.'),
(66110, '오류 발생. 더 이상 구조물을 생성할 수 없습니다.'),
(66111, '공허가... 기다리고 있다.'),
(66112, '늦었어, 비참한 잡종들아! 주인님께서 우리를 돕기 위해 최고의 병사를 보내셨다! 이제 너희의 최후는 끝났다!'),
(66113, '자, 경주 참가를 위해 줄을 서세요!'),
(66114, '부엉!'),
(66115, '아, 그러니까 요즘은 리사가 이런 파티를 여는 거였군? 정말 좋은 정보다, 고마워! 아는 게 힘이고, 힘은 많은 돈을 벌어다 주잖아, 그렇지? 맞아. 다음에 또 보자, 친구.'),
(66116, '해변 파티가 있다고?! 초대받은 걸 보니 꽤 큰 모임 같군. 평소 같으면 너무 바빠서 못 간다고 했을 텐데, 이번엔 기회인 것 같아. 휴식도 취하고, 여유도 즐기고, 돈도 벌 수 있잖아! 꼭 갈게, 장담해.'),
(66117, '감히? 넌 여기서 살아나가지 못할 거야!'),
(66118, '야호!'),
(66119, '바아아! 바아아!'),
(66120, '바아아!'),
(66121, '쿠엘도레이, 저희가 왔습니다. 당신의 말씀으로 보아 이 소환은 급한 것 같았습니다. 부디 저희 시간을 낭비하지 않으셨기를 바랍니다.'),
(66122, '대제사장님, 저는 몰랐습니다. 제 고향에서 암울한 소식이 들려왔습니다. 아시다시피, 그곳은 멸망 이후 줄곧 스컬지의 지배하에 있었습니다. 태양샘은 켈투자드의 사악한 마법에 의해 더럽혀졌습니다.'),
(66123, '하지만 최근 탈라시안 협곡은 남쪽으로 밀려오는 언데드 떼로 들끓고 있으며, 우리 마법사들은 그 지역에서 지옥의 기운을 감지했습니다. 저는 레인저 군주 호크스피어와 함께 그 지역으로 정찰대를 보냈습니다. 12명의 레인저 중 단 두 명만이 돌아왔습니다.'),
(66124, '"하지만 그 두 사람이 목격한 것은 우리가 무시할 수 없는 일이었습니다. 스컬지가 남쪽에서 침공을 위해 군대를 집결시키고 있으며, 쿠엘탈라스 북부 지역은 악마들로 들끓고 있습니다."'),
(66125, '마법에 무감각한 레인저들조차도 공기 중에 감도는 악마의 기운을 느낄 수 있었습니다. 우리는 태양샘이 악마의 기운에 오염되었을 가능성이 있으며, 어쩌면 악마를 소환하는 통로가 되었을지도 모른다고 의심합니다.'),
(66126, '그들은 아직 스컬지를 공격하지 않고 있습니다. 아마도 동맹 관계이거나 악마들이 공세를 준비하고 있는 것으로 추측됩니다.'),
(66127, '뭐라고?! 정말 확실해?! 또다시 너희의 행태가 이 세상에 파멸을 가져오는구나, 고귀한 자들이여!'),
(66128, '진정하세요, 대제사장님. 쿠엘도레이는 이 일에 책임이 없습니다. 오히려 그들은 이 문제를 해결하고 싶어합니다. 우리 군대는 어려움을 겪고 있지만, 악마들이 돌아오고 있다면 외면할 수 없습니다."'),
(66129, '우리 의견이 일치합니다.'),
(66130, '좋습니다. 당신네 땅에 있는 우리 백성들이 당신네 사람들이 우리의 방식을 존중하고, 심지어 엘룬을 따르기 시작한 사람들도 있다고 하니, 당신을 의심하지 않겠습니다. 하지만 당신네 백성들이 당신들이 저지른 일을 수습해야 합니다.'),
(66131, '대제사장님, 저도 더 바랄 게 없습니다만, 저희에게는 그럴 만한 병력이 부족합니다. 함선은 고작 몇 척뿐입니다.'),
(66132, '바다를 순찰하는 언데드 함선을 격파하기엔 역부족입니다. 저희는 이제 막 얼라이언스에 합류했을 뿐입니다.'),
(66133, '그럼 당신은 우리가 당신이 저지른 실수를 또다시 수습해주길 바라시는 건가요?'),
(66134, '대제사장님, 저희는 얼라이언스입니다. 그들의 문제는 곧 우리의 문제입니다. 함께 협력합시다. 이 문제는 결코 외면할 수 없습니다.'),
(66135, '귀족들과 회의를 소집하여 군대와 함대를 출정 준비시키겠습니다. 한 달 안에 출항 준비가 완료될 것입니다.'),
(66136, '한 달 동안 악마 같은 벌레들이 이 세상에 쏟아져 들어온다고?! 제정신이세요?'),
(66137, '동원에는 시간이 걸립니다, 아가씨. 우리도 원로원과 회의를 해야 합니다. 상륙할 함대가 없으니 육로로 이동하여 역병지대로의 진입을 막는 것이 좋겠습니다. 은빛 기사단은 우리의 노력을 높이 평가할 것입니다.'),
(66138, '"우리가 가진 것은 많지 않지만, 이번 공세를 위해 우리의 항공기, 시즈 탱크, 그리고 조종사들을 아낌없이 투입할 것입니다."'),
(66139, '그들이 도착하는 데는 시간이 걸리겠지만, 탈라시안 고개를 넘어 아무것도 넘어가지 않도록 막아줄 것입니다.'),
(66140, '나야말로 악마들이 얼마나 사악한지 잘 알고 있다. 테라모어 함대는 최대한 빨리 지원할 준비가 되어 있을 것이다."'),
(66141, '좋습니다, 당신에게는 당신만의 이유와 방식이 있겠지만, 저는 이 위협을 무시할 수 없으며, 우리가 빨리 조치를 취할수록 상황은 더 나아질 것입니다.'),
(66142, '연합군 주력 부대가 착륙할 장소가 필요하며, 우리 칼도레이족은 그곳을 확보할 것입니다. 윈드러너 의장님과 프라우드무어 부인, 이 작전을 최대한 지원해 주십시오.'),
(66143, '물론, 우리 함선들이 귀국의 함대를 지원할 것입니다.'),
(66144, '저의 마법사들과 레인저들을 대리하여 돕겠습니다. 저희는 할 수 있는 모든 방법으로 돕겠습니다, 대사제님. 조국을 되찾는 것은 저희에게 매우 중요하며, 이 위협을 막는 것 또한 마찬가지입니다.'),
(66145, '이건 널 위해서 하는 게 아니야, 아가씨. 불타는 군단이 돌아오는 걸 용납할 수 없어. 이제 페더문 장군과 만나야 해. 텔드라실로 돌아가야 한다고.'),
(66146, '이 회의는 이제 끝난 것 같습니다. 우리 모두 각자의 임무가 있으니까요.'),
(66147, '알라탈라스로 오세요. 할 얘기가 많습니다.'),
(66148, '알 디엘 샬라!'),
(66149, '음... 엄청나게 화학적으로 변형된 크래커...'),
(66150, '이게 무슨 꽥꽥거리는 소리야? 꽥꽥꽥, 꽥꽥? 꽥꽥!'),
(66151, '똥! 온통 똥투성이야! 숲을 정화해야 해!'),
(66152, '쉿... 부티 베이로 가세요, 크릴이 도움이 필요해요...'),
(66153, '크릴은 부티 베이에서 당신의 도움이 필요해요!'),
(66154, '크릴의 발명품이 당신의 삶을 획기적으로 바꿀지도 모릅니다... 부티 베이에서 그를 도와주세요!'),
(66155, '당신과 당신 가족에게 행운이 가득하길 바랍니다. 당신은 품위와 명예를 지키며 이 세상을 살아가고 있습니다. 다른 사람들도 당신의 본보기를 따르기를 바랍니다.'),
(66156, '앤트노미에 집중해! 그녀를 처치하면 내가 아는 모든 걸 알려줄게!')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66157, '뭐라고? 너도 용이라고?! 그녀랑 똑같다고?!'),
(66158, '록 나라쉬! 팔은 안정! 사격!'),
(66159, '나이트 엘프는 민첩합니다. 그들의 움직임보다 앞서서 쏘세요!'),
(66160, '우리 대장님이 저것보다 훨씬 세게 때리세요!'),
(66161, '더 세게! 얼라이언스은 그렇게 관대하지 않을 거야!'),
(66162, '공격에 대비하세요! 적의 움직임을 주시하세요!'),
(66163, '끔찍한 괴물이 오고 있다! 도즈! 페이지! 이리 와서 우리를 도와줘!'),
(66164, '검은무쇠 디세크레이터의 설계도라고? 어, 어휴, 좋아. 너무 많은 걸 요구하네. 그에게 빚진 건 다 청산했다고 전해줘.'),
(66165, '당신들은 이 땅에 평화를 가져다주었습니다. 테라모어의 모든 생명체를 대표하여, 이 범죄를 종식시키기 위해 목숨을 걸고 헌신해 주신 당신들께 감사드립니다.'),
(66166, '아르덴트 워치는 아르젠트 던과 그 해외 작전 대대인 아르젠트 뱅가드의 가장 중심적인 작전 기지입니다. 라이트즈 호프 자체를 제외하면, 이곳은 옛 이스트웰드 지역에서 스컬지와의 전투에 있어 가장 견고하게 요새화된 요새 중 하나입니다.'),
(66167, '은빛 여명회의 일원으로서, 그들은 스컬지와의 싸움에서 호드나 얼라이언스와 협력하는 것 외에는 어느 쪽과도 직접적인 연관이 없습니다. 필요에 따라 은빛 여명회과 붉은 성전은 현재 비적대적 관계를 유지하기로 조약을 맺었지만, 긴장감은 여전히 ​​존재합니다. 스컬지 소속이거나 다른 어둠의 조직에 속한 자들은 환영받지 못할 것입니다.'),
(66168, '이곳에 있는 것을 건드리지 못할 것이다!'),
(66169, '이곳에서 당신 백성들에게 남은 것은 오직 죽음뿐입니다! 저는 수많은 사람들 중 한 명일 뿐입니다...'),
(66170, '안전한 여행 되세요, 친구!'),
(66171, '어휴, 이 교활한 놈이 사라졌나 보네.'),
(66172, '드디어 로브가 저 멍청이를 혼내줄 때가 됐군. 로브가 저놈을 혼내줄 거야.'),
(66173, '이봐, 이봐, 얼굴 좀 그만해!'),
(66174, '우리 얘기 좀 해야 해!'),
(66175, '지금 당장 내 창을 찾으러 가겠어- <으악> -안 돼!'),
(66176, '노르보크, 완전히 회복될 때까지는 어디에도 가지 마. 우리 친구가 네 창을 지켜볼 거라고 확신해.'),
(66177, '멈춰, 포기할래! 제발 살려줘, 감옥에 가더라도 감수할게.'),
(66178, '붉은십자군을 위하여!'),
(66179, '이해합니다.'),
(66180, '정말 잘 찾았군. 우리 아들들이 놈을 쇠사슬로 묶어버리겠어. 우리가 처리하는 동안 가서 맥주나 한잔 마셔.'),
(66181, '붉은십자군을 위하여!'),
(66182, '마법의 기운이 느껴졌어요! 여기서 뭐 하고 있는 거죠?'),
(66183, '이게 당신이 보여줄 수 있는 전부인가요?'),
(66184, '요즘 젊은이들은 실망스럽다.'),
(66185, '전혀 어려운 일이 아니죠!'),
(66186, '흠, 인정하건대 자네에게 약간의 재능은 있군. 오늘은 자네를 놓아주겠다!'),
(66187, '할리스터 말인가? 정말 오랜만에 연락이군. 할 얘기가 많으니 만나야겠어. 비전 레조네이터는 내가 빌려줄 수 있는데, 할리스터한테 꼭 직접 가져다 달라고 전해줘!'),
(66188, '잘됐군! 그가 저지른 모든 피해에 대해 이제 드디어 대가를 치르게 될 거야!'),
(66189, '실험 도구가 집 앞까지 배달될 때, 정말 기분 좋지 않나요?'),
(66190, '뭐라고? 그 어리석은 음도가 너를 보냈단 말이냐? 너는 멸망할 것이다!'),
(66191, '저는 관객 여러분을 맞이할 준비가 되었습니다.'),
(66192, '자, 가자!'),
(66193, '이게 무슨 뜻이지? 경비병들! 무기를 준비하라! 오물이 내 도시에 들어온 것 같다.'),
(66194, '자, 자, 부인, 서두를 이유가 없어요.'),
(66195, '바리마트라스, 이게 네 짓인가? 내 등 뒤에서 무슨 음모를 꾸민 거냐?'),
(66196, '부인, 저는 결코 당신을 해치려는 음모를 꾸미지 않았습니다. 당신의 비난에 진심으로 상처받았습니다. 이 트롤들과 저기 있는 모험가는 그저 저희의 임무를 도와준 것뿐입니다. 힐스브래드에서 우리가 겪었던 일들을 기억하시죠?'),
(66197, '그게 내 방에 있는 숲개구리 배설물과 무슨 상관이 있습니까?'),
(66198, '자, 자, 밴시 여왕님. 손님을 이렇게 대하는 게 예의인가요? 특히 그렇게 오랫동안 알고 지낸 손님이라면 더더욱요.'),
(66199, '여기선 환영받지 못하는 트롤이군. 어서 할 말 다 해 봐. 안 그러면 내가 참을성을 잃을 테니까. 지도교수님과는 나중에 얘기하자.'),
(66200, '여왕 폐하께서 원하시는 대로 하겠습니다.'),
(66201, '실바나스, 악마를 탓하지 마. 네 문제를 해결해 준 후에 우리가 밴시 여왕을 만나게 해달라고 부탁한 거잖아.'),
(66202, '별문제 아니야. 우리가 충분히 해결할 수 있는 일이지. 이제 와서 내가 감사에 엎드려 빌 거라고 생각하는 거야, 줄진?'),
(66203, '여왕님, 그런 뜻이 아닙니다. 레반터스크를 호드에 편입시키는 서류에 서명하는 것을 다시 생각해 주시길 바랍니다. 다른 건 몰라도 이 도움은 당신의 호의를 보여주는 것이라고 생각해 주십시오.'),
(66204, '내가 그걸 용납할 거라고 생각하는 이유가 뭐지? 네가 내 동족을 몇 명이나 학살하고, 도살하고, 불구로 만들었는데?'),
(66205, '당신네 사람들 중에 나에게 똑같이 한 사람이 몇 명이나 됩니까? 당신이 말하는 사람들은 오늘날 당신을 적으로 보지만, 아마니족은 그렇지 않습니다. 원한을 계속 품고 있을 순 없어요. 앞으로도 오랫동안 살아가야 할 텐데, 전쟁에는 언제나 사상자가 발생하기 마련입니다. 과거는 잊어버리세요, 실바나스. 저는 기꺼이 그럴 준비가 되어 있고, 당신과 호드의 모든 사람들에게 우리가 호드의 깃발을 들 자격이 있음을 증명해 보이겠습니다.'),
(66206, '과거는 잊어버려, 실바나스. 난 기꺼이 그럴 거야. 우리가 호드의 깃발을 휘날릴 자격이 있다는 걸 너와 호드의 모든 이들에게 증명해 보이겠어.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66207, '줄진, 늙고 흉측한 개구리에게 훈계를 듣고 싶진 않지만, 네 말에도 일리가 있다. 과거의 원한은 득보다 실이 클 뿐이다.'),
(66208, '오히려 내가 당신네 사람들이 얼마나 끈질긴지 잘 알아야 할 사람이죠. 좋습니다, 기회를 주겠지만 이것만은 명심하세요. 내 앞길을 막지 마십시오. 당신을 좋아하지 않아도 당신의 동맹이 될 수 있으니까요.'),
(66209, '부인, 제가 절차를 처리해야 할까요?'),
(66210, '바리마트라스, 네 마음대로 해라. 하지만 이는 네가 나중에 내게 책임을 져야 한다는 사실을 바꾸지는 못할 것이다.'),
(66211, '물론이죠, 여왕님.'),
(66212, '이제 사라져라, 줄진. 오늘은 산 채로 살기엔 충분하다.'),
(66213, '줄진은 고개를 끄덕이고 경호원들과 함께 자리를 떠났다.'),
(66214, '잘했어, %s. 오지에서 만나자.'),
(66215, '스톰윈드에 오신 것을 환영합니다, 여행자님! 안전하게 여행하세요!'),
(66216, '인사말!'),
(66217, '안녕하세요, 스톰윈드에서 즐거운 시간 보내세요!'),
(66218, '도움이 필요할 땐 언제든 저에게 연락하세요.'),
(66219, '빛이 당신을 보호하길!'),
(66220, '얼라이언스을 위하여!'),
(66221, '빛이 당신을 보호하길!'),
(66222, '국왕의 이름으로.'),
(66223, '여행자님, 안전운전하세요.'),
(66224, '즐거운 여행 되세요, 친구!'),
(66225, '스톰윈드에서 즐거운 시간을 보내셨기를 바랍니다.'),
(66226, '스톰윈드를 떠나기 전에 식량을 충분히 비축해 두세요.'),
(66227, '다음에 또 뵙겠습니다.'),
(66228, '빛이 당신의 여정을 지켜주기를!'),
(66229, '이 노래 정말 오랜만에 듣네요!'),
(66230, '그거 참 좋은데요!'),
(66231, '오리 한 마리가 약국에 들어가더니 "립밤 좀 주세요... 그리고 제 부리에 발라주세요!"라고 말했습니다.'),
(66232, '오크 한 마리가 어깨에 앵무새를 얹고 술집에 들어갔습니다. 바텐더가 "이봐, 그 앵무새 어디서 났어?"라고 묻자, 앵무새가 "듀로타에서요. 거기엔 앵무새가 엄청 많아요!"라고 대답했습니다.'),
(66233, '날 웃기려면 더 노력해야 할 거야.'),
(66234, '하! 꽤 강해 보이네! 이것 좀 봐.'),
(66235, '계속 훈련하면 언젠가는 나처럼 강해질 거야. 하하!'),
(66236, '저 빛 속에 비친 이 얼마나 강력한 힘인가!'),
(66237, '스톰윈드에서 당신처럼 강인한 여행자를 만나게 되어 기쁩니다.'),
(66238, '스톰윈드 경비병들에게 존경심을 표하십시오!'),
(66239, '이건 저한테는 효과가 없어요.'),
(66240, '너는 스스로를 바보로 만들고 있어.'),
(66241, '이봐, 저리 가!'),
(66242, '하하하! 그만해! 나 여기서 일하고 있단 말이야!'),
(66243, '뭐라고요? 전 완전무장 상태인데요. 그게 통할 거라고 생각하셨어요?'),
(66244, '도와드릴까요?'),
(66245, '여행자여, 환영합니다. 당신은 수많은 전투를 치르셨을 겁니다. 부디 원하시는 만큼 머무르시면서 대자연의 품 안에서 몸과 마음을 달래십시오.'),
(66246, '이슈누알라.'),
(66247, '무슨 일로 오셨나요?'),
(66248, '엘룬이 당신과 함께하길.'),
(66249, '이슈누-달-디엡.'),
(66250, '대제사장을 위하여.'),
(66251, '엘룬 신께서 당신을 인도하시기를.'),
(66252, '얼라이언스을 위하여.'),
(66253, '이곳에서 편히 쉬시는 동안 저희가 당신을 보호해 드리겠습니다!'),
(66254, '여행자여, 엘룬 신께서 당신의 여정을 보호하시기를!'),
(66255, '안녕히 가세요, 편히 쉬고 싶을 때 언제든 다시 오세요.'),
(66256, '다음에 또 만나요!')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66257, '벌써 떠나시는 거예요? 안전하게 다녀오세요.'),
(66258, '하하! 재밌네요!'),
(66259, '하! 자, 하나 알려줄게. 우리는 모두 나이트 엘프지만... 난 아침형 엘프에 더 가깝지.'),
(66260, '아, 죄송해요. 뭐라고 하셨죠? 생각에 잠겨 있어서요.'),
(66261, '엘룬 여신이시여, 이건 꼭 기억해야겠어요!'),
(66262, '이쯤에서 웃어야 할까요?'),
(66263, '와! 자연의 축복을 제대로 받으셨네요!'),
(66264, '당신처럼 강한 분이 이곳에 좀 더 오래 머물러 주셔서 기쁩니다.'),
(66265, '여기 강한 사람은 당신뿐만이 아닙니다.'),
(66266, '명심해, 큰 힘에는 큰 힘이 따른다는 걸! 아니, 잠깐... 엄청난 힘에는... 아, 됐어! 너 멋져 보여!'),
(66267, '누구를 건드리는지 조심하는 게 좋을 거야.'),
(66268, '당신의 시도는 그저 우리의 깨끗한 공기를 낭비하는 것일 뿐입니다.'),
(66269, '감히 그 더러운 입으로 주변 공기를 더럽히다니!'),
(66270, '당신은 무녀를 찾아가 마음을 정화해야 합니다.'),
(66271, '그만해요!'),
(66272, '나는 집중해서 잠재적인 위협 요소를 찾아야 해, 방해하지 마. 하하하!'),
(66273, '이봐! 보기만 할 뿐, 만지지 마!'),
(66274, '산이 당신에게 충분히 따뜻하길 바랍니다.'),
(66275, '잠시 여관에 들러 휴식을 취하세요.'),
(66276, '드워프의 고향인 이 산은 얼라이언스 모두에게 개방되어 있습니다.'),
(66277, '아이언포지에 오신 것을 환영합니다, 여행자님. 저희 주점에서 맛있는 맥주 한 잔을 즐겨보세요.'),
(66278, '하! 다시 만나서 반갑네. 벽난로 옆 의자에 앉으렴.'),
(66279, '안녕, 친구. 길을 잃으면 나한테 와서 얘기해!'),
(66280, '청동수염을 위하여!'),
(66281, '마그니 왕을 위하여!'),
(66282, '언제든지 문의해 주세요.'),
(66283, '저희가 여러분을 보호해 드리겠습니다. 저희 도시에 오신 것을 환영합니다.'),
(66284, '따뜻한 여관에서 맥주 한 잔 하고 싶으면 다시 오세요, 알겠죠?'),
(66285, '만나서 반가워요, 여행자님. 몸조심하시고, 가는 길에 멋진 생물들도 많이 사냥하세요!'),
(66286, '잊지 마세요, 산은 얼라이언스의 모든 구성원을 환영합니다!'),
(66287, '친구여, 행운이 가득하길!'),
(66288, '그건 여관에서 쓸 만한 거네. 하하하하!'),
(66289, '마그니스 왕의 수염에 맹세코! 하하하하. 그거 어디서 나온 거야?!'),
(66290, '하하하! 난 이제 술을 안 마셔... 물론, 덜 마시는 것도 아니고! 바하하하하하!'),
(66291, '음... 아마 그 얘기를 웃어넘기려면 맥주가 더 필요할지도 모르겠네요.'),
(66292, '정말 멋진 근육이네요!'),
(66293, '당신이 들러주시면 아이언포지는 분명 안전할 겁니다.'),
(66294, '근육질 난쟁이에게 잘 보이려고 하는 거야? 봐, 난 근육 50%에 맥주 50%라고! 하하하!'),
(66295, '당신은 마치 밀짚처럼 가늘군요!'),
(66296, '트롤의 지독한 방귀에 맹세코, 내가 지금 당직이라 다행인 줄 알아!'),
(66297, '내가 화를 내기 전에 물러서는 게 좋을 거야!'),
(66298, '맨손으로 대장간에 손을 넣으면 안 돼요. 화상을 입을 수도 있어요.'),
(66299, '내 팔은 작을지 몰라도 네 두뇌는 작잖아!'),
(66301, '제가 잘못 들었기를 바랍니다.'),
(66302, '하하하! 그만해 친구!'),
(66303, '지-그그... 바하하하!'),
(66304, '이봐, 친구. 너… 여기 경비원들을… 그냥… 간지럽히면 안 돼! 하하!'),
(66305, '너… 내가 간지럼 저항력 +10이 붙은 갑옷을 입고 있다는 거 알지?'),
(66306, 'ㅋㅋㅋ'),
(66307, '트롬카!')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66308, '록타르!'),
(66309, '록타르 오가르!'),
(66310, '여행자님, 환영합니다.'),
(66311, '너무 오래 머물지 마세요, 전쟁의 길은 결코 끝나지 않습니다!'),
(66312, '문제를 일으키지 마세요.'),
(66313, '힘과 명예!'),
(66314, '승리와 영광!'),
(66315, '내 목숨은 호드를 위해 바친다!'),
(66316, '대족장을 위하여.'),
(66317, '피와 천둥!'),
(66318, '거기서 죽지 마세요!'),
(66319, '다음에 돌아올 땐 네 몸에 흉터가 있는 걸 보고 싶어!'),
(66320, '항상 경계하십시오.'),
(66321, '호드에 영광을 가져다주세요!'),
(66322, '가서 적들을 처치해! 쓸데없는 소리 하지 마.'),
(66323, '농담은 다른 사람한테 해, 나 바빠!'),
(66324, '바하하!'),
(66325, '그럴 시간 없어! 박살내고 파괴하고... 어... 오... 반짝반짝하네...'),
(66326, '당신은 수많은 전투를 치르셨겠군요!'),
(66327, '당신 같은 사람이 더 많아야 합니다.'),
(66328, '네가 강하다고 생각하니? 내가 진짜 강한 게 뭔지 보여줄게! 하하하!'),
(66329, '진정한 투사시군요! 우리 편에 합류해 주셔서 감사합니다!'),
(66330, '하! 드레나이가 너보다 근육이 더 많다고! 바하하하하'),
(66331, '제 말을 믿으세요... 이 일은 절대 시작하고 싶지 않을 거예요.'),
(66332, '전투 중에는 무기가 부러져야 합니다!'),
(66333, '내가 당직이 아니었다면 네 목을 나뭇가지처럼 부러뜨렸을 거야!'),
(66334, '너 같은 노움은 싸움을 걸려고 해서는 안 돼.'),
(66335, '날 건드리지 말고 왜 군대나 지휘하지 그래!?'),
(66336, '날 건드리지 마!'),
(66337, '다 하셨나요?'),
(66338, '쿡쿡쿡 찌르기 - 그게 네가 하는 전부야?'),
(66339, '평화가 함께하길, 친구.'),
(66340, '바람이 당신을 인도합니다.'),
(66341, '어떻게 도와드릴까요?'),
(66342, '썬더블러프에 오신 것을 환영합니다! 절벽에서 멀리 떨어지세요!'),
(66343, '바람이 당신의 도착을 알렸습니다.'),
(66344, '대지모신가 당신을 보호해 주십니다.'),
(66345, '이쉬네알로 포르아'),
(66346, '바람 속에서 평화를 찾으시길 바랍니다.'),
(66347, '좀 진정하세요. 저희가 안전을 지켜드리겠습니다. 물론 절벽 근처에는 가지 않으시면요.'),
(66348, '대지모신가 이곳에서 당신을 안전하고 아늑하게 지켜주실 거예요.'),
(66349, '바위처럼 단단하고 바람처럼 자유로운, 여행자여, 우리가 당신을 지켜드리겠습니다.'),
(66350, '대지모신와 함께 걸으세요.'),
(66351, '바람이 등 뒤에서 불어오길 바랍니다.'),
(66352, '영원한 태양이 당신을 비추기를.'),
(66353, '영원한 태양이 당신을 비추기를.'),
(66354, '작별!'),
(66355, '반갑습니다, 여행자님.'),
(66356, '승리의 기쁨을 계속 누리세요, 친구여.'),
(66357, '호호호호. 다른 사람들에게도 꼭 알려줘야겠어!')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66358, '웃으면 안 되는데... 흠... 흠흠.... 호하하하!'),
(66359, '아… 농담이었어요. 하하… 하… 그렇게 재밌진 않았죠.'),
(66360, '엘리베이터 타고 여기까지 올라오셨어요? 땀 한 방울 흘리지 않고도 걸어 올라올 수 있을 것 같은데요!'),
(66361, '대지모신시여, 전쟁터에서 당신과 맞서는 자는 누구든 불쌍하소서!'),
(66362, '그게 강하다고? 진정한 강함이 뭔지 보여주지!'),
(66363, '그만해, 다른 사람이 질투하잖아.'),
(66364, '아시다시피... 여기서 떨어지면 정말 깊어지죠.'),
(66365, '바람은 당신의 자만심을 기억할 것입니다!'),
(66366, '썬더블러프는 모두를 위한 고향입니다. 저를 다른 일로 몰아넣지 마세요.'),
(66367, '음메. 이제 만족하니?!'),
(66368, '하, 너 스스로 바보짓을 하는구나.'),
(66369, '호호호호!'),
(66370, '손가락이 바람처럼 빠르시네요! 하하하!'),
(66371, '그건 나한테 통하지 않아...'),
(66372, '자, 시작해 볼까! 깨어나라!'),
(66373, '시작 중...'),
(66374, '처리 중...'),
(66375, '미확인 생명체를 스캔 중입니다. 위협은 최소화되었으며, 범용 번역기가 작동 중입니다.'),
(66376, '시스템 온라인 상태입니다. 분석기 X-51도 온라인 상태입니다. 메모리 뱅크 사용이 현재 제한되어 있습니다. 어떻게 도와드릴까요?'),
(66377, '작동한다! 말도 한다! 어떻게 된 건지 모르겠지만 우리를 스캔해서 우리 언어를 배웠어! 놀랍군! 흠... 넌 뭐야?'),
(66378, '저는 분석기 X-51입니다. 제 주된 목적은 시스템과 메커니즘을 분석하여 결함을 파악하는 것입니다. 예를 들어, 당신은 본래의 목적을 잃고 나약하고 유기적인 존재로 변모했습니다.'),
(66379, '뭐라고요? 잠깐, 당신은 당신이... 원래 그놈족의 모습이라는 말인가요?'),
(66380, '기본 설계는 비슷하네요. 하지만 당신이 분석가인지는 확신할 수 없습니다. 사실, 당신의 구조를 보면 애초에 어떤 목적을 부여받았는지조차 알 수 없네요. 더 자세한 정보가 필요합니다.'),
(66381, '정말 놀랍네요. 더 말씀해 주실 수 있나요? 어디에서 근무하셨나요? 이곳 시설에 배치되셨던 건가요? 혹시 당신과 같은 분들이 더 계신가요?'),
(66382, '제 팔다리는 서로 다른 모델의 부품으로 이루어져 있고, 몸통은 이 몸에 맞게 설계되지 않았습니다. 저와 같은 사람들이 존재했거나 존재할 가능성이 높다고 생각합니다. 나머지 질문에는 답할 수 없습니다. 제 기억의 97%는 접근이 제한되어 있습니다.'),
(66383, '그것들을 제한 해제할 방법이 있을까요?'),
(66384, '안 됩니다. 추가 구성 요소 설치, 즉 활성화 키가 필요합니다.'),
(66385, '힘의 물약이라고?! 하즈고르그가 주제 파악을 제대로 했군, 하하!'),
(66386, '추가 지시나 문의 사항이 있으시면 언제든지 말씀해 주십시오.'),
(66387, '하하! 그럼 켜 봐!'),
(66388, '미확인 생명체를 스캔 중입니다. 위협은 최소화되었으며, 범용 번역기가 작동 중입니다.'),
(66389, '시스템 온라인 상태입니다. 분석기 X-48도 온라인 상태입니다. 메모리 뱅크 사용이 현재 제한되어 있습니다. 어떻게 도와드릴까요?'),
(66390, '와! 타이타닉호 번역기라도 있어야 하나 싶었어. 야, 친구! 금이랑 희귀 기술 장비 어디서 찾을 수 있는지 알려줘!'),
(66391, '저는 분석기 X-48입니다. 제 주된 임무는 시스템과 메커니즘을 분석하여 그 안에 있는 결함을 파악하는 것입니다. 예를 들어, 당신의 순수한 탐욕과 기술에 대한 갈망은 잘못된 것이며 파멸로 이어질 수 있습니다.'),
(66392, '뭐라고? 지금 날 깔보는 거야?! 내가 너한테 생명을 줬잖아? 네가 일할 수 있게 하려고 시간, 노력, 그리고 돈까지 쏟아부었는데, 좀 도와줘 봐. 걱정하지 마, 내 욕심이 아무리 커도 괜찮을 거야. 돈만 충분히 모으면 이 욕심도 사라질지도 몰라. 그러니까, 도와줘도 좋아.'),
(66393, '당신의 진심을 의심스럽지만, 어쨌든 당신에게 큰 은혜를 입었습니다. 더 많이 도와드리고 싶지만, 현재 제 메모리 저장소에 접근이 제한되어 있습니다. 제 메모리 저장소의 98%가 잠겨 있어 사용하려면 키가 필요합니다.'),
(66394, '열쇠요? 엥? 그런 열쇠를 어디서 구하죠? 당신 머리를 열 다른 방법이 있나요? 만약 우리가 그 방법을 찾으면 도와주시겠어요?'),
(66395, '제가 아는 한 다른 방법은 없습니다. 제 안에 있는 기억을 되살릴 열쇠가 필요합니다. 기억을 되찾으면 저를 재건해 주신 대가로 당신이 찾는 지식을 알려드리겠습니다.'),
(66396, '이 지식이 뭔지 아세요? 당신의 분석 능력이 도움이 될 수도 있고, 도박이나 광물 탐사 같은 걸로 돈을 좀 벌 수도 있겠지만, 좀 더 실질적인 걸 원해요. 혹시 당신만의 설계도를 가지고 계신가요?'),
(66397, '제 제한된 기억 저장소에 어떤 지식이 저장되어 있는지는 저도 모릅니다. 하지만 기억이 제한되어 있다는 점을 고려하면, 제 동족에게는 매우 귀중한 비밀일 것이라고 추측합니다. 따라서 설계도나 기술, 또는 다른 중요한 정보들이 담겨 있을 가능성이 있습니다.'),
(66398, '좋아! 이봐 파트너, 이리 와서 나랑 얘기 좀 해! 분석가, 넌 좀 쉬어도 돼. 나중에 얘기하자.'),
(66399, '네, 대기하겠습니다.'),
(66400, '배에 손님이 왔어요! 본토 사람들을 밀어내야 해요!'),
(66401, '당신은 누구죠? 싸움도 없이 내 배를 빼앗을 수 있다고 생각하는 겁니까?!'),
(66402, '이 비열한 놈아, 넌 나한테 절대 못 이길 거야!'),
(66403, '죽을 준비를 해라!'),
(66404, '우는 민들레라니? 자네가 낭만적인 사람인 줄은 몰랐네. 좋아, 그럼 이제부터 배 이름을 그렇게 짓겠다고 선원들에게 알려두지.'),
(66405, '나는 신비와 초록빛 안개에 휩싸인 머나먼 땅에서 왔습니다. 당신은 이해할 수 없는 이들, 그리고 이 신비로운 땅에 사는 이들의 축복을 받았습니다. 나는 친족으로부터 버림받았고, 새로운 삶의 목적을 찾아 이곳에 왔습니다. 그리고 그 목적은 바로 이 섬들에서 발견되었습니다.'),
(66406, '서서히, 날마다 어둠이 밀려왔다. 나와 닮아 있는 힘이 내가 세운 통치에 감히 도전해 들어왔다. 나는 조금씩 이 한심한 권력 과시 싸움에서 패배할 운명이었다. 지역 주민들을 내 편으로 끌어들이려는 시도는 결국 실패로 돌아갈 것이다.'),
(66407, '결국, 나는 내 추종자들에게 내 힘의 비밀을 전수할 수 없었다. 결국, 대부분의 추종자들과 숭배자들은 이 어둠의 에너지가 가져다주는 영광을 누리기 위해 물러났다. 이제 나는 복수를 다짐한다. 이 땅에서 다시 한번 내 왕좌를 되찾으려 한다. 필멸자들이여, 내 말을 이해하겠느냐?')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66408, '자, %s여. 이제 이 악을 몰아낼 때다.'),
(66409, '우리는 카존 섬의 중심부로 가야 합니다. 그곳에서 저는 라피디스와 길리짐 두 신의 에너지를 끌어낼 수 있습니다.'),
(66410, '저의 에너지와 다른 사람들의 에너지를 합쳐 이 땅을 괴롭혀 온 부패를 뿌리뽑을 수 있을 것입니다.'),
(66411, '자, 이제부터 저 존재를 물리적 형태로 불러내려면 상당한 집중력이 필요할 겁니다. 저 존재를 약화시키는 건 당신에게 달려 있습니다! 충분히 약해지면 저도 당신과 합류할 수 있을 겁니다. 그때까지 저를 보호해 주세요!'),
(66412, '너희들은 누구냐, 침입자들아? 너희들이 내 계획을 막을 수 있다고 생각하는 거냐?'),
(66413, '다 끝났어! 어둠이 사라졌어. 네 눈앞에서 어둠이 사라지는 게 느껴지니? 난 동굴로 돌아갈 거야. 거기서 만나자.'),
(66414, '누가 너를 이 탑에 들여보냈어?! 네가 지금 누구랑 엮이고 있는지 알아?!'),
(66415, '알잖아... 아무것도 아니야... 난 너희 모두보다 더 강력했어.'),
(66416, '보이는군요... 눈부시게 빛나는 도시... 사람들로 가득하네요.'),
(66417, '그들은 죽어가고 있다... 거대한 파도가 그들을 모두 삼켜버린다.'),
(66418, '마법의 에너지가 약해지고, 푸른 수정들이 솟아오르고... 굉음이 들려온다.'),
(66419, '용의 그림자인가...?'),
(66420, '이게 다야... 나 좀 쉬어야겠어.'),
(66421, '쿠키는 슬픈 눈빛으로 그레이슨을 바라보며 손을 흔들어 그를 돌려보낸다.'),
(66422, '므르글?'),
(66423, '쿠키, 정말 미안해! 꼭 바로잡을게. 잘 가, 친구.'),
(66424, '당신에게 거짓말을 하고 권력을 위해 당신을 이용한 것에 대해 사과드립니다. 부디 이해해 주십시오. 그 모든 것은 지역의 더 큰 이익을 위한 것이었습니다.'),
(66425, '이곳을 떠나! 떠나! 이곳이 우리를 삼켰듯이, 너도 삼킬 거야!'),
(66426, '어이! 자, 이제 럼주 마시면서 신나게 놀아보자!'),
(66427, '요호호!'),
(66428, '아즈샤라의 영혼들이여, 나의 부름에 응답하소서. 이 땅에 무슨 일이 벌어지고 있는지 말해 주소서.'),
(66429, '저는 한때 섀도우포지 광부 조합의 최고 감독관이었습니다. 저와 제 부하들은 도시의 많은 건물들을 짓는 데 일조했고, 상원 의원들의 음모와 변덕을 잠재우기 위해 끊임없이 노력했습니다. 우리는 충성을 다했고, 그에 대한 대가로 복지 혜택을 받으며 열심히 일했습니다.'),
(66430, '그때 원로원의 계획은 실패했고, 학장님은 화가 나서 우리에게 점점 더 분노를 품기 시작했습니다. 헤이트포지 채석장 프로젝트는 많은 사람들을 한계까지 몰아붙였고, 과거의 잘못은 전혀 고려하지 않은 채 위험한 환경에서 일하도록 우리를 고향에서 멀리 떨어뜨려 놓았습니다.'),
(66431, '우리는 불가능한 임무를 부여받았고, 그 모든 책임은 내게 돌아갔다. 동료 광부들 중 많은 이들이 나를 배신했고, 새로운 반장이 내 자리를 대신했다. 충성을 유지한 이들은 노예가 되었고, 나머지는 추방당했다. 우리는 며칠 동안 추방된 채 길을 헤매다 많은 이들이 목숨을 잃었다.'),
(66432, '나는 배신당하고, 뒤통수를 맞고, 억울한 일을 당했다. 내 심장은 검은바위 산보다 더 뜨겁게 타오르고, 복수를 갈망한다. 내가 왜 도움을 청하는지 알겠나? 너도 검은무쇠 가문을 막아야 할 이유가 있겠지. 내가 네 손을 이끌게 해 주겠다. 그러면 우리 둘 다 만족할 수 있을 것이다.'),
(66433, '함께 일할 수 있어서 영광이었습니다.'),
(66434, '이상하지만... 기발하네요.'),
(66435, '정말? 고블린들은 미쳤어.'),
(66436, '그러니까 가능성이 있다는 거죠...'),
(66437, '준비하세요! 이제 골렘을 활성화시키겠습니다! 골렘의 주의를 끌면 제가 재배선 마법을 시전하겠습니다. 골렘에게 너무 많은 피해를 주지 마세요. 온전한 상태로 유지해야 합니다!'),
(66438, '성공했어요!'),
(66439, '글씨가 엉망이네, 마치 눈이 먼 사람이 쓴 것 같아. 자, 들어봐. 잘 들어.'),
(66440, 'G에게 다크샤이어 사람들이 점점 맛있어지고 있다고 전해줘. 아, 수상해 보여서 미안.'),
(66441, '야간 경비대가 매일 내 오두막을 감시하고 있어. 룬 제작을 계속하려면 어서 이사를 가야겠어.'),
(66442, '누군가를 보내라. 스톰윈드는 함락될 것이다, 어쩌고저쩌고, F.W. 끝.'),
(66443, '흥미로운 얘기군, 친구. 자네와 휴엔이 곤경에 처할지도 모르겠군. 하지만 그건 내 알 바 아니지.'),
(66444, '이 심장 속에 담긴 힘이 나를 도울 것이지만, 너무 약하고 희미해졌어. 내가 진정으로 마법을 익히려면 훨씬 더 강력한 무언가가 필요해.'),
(66445, '내 혈관에 힘이 흐르는군! 더욱 강해지고, 강력해진 기분이야! 이 힘으로 적들을 제압할 것이다!'),
(66446, '호드의 전사이자 마지막 숨을 거둘 때까지 병사였던 라즈골의 이름으로. 편히 가거라, 친구여. 너는 결코 잊혀지지 않을 것이다.'),
(66447, '당신이 없었더라면 우리의 계획은 분명히 발각되었을 겁니다. 당신의 도움에 진심으로 감사드립니다.'),
(66448, '네가 행한 행동으로 네 이름은 영광스럽게 울려 퍼질 것이다. 조용히 걸어가라, 호드의 고귀한 용사여.'),
(66449, '나는 자유다! 마침내 그 저주받은 형체에서 벗어났다!'),
(66450, '반지를 받으세요. 저는 도저히 쳐다볼 수가 없네요. 모든 것에 감사드립니다. 마음이 좀 진정되면 떠나겠습니다.'),
(66451, '오, 강력한 로아여! 적들을 쳐부수세요!'),
(66452, 'Dunemaul의 다 오우거들. 저주해라!'),
(66453, '네 분노를 그들에게 느끼게 해 줘...'),
(66454, '바이스클로, 내 사랑. 오늘 잔치야!'),
(66455, '착한 아이.'),
(66456, '처음 이 숲을 누비던 시절에는 나를 따르는 무리가 있었다. 그들은 나의 혈육이었고, 충성스러웠다. 하지만 그들의 불완전함에 싫증이 나기 시작했고, 혼자라면 더 잘할 수 있을 거라고 생각했다. 사냥도 하고, 영광스럽게 싸우기도 했지만, 결국 가까운 자들을 버렸다.'),
(66457, '나는 곰 떼의 매복 공격을 받아 바로 이 폭포로 도망쳤고, 그곳에서 궁지에 몰려 홀로 남겨져 죽임을 당했다. 그리고 이제 완전히 다른 모습으로 이 세상을 걷고 있다. 만약 내가 충성을 지키고 무리와 함께 있었더라면, 아마도 비극적인 최후를 맞지 않았을 것이다. 젊은이여, 내가 너에게 가르치는 것이 무엇인지 알겠느냐? 너는 산처럼 강할 수 있지만, 혼자라면 결국 쓰러질 것이다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66458, '테라모어는 약했다. 호드 편에 서는 것은 배신이다. 그토록 많은 이들이 죽었다! 우리는 그렇게 쉽게 멈추지 않을 것이다. 복수심에 불타는 항해사는 결코 잊지 않을 것이다!'),
(66459, '아, 맞아요. 최근에 상당한 병력이 이쪽으로 이주해 왔죠... 아주 최근에 말이에요. 그들은 그림토템 타우렌인데, 제가 알기로는 호드와 사이가 안 좋아요. 잘 됐네요. 걔네끼리 싸우게 놔두세요.'),
(66460, '타우렌이라고요? 글쎄요, 여기서는 정말 오랜만에 보네요. 북쪽 그림토템에 대해 들어본 것 같은데... 브래큰월 마을 근처에서 물어보시는 게 더 나을 거예요. 혹시 새로 온 타우렌에 대해 아는 사람이 있을지도 몰라요.'),
(66461, '음... 생각해 보니, 최근에 여기 오는 타우렌은 본 적이 없네. 브래큰월 마을은 외딴 전초기지라서 교역할 물건도 거의 없거든. 그런데, 브래큰월에 타우렌 한 명이 살았던 게 기억나네. 공성전 때 우리 둘이서 나란히 싸웠었는데... 정말 오랜만에 보네. 아마 늪에 빠져 죽었겠지.'),
(66462, '오, 당신은 그렇게 하면 후회할 거예요, 여보.'),
(66463, '당신이 해주신 모든 것에 감사드립니다. 그 교회에서 쌓은 추억들은 결코 잊지 않겠습니다. 그리고 시간이 흘러 땅이 회복되고 작물이 자라나면 그곳에서 더 많은 추억을 만들 수 있기를 바랍니다. 만약 신의 은총이 있다면, 그런 미래가 우리에게 있을지도 모릅니다. 안녕히 계세요, 부디 안전한 여정을 함께하시길 바랍니다.'),
(66464, '당신의 도움이 없었더라면 우리는 모든 걸 처음부터 다시 시작해야 했을 거예요. 그 망할 독수리들이 모든 걸 망쳐놨어요!'),
(66465, '이제 당신은 축복받은 자입니다. 당신은 우리 동족의 지구 방랑자이며, 외부인으로서 우리 가운데 처음으로 발을 디딘 자입니다. 우리는 당신과 겔키스 대의를 위한 당신의 도움에 경의를 표합니다.'),
(66466, '자네 덕분에 이 늙은이가 정말 자랑스럽네, 꼬마야... 유전 지대를 마치 자기 집처럼 접수했을 뿐만 아니라, 직원들까지 포함해서 자랑스럽게 노조에 넘겨줬잖아. 맞아, 생존자들 중 일부는 우리와 함께하기로 했어! 자네 덕분에 우리 작은 마을이 조금 더 안전해졌네, 뭐, 최대한 안전하게 말이지!'),
(66467, '모든 게 잘 되고 있어. 맥주도 마시고, 남쪽 아가씨들도 구경하고, 육지에서 날씨도 즐기고 있지. 그는 내가 외국에서 문제를 일으키지 않는다는 걸 알아야 해.'),
(66468, '저 잘 지내는지 확인하러 오셨다고요? 하하! 전 아무 문제도 일으키지 않았어요. 그 착한 척하는 밀도우는 좀 즐기는 법을 배워야 할 텐데요. 전 그냥 구경하는 중이에요. 여기는 보랄루스랑은 참 많이 다르잖아요.'),
(66469, '몇 주 전, 쿨 티라스는 볼바르 포드라곤의 제안으로 스톰윈드 시에 대사관을 개설할 수 있게 되었는데, 이는 두 나라 간의 외교 관계 개선을 위한 시도였다.'),
(66470, '상황이 꽤 순조롭게 진행되는 것처럼 보이지만, 쿨 티라스가 여전히 자신들의 이상과 전통, 명예에 대한 신성함, 그리고 전사자에 대한 존경심을 고수하고 있다는 것은 많은 이들이 분명히 알고 있으며, 그들의 가치는 가장 고귀한 성기사들과 비견될 만합니다.'),
(66471, '현재로서는 합의된 바가 없으며, 스톰윈드는 정당한 이유 없이 전쟁에 휘말리고 싶지 않습니다. 저는 믿을 만한 소식통과 정보에 따르면 쿨 티라스와 얼라이언스 사이에 이 문제에 대한 협력은 없다는 것을 알려드립니다. 당신들이 직면한 이 \'침공\'은 스랄이 알아서 처리해야 할 문제이며, 그가 적절하다고 판단하는 방식으로 대처할 것입니다.'),
(66472, 'SI:7은 양측의 이익을 위해 이 정보를 전달할 수 있는 명확한 권한을 제게 부여했습니다. 이 내용을 당신의 지도자에게 전달하고 알려주십시오.'),
(66473, '바하! 진정한 호드의 병사로군! 강인한 의지와 투지를 가진 자여, 쿨 티란 놈들은 자네에게 상대가 안 될 걸세!'),
(66474, '듀로타는 굳건히 서 있다. 어떤 인간도 호드의 막강한 힘을 꺾을 수 없다!'),
(66475, '맞아, 온몸으로 느껴져! 음... 기분이 묘하고 좋아. 하즈고르그에게 물약 고마워한다고 전해줘. 아까 그가 했던 말을 곰곰이 생각해 봤는데, 마울오그는 적을 박살내기보다는 푹 쉬면서 영토를 확장하는 전략을 생각해 보는 게 좋을 것 같아.'),
(66476, '고울팽은 최강의 왕이다. 감히 고울팽에게 도전할 자는 아무도 없다!'),
(66477, '당신은 테라모어를 안전하게 지켜냈습니다. 영광이 당신을 따르기를 바랍니다.'),
(66478, '저는 테라모어의 정찰병 팔그란 하스틸입니다. 이 회의를 소집하신 이유가 무엇입니까?'),
(66479, '우리는 당신이 여관을 조사하는 것을 보았습니다. 이것은 호드의 소행이 아니라는 것을 확신시켜 드리고 싶었습니다.'),
(66480, '우리는 여관 벽에 묶여 있는 이 방패를 발견했습니다. 혹시 이 물건에 대해 기억나는 것이 있으신가요?'),
(66481, '어디 보자.'),
(66482, '카고로는 방패를 꼼꼼히 조사한다.'),
(66483, '선조들의 이름으로. 그래, 이 방패를 알아. 브래큰월 마을에 살았던 타우렌 전사 와타포의 것이었지. 그는 오래전에 세상을 떠났어.'),
(66484, '그게 어떻게 여관에 오게 됐는지 아세요? 우리가 그의 무덤을 찾았는데, 최근에 파헤쳐진 흔적이 있었어요.'),
(66485, '전사한 전사의 무덤을 훼손하는 일은 결코 알지 못합니다.'),
(66486, '누군가 우리에게 여관 화재의 책임을 당신에게 지우려고 했던 것 같습니다.'),
(66487, '그렇군요. 조사 과정에서 다른 발견 사항은 없으셨나요?'),
(66488, '네, 쇠물멧돼지 발자국이네요...'),
(66489, '잘못된 단서.'),
(66490, '너도 일을 좀 했구나.'),
(66491, '카고로는 고개를 끄덕인다.'),
(66492, '그리고 이건 탈영병 중 한 명의 배지입니다. 파발 레테의 배지죠. 하지만 레테는 찾을 수가 없었어요. 혹시 보신 적 있으세요?'),
(66493, '이건… 좀 민감한 문제이고, 제가 회의를 소집한 진짜 이유이기도 합니다. 파발 레테가 죽었습니다.'),
(66494, '그는 탈영병이었습니다. 저는 여전히 그를 체포하여 공정한 재판을 받게 하고 싶었지만, 당신이 그를 죽였다는 것을 이해합니다. 우리는 당신을 비난하지 않습니다.'),
(66495, '일이 그렇게 간단하기만 하면 좋았을 텐데. 우리는 그가 여관 방화 사건과 연관되어 있다는 것을 알고 있었고, 그를 조사하고 싶었다. 그가 말을 꺼내기도 전에… 우리는 공격을 받았다. 테라모어 병사들이었다. 그중 한 명의 이름은 콜드웰이었다.'),
(66496, '공격당했다고? 아무 이유 없이, 테라모어 병사들에게? 빛의 신께 맹세하건대, 오크 자식아. 네가 거짓말을 하고 있다면...'),
(66497, '나는 내 조상들과 나의 대족장을 걸고 맹세한다. 그들은 냉혹하게 그를 죽였다. 빠른 화살이 그의 심장을 꿰뚫었다. 우리도 간신히 살아남았다.'),
(66498, '테라모어 군인들은 절대… 우리가 조사해 보겠습니다. 하지만 당신의 말이 사실이 아니라는 것이 밝혀진다면…'),
(66499, '전우들을 잃으신 데 대해 깊은 유감을 표합니다. 당신이 이 사건을 조사하는 동안, 우리는 다른 단서를 추적하겠습니다. 검은용군단입니다.'),
(66500, '우리는 테라모어에서 조사를 진행할 것이다. 하지만 오크, 경고한다. 네 이야기는 앞뒤가 맞지 않는다.'),
(66501, '더 자세한 내용을 알게 되면 여기서 다시 만나요. 당신의 돌의 도시에서 진실을 찾을 수 있기를 바랍니다.'),
(66502, '카고로! 준비됐어.'),
(66503, '팔그란.'),
(66504, '카고로, 얼라이언스과 테라모어 시를 대표하여 당신을 믿지 않고 거짓 비난을 했던 것에 대해 사과드립니다. 이제 우리는 탈영병들이 여관에 불을 질렀다는 것을 확신합니다.'),
(66505, '다행이네요. 블랙 드래곤에 대한 저희 조사에서는 아무런 성과도 없었습니다. 그런데 어떻게 진실을 알게 되셨습니까?'),
(66506, '물론 마법의 힘을 통해서죠. 점술을 통해서요. 우리는 파발 레테의 영혼과 교감했습니다.'),
(66507, '정말 놀랍군. 역시나 마법이 대단해. 그런데... 왜? 왜 여관을 불태운 거지?')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66508, '자, 여기서부터 좀 복잡해집니다. 탈영병들은 여관의 단골손님들이었습니다. 술에 취한 그들은 여관 주인에게 무언가를 고백했습니다. 그 사실이 테라모어에 알려질까 두려워, 그들은 여관 주인을 죽이고 거짓 증거를 남기기로 했습니다.'),
(66509, '방패... 네, 일리가 있네요.'),
(66510, '파발 레테는 그들을 막고 싶었다. 그는 탈영병이었지만, 마음속에는 아직 약간의 명예가 남아 있었다.'),
(66511, '그래서 그들은 그를 늪에 버려두고 간 것이다. 그런데 탈영병들에게 그토록 소중했던 정보는 무엇이었을까?'),
(66512, '이 부분에 대해서는 저희도 잘 모르겠습니다. 그들의 진짜 지도자로 알려진 \'복수심에 불타는 선원\'에 관한 이야기인 것 같은데, 혹시 들어보신 적 있으신가요?'),
(66513, '복수심에 불타는 선원... 오거들은 귀신에 홀린 선원이 해안을 공포에 떨게 한다고 말하지만, 관련이 있을지는 의문입니다.'),
(66514, '곧 탈영병들의 죄에 대한 정의를 구현할 것입니다. 카고로, 정보 주셔서 감사합니다. 호드는 이 땅에서 많은 도움을 주었습니다.'),
(66515, '우리는 당신들의 동맹과 마찬가지로 정의를 믿습니다. 명예롭게 나아가십시오, 친구.'),
(66516, '우리는 개런 바임스 선장에게 보고하고 우리가 발견한 내용을 알려야 합니다.'),
(66517, '제 형 다르니르는 용맹한 전사였으며, 함께 복무하던 동료들 사이에서 존경받는 인물이었습니다. 그는 가문의 도끼를 들고 이 먼 땅으로 건너와 제3차 대전쟁 동안 호드와의 전투에서 큰 공을 세웠습니다.'),
(66518, '호드와 얼라이언스 사이에 휴전이 체결되었고, 양 진영은 하이잘로 향했다. 내 동생은 이 전투에서 마지막 희생자 중 한 명이 될 운명이었다. \'스카터스크\'라는 사악한 오크가 매복 공격을 가해 우리 가문의 도끼를 빼앗아 갔기 때문이다.'),
(66519, '이 오크는 오늘날에도 살아 숨 쉬고 있다. 호드의 사면을 받았고, 여전히 내 형이 휘두르던 도끼, 우리 가문의 가보를 휘두르고 있다. 나는 무엇보다도 복수를 원한다.'),
(66520, '위로, 위로, 멀리!'),
(66521, '돌발톱 산맥 내부에 부패가 만연하다고? 놀랍지도 않다. 평화로운 잿빛 골짜기에서도 토착 종족들이 공격적인 모습을 보이기 시작했으니 말이다. 그중에서도 펄볼그가 가장 두드러진다.'),
(66522, '한때 우리의 동맹이었던 펄볼그는 이제 적이 되어, 눈에 보이는 대로 공격하고 주저 없이 싸움을 걸어온다. 많은 드루이드들은 자연 자체가 이러한 갈등에 적응하여 스스로를 보호하기 위해 더욱 적대적이고 고립되어 가고 있다고 말한다. 돌발톱 산맥도 그러한 사례일 수 있다.'),
(66523, '하지만 이곳 잿빛 골짜기에는 무언가 깊숙이 뿌리내려 우리가 신성하게 여기는 모든 것의 근간을 흔드는 것이 있습니다. 무엇인지는 모르지만, 분명히 느껴집니다...'),
(66524, '제가 아는 건 여기까지입니다. 말로란 씨에게 도움이 되기를 바랍니다. 우리 자연 수호자들은 항상 경계를 늦추지 말아야 합니다.'),
(66525, '이렇게 먼 길을 여행해 주셔서 감사합니다. 보내주신 정보는 매우 귀중할 것입니다. 이제 제가 문제의 근원을 찾아야 할 차례입니다.'),
(66526, '당신의 군대는 패배했고, 이제 당신은 코르탄의 왕 앞에 서 있습니다. 생존자들과 당신 자신의 목숨을 구하고 싶다면, 왕인 나에게 충성을 맹세해야 합니다.'),
(66527, '코르탄의 왕이시여, 당신께 충성을 맹세합니다.'),
(66528, '저는 충성을 다할 것입니다.'),
(66529, '저는 카고로입니다. 당신들이 여관을 조사하는 것을 보았습니다. 이것은 호드의 소행이 아니라는 것을 확신시켜 드리고 싶었습니다.'),
(66530, '우리는 여관 벽에 묶여 있는 이 방패를 발견했습니다. 혹시 이 물건에 대해 기억나는 것이 있으신가요?'),
(66531, '어디 보자.'),
(66532, '카고로는 방패를 꼼꼼히 조사한다.'),
(66533, '선조들의 이름으로. 그래, 이 방패를 알아. 브래큰월 마을에 살았던 타우렌 전사 와타포의 것이었지. 그는 오래전에 세상을 떠났어.'),
(66534, '그게 어떻게 여관에 오게 됐는지 아세요? 우리가 그의 무덤을 찾았는데, 최근에 파헤쳐진 흔적이 있었어요.'),
(66535, '전사한 전사의 무덤을 훼손하다니... 정말이지, 저는 그런 일에 대해 전혀 아는 바가 없습니다.'),
(66536, '누군가 우리에게 여관 화재의 책임을 당신에게 지우려고 했던 것 같습니다.'),
(66537, '그렇군요. 조사 과정에서 다른 발견 사항은 없으셨나요?'),
(66538, '네, 쇠물멧돼지 발자국이네요...'),
(66539, '잘못된 단서.'),
(66540, '너도 일을 좀 했구나.'),
(66541, '그리고 이건 탈영병 중 한 명의 배지입니다. 파발 레테의 배지죠. 하지만 레테는 찾을 수가 없었어요. 혹시 보신 적 있으세요?'),
(66542, '이건… 좀 민감한 문제이고, 제가 회의를 소집한 진짜 이유이기도 합니다. 파발 레테가 죽었습니다.'),
(66543, '그는 탈영병이었습니다. 저는 여전히 그를 체포하여 공정한 재판을 받게 하고 싶었지만, 당신이 그를 죽였다는 것을 이해합니다. 우리는 당신을 비난하지 않습니다.'),
(66544, '일이 그렇게 간단하기만 하면 좋았을 텐데. 우리는 그가 여관 방화 사건과 연관되어 있다는 것을 알고 있었고, 그를 조사하고 싶었다. 그가 말을 꺼내기도 전에… 우리는 공격을 받았다. 테라모어 병사들이었다. 그중 한 명의 이름은 콜드웰이었다.'),
(66545, '공격당했다고? 아무 이유 없이, 테라모어 병사들에게? 빛의 신께 맹세하건대, 오크 자식아. 네가 거짓말을 하고 있다면...'),
(66546, '나는 내 조상들과 나의 대족장을 걸고 맹세한다. 그들은 냉혹하게 그를 죽였다. 빠른 화살이 그의 심장을 꿰뚫었다. 우리도 간신히 살아남았다.'),
(66547, '테라모어 군인들은 절대… 우리가 조사해 보겠습니다. 하지만 당신의 말이 사실이 아니라는 것이 밝혀진다면…'),
(66548, '전우들을 잃으신 데 대해 깊은 유감을 표합니다. 당신이 이 사건을 조사하는 동안, 우리는 다른 단서를 추적하겠습니다. 검은용군단입니다.'),
(66549, '우리는 테라모어에서 조사를 진행할 것이다. 하지만 오크, 경고한다. 네 이야기는 앞뒤가 맞지 않는다.'),
(66550, '카고로, 얼라이언스과 테라모어 시를 대표하여 당신을 믿지 않고 거짓 비난을 했던 것에 대해 사과드립니다. 이제 우리는 탈영병들이 여관에 불을 질렀다는 것을 확신합니다.'),
(66551, '다행이네요. 블랙 드래곤에 대한 저희 조사에서는 아무런 성과도 없었습니다. 그런데 어떻게 진실을 알게 되셨습니까?'),
(66552, '물론 마법의 힘을 통해서죠. 점술을 통해서요. 우리는 파발 레테의 영혼과 교감했습니다.'),
(66553, '정말 놀랍군. 역시나 마법이 대단해. 그런데... 왜? 왜 여관을 불태운 거지?'),
(66554, '자, 여기서부터 좀 복잡해집니다. 탈영병들은 여관의 단골손님들이었습니다. 술에 취한 그들은 여관 주인에게 무언가를 고백했습니다. 그 사실이 테라모어에 알려질까 두려워, 그들은 여관 주인을 죽이고 거짓 증거를 남기기로 했습니다.'),
(66555, '방패... 네, 일리가 있네요.'),
(66556, '파발 레테는 그들을 막고 싶었다. 그는 탈영병이었지만, 마음속에는 아직 약간의 명예가 남아 있었다.'),
(66557, '그래서 그들은 그를 늪에 버려두고 간 것이다. 그런데 탈영병들에게 그토록 소중했던 정보는 무엇이었을까?')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66558, '이 부분에 대해서는 저희도 잘 모르겠습니다. 그들의 진짜 지도자로 알려진 \'복수심에 불타는 선원\'에 관한 이야기인 것 같은데, 혹시 들어보신 적 있으신가요?'),
(66559, '오거들은 귀신 들린 선원이 해안을 공포에 떨게 한다고 말하지만, 나는 그것이 관련이 있을 거라고 생각하지 않는다.'),
(66560, '음... 지금 우리는 탈영병들을 체포하는 데 집중하고 있습니다. 그들은 수렁 속에 은신처를 두고 있으며, 셀릭 보스라는 자가 그들을 이끌고 있습니다.'),
(66561, '셀릭 보스?'),
(66562, '셀릭 보스는 테라모어의 대장이었습니다. 그는 얼라이언스와 호드 사이에 적대감을 조장하려 했으며, 그의 행동으로 인해 많은 사람들이 목숨을 잃었습니다.'),
(66563, '우리가 \'셀릭 보스\'를 찾을 기회를 얻게 된다면, 호드는 더스트왈로우에 평화를 가져오는 데 도움을 줄 것입니다.'),
(66564, '자, 그럼 이 재가 정말 용이 만든 것인지 한번 봅시다...'),
(66565, '기지크는 현미경으로 물푸레나무를 자세히 관찰한다.'),
(66566, '음, 결국 내 생각이 틀렸던 것 같군. 이건 용의 불꽃이 전혀 아니었어!'),
(66567, '자, 이제 다 고쳐졌고, 타이밍도 딱 맞았네요! 이제 모든 게 안정되었는지 확인하기만 하면 돼요...'),
(66568, '아, 내 믿음직한 아크라이트 스패너야, 아빠 품으로 돌아온 걸 환영한다.'),
(66569, '드림 더스트를 사용하면 내 에너지를 바나나에 집중시켜 성장이라는 결과를 얻을 수 있습니다...'),
(66570, '텔아빔 바나나는 신비로운 에너지로부터 자라나기 시작합니다.'),
(66571, '하고 있어요! 조금만 더요!'),
(66572, '꿈의 가루를 첨가하면 성장이 가속화되어 곧 거대한 텔아빔 바나나가 됩니다.'),
(66573, '우리가 해냈어! 거대 바나나의 비밀이 드디어 밝혀졌고, 우리 손끝에 들어왔어! 오늘 우리가 한 일을 믿을 수 있겠어?! 도와준 보답으로, 언제든 내가 만들어 줄게. 필요한 재료만 가져오면 바로 네 거야.'),
(66574, '정말 이상한 개체군... 성장이 stunted(왜곡)되었고 필수 영양분도 부족하니, 이건 분명히 안 되겠어.'),
(66575, '타조 기어파이어는 거대 성장의 묘약을 바나나 위에 붓습니다.'),
(66576, '바나나가 부풀어 오르기 시작하고, 과도하게 부풀어 오르면서 껍질이 찢어지다가 결국 푹 꺼져 버립니다.'),
(66577, '음, 김빠지는 결말이었네...'),
(66578, '이렇게 훌륭한 샘플을, 바로 내 눈앞에 있는 섬에서 오랫동안 찾지 못하다니! 구해 주셔서 정말 감사드립니다.'),
(66579, '몇 주 전 일입니다. 저희는 예전에는 빅슬스 스토어하우스 주변, 북쪽 먼 곳에서 작전을 수행했는데, 좀 더 욕심을 내서 섬의 최북단에 있는 재기드 아일즈에 관심을 돌렸습니다.'),
(66580, '그곳에서 가장 큰 섬에서 나보다 더 큰 바나나를 발견했어! 뿌리와 덤불 속에 파묻혀 있어서 거의 옮길 수가 없었지. 그러다 원숭이들이 창고를 공격하는 소란스러운 소리가 들려서 곧 그곳을 떠났어.'),
(66581, '굳이 찾아보려 하지 마세요. 험준한 섬에는 멀록, 나가, 그리고 온갖 종류의 생물들이 우글거려서 시간 낭비일 뿐입니다.'),
(66582, '누가 내 안식을 방해하는가? 죽어서도 얼라이언스에 대한 의무를 져야 하는가? 부디 평안히 영혼의 세계로 가게 해다오.'),
(66583, '파발 레테. 당신은 살아생전 명예를 지키지 못했습니다. 친구와 가족을 버렸죠. 이제 당신에게는 명예를 회복할 기회가 왔습니다.'),
(66584, '너무나 당연한 거 아니야? 탈영병들이 한 짓이지. 난 아니야. 마지막 날들에 난 옳은 일을 했어. 그들을 막으려고 했지. 그래서 그들이 날 늪에 버려둔 거야.'),
(66585, '왜? 왜 그걸 불태웠지?'),
(66586, '셰이디 레스트 여관은 누구에게나 열려 있었습니다. 우리도 예외는 아니었죠. 우리는 그곳에서 많은 저녁 시간을 보내며 웃고 마시곤 했습니다. 그런데 어느 날, 우리 일행 중 몇 명이 너무 취해서 여관 주인에게 시비를 걸기 시작했습니다. 그러다 결국 너무 심한 말을 해버렸죠. 복수심에 불타는 선원에 관한 이야기였는데, 그 소문이 테라모어에까지 퍼지는 걸 막을 수 없어서 여관에 불을 질렀습니다. 목격자는 아무도 없었습니다.'),
(66587, '복수심에 불타는 선원?'),
(66588, '파발 리테는 크게 웃는다.'),
(66589, '당신은 이해하지 못할 거예요.'),
(66590, '파발 레테의 정신이 사라졌다.'),
(66591, '파발! 저주받을 놈, 돌아와! 리테!'),
(66592, '마법사 할리스터는 한숨을 쉬었다.'),
(66593, '음, 아무래도 그는 영영 우리 곁을 떠난 것 같군. 그래도 최소한 몇 가지는 알아냈으니 다행이지. 자, 이제 개런 바임스 함장에게 돌아가거라. 그가 다음 조치를 알 것이다.'),
(66594, '도와주신 모든 것에 감사드립니다. 이 기계를 사는 데 엄청난 돈을 썼는데, 지금 당장 더 많은 돈을 쓸 여유가 없네요.'),
(66595, '이처럼 엄청난 파괴력을 지닌 무기가 이제 당신의 손에 들어왔습니다. 부디 책임감 있게 사용해주시길 바랍니다. 만약 그렇지 않다면, 모든 책임은 당신에게 있으며, 저와는 아무런 상관이 없습니다!'),
(66596, '이봐, 꼬마야, 처음엔 솔직히 널 의심했고, 여기 있는 내내 의심했지만, 넌 결국 결과를 냈고, 그 망할 모로고를 처리해줬잖아. 오랜만에 이렇게 발을 딛고 일하는 사람이 생겨서 정말 좋군! 잘했어.'),
(66597, '나는… 자유로워졌습니다. 어둠의 카미가 나를 억압하던 손아귀에서 벗어났습니다. 낯선 이여, 이 은혜를 갚을 수는 없겠지만 진심으로 감사드립니다. 제 집은 마음대로 쓰셔도 좋습니다. 저는 더 이상 필요하지 않으니까요. 안녕히 계세요!'),
(66598, '임무 완수 잘했어, 신병! 쿨 티라스의 자랑이 됐군!'),
(66599, '지금 공기 중에 안도감이 느껴지시나요? 자부심을 느껴야 합니다.'),
(66600, '어이! 우리 언젠가 같이 명상해 볼까? 우리 성격이 비슷한 것 같아.'),
(66601, '티리스팔 평의회의 권한을 발동한다!'),
(66602, '아라날, 레델! 엔도렐 알루미늄, 엔달라 피넬 엔달!'),
(66603, '카라잔, 셀라마 앰오로노르! 팔라안두, 팔라.'),
(66604, '끝났습니다. 열쇠가 다시 온전해졌습니다.'),
(66605, '젠장... 내가 가진 재료가 부족한 것 같군... 잠깐만, 생각났다!'),
(66606, '젠장! 결국 그 빌어먹을 책이 필요하겠군.'),
(66607, '또 다른 자가 이 땅을 괴롭히러 왔단 말인가? 나는 다른 자와 장난칠 여유가 없다. 차갑고 황량한 땅에서 우리와 함께하자.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66608, '고대의 계약을 발동한다! 이세라여, 이 필멸자를 축복하소서. 그에게 에메랄드의 꿈에 대한 길을 열어 주소서!'),
(66609, '지금까지 훌륭히 임무를 수행해 왔고, 녹색용군단은 이미 당신에게 큰 빚을 졌습니다. 이에 당신이 우리의 신성한 영역에 들어오는 것을 축복합니다.'),
(66610, '각성을 막아라.'),
(66611, '편히 쉬세요, 프랭클린. 당신이 그리울 겁니다.'),
(66612, '어둠의 마법이 감돌고 있다. 그 의도는 불길하다...'),
(66613, '자, 이제 그 눈을 목격하세요!'),
(66614, '그렇군요... 전투는 고요했지만...'),
(66615, '이건 말도 안 돼. 그레이메인이... 그런 힘을 갖고 있다니.'),
(66616, '완료되었습니다! 결합에 에너지가 공급되었습니다!'),
(66617, '세나리우스의 축복을 받으며 걸으십시오. 고귀한 이여, 자연이 당신의 길을 인도하길 바랍니다.'),
(66618, '끝났습니다!'),
(66619, '마법사 할리스터는 신비로운 힘을 불러일으키기 시작하고, 그의 마법 시전은 영적인 영역의 에너지를 끌어낸다.'),
(66620, '그 혼합물이 격렬하게 폭발하면서 오르반은 피투성이가 되었다.'),
(66621, '상위 결속부가 에너지로 빛나기 시작한다.'),
(66622, '로레쉬의 송곳니를 뒤덮었던 어둠의 마법이 서서히 사라지기 시작한다.'),
(66623, '로레쉬의 송곳니에서 어둠의 마법이 사라진다.'),
(66624, '이제 너는 우리 편이다! 마그람에게 챔피언이 생겼다! 네가 우리를 승리로 이끌어 줄 것이다!'),
(66625, '오늘 폭정은 패배했다! 우리 땅은 숲을 오염시키고 수많은 무고한 사람들을 학살했던 악으로부터 해방되었다. 새로운 왕이 즉위했으니, 길니아스에 영광을!'),
(66626, '저는 에버윌 문시커를 대신하여 왔습니다. 그는 \'자연의 품어짐\'이라는 책을 빌리고 싶어합니다.'),
(66627, '자연의 활력소라니, 에버윌이라는 이름이 생각나네요. 그가 이걸 다 쓰면 꼭 돌려주길 바란다고 전해주세요.'),
(66628, '저는 상형문자를 구매하고 싶습니다.'),
(66629, '저는 \'느리고 꾸준한 챌린지\'를 이제 완전히 끝내고 싶습니다.'),
(66630, '저는 탈진 챌린지를 완전히 끝내고 싶습니다.'),
(66631, '전쟁 모드 도전을 끝내겠습니다.'),
(66632, '거북이의 문양에 대해 알려 주세요.'),
(66633, '탈진의 문양에 대해 알려 주세요.'),
(66634, '전쟁의 문양에 대해 알려 주세요.'),
(66635, '방랑자의 문양에 대해 알려 주세요.'),
(66636, '분석 칩을 빼내려고 시도하십시오.'),
(66637, '무왕이시여, 당신에게 도전하고 싶습니다.'),
(66638, '좋아, 젊은이...'),
(66639, '소 레벨로 순간이동시켜 주세요'),
(66640, '좋아, 시작하지!'),
(66641, '지금은 안 돼요, 잠시만 기다려 주세요.'),
(66642, '당신 형에게서 온 편지가 있어요.'),
(66643, '아놀드가 아직 어딘가에 살아있다는 건 알고 있었지만, 바다 한가운데 외딴 섬에 고립된다면 어떨지 상상도 할 수 없네요. 부디 무사히 집으로 돌아오길 바랍니다.'),
(66644, '당신에게 온 편지가 있습니다. 그에게 어서 전해 주십시오.'),
(66645, '아놀드에게서 온 편지... 나는 그가 바다에서 죽었다고 생각했어. 정말 오랫동안 소식을 듣지 못했거든.'),
(66646, '정말 좋은 소식이네요. 자, 이걸 그에게 전해주세요.'),
(66647, '뭐라도 사겠나?'),
(66648, '요리하는 법 좀 가르쳐줘, 친구!'),
(66649, '슬림이 소금을 달라고 하네요.'),
(66650, '좋아, 알았어. 하지만 그는 나한테 빚진 거야. 꼭 그에게 전해줘!'),
(66651, '물건을 보여 주세요.'),
(66652, '사우스시 리저브 레시피를 알려주면 살려줄게!'),
(66653, '좋아! 제발 그만해, 레시피 줄게!'),
(66654, '독성 곡물.'),
(66655, '물통에 물을 부으세요.'),
(66656, '화약에 불을 붙여라.'),
(66657, '럼주에 독을 넣으세요.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66658, '모건의 얼굴에 침을 뱉어라.'),
(66659, '저도 함께하고 싶어요.'),
(66660, '준비됐어요!'),
(66661, '나는 이 작품에 \'우는 민들레\'라는 제목을 붙일 거야.'),
(66662, '훌륭합니다, 선장님!'),
(66663, '베일을 높이 쓰고 블러드세일 해적단의 해적기 아래, 너의 이름으로 이 세상을 정복하라!'),
(66664, '내가 너의 고통을 끝내주겠다.'),
(66665, '자, 내 뛰어난 재능과 기발한 재치, 그리고 지략을 보라! 이 물건들만 있으면 다시 부자가 될 수 있다! 하하!'),
(66666, '흠... 아마 시간이 좀 걸리는 게 정상인가 보네요. 다른 방법을 생각해 봐야겠어요. 다시 한번 고마워요!'),
(66667, '다엘라 에버문이 당신이 괜찮은지 묻고 있었어요.'),
(66668, '누구야?! 에버문이 내가 약한지 묻는다고?! 에버문이 날 죽이려는 건가?! 넌 누구냐, 전령인가, 정찰병인가?'),
(66669, '내 약점을 캐낼 수 있다고 생각하는 거야?!'),
(66670, '당신의 이야기를 들을 준비가 되었습니다.'),
(66671, '우리는 함께 이 악을 몰아내야 합니다.'),
(66672, '자, 이제 다 됐습니다. 열쇠가 맞춰졌으니, 필요한 대로 사용하세요. 어떤 용도로 사용하시든 유용하게 쓰이길 바랍니다.'),
(66673, '필멸의 존재여, 자네에게 고백해야 할 것이 있네. 나는 정보를 숨기는 자도 아니고, 아무 이유 없이 거짓말을 하는 자도 아니네. 나는 가라앉은 사원 깊은 곳에서 예언자 자말란이 죽은 데에는 여러 가지 이유가 있었네.'),
(66674, '저는 전투형 드레드로드를 찾고 있습니다.'),
(66675, '느껴지지, 그렇지? 지식이 네 마음속에서 솟아오르고, 내 마법의 본질이 네 생각에 달라붙는 것을. 너는 동족에게 금지된 지식을 선물 받았고, 네가 이 검을 만들어내는 순간, 그 지식은 영원히 잊혀질 것이다.'),
(66676, '도움을 요청하러 왔습니다. 혹시 예전에 오크 검술의 달인을 만난 적이 있으신가요?'),
(66677, '음, 말씀하시니 그런 인물이 생각나네요. 근육질의 오크였는데, 꽤 친절했죠. 몇 년 전 악마 침공 때였는데, 마지막으로 봤을 땐 아르코란 사원에서 전투를 벌이려고 하더군요. 도움이 되셨으면 좋겠습니다.'),
(66678, 'Shattered Strand로 순간이동하세요.'),
(66679, '아르코란 사원으로 순간이동하세요.'),
(66680, '티자 아샨 달라샤.'),
(66681, '크룩조그 경, 저는 하즈고르그를 대신하여 왔습니다. 그는 당신의 무모한 공격을 중단해 달라고 간청하고 있습니다.'),
(66682, '크룩조그 님, 하즈고르그께서 당신의 막강한 힘을 더욱 강화시켜 줄 이 힘의 물약을 전해달라고 부탁하셨습니다!'),
(66683, '하하!'),
(66684, '저는 위대한 예언자 하즈고르그를 대신하여 크룩조그 경과 관련된 상황을 해결하기 위해 파견되었습니다.'),
(66685, '한동안 하즈고르그와 이야기를 나누지 못했지만, 내 백성들도 그와 마찬가지로 암흑기를 맞고 있으며 폭군의 지배를 받고 있다. 나는 더 이상 아무런 권력도 없지만, 만약 내가 마울로그를 도울 수 있다면 더 큰 선을 위해 무언가를 한 것이라고 생각한다.'),
(66686, '폭군이 권력을 잡기 전에, 나는 그의 마음을 움직여 덜 적대적인 방법을 찾도록 유도하는 묘약이나 물약, 혹은 마법을 만들어 볼까 생각했었다. 어쩌면 이것이 크룩조그 경이 광기에 휩싸이는 것을 막고 진정시키는 데 효과가 있을지도 모른다. 이 정보를 하즈고르그에게 가져가면, 그가 내가 알아내지 못한 무언가를 찾아낼 수 있을지도 모른다.'),
(66687, '타크가르 딥헤이트.'),
(66688, '고인을 기리셨으니, 그의 영혼이 동료 스승들에게 무사히 인도되기를 바랍니다.'),
(66689, '해냈다! 신비로운 힘이 내 혈관을 타고 흘러넘쳤고, 한때 열쇠에 깃들어 있던 마법을 되살릴 수 있었다. 이제 호드의 보호가 우리의 생각을 지배하고 다음 발걸음을 인도할 것이다.'),
(66690, '자, 됐습니다! 상당한 집중력이 필요했지만, 열쇠에 마법을 걸 수 있었어요. 이제 카라잔 지하에 도사리고 있는 악에 집중할 수 있겠군요.'),
(66691, '이눈쿠아크로 여행할 준비가 됐어요, 출발합시다!'),
(66692, '이눈쿠아크, 나는 다크쇼어로 돌아가고 싶다'),
(66693, '나를 베시에게 순간이동시켜줘'),
(66694, '저는 아즈렐스톤에 얽힌 이야기를 듣고 싶습니다.'),
(66695, '아주 오래전, 우리는 아이언포지의 지하 통로를 파헤치던 중 푸른 보석을 처음 발견했습니다. 처음에는 그저 아름다운 푸른 보석으로 여겨졌고, 자연적인 가치를 지닌 것으로 생각되었습니다. 하지만 얼마 지나지 않아, 마법에 천부적인 재능을 가진 한 드워프가 푸른 보석의 힘을 발견하게 되었습니다.'),
(66696, '후이드그라르 아주르브로우는 푸른 돌을 연구하고 그 힘을 다른 이들에게 가르쳤으며, \'푸른 돌\'이라는 이름은 그의 이름에서 유래했습니다. 그의 제자들은 \'푸른 돌 기사단\'을 창설했습니다. 푸른 돌 기사단은 세 망치의 전쟁부터 오크들이 아이언포지에 근접했을 때까지 역사 속 여러 중요한 순간에 중추적인 역할을 해왔습니다!'),
(66697, '후이드그라르가 길고도 활기 넘쳤던 삶을 마감하고 세상을 떠났을 때, 푸른 돌 기사단 또한 그와 함께 몰락하여 세월 속에 잊혀졌다. 이제 우리, 타고난 재능을 지닌 이들이 이 고대의 집단을 부활시키고, 불과 얼음, 그리고 마법에 대한 우리의 기량을 세상에 보여줄 차례다!'),
(66698, '정령들이여, 현자 팔레러너인 내가 필멸의 세계에서 또 다른 영혼을 불러들여 우리의 품으로 인도하려 합니다. 그들은 이미 필요한 영혼의 잎을 모으기 위해 험난한 황야를 용감하게 헤쳐 나갔으며, 역경 속에서도 진정한 용기를 보여주었습니다.'),
(66699, '부디 당신의 마법이 그들의 몸에 흘러들어 대지모신의 축복을 받게 하소서. 그들은 지금부터 세상 끝날까지 우리의 문화와 전통을 이어갈 것입니다.'),
(66700, '의식이 완료되었습니다. 이제 그들이 당신을 만나 당신이 진정으로 자격이 있는지 확인할 것입니다.'),
(66701, '나는 네가 준 교훈을 배우러 왔다.'),
(66702, '그렇게 될 것이다. 내가 이 세럼에 마법의 힘을 담았으니.'),
(66703, '엔리비, 당신에게 바치는 헌사로 이 세럼을 가져왔습니다.'),
(66704, '개굴!'),
(66705, '리이빗!'),
(66706, '리빗!'),
(66707, '개굴개굴!')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66708, '우리는 구원받았습니다!'),
(66709, '제가 얼마나 몸매가 좋은지 보여드리겠습니다.'),
(66710, '아르르!'),
(66711, '페랄라스로 출항하자!'),
(66712, '<어이없다는 듯 눈을 굴리며 자리를 떠납니다.>'),
(66713, '좋아, 시작하지!'),
(66714, '아니, 내 생각엔 아닌 것 같아!'),
(66715, '마법사 소바티르, 어떻게 이런 일이 가능하죠?'),
(66716, '낡은 목걸이를 가져가세요.'),
(66717, '그레이슨, 쿠키는 너에게 어떤 존재였니?'),
(66718, '당신은 제게 엄청난 힘을 지닌 물건들을 주셨습니다. 저는 이 물건들을 사용하여 마지막 숨을 거둘 때까지 이 숲을 지키겠습니다. 속임수는 누구에게서든 올 수 있으며, 심지어 친구에게서도 올 수 있습니다. 앞으로는 조심하시고, 이번 일을 교훈으로 삼으십시오.'),
(66719, '확신을 가지고 내 글레이브를 휘두르시오, 행운을 빕니다.'),
(66720, '물건을 보여 주세요.'),
(66721, '저는 \'그로이\' 앞으로 온 소포를 찾으러 왔습니다.'),
(66722, '저는 라드간 딥블레이즈의 지시로 무언가를 가져오라는 임무를 받았습니다...'),
(66723, '이봐, 조용히 해. 내 사생활을 남들이 다 알 필요는 없잖아. 자, 여기 있어. 더 필요한 게 있으면 언제든 나한테 연락해!'),
(66724, '아, 그거요? 그가 알아챌까 궁금했어요. 이 정보를 얻는 데 꽤 많은 시간을 들였거든요. 자, 누가 우리를 보기 전에 어서 가세요.'),
(66725, '저는 브린 대령의 지시로 귀하의 보고서를 수집하러 왔습니다.'),
(66726, '대령님께서 꼭 받으시도록 하세요.'),
(66727, '마지막 한 명은 테라모어로 돌아오지 못했어요. 서두르세요.'),
(66728, '도와주셔서 다시 한번 감사드립니다! 앞으로 같은 일이 반복되지 않도록 꼭 이 내용들을 공부하겠습니다!'),
(66729, '바엘로스 사령관께서 당신의 보고서를 기다리고 계십니다.'),
(66730, '아, 여기 있어요. 아직 전달할 시간이 없었네요. 감사합니다.'),
(66731, '셰어 부관이 당신의 보고서를 가져오라고 저를 보냈습니다.'),
(66732, '아, 여기 있네요! 제 실험이 오늘 하루 종일 늦어졌으니, 이걸 그에게 가져다 주세요.'),
(66733, '최악의 상황이 오지 않았기를 기도해야 할 때입니다.'),
(66734, '네, 우리가 예상했던 대로입니다만, 조치를 취하기 전에 확실히, 완전히 확신해야 합니다.'),
(66735, '이 물건들은 강력한 악마의 기운을 띠고 있는 것으로 보아, 오랫동안 방치되어 있지 않았던 것 같습니다.'),
(66736, '최악의 상황이 오지 않았기를 기도해야 할 때입니다.'),
(66737, '감사 인사 절차를 시작합니다.... 감사합니다'),
(66738, '오르바크, 당신의 이야기를 들려주세요.'),
(66739, '말티모어 가트사이드가 설계도를 살펴봅니다.'),
(66740, '<그에게 편지를 건네주세요.>'),
(66741, '계속 듣는다.'),
(66742, '프랭클린 하마르는 쪽지를 살펴본다.'),
(66743, 'Defias용 애니메이션 룬을 제작하셨나요?'),
(66744, '<말없이 응시한다.>'),
(66745, '<공격.>'),
(66746, '늑대를 워그 케이지에 가두세요.'),
(66747, '저는 샌드퓨리 부대를 대신하여 파견되었습니다. 그들은 본거지에서 쫓겨났습니다.'),
(66748, '샌드문 마을의 샌드퓨리는 다크스피어를 떠올리게 합니다.'),
(66749, '저는 그들을 잘 알지는 못하지만, 그들은 저를 마을 친구처럼 따뜻하게 맞아주었습니다. 그들은 지도자의 박해와 폭정 때문에 줄파락을 떠나야만 했습니다. 그곳에서 벌어지는 일들을 목격하고 도망쳐 나온 것입니다. 그들은 어둠과 부패를 보고 도망쳤습니다.'),
(66750, '바이스클로: <낄낄거림>'),
(66751, '<고대 늑대 정령이 있는 곳 주변에 가루를 뿌리세요.>'),
(66752, '저는 당신의 이야기를 들을 준비가 되어 있습니다.'),
(66753, '나는 너에게 도전할 준비가 되어 있다. 싸워보자.'),
(66754, '고기를 내놓으세요.'),
(66755, '멀록 오두막을 확인해 보세요.'),
(66756, '멀록 둥지를 확인해 보세요.'),
(66757, '그에게 먼지진흙 습지대에 타우렌이 있는지 물어보세요.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66758, '그러니까, 당신의 아내는 당신이 다른 여자와 바람을 피웠다는 증거를 가지고 있다고 생각하는 것 같군요.'),
(66759, '<펠바운드 펜던트를 제시하십시오.>'),
(66760, '그렇다면 웨스트폴에서 정확히 무슨 일이 일어났을까요?'),
(66761, '계속 듣는다.'),
(66762, '조치가 저를 당신께 보냈습니다, 위대한 칸이시여.'),
(66763, '<피를 마셔라.>'),
(66764, '아니요.'),
(66765, '예수게이는 "당신이 저를 부르셨습니다."라고 말했습니다.'),
(66766, '아니요.'),
(66767, '<숨을 깊이 들이쉬세요.>'),
(66768, '밀도우 하사관께서 당신의 안부를 확인해 보라고 하셨습니다.'),
(66769, '맬리, 당신의 이야기를 들을 준비가 되었습니다.'),
(66770, '보그포 트루스세이는 어떤 놀도 고울팽보다 강하지 않다는 것을 알고 있다! 고울팽이 세상을 지배할 것이다!'),
(66771, '고울팽, 모스하이드의 우두머리!'),
(66772, '크리스탈을 만져보세요.'),
(66773, '크리스탈을 만져보세요.'),
(66774, '저는 회의 준비가 완료되었습니다.'),
(66775, '저는 그 이야기를 들을 준비가 되었습니다.'),
(66776, '말로란 오크브랜치가 저를 보냈습니다. 그는 현재 돌발톱 산맥의 딥모스 오염 현상을 조사 중인데, 당신이 뭔가 단서를 가지고 있을지도 모른다는 이야기를 들었습니다.'),
(66777, '제스의 망치로 징을 치세요.'),
(66778, '당신의 이야기를 들을 준비가 되었습니다.'),
(66779, '계속 듣는다.'),
(66780, '당신의 이야기를 들을 준비가 되었습니다.'),
(66781, '저는 빅슬 스크루퓨즈의 심부름을 받았습니다. 그는 당신이 자신에게 베풀어준 은혜에 대한 보답으로 검은무쇠 디세크레이터의 설계도를 넘겨달라고 부탁하고 있습니다.'),
(66782, '니부, 너는 자유다. 에부로 돌아가라!'),
(66783, '그럼 이 고대 유물을 윈터스프링에서 찾을 수 있는 건가요?'),
(66784, '이 족장을 어디서 찾을 수 있을까요?'),
(66785, '그를 어디서 찾을 수 있을까?'),
(66786, '그렇다면 이 위대한 겨울의 정령은 어디에서 찾을 수 있을까요?'),
(66787, '그를 어디서 찾을 수 있을까?'),
(66788, '그를 어디서 찾을 수 있을까요?'),
(66789, '포레스트 송에서 파수꾼들과 드루이드들 사이에 무슨 문제가 있는 것 같군요?'),
(66790, '숲의 노래에서 드루이드와 파수꾼들 사이에 무슨 문제가 있는 것 같군요?'),
(66791, '그렇다면 왜 그들을 돕지 않는 겁니까? 스타윈드 사령관은 드루이드들이 파수꾼들과 함께 싸우기를 바라고 있습니다!'),
(66792, '그럼 당신은 여기 서서 아무것도 안 하실 건가요?'),
(66793, '그렇다면 보초병들은 단지 주의를 분산시키는 역할만 할 뿐이겠군요. 그들이 피를 흘리는 것을 틈타 적진 후방을 공격할 수 있겠습니까?'),
(66794, '이 문제에 대해 생각해 봐야겠습니다.'),
(66795, '그렇다면 왜 후퇴하지 않는가? 브롤탄 철창은 모두가 안전하게 포레스트 송으로 돌아오면 지원을 제공할 의향이 있다!'),
(66796, '그럼 계획도 없이, 재정비도 없이 계속 싸우겠다는 겁니까?'),
(66797, '그렇다면 드루이드들은 그저 방관자에 불과하고, 파수꾼들은 영광을 위해 스스로를 희생하는 것입니까?'),
(66798, '에본록 경, 당신의 이야기를 들려주십시오.'),
(66799, '<이야기를 계속 듣는다.>'),
(66800, '당신의 이야기를 들려주세요.'),
(66801, '<이야기를 계속 듣는다.>'),
(66802, '나는 당신을 자유롭게 해주려고 왔습니다!'),
(66803, '밤의 여인, 새벽녘 입에 금을 물고 있네.'),
(66804, '장기간의 눈보라, 새벽녘의 얼음 이슬.'),
(66805, '태양의 여인, 밤에는 귀에 은빛 귀걸이를 하고.'),
(66806, '안녕히 가세요.'),
(66807, '알파 채널 밸브를 활성화하십시오.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66808, '예비 펌프 레버를 작동시키십시오.'),
(66809, '화학자 볼터화이트가 골볼라 광석 배송을 요청하라고 저를 보냈습니다.'),
(66810, '아, 그분이 광석을 가져오라고 시켰군요? 이번에는 꼭 그분께 전달해 드리도록 하세요.'),
(66811, '불을 더 자세히 살펴보세요.'),
(66812, '길니아스 상황에 대해 간략히 설명해 주십시오.'),
(66813, '<계속>'),
(66814, '알겠어요.'),
(66815, '목걸이를 무덤 위에 놓으세요.'),
(66816, '룬스톤을 활성화하세요'),
(66817, '이 물품을 검사해 보세요.'),
(66818, '카라잔에서 특이한 것을 보거나 들으신 적이 있나요?'),
(66819, '대리석 흉상을 자세히 살펴보세요.'),
(66820, '외국의 간섭이 감지되었습니다! 위협을 보고합니다!'),
(66821, '자, 이제 이걸 여기에 놓고...'),
(66822, '바로 이거야! 터보차지 흔들림 방지 발포 디스크가 유용할 줄 알았어.'),
(66823, '헤어스타일을 바꾸고 싶어요.'),
(66824, '수염을 다듬고 싶어요.'),
(66825, '저는 제 얼굴을 바꾸고 싶어요.'),
(66826, '피부색을 바꾸고 싶어요.'),
(66827, '저는 제 얼굴을 바꾸고 싶어요.'),
(66828, '피부색을 바꾸고 싶어요.'),
(66829, '스톰윈드 시티로 항로를 설정하세요.'),
(66830, '오그리마로 항로를 설정하세요.'),
(66831, '역병지대로 향하라!'),
(66832, '미라지 레이스웨이를 방문하려면 버섯구름 봉우리의 쉬머링 플랫츠행 항공편을 구매하세요.'),
(66833, '특성을 초기화하고 싶습니다.'),
(66834, '첫 번째 전문화를 저장하세요.'),
(66835, '두 번째 전문화를 저장하세요.'),
(66836, '아던트 워치는 무엇인가요?'),
(66837, '아던트 워치에는 누가 가입할 수 있나요?'),
(66838, '문킨에게 따뜻한 에그노그 한 잔을 주세요.'),
(66839, '겨울 축제 잘 보내세요, 프로스티!\r\n겨울 축제가 열리는 곳으로 순간이동시켜 주세요!'),
(66840, '상어는 몹시 겁에 질린 표정으로 당신 같은 사람들로 가득 찬 이 끔찍한 곳에서 벗어나고 싶어 안달이 난 것 같습니다.'),
(66841, '샌드로켓이 해변 파티를 열어요. 꼭 방문해주세요!'),
(66842, '리사 샌드로켓이 해변 파티를 열어요. 꼭 방문해주세요!'),
(66843, '남작님, 선물입니다.'),
(66844, '살고 싶다면 나와 함께 가자!'),
(66845, '양털을 좀 모아 보세요.'),
(66846, '양은 송로버섯을 게걸스럽게 먹어치운 다음, 더 찾으려고 당신의 가방 속으로 뛰어듭니다!'),
(66847, '관심 없어요, 안녕히 가세요.'),
(66848, '내 지위를 다시 보여줄 준비가 됐어!'),
(66849, '네... 좀 조용히 하고 싶은데, 제 랭크를 숨겨주시겠어요? 골드 드릴게요.\r\n\r\n경고: 이 서비스는 골드 5개를 소모합니다!'),
(66850, '이 말을 50코퍼에 빌리세요.'),
(66851, '이 늑대를 고용하려면 구리 50개를 내야 합니다.'),
(66852, '이 말을 50코퍼에 빌리세요.'),
(66853, '이 숫양을 구리 50개에 고용하세요.'),
(66854, '이 숫양을 구리 50개에 고용하세요.'),
(66855, '이 코도를 고용하려면 구리 50개를 내야 합니다.'),
(66856, '이 코도를 고용하려면 구리 50개를 내야 합니다.'),
(66857, '그리핀에게 먹이를 주고 무슨 일이 일어나는지 보세요.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66858, '여기서 나가게 해 줘.'),
(66859, '시간의 동굴을 안내해 주세요.'),
(66860, '와이번에게 먹이를 주고 무슨 일이 일어나는지 보세요.'),
(66861, '내 운세를 말해줘.'),
(66862, '블러드 링 전투 (3v3 솔로).'),
(66863, '블러드 링 전투 (3v3 그룹).'),
(66864, '난 이제 더 이상 그걸 원하지 않는 것 같아...'),
(66865, '망원렌즈를 설치해 주세요!'),
(66866, '제발, 저에게 마법을 부려주세요!'),
(66867, '안녕하세요! 도와드리려고 왔습니다.'),
(66868, '네, 준비됐습니다.'),
(66869, '계속 듣는다.'),
(66870, '알라탈라스로 가는 포털을 열어주세요.'),
(66871, '스톰윈드로 가는 포털을 열어주세요.'),
(66872, '듀로타로 항로를 설정하라! 전속력으로!'),
(66873, '가르톡 족장님! 저희 선원들을 소개해 드리겠습니다. 저희는 갈 곳이 없어 호드를 도와드리고자 합니다. 다만, 음식과 숙소를 제공해주시면 감사하겠습니다!'),
(66874, '나한테는 별 차이 없어. 너도 해골 부수는 거 좋아하고, 나도 해골 부수는 거 좋아하잖아... 난 호드를 위해 태어났어!'),
(66875, '정말이야? 너희들이 여기서 활을 쓴다고? 이봐, 시대에 뒤떨어지지 마! 내가 너희들에게 진짜 무기 쓰는 법을 가르쳐주지!'),
(66876, '레이티 퀵텅은 말없이 고개를 숙인다.'),
(66877, '여기 마법사 있나요? 기온이 섭씨 1000도나 돼요! 제가 직접 가서 물이라도 좀 만들어 드려야겠네요. 물론 돈은 내셔야겠지만요! ... 아, 그리고 호드 진영을 위해서요!'),
(66878, '나도 악마와 나쁜 거래를 몇 번 했고, 너희 오크들도 악마와 나쁜 거래를 몇 번 했지. 공감하겠지? 우리를 받아줘서 고마워.'),
(66879, '명예 따위 누가 신경 써? 음식은 어디 있어?!'),
(66880, '가르톡이 웃는다.'),
(66881, '좋아, 신병들. 시험의 골짜기에서 온 오크나 트롤과 똑같은 기회를 주겠다. 칼바위 언덕에는 너희가 할 일이 많다. 여기서 시작해서 새로운 동맹들의 존경을 얻고 호드에 영광을 가져다주어라!'),
(66882, '좋아, 솔직히 말할게. 사장님은 우리가 보물을 가져다주지 않으면 좋아하지 않으실 거야. 하지만 난 충분히 봤고, 너희도 마찬가지겠지?'),
(66883, '투자개발회사로 돌아갈 순 없어! 돌아가면 우린 모두 죽은 목숨이야! 스팀휘들 카르텔이 우리를 받아줄 리가 없잖아. 이미 우리 사이에 앙금이 쌓여 있는데 말이야.'),
(66884, '그래서 우리는 지금 여기에 있습니다. 냄새나고 더러운 난민 무리, 주머니에 돈 한 푼 없는 신세죠. 우리에게 남은 기회는 단 하나, 스랄의 발에 입맞추는 것뿐입니다.'),
(66885, '네르트 블래스텐톰이 미소를 짓는다.'),
(66886, '다들 주그주그 연습 열심히 하셨길 바라요. 듀로타로 갈 거거든요! 모두 비행기에 타세요!'),
(66887, '겁먹지 마십시오. 이 트로그들은 작고 약해서 혼자서도 쉽게 처리할 수 있습니다. 하지만 만약 트로그들이 무리를 지어 몰려든다면 사람들이 다칠 수 있고, 우리는 오두막 주변의 다른 위협들을 막아내는 와중에 더 많은 병력을 투입해 트로그들을 상대할 여유가 없습니다.'),
(66888, '말비나, 우리 얘기 좀 해야 해.'),
(66889, '여동생분이 무사해서 다행이에요!'),
(66890, '내 여동생도 그 마차에 타고 있었어!'),
(66891, '우리 모두 위험이 있다는 건 알고 있었지만… 그녀는 거의 여기 와 있었잖아요! 우리 중 누구라도 될 수 있었어요!'),
(66892, '어떻게 이런 일이 일어날 수 있지?! 우리는 스컬지, 습지대, 그리고 호드까지 모두 물리치고 살아남았는데, 납치당하는 와중에 소지품이 잿더미로 변해버리다니?! 너무 불공평해!'),
(66893, '죄송합니다. 이런 일로 부담을 드리고 싶지 않았는데. 쿠엘탈라스를 잃은 후로 우리 모두 힘든 시간을 보냈지만, 당신은 늘 큰 힘이 되어주셨습니다.'),
(66894, '숲도, 물도, 심지어 그 끔찍한 트로그 괴물들까지 물리쳤잖아요. 당신 말이 맞아요, 침착해야 해요. 어쩌면 제 여동생이 아직 어딘가에 있을지도 몰라요. 그녀는 제게 남은 유일한 가족이고, 만약 누군가 그녀를 구할 수 있다면 그건 당신일 거예요.'),
(66895, '그 뻔뻔스러운 여자, 호위대를 이끌었던 그 여자에게 가서 말을 걸어봐. 어쩌면 그녀가 도움을 줄지도 몰라!'),
(66896, '당신 덕분에 제 여동생이 살았어요!'),
(66897, '당신을 친구라고 부를 수 있어서 얼마나 영광인지 이루 말할 수 없어요. 당신 덕분에 어린 아리샤가 안전합니다. 당신의 영웅적인 행동에 모두 깊은 감명을 받았어요.'),
(66898, '당신이 없는 동안 몇몇 마차는 스톰윈드로 떠났지만, 우리 중 많은 이들이 당분간, 어쩌면 영원히 이곳에 남기로 했습니다.'),
(66899, '캐시가 당신과 이야기하고 싶어하는 것 같아요. 제가 준비한 선물입니다. 잘 지내세요. 어디에 계시든, 우리는 언제나 친구로 남을 거라는 걸 잊지 마세요!'),
(66900, '여동생을 다시는 못 볼 줄 알았어요. 정말 고마워요, 영웅님!'),
(66901, '이샬라, 준비됐어. 나를 골드샤이어로 순간이동시켜줘!'),
(66902, '스터크가 로브에게 주먹 한 방 먹여준 빚을 졌다는 소문이 들리던데요.'),
(66903, '아마니알로르로 가는 포털을 여세요.'),
(66904, '영혼들이 당신과 함께하고 로아가 당신의 발걸음을 인도하길 바랍니다.'),
(66905, '정말 고마워요, 고마워요, 고마워요! 너무 기뻐요! 스톰윈드로 가야겠어요. 도움을 줄 수 있는 중요한 사람을 찾아야죠! 황금 새벽회 연구소의 타닐라에 양이 우리를 데려다 줄 수 있을 거예요!'),
(66906, '엄마는 돌아가셨지만, 우리는 꼭 엄마를 찾을 거야! 난 확신해! 그때까지, 너와 함께 신나는 모험을 떠날 생각에 너무 행복하고 신나! 우리는 이제 제일 친한 친구잖아! 세상을 구경하면서 정말 재밌는 시간을 보낼 거야! 헤헤!'),
(66907, '와, 여기 엄청 넓네! 이제 어디로 가야 하지? 마법사 지구부터 가보자! 저 이상한 냄새 나는 곳도 구경해 봐야겠다. 저 술집 말이야? 사람들이 슬플 때 거기서 특별한 술을 마신다고 들었어! 우리 엄마는 내가 없어서 분명 슬퍼하실 거야.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66908, '공기 중에 마법이 느껴져요! 여기도 좋긴 하지만 실버문만큼 예쁘거나 마법 같지는 않네요!'),
(66909, '엄마는 여기 없네... 계속 가자!'),
(66910, '여기는 무서워요. 나쁜 마법이 깃들어 있고, 냄새도 끔찍해요! 우리 여기서 나갈 수 있을까요?! 제발요?'),
(66911, '저기 봐, 나이트 엘프 여사제다! 그리고 달샘도 있네! 풀이랑 빛나는 식물들이 너무 예뻐. 여기 정말 멋지다. 엄마도 좋아하실 거야! 엄마한테 보여줄 수 있도록 계속 찾아보자.'),
(66912, '으악! 여기 냄새나. 엄마가 정말 여기 계실까?'),
(66913, '오, 이곳은 다른 곳보다 훨씬 더 좋은 곳처럼 보이네. 하지만 우리 엄마는 분명 난쟁이들의 땅에는 가본 적이 없을 거야.'),
(66914, '여기가 우리 조상들이 정착했던 곳이야! 예쁘네. 실버문만큼 예쁘진 않지만, 그래도 예뻐. 하지만 여기는 크지 않고, 엄마도 안 계시네. 계속 찾아보자!'),
(66915, '저거 진짜 이상하게 생겼네. 난쟁이들이 만든 거지? 엄마는 여기 안 계실 거야. 저 전차는 난쟁이 도시로 가는 것 같아. 거기 엄청 춥잖아, 엄마는 추위를 엄청 싫어하시고.'),
(66916, '왕이 저기에 사셔! 하지만 엄마를 찾는 게 정말 중요하긴 해도 방해하면 안 돼. 엄마는 거기 없을 거야. 들어올 수 없을 테니까. 우린 가진 게 별로 없어. 엄마는 정말 예쁘시지만, 쿠엘탈라스가 함락됐을 때 모든 걸 잃었어.'),
(66917, '여기가 신도시가 건설되기 전부터 있었다는 얘기를 들었어요! 가게는 정말 많은데, 거리가 너무 빽빽하게 들어서 조금 무섭기도 해요.'),
(66918, '여기 냄새가 심해. 엄마도 안 계셔. 너무 걱정돼. 엄마는 또 어디에 계실까?'),
(66919, '군대가 와 있어요. 엄마가 체포된 걸까요? 하지만 엄마는 아무 죄도 짓지 않았는데. 여기가 엄마를 찾을 장소는 아닌 것 같지만, 다른 곳에서 못 찾으면 다시 여기로 돌아올 수 있을 거예요.'),
(66920, '저기가 바로 대성당이네! 와, 정말 거대하다! 놀랍다!'),
(66921, '엄마가 정말로 돌아가셨다면, 저도 그런 곳에 가게 될지도 몰라요. 생각만 해도 너무 슬퍼서 눈물이 날 것 같아요.'),
(66922, '이곳 좀 봐! 정말 놀랍다! 와, 숨이 멎을 듯 아름답다!'),
(66923, '이거 정말 끔찍하고 역겹고 무서워요. 제발 여기서 나가게 해주세요. 빨간 옷 입은 남자가 저를 쳐다보는 게 마음에 안 들어요.'),
(66924, '이건 안 좋아. 정말 안 좋아. 여기 싫어. 제발, 가자. 무서워.'),
(66925, '어머, 여기 사람이 정말 많네요! 그리핀 등에 타고 날아와서 처음 도착했을 때가 기억나요! 그리핀 깃털이 정말 폭신하고 부드러웠는데. 엄마도 여기 계실까요?'),
(66926, '아, 저기요! 저기가 우리가 도착했을 때 처음 체크인했던 방문자 센터예요. 거기 가면 뭔가 알 수도 있을 거예요!'),
(66927, '나이테가 거의 없는 어린 나무 \'애플보우\'가 잎사귀에 대한 조언과 전문 지식을 얻기 위해 우리를 찾아왔습니다. 이 나무의 병을 고치는 데 도움을 주시겠습니까?'),
(66928, '아! 애플버우군요. 당연하죠. 여기 도움이 될 연고가 있습니다.'),
(66929, '내 나뭇잎들이 떨어져요. 너무 슬퍼요.'),
(66930, '초록색이었고, 과일도 있었고, 행복했어요...'),
(66931, '활력이 되살아난 것 같아요! 제 가지들에 생기가 다시 흐르는 것 같습니다. 감사합니다. 이 친절을 절대 잊지 않겠습니다!'),
(66932, '로아니아와 그녀의 언니 리렌은 두건이라는 인간 성기사의 딸들입니다. 저는 두건을 제2차 대전쟁 때 함께 호드와 싸웠을 때부터 알고 지냈습니다.'),
(66933, '제2차 대전쟁 동안, 저와 두건, 그리고 와일드해머 부족 출신의 드워프 카르단은 아주 가까운 동료였습니다. 전쟁이 끝난 후, 두건과 그의 아내 아데나는 그랜드 햄릿에 정착했습니다.'),
(66934, '그랜드 햄릿은 이후 저주를 받아 다크샤이어라는 이름으로 알려지게 되었지만, 이야기가 옆길로 새는군요. 어느 날, 두간은 근처에 있는 저주받은 탑 카라잔에서 마을 사람들이 사라진다는 소식을 들었습니다. 그는 카르단과 저를 불렀고, 우리는 함께 탑으로 들어가 구조를 시도했습니다.'),
(66935, '결과는 좋지 않았습니다. 카라잔은 예상했던 것보다 훨씬 더 험난했죠... 두건은 결국 세상을 떠났고, 그의 아내는 삶의 의욕을 잃었습니다. 카르단과 저는 그의 어린 쌍둥이 딸들을 각각 입양하여 친자식처럼 키웠습니다.'),
(66936, '저는 이 소녀들에게 밝은 미래가 있다고 믿습니다. 어쩌면 당신도 그 미래에 함께하게 될지도 모르죠. 지금은 이것을 당신의 보상으로 받아들이고, 제 축복을 전합니다.'),
(66937, '경비원이 몇 명 부족하네요.'),
(66938, '당신 부대에서 몇 명이 전사했다는 소문이 있는데, 사실입니까?'),
(66939, '다른 두 야영지에서도 경비병 몇 명이 사라졌는데, 여기도 그런 일이 있었나요?'),
(66940, '뭐 좀 사주시겠어요?'),
(66941, '어떻게 그 정보를 얻으셨는지는 모르겠지만, 네, 붉은십자군 잔당 몇 명이 제 죽음의경비병 ​​순찰대를 공격했습니다. 일부는 돌아오지 못했고, 나머지는 깊은 잠에 빠졌습니다. 이상한 잠에 빠지기 전에 경비병 중 한 명이 수도원으로 향하고 있다고 말했습니다.'),
(66942, '붉은십자군 소규모 병력이 숲 속 깊숙이 침투하여 순찰대 하나를 공격했습니다. 우리는 입에서 이상한 액체를 흘리는 시체 하나를 발견했습니다. 다른 죽음의경비병 ​​병사 한 명이 그 액체를 만지자 곧 깊은 잠에 빠졌는데, 그 병사는 어쩌면 죽음 그 자체와 혈연관계일지도 모릅니다.'),
(66943, '정확히 맞습니다. 우리 병력은 더욱 줄어들었고, 시체는 발견되지 않았지만 진흙으로 뒤덮인 무기는 찾았으나 피는 없었습니다. 저항하지 않은 것 같습니다.'),
(66944, '당신을 지역 경찰서로 데려가겠습니다.'),
(66945, '이 남자는 에어리 피크로 향하던 대상 행렬을 공격했던 사람들 중 유일한 생존자입니다. 그는 항복했고, 저는 그의 목숨을 살려주었습니다.'),
(66946, '레이크셔 출신의 블라데우스 스프링리버 맞죠?'),
(66947, '당신은 오른손 주먹으로 그의 옆구리를 강타합니다.'),
(66948, '블라데우스는 아무 말 없이 고개를 살짝 끄덕였다. 끄덕인 후 기침을 했다. 오랫동안 쇠사슬에 묶여 있어서 목이 말랐을 거라고 짐작할 수 있다.'),
(66949, '블라데우스에게 물을 바치십시오.'),
(66950, '고맙습니다. 저를 붙잡으신 분이 당신이시죠? 목숨을 살려주셔서 감사하지만, 말씀드릴 수 있는 건 아무것도 없습니다.'),
(66951, '블라데우스, 제발 우리 둘 다 편하게 해 주세요. 당신은 괜찮은 사람처럼 보여요. 레이크셔 사람들은 제가 당신들을 모두 데려오길 바랐어요.'),
(66952, '이미 너무 늦은 거 아니야? 네가 나머지 사람들의 목숨을 앗아갔으니, 더 이상 할 말이 없어. 빨간 두건을 쓴 남자는 집으로 돌아가서… 아, 너무 많이 말해버렸네.'),
(66953, '내가 곁에 있으니 두려워할 것은 없다. 얼라이언스이 네 가족을 지켜줄 것이다. 붉은십자군은 이미 수없이 실패했다.'),
(66954, '어쩌면 당신 말이 맞을지도 몰라요. 정말 이렇게 끝나길 바라진 않았어요. 우린 더 나은 삶을 약속받았는데... 난... 난 그들이 나에게 무고한 사람들을 죽이게 할 거라고는 상상도 못 했어요. 제발 믿어주세요!'),
(66955, '네, 제 말을 믿으세요. 누가 당신을 채용했고, 그 이유는 무엇입니까?'),
(66956, '그의 얼굴은 제대로 보지 못했어요. 빨간 두건을 쓰고 몇 분마다 웃기만 했거든요. 돌이켜보면, 제가 했던 선택 중 가장 어리석은 선택이었죠. 왜 우리를 모집했는지는 잘 모르겠어요. 그는 우리를 십자군 비밀 장소로 데려가 훈련시킬 거라고 했어요. 십자군 병력이 적고 지도자 두 명이 죽은 후로 의기소침해졌다고 불평했죠. 아벤티스나 아덴티스라는 이름을 언급했던 것 같기도 하고요.'),
(66957, '아벤디스?')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(66958, '네, 바로 저곳이에요! 제발, 저는 다른 건 아무것도 몰라요. 집에 돌아가고 싶어요.'),
(66959, '아벤디스?'),
(66960, '으악, 이 자식! 왜 그랬어?'),
(66961, '블라데우스는 이를 악물었다.'),
(66962, '입 닥쳐, 잡종아. 내가 더 이상 행동하기 전에 네가 먼저 입을 열기 시작할 거야.'),
(66963, '난 너에게 아무것도 말하지 않을 거야!'),
(66964, '블라데우스의 짧은 말 뒤에 기침이 터져 나온다. 오랫동안 사슬에 묶여 있었으니 목이 마를 거라고 짐작할 수 있다.'),
(66965, '지난번에 수도원에 갔을 때, 당신네 사람들이 이 도구를 사용하는 걸 봤던 기억이 나네요.\r\n\r\n<뜨거운 부지깽이를 집어 블라데우스의 목에 갖다 댄다.>\r\n\r\n자, 이제 말해 봐!'),
(66966, '나는 내 동료들을 살해한 자에게 아무 말도 하지 않겠다!'),
(66967, '당신의 동료들은 무고한 사람들을 살해했습니다.\r\n\r\n<당신은 집게를 잡으려 손을 뻗습니다.>'),
(66968, '멈춰! 제발 멈춰, 말할게요. 이렇게 되길 원하지 않았어요, 맹세해요! 빨간 두건을 쓴 남자가 우리가 말을 듣지 않으면 가족을 죽이겠다고 했어요, 제발, 이해해 주세요!'),
(66969, '지금 이 순간 당신의 목숨을 쥐고 있는 사람은 그가 아닙니다.\r\n\r\n<당신은 갈고리를 그의 얼굴 가까이 가져갑니다.>'),
(66970, '그는… 그는 우리를 훈련시키기 위해 비밀 장소로 데려갈 거라고 했어요. 병력이 부족하고, 지도자 두 명이 죽어서 상황이 좋지 않다고 했죠. 그는 또 아벤티스인지 아덴티스인지 모를 이름도 언급했어요.'),
(66971, '아벤디스?'),
(66972, '네, 제발 부탁드립니다. 저는 다른 건 전혀 몰라요.'),
(66973, '블라데우스는 극도로 겁에 질렸다.'),
(66974, '그의 무릎을 차버려.'),
(66975, '블라데우스는 밖에서도 들릴 정도로 고통스럽게 비명을 질렀다.'),
(66976, '브리짓 아벤디스는 전직 최고 사령관 아벤디스의 딸이며, 언데드를 극도로 증오하는데, 붉은십자군과 관련된 인물이니 당연한 일이기도 하죠.'),
(66977, '문제는 그녀가 이 목적을 달성하기 위해서라면 어떤 수단이든 가리지 않을 거라는 겁니다. 당신이 말해준 내용과 다른 지도자들의 운명을 고려해 볼 때, 그녀는 이미 정신적으로 무너져서 미쳐버렸을 가능성이 큽니다.'),
(66978, '내가 마지막으로 들은 바로는 그녀는 티르의 손에 있지만, 만약 그 죄수가 비밀 훈련소라고 불렀던 곳이 있다면, 그곳에 대해 아는 사람은 그녀뿐일 거야. 애쉬브링어에서 그녀의 아버지에게, 그리고 아버지에서 그녀에게로 전해진 정보일 테니까.'),
(66979, '제가 말씀드리건대, 붉은십자군는 확실히 무너졌고 전성기는 지났지만, 아벤디스는 언데드를 소탕하기 위해서라면 스컬지든 아니든 가리지 않고 무슨 짓이든 서슴지 않을 겁니다.'),
(66980, '매버릭, 준비됐나?'),
(66981, '매버릭의 상태를 점검하세요.'),
(66982, '이 어리석은 광신도들에게 파멸을 안겨주자!'),
(66983, '함정이야! 함정이라고!'),
(66984, '기분이… 이상해.'),
(66985, '그는 정말 의식을 잃은 것뿐이군요, 이상하네요...'),
(66986, '레빌가즈는 브라이트워터 선원들을 추적하는 집단에 대한 정보를 찾아보라고 나에게 지시했다.'),
(66987, '오, 그랬군요? 글쎄, 나도 그 일에 대해 조금은 알 것 같긴 한데, 그 고블린들의 목을 원하는 놈들은 솔트 투스 선장밖에 없을 겁니다. 그놈은 경기장 근처 북쪽에 진영을 두고 있거든요. 내가 아는 건 이게 전부예요, 맹세해요!'),
(66988, '드디어 진짜 침대에서 잘 수 있게 됐어요!'),
(66989, '그럼, 푹 쉬고 나면 곧 다시 항해를 시작할 수 있겠네요! 감사합니다!'),
(66990, '행운을 빌어요, 그리고 뱃사람의 행운이 함께하길!'),
(66991, '정말 어려운 일이었지만, 저는 제 일을 끝냈고, 열쇠에는 마법이 걸려 있을 겁니다.'),
(66992, '안전하게 여행하세요, 친구!'),
(66993, '안녕하세요. 테라모어에 있는 마법사 할리스터에게 필요한 비전 레조네이터를 찾고 있는데, 혹시 가지고 계신가요?'),
(66994, '건배!'),
(66995, '아, 딱 좋다!'),
(66996, '히즐, 여기 있네. 네 포로를 현장에서 잡았어.'),
(66997, '먼저, 이걸 여기에 놓고, 그다음에 이걸... 여기에...'),
(66998, '그러면 "아! 젠장!"이라고 외치기만 하면 되죠.'),
(66999, '자, 여기 있습니다! 제가 해냈어요! 제 임무는 완료되었습니다!'),
(67000, '줄진, 너한테 무슨 일이 있었던 거야?'),
(67001, '줄진, 갈 준비 됐나?'),
(67002, '아마니와 호드의 연합군이 엘프 땅 공격에 실패한 후, 우리는 물러서지 않았고 나와 내 동족은 그 대가를 치렀습니다.'),
(67003, '그들은 나를 호수 근처에서 궁지에 몰아넣었고, 브라이트윙이라는 수줍은 엘프에게 붙잡혔다.'),
(67004, '그들은 나를 괴롭히고 심지어 내 눈까지 뽑아갔어. 그들은 나를 자기네 정착지로 데려가서 다른 모든 엘프들 앞에서 내 목숨을 끊어 도덕성을 높이려고 했던 것 같아.'),
(67005, '그때 늙은 줄진은 운명을 걸고 도박을 했지. 내 부하들이 적진을 포위 공격하는 동안 나는 창으로 내 팔을 잘라내고 숲 속으로 도망쳤어.'),
(67006, '나는 다시 군대를 재정비하고 회복시켰다. 스컬지가 실버문을 점령하기 얼마 전, 행동에 나서야 할 때가 왔다. 하지만 로아의 축복이 있었음에도 불구하고 우리는 언데드들을 막아낼 수 없었고 결국 실패했다.'),
(67007, '내 영토는 산 자들의 손에 황폐해져 버렸고, 나는 우리 영토를 되찾기 위해 무슨 일이든 할 것이다. 어떤 하이 엘프나 스컬지도 아마니와 호드의 힘에 맞설 수 없을 것이다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(67008, '그곳은 우리 땅이었어, 트롤의 땅이었지. 아마니는 누구보다 먼저 그곳에 있었고, 얼라이언스도, 스컬지도, 악마도 우리가 그 땅을 되찾는 것을 막을 수 없어.'),
(67009, '들어보세요!'),
(67010, '우리는 데 아마니다, 우리는 아무도 두려워하지 않는다!'),
(67011, '우리는 절대 포기하지 않을 것이다. 왜냐하면 우리는 절대 죽지 않기 때문이다!'),
(67012, '아직 준비가 안 됐어, 친구. 곧 나를 보러 와.'),
(67013, '마틴 코린트, 당신은 얼라이언스에 대한 범죄로 처형될 것입니다.'),
(67014, '처형당했다고?! 당신이 누구랑 얘기하고 있는지 알아요?'),
(67015, '당신이 지금 누구를 협박하고 있는지 알고 있나요?!'),
(67016, '나를 막으려는 자들은 너와 그 외 모든 자들을 파멸시키겠다!'),
(67017, '자, 이제 감쇠 현상이 멈췄는지 확인해 봅시다...'),
(67018, '우리의 노력이 헛수고였던 것 같군요... 새로운 해결책을 찾아야 합니다...'),
(67019, '팔찌에 어떤 주술적인 저주가 깃든 것 같아. 여기서도 그런 기운이 느껴져.'),
(67020, '팔찌에 걸린 저주가 풀렸습니다. 필멸자의 나약한 마법으로는 정령계에 맞설 수 없습니다.'),
(67021, '정말 감사드립니다. 당신의 도움은 매우 큰 도움이 되었습니다.'),
(67022, '당신 덕분에 하버리지가 살아남았습니다!'),
(67023, '노보루가 죽었다고요? 외부인님, 감사합니다!'),
(67024, '우리는 더 이상 노보루의 위협을 두려워하지 않을 것이다.'),
(67025, '결국 우리의 여정은 헛되지 않았네요, 감사합니다.'),
(67026, '알겠습니다... 그럼 나중에 하나 구입해야겠네요. 분석기 X-51, 감사합니다. $R, 잠시 이쪽으로 와 보세요.'),
(67027, '하즈고르그는 마울로그를 이끌 만큼 강하지 않아. 난 내 마음대로 할 거야. 내가 제일 강해. 꼬맹이 $R, 그런 말을 듣고 살아남은 걸 보면 운이 좋은 줄 알아.'),
(67028, '끝났다! 라피디스의 폭정은 종식되었다! 카엘란 제독의 영혼은 이제 편히 쉬게 되었다. 영웅적인 행동을 보여준 $N에게 찬사를 보낸다!'),
(67029, '당신은 우리의 적 $N을 물리치고 진정한 힘을 보여주셨습니다. 록타르, 저는 그 영광에 경의를 표합니다.'),
(67030, '더 자세한 내용을 알게 되면 여기서 다시 만납시다. 당신의 돌의 도시에서 진실을 찾으시길 바랍니다. $N, 머드스프로켓에게 보고하세요. 저희가 단서를 조사하겠습니다.'),
(67031, '엘룬 여신께서 당신에게 굳건한 발걸음을 축복하시기를, $N!'),
(67032, '대지모신를 당신의 발판으로 삼으세요, $N!'),
(67033, '내 가문의 지팡이가 자네에게 도움이 되길 바라네, $N.'),
(67034, '$N님, 다시 한번 감사드립니다. 안전한 여행 되세요. 당신은 키린 토의 영웅입니다.'),
(67035, '저는 방랑자 챌린지를 완전히 끝내고 싶습니다.'),
(67037, '멧돼지 도전을 이번에 완전히 끝내고 싶습니다.'),
(70000, '망원경과 곡괭이의 유용성을 결합한 제품이 이렇게 큰 인기를 끌 줄 누가 알았겠습니까! 당신 같은 훌륭한 $r 분이시라면 그 매력을 아실 거라고 확신합니다!$B$B 만약 하나 갖고 싶으시다면, 화려한 망원경과 얇은 가죽을 한 10개 정도 가져오세요.'),
(70001, '내가 마을에 들어오는 아무에게나 내 채굴 비밀을 알려줄 거라고 생각하는 거야? 하! 이 사람들이 너를 좀 더 호의적으로 생각하게 되면 다시 와.'),
(70002, '안녕하세요 $r님, 제 작품 중 하나를 소장하고 계시는군요. 아마도 지금까지 선택하신 것 중 가장 훌륭한 선택이신 것 같습니다.'),
(80000, '우리는 친구야. 도망가지 마.'),
(80001, '목표물을 식별할 수 없습니다. 제거를 진행하십시오.'),
(80002, '목표물 포착. 종료 활성화됨.'),
(80003, '위협이 감지되어 프로토콜 66이 활성화되었습니다.'),
(80004, '적대적인 자들을 섬멸하라.'),
(80005, '전멸시키다.'),
(80011, '오류 132: 메모리를 읽을 수 없습니다.'),
(80012, '오류 132: 치명적인 예외가 발생했습니다.'),
(80013, '오류 134: 필요한 아카이브 파일을 열 수 없습니다...'),
(80014, '오류 132: 접근 권한 위반.'),
(80015, '오류... 종료합니다.'),
(80016, '시스템 처리 중 오류. 오류. 오류.'),
(80100, '오늘 첫 출근이구나, 꼬마야?\r\n\r\n그래, 나도 한때는 너처럼 어리고 경험이 부족했지. 지금은 그냥 초보일 뿐이야! 어쩌겠어?\r\n\r\n어쨌든, 이제 그만 게으름 피우고 일이나 해. 안 그러면 월급에서 깎을 거야!'),
(80101, '잘 지내니, 얘야? 이리 와서 엄마 스프랫에게 안아봐. 부끄러워하지 마!\r\n\r\n내가 요리 솜씨가 제일 좋단다. 뭐든지 맛있게 만들어 줄 수 있지.\r\n\r\n네 엄마처럼 맛있는 거 먹여 줄게. 혹시 네 엄마가 그렇지 않았다면... 날 새 엄마라고 생각해도 돼!'),
(80104, '이봐, 친구, 어떻게 상대를 거칠게 다루는지 좀 배워볼까?\r\n\r\n자, 조언 하나 해줄게. 우선 무릎부터 노려봐. 걔가 네 눈높이까지 내려오면, 더 이상 널 깔보지 못할 걸. 무슨 말인지 알겠어?\r\n\r\n꽤 괜찮은 조언이군. 돈 좀 줘야겠어.'),
(80105, '총. 아, 난 총을 정말 좋아해. $N, 너도 그렇지?\r\n\r\n그 우렁찬 쾅 하는 소리를 들을 때마다 심장이 두근거려. 사격 훈련 필요해? 돈만 있으면 내가 실력으로 가르쳐 줄게.'),
(80106, '동전 한 자루보다 더 좋은 게 뭔지 알아, $N? 호구 주머니에서 훔친 동전 한 자루지. 그것보다 더 좋은 건? 그놈의 차가운 시신에서 뜯어낸 동전 한 자루야.\r\n\r\n시신 한 구를 통째로 팔면 꽤 많은 돈을 딸 수 있다는 얘기도 들었어… 그러니까 날 시험하지 마.'),
(80107, '$N, 아무도 고블린을 의심하지 않아. 정말 아무도! 그러니 누가 어둠의 마법에 손을 대는 걸 망설이겠어?\r\n\r\n분명히 넌 서큐버스를 소환하는 법을 배우고 싶어 안달이 났겠지... 아니면 인큐버스를 더 좋아하는 건가? 친구, 쾌락보다는 사업이 우선이야. 돈이 먼저고, 소환 마법은 그 다음이지!')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(80108, '이봐, 내 절친! 마법에 한번 도전해 볼 생각 없어? 마법사 말이야? 너도 나처럼 머리가 좋아 보이는데. 이런 마법들을 익히면 돈 엄청 벌 수 있을 거야.\r\n\r\n물도 만들어내고, 음식도 만들어내고, 차원문도 열어볼 수 있지. 이런 편리한 마법들은 곧 돈을 벌어다 준다는 뜻이야: 땡그랑! 물론, 돈을 벌고 싶으면 나한테도 돈 좀 줘야지, 알겠지?'),
(80121, '듀로타는 휴양지라고 하기엔 좀 그렇군. 모래사막에 전갈, 하피까지 우글거리고, 게다가 마지막으로 갔을 때보다 악마 숭배 집단까지 생긴 것 같더군. 그래도 투자개발회사의 깡패 무리에게 당하는 것보다는 낫지.\r\n\r\n<네르트가 한숨을 쉬었다.>\r\n\r\n내가 한때 그 깡패 무리였지.\r\n\r\n어쨌든, 유능한 사업가는 항상 미래를 내다보는 법이지. 호드한 곳에 기회가 있는 법이야. 호드는 아제로스에서 가장 험난한 황무지를 개척하는 데 특화된 것 같으니, 노하우만 좀 쌓으면 남태평양의 원하는 섬으로 휴가를 갈 만큼 돈을 벌 수 있을 거야.'),
(80130, '네가 정말로 배우고 싶은 건 무기 사용법이야?!\r\n\r\n그래, 그래, 친구, 오해는 하지 마. 다만 저 다른 녀석들은 대부분 겁쟁이들이잖아, 알지?'),
(80131, '제가 지금 주변을 청소하느라 바쁜 거 안 보이세요?'),
(80136, '난 아무나 가르치지 않아, 친구. 우리 사이가 좀 나아지면 다시 와.'),
(80200, '태양샘에 감사해야겠군, $N. 무사히 도착했으니 말이야. 해야 할 일이 많네.'),
(80217, '우리 동족은 지성과 마법에 자부심을 품고 있지. 하지만 때로는 좀 더 강경한 방법이 필요하다는 걸 자네도 나도 알고 있네.'),
(80218, '태양샘이 무너진 뒤로 우리는 마나를 최대한 아껴 쓰고 있네. 한때 비전 마법의 정점에 섰던 우리가, 이제는 옛 영광의 그림자만 남았군.'),
(80219, '원정순찰대는 자랑스러운 순찰대였네. 조국이 몰락하며 그들 대부분도 목숨을 잃었지. 그래도 그 유산은 우리를 통해 이어질 걸세.'),
(80220, '오늘 우리가 이 자리에 설 수 있는 것은 오직 빛의 은총 덕분일세. 스컬지와 그 밖의 위협으로부터 우리 동족을 지키는 건 우리의 몫이지. 다만 기억하게. 정의는 공정해야 하며, 복수심에 눈이 멀어서는 안 되네.'),
(80221, '지금은 암울한 시기이지만, 우리의 동족들을 빛으로 인도해야 합니다. 그들의 상처는 완전히 치유될 수는 없겠지만, 우리는 온 힘을 다해 보살펴야 합니다.'),
(80223, '귀족의 주머니를 털고 싶든, 어두운 구석을 탐험하고 싶든, 보물 상자를 열고 싶든, 언제나 태양샘을 기억하세요.'),
(80227, '먼 길을 오셨군요. 저희 집에서 편히 쉬십시오. 태양이 당신을 인도하길 바랍니다.'),
(80243, '암울한 시대일세, $N. 하지만 우리는 동족을 빛으로 인도하고, 할 수 있는 한 그 상처를 돌봐야 하네.'),
(80244, '빛의 축복 덕분에 오늘 우리 둘 다 이 자리에 서 있네, $N. 우리는 스컬지와 다른 위협에 맞서 동족을 위해 싸울 걸세. 하지만 가르침을 잊지 말게. 복수는 정의의 이름 아래 이루어져야 하네.'),
(80245, '원정순찰대는 자랑스러운 순찰대였네. 조국이 무너지며 그들 또한 사라졌지만, 그 유산은 우리 안에서 이어질 걸세.'),
(80246, '태양샘을 잃은 뒤로 우리는 마나를 가능한 한 아껴 쓰고 있네. 한때 비전 마법의 정점에 섰던 우리가 이 지경이 되었군, $N.'),
(80247, '우리 동족은 지성과 마법을 자랑스럽게 여기지만, 때로는 좀 더 거친 방법이 필요한 법이지.'),
(80248, '귀족의 주머니를 털든, 그림자 속을 기어 다니든, 남의 상자 자물쇠를 따든 태양샘을 잊지 말게.'),
(80450, '안녕하세요, $C님. 저희를 도와주러 오셨나요? 그렇다면 정말 기쁠 겁니다. 방어선을 안정시키거나 목표물을 무력화할 수 있다면 더할 나위 없이 좋죠. 그 안에 뭐가 숨어 있는지 상상도 못 하실 겁니다.'),
(80451, '안녕하세요, 잘 지내시나요?\r\n\r\n저는 콜리입니다. 이 문제를 처리하기 위해 왔습니다. 서로에게 친절하게 대해주세요. 싸울 시간이 없습니다!\r\n\r\n안으로 들어가면 이미 충분한 폭력이 있을 겁니다.'),
(80452, '저는 실버문 잔존 세력의 엘프들과 그들의 동맹들만 가르칩니다.'),
(80460, '나보다 나이가 많고 현명한 나무를 알았으면 좋겠어. 나무는 아름다운 잎사귀를 가져야 하는데, 내 나무는 시들고 죽어가고 있어.\r\n\r\n나는 살아남을 수 있을까?'),
(80601, '이봐요, 코인을 안 쓸 거면 나가세요. 진짜 손님들을 방해하고 있잖아요.'),
(80602, '안녕, 자기야. 장기 투자할 생각 있어?\r\n\r\n혹시 도박 한 판 해볼까, 꼬마 $c? 얼마 걸지 말해봐. 내가 주사위를 던져줄게. 50보다 크면 판돈을 두 배로 늘려줄게. 50보다 작으면 판돈은 영원히 사라지고.\r\n\r\n같은 금액으로 세 번 연속 이기면 상금이 세 배가 돼. 단, 세 번째 주사위 눈금이 75보다 커야 해. 세 번째 눈금이 75보다 작으면 판돈은 없어져.'),
(80603, '고블린 브루저는 가슴을 쫙 펴고 서서 낮은 목소리로 중얼거렸다.'),
(80605, '내 직감이 이 술집 주변에서 뭔가 수상한 일이 벌어지고 있다고 말해주는 것 같아.'),
(80855, '총을 든 노움이 뭘 할 수 있는지 절대 과소평가하지 마, $c!'),
(80867, '<줄진의 눈이 위아래로 움직이며 당신을 머리부터 발끝까지 훑어봅니다.>'),
(80877, '우리 민족이 가장 힘든 시기를 겪던 때, 저의 변함없는 헌신이 우리를 하나로 묶어 이 희망의 안식처를 건설하게 했습니다. 진심 어린 노력으로 저는 우리 민족과 얼라이언스 사이의 유대를 회복하고 흔들렸던 신뢰를 되살렸습니다. 저는 왕족의 칭호나 거창한 야망을 추구한 적이 없으며, 단지 확고한 지도력이 절실히 필요하다는 것을 깨달았을 뿐입니다.$B$B 그러나 명예와 선견지명으로 고귀함을 정의해야 할 우리 민족의 세계에서는 여전히 맹목적인 인식이 존재합니다. 영향력과 부의 그물에 얽매인 귀족 가문들은 우리 모두의 여정의 진정한 의미를 깨닫지 못하고 있습니다. 개인적인 이익이 아닌 우리 국민의 복지를 위해 맡았던 의장직을 부당하게 박탈당한 저는, 실망스럽게도 초점이 흐려진 현실을 목격하고 있습니다.$B$B 우리 앞에 놓인 시급한 과제에 맞서기 위해 자원과 집단적인 지혜를 총동원해야 할 때, 우리는 나아갈 길을 흐리게 하는 불필요한 논쟁에 휩싸여 있습니다.'),
(80903, '나는 고블린들에게 근육과 두뇌를 모두 사용하는 법을 가르친다.'),
(80925, '안녕하세요, $c님, 제가 도와드릴 일이 있을까요?'),
(80943, '필멸자여, 수호자들의 인정을 받고 싶은가? 시간의 흐름 속에서 조화를 유지하고 싶은가?\r\n\r\n그렇다면 더 이상 찾을 필요가 없다. 우리가 가만히 있는 하루하루가 혼돈이 질서를 파괴하기 시작하는 하루가 될 것이다.\r\n\r\n우리의 노력을 방해하려는 세력은 멈추지 않을 것이다. 하지만 언제나 더 많은 일을 할 수 있고, 당신은 바로 그 때문에 여기에 있는 것이 아니겠는가?'),
(81030, '어이쿠... 마음이 바뀌었나 보군? 갑자기 나랑 볼일이 생겼다고? 하지만 난 너랑 볼일 없어.\r\n\r\n저리 가!'),
(81050, '어둠의 여왕께서 저에게 그분의 지식을 전수할 책임을 맡겨주신 것은 저에게 진심으로 큰 영광입니다.'),
(81055, '우리 나라는 굳건히 서 있다! 나는 필요한 일을 했을 뿐이다.'),
(90001, '지속적인 성원에 감사드립니다.'),
(90002, '여긴... 여긴 어디지? 내가 살아있는 건가?'),
(90003, '쉿... 네가 금화 5개를 가져오면 가짜 서류로 네 진짜 정체를 숨길 수 있게 해줄게.'),
(90004, '아무리 훌륭한 칼이라도 관리를 하지 않으면 녹슬고 무뎌지기 마련이다. 너는 이미 무기를 선택했으니, 이제 싸워라!'),
(90010, '배를 사과로 가득 채워주니 이제 저를 따라오네요!'),
(90011, '거북이를 타고 싶어요! 어떻게 해야 할까요?'),
(90012, '안녕 꼬마야. 여기 맛있는 사과 하나 줄게!'),
(90013, '정말요? 사과가 없다고요? 그럴 리가 없잖아요.'),
(90014, '갑시다!'),
(90015, '잘했어! 이 꼬맹이에게 다시 말을 걸면 네가 탈 수 있게 해줄 거야!'),
(90016, '이 작은 거북이는 빨간 사과에만 관심이 있는 것 같네요.'),
(90017, '난 네가 싫어, 저리 가! 맛있는 사과 좀 가져와.'),
(90018, '음... 이 사과 정말 맛있네! 냠냠냠 내 친구한테 데려다주면 아마 태워줄지도 몰라. 가자!'),
(90019, '우리는 라스베가스에 갈 거야... 아니, 부티 베이에 갈 거야!')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(90020, '먼저 거북이를 길들여야 해요!'),
(90100, '안녕하십니까, $GLord:Lady; Turtle $N 님!\r\n\r\n침략자들로부터 우리 영토를 지키는 데 당신의 도움이 필요합니다!\r\n\r\n제 손을 잡으십시오. 제가 당신을 전장으로 인도하겠습니다.'),
(90101, '전장으로의 수송이 진행 중입니다! 느리지만 꾸준히 나아가면 승리합니다. 대기하세요!'),
(90150, '흠, 젊은이, 네게서는 바람의 정령의 축복이 느껴지지 않는군.\r\n\r\n요른 스카이시어와 이야기를 나누었나, 아니면 황무지에서 바람을 쫓고 있었나?'),
(90151, '바람을 맞으며 광활한 평원을 가로지르고, 숲을 지나고, 산을 넘는 당신의 모습을 상상해 보세요...\r\n\r\n미지의 땅을 달리며, 눈앞에 펼쳐진 경이로운 풍경, 지평선 너머로 펼쳐질 당신의 운명을 바라보는 여정.'),
(90152, '어머, 아직도 돌아다니고 계시는군요? 사에른이 당신을 기다리고 있을 거예요!'),
(90200, '그레이스틸 가족에게 문제를 일으켰던 마지막 사람은 결국 운하에 떠내려갔지... 무슨 말인지 알겠어?'),
(90201, '자, 토끼굴이 얼마나 깊은지 보러 오셨군요...\r\n\r\n-빨간색과 파란색 돌 두 개를 꺼낸다-\r\n\r\n파란색 돌을 선택하면 뱃사공 아이크에게 돌아가 실버파인으로 가는 배를 타고 여기서 일어난 모든 일을 잊을 수 있습니다.\r\n\r\n빨간색 돌을 선택하면... 우리 캠프로 들어와 어둠의 여왕에 대한 진실을 알게 될 겁니다. 하지만 조심하세요. 우리 편에 서게 되면 쉽게 떠날 수 없고, 영원히 포세이큰을 등져야 할 겁니다.\r\n\r\n신중하게 선택하세요.'),
(90202, '맙소사, 드디어 도착했군! 이제 얼른 내 배에서 내려! 안 그러면 배가 가라앉을 거야!\r\n\r\n술 한잔 할래? 배짱만 있다면 뭐 좀 줄게. 하지만 눈이 멀더라도 날 탓하지 마!'),
(90203, '경비원은 아무 말도 하지 않고 당신을 유심히 지켜봅니다.'),
(90250, '승자는 가장 빠른 차를 가진 사람이 아니라, 절대 지지 않으려는 사람이다.'),
(90251, '특별한 비결은 없습니다. 그냥 액셀을 끝까지 밟고 왼쪽으로 핸들을 꺾으면 됩니다.'),
(90252, '역대 최고의 레이스 이벤트 최신 소식! 매거진을 받아보세요!'),
(90253, '반짝이는 플랫츠로 향하는 일등석 좌석에 바로 탑승하세요! 저렴한 가격으로 최고의 여행 경험을 누리세요. 어디에서도 찾아볼 수 없는 최저가!'),
(90254, '상금과 보상은 버섯구름 봉우리의 쉬머링 플랫 한가운데에 있습니다! 그곳에서 그레고르나 지즐에게 말을 걸어 경주에 참여하세요!'),
(90255, '현재 고블린 팀에 참가할 사람을 기다리고 있습니다.'),
(90256, '현재 노움 팀에 참가할 사람을 기다리고 있습니다.'),
(90260, '가젯잔 타임즈 2권이 드디어 나왔습니다! 말 그대로 금처럼 값진 소장품입니다!'),
(90261, '우리 수호자들은 아즈샤라의 비밀을 미스터리로 남겨두기 위해 이 지역에서 활동해 왔습니다. 그러나 이제 우리는 어둠 속으로, 혼란 속으로 빠져 서로 제대로 소통조차 할 수 없게 되었고, 뿔뿔이 흩어졌습니다. 사방이 적들로 둘러싸여 있으며, 한때 존재했던 모든 것은 폐허의 희미한 기억으로만 남아 있습니다.'),
(90262, '이렇게 마법을 휘두를 기회를 얻은 지 정말 오래되었는데, 엘다라의 지팡이를 제작하면서 한 줄기 희망을 얻게 되었습니다.'),
(90300, '작은 상자가 지직거리는 소리를 내며 당신의 손길에 마치 살아 움직이는 듯합니다. 여러 개의 버튼과 레버가 마치 당신에게 누르라고 손짓하는 것 같습니다. 그러면 당신이 선택한 멜로디가 흘러나올 것입니다.'),
(90301, '필멸자여! 네 시대는 아직 오지 않았다!\r\n\r\n저리 가라… 뭐라고?\r\n\r\n스피디 말이지? 젊은이, 네 말에 귀 기울이고 있구나…'),
(90305, '야호! 생일이다! 생일은 일 년에 한 번 축하하는 풍습이 있다고 들었어. 축하에는 파티가 필수지. 파티에는 선물! 파티에는 맛있는 음식! 그리고 파티에는 즐거움이 가득하다고 들었어. 술이 없으면 즐거움이 무슨 의미가 있겠어? 아니, 술 말이야.'),
(90310, '이 양은 겁먹은 것처럼 보이네요.'),
(90315, '전사가 의무를 소홀히 하거나, 비겁하게 행동하거나, 불충하면 그는 아무것도 아니다.'),
(90316, '평화는 사업에 해롭다.'),
(90317, '또 한 명의 어리석은 자가 죽음으로 걸어 들어가는군. 자, 이제 블러드세일을 거스르는 자들에게 어떤 일이 벌어지는지 보여주지!'),
(90318, '깃털은 눈으로 덮여 있고, 갓 부화한 새끼는 추위에 떨고 있다.'),
(90319, '%s는 에그노그를 마시기 시작합니다.'),
(90320, '여기 온 건 정말 어리석은 짓이야, 여긴 이제 데피아즈의 땅이야.'),
(90325, '가장 용감한 영웅들에게 주목하세요!'),
(90326, '<눈사람이 노래해요.>\r\n\r\n겨울 축제가 시작되었어요. 온 나라에 사람들이 손에 눈덩이를 들고 뛰어다녔답니다.\r\n\r\n겨울의 장막이 모두에게 선물과 놀라운 것들을 가져다주었어요! 호호호!'),
(90328, '누구나 눈싸움을 좋아하죠. 얼어붙고 파랗게 변한 손으로 눈을 퍼 모아 뭉쳐서 공처럼 만든 다음, 있는 힘껏 친구에게 던지는 거예요.'),
(90330, '안녕하세요, 여러분! 윈터 베일 축제가 돌아왔습니다! 윈터 베일 축제에서 즐거운 사람들과 함께 연휴를 만끽하세요!'),
(90335, '반짝이는 장갑을 잃어버린 나, 내가 제일 아끼던 장갑을 도둑맞았어, 아, 왜 눈물이 나지 않는 걸까?!\r\n\r\n도둑들의 이름은 내 목록에 가득해, 얼어붙은 분노로 그들을 벌해야 해, 그들은 잘못을 저질렀으니까!'),
(90336, '전쟁! 윈터 베일의 즐거운 축제 분위기가 무자비한 모험가들의 공격으로 무너지고 있다!\r\n\r\n사방에 영웅들이 포진해 있고, 눈덩이가 사방에 흩날린다!\r\n\r\n전투에 참여하여 다양한 직업의 적들에게 얼음 투사체를 날리고, 겨울 특전 상자를 보상으로 받아가세요!'),
(90338, '사람들은 장작 패는 것을 좋아합니다. 이 활동은 결과를 바로 확인할 수 있게 해주기 때문입니다.'),
(90341, '레드워터 신디케이트는 길드에 합류할 새로운 구성원을 모집하고 있습니다.'),
(90342, '얼핏 보기만 해도 드워프의 정교한 솜씨와 노움의 공학 기술이 엿보입니다. 이 기계는 드넓은 푸른 하늘을 가로질러 먼 거리를 이동할 수 있게 해줍니다. 특히 이 기계는 북쪽 아르덴트 감시탑으로 향하는 것 같습니다.\r\n\r\n이 기계를 이용하면 북쪽 역병지대로 이동할 수 있으며, 가격은 은화 50개입니다.'),
(90343, '엘룬의 인도하는 빛이 이 슬픔에 잠긴 땅의 용감한 수호자들을 비추듯, 당신에게도 비추기를 바랍니다.'),
(90345, '으, 저게 패션이라고? 대체 어떤 사람이 저렇게 창피한 옷차림을 하고 밖에 나가는 거야?\r\n\r\n다행히 패션 코인 몇 개만 주면 이 멋진 옷 중 하나로 바꿔줄 수 있어. 그럼 넌 이 동네에서 제일 옷 잘 입는 $C가 될 거야. 패션 감각 좀 키우고 나서 다시 얘기하자.'),
(90350, '1. 기기를 양손으로 잡으세요.\r\n\r\n2. 머리 위로 들어 올리세요.\r\n\r\n3. 손을 놓으세요.\r\n\r\n4. 티 없이 맑아진 마음의 햇살을 만끽하세요.'),
(90351, '정성껏 수작업으로 제작된 화분에 비옥하고 물을 충분히 준 흙이 담겨 있습니다.'),
(90352, '정원과 서재가 있다면 필요한 모든 것을 갖춘 셈입니다.'),
(90353, '제 꿈은 세계에서 가장 큰 호박을 키우는 거예요!\r\n\r\n여러분 꿈은 무엇인가요?'),
(90354, '아, $N님, 오실 줄 알았습니다.\r\n\r\n씨앗을 키우고 흙을 가꾸는 법을 배우러 오셨나요?\r\n\r\n딱 맞춰 오셨네요.'),
(90355, '저는 모스후프 부족의 가장 현명한 원로 중 한 분이신 샨도 컨에게 생존 기술을 배우기 위해 이곳에 왔습니다.\r\n\r\n제 누나는 상처를 치료하고 응급처치를 가르치는데, 저는 진정한 치유는 어떤 붕대로도 고칠 수 없는 대지모신로부터 온다는 것을 확신합니다. 그것은 바로 대지가 준 선물입니다.\r\n\r\n식량 재배는 제 발굽만큼이나 제가 간절히 배우고 싶은 기술입니다.'),
(90357, '흙. 요즘 내게 남은 건 이것뿐이군.\r\n\r\n차라리 새로운 균사체를 계속 배양해서 새로운 종류의… 뭐?\r\n\r\n아, 버섯도 좋아하시는구나?'),
(90358, '내가 여기 혼자 흙더미를 파헤치는 모습을 보면 너도 다른 사람들처럼 똑같이 생각하지 않니?\r\n\r\n걱정 마, 그건 당연한 일이야.\r\n\r\n어쨌든 넌 버섯과는 비교도 안 되잖아.'),
(90360, '잠시 동안 살아있었던 내 모습은 오만함, 용기, 그리고 어리석음의 전형이었으며, 네가 감히 그곳에 갈 수 있을 것 같으면 직접 목격할 수 있을 것이다.\r\n\r\n저 끔찍한 괴물은 네가 지금까지 본 것과는 전혀 다를 것이다.\r\n\r\n그중 절반만 거미처럼 생겼고… <피를 토하며> 언데드… 적어도 열 명은 될 것 같아…')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(90361, '저 거미들은 내가 죽여본 적 없는 종류야.\r\n\r\n떼로 쳐도… 세 명은 있어야 저 짐승에게 흠집 하나라도 낼 ​​수 있을걸.\r\n\r\n이 땅에서는 절대 혼자 다니지 마! 절대로!'),
(90362, '이봐요! 당신의 도움이 필요해요!'),
(90365, '말이 당신을 좋아하는 것 같네요.'),
(90366, '그리핀의 나른한 태도를 보니 당분간은 날 준비가 안 된 것 같군.\r\n\r\n무기력하고 배고픈 게 분명해. 드워프 순한 음료 좀 주면 기운이 나고 날아오를 수 있을 거야.'),
(90367, '신뢰는 돈으로 살 수 있는 게 아니야, $C.'),
(90368, '늑대가 무언가를 찾으려는 듯 땅을 긁습니다. 당신이 다가가자 늑대는 고개를 듭니다. 새로운 냄새가 늑대의 주의를 끈 것입니다.'),
(90369, '말은 비록 불멸의 생물이지만, 당신의 움직임을 감지하는 듯 보입니다.'),
(90370, '이봐! 나 좀 내보내 줘!'),
(90371, '마법은 언제나 우리 주변에 있단다, $R. 마법을 느끼고, 다루고, 아제로스 모두의 행복을 위해 나누도록 하렴. 우리가 목격했던 똑같은 실수를 반복하지 않도록.'),
(90372, '$R, 언뜻 보기에는 잘 드러나지 않을 수도 있지만, 이처럼 어려운 시기에 얼라이언스이 베풀어주는 도움을 기꺼이 받아들이겠다는 점을 말씀드리고 싶습니다.'),
(90373, '스마이트 사제가 최고의 사제다.'),
(90374, '영혼의 고리 흑마법사가 PvP 최강이다!'),
(90375, '뭘 쳐다봐? 가서 파밍이나 해.'),
(90376, '성기사는 탱킹할 수 있고, 앞으로도 탱킹할 것이다!'),
(90377, '소환수 치워!'),
(90378, '어그로 뺏어놓고 그게 정상이라고 생각해?!'),
(90379, '도적은 PvP에서 쓸모없어!'),
(90381, '숫양은 위엄 있는 만큼이나 고집스러운 동물입니다. 숫양이 당신을 응시합니다.'),
(90382, '코도 비스트는 평화로운 생물입니다. 일단 움직이기 시작하면 막을 수 있는 것은 거의 없습니다.'),
(90500, '이슈누-알라, 섀도우리프 보병 전초기지에 오신 것을 환영합니다. 저희는 페랄라스에서 왔으며, 티란데와 그녀의 백성을 도와 이 땅을 타락으로부터 해방시키고, 호드가 우리 숲을 파괴하지 못하도록 막고 있습니다!\r\n\r\n아, 저희 사정으로 불편을 드려 죄송합니다. 여기까지 오셨으니, 원하시면 음식을 사 드시거나 하룻밤 묵으셔도 좋습니다.'),
(90501, '난 자유 기사야! 주군이 없다고. 뭐가 문제라도 있어?\r\n\r\n<그녀는 잠시 당신을 노려보다가 얼굴에 미소를 짓는다.>\r\n\r\n아, 뭐... 우리 예배당에 온 걸 환영해! 침낭이나 식량을 드릴 수 있어.'),
(90560, '타우렌과 소고기를 절대 먹지 마세요.'),
(90561, '내일은 멋진 무언가를 발견하게 될 거예요.'),
(90562, '과거의 적이 머지않아 아군이 될 것입니다.'),
(90563, '당신은 손대는 모든 일에서 행운을 얻을 것입니다.'),
(90564, '누군가가 당신에 대해 좋게 이야기하고 있어요.'),
(90565, '낯선 지역에 착륙할 때는 주의하십시오.'),
(90566, '불필요한 위험을 감수하지 마세요.'),
(90567, '당신은 큰 재산을 상속받게 될 것입니다.'),
(90568, '당신의 첫사랑이자 마지막 사랑은 자기애입니다.'),
(90569, '휴식은 좋은 것이지만, 지루함은 휴식의 형제와 같다.'),
(90570, '소박한 취향을 가진 사람들은 언제나 최고로 만족한다.'),
(90571, '전쟁의 물결에 휩쓸리지 마세요.'),
(90572, '당신은 적들을 말문이 막히게 만듭니다.'),
(90573, '당신은 위선을 잘 간파하는 눈이군요.'),
(90574, '남을 가르칠 때 가장 많이 배운다.'),
(90575, '머지않아 당신은 중요한 문제에 대해 선택을 내려야 할 순간이 올 것입니다.'),
(90576, '정당한 이유 없이 난쟁이를 발로 차지 마세요.'),
(90577, '다음에 듣는 제안을 받아들이세요.'),
(90578, '포세이큰이 뭔가 꾸미고 있는 게 분명해.'),
(90579, '가만히 서 있으면 많은 잘못된 선택을 하게 된다.'),
(90580, '신성한 방패와 귀환석이 영웅을 영웅답게 만드는 것은 아닙니다.'),
(90581, '파란색으로 표시된 답변은 항상 정답입니다.'),
(90582, '화산심장부에서 당신의 행운이 기다리고 있습니다.'),
(90583, '생존에 특화된 사냥꾼이라고 해서 반드시 살아남는 것은 아닙니다.'),
(90584, '샤먼의 축복은 아주 간단합니다.'),
(90585, '내일은 해가 뜰 것이다.'),
(90586, '당신이 기울이는 모든 노력은 수리 비용을 충분히 상쇄할 만큼 가치가 있습니다.'),
(90587, '지갑이 텅 비는 동안, 악당의 마음은 가득 찼다.'),
(90588, '빛을 믿으되, 당신의 탈것을 잘 살펴보십시오.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(90589, '낚시라는 직업을 통해 큰 휴식 능력과 인내심을 기를 수 있을 것입니다.'),
(90590, '당신은 아직 운이 좋지 않네요.'),
(90591, '닦을 것을 기대하는 사람은 결코 실망하지 않을 것이다.'),
(90592, '친구는 당신의 시간을 부탁합니다. 길드는 당신의 돈을 부탁합니다.'),
(90593, '용의 그림자 아래에는 절대 서 있지 마라.'),
(90594, '근처에 있는 누군가가 당신에게 추파를 던지고 싶어합니다.'),
(90595, '가벼운 마음가짐은 험난한 전장을 헤쳐나가는 데 도움이 됩니다.'),
(90596, '당신의 미래는 보라색 비로 흐려져 있습니다.'),
(90597, '트롤은 절대 믿지 마세요. 도적도 마찬가지고요. 특히 트롤 도적은 더더욱 믿지 마세요.'),
(90598, '지금이야말로 새로운 것을 시도해 볼 때입니다. 어쩌면 새로운 기술을 배워보는 것도 좋겠죠.'),
(90599, '당신의 행운의 숫자는 4, 8, 15, 16, 23, 42입니다.'),
(90600, '인생이 당신에게 레몬을 준다면, 수리 비용을 지불하세요.'),
(90601, '모든 허브는 제각기 다른 아름다운 시기에 꽃을 피웁니다. 그때 따면 되죠!'),
(90602, '검은바위 산으로 가는 길은 선의로 포장되어 있다.'),
(90603, '당신은 길고 행복한 삶을 살게 될 것이며, 그 과정에서 여러 번 부활하게 될 것입니다.'),
(90604, '가서 좀 쉬세요. 그럴 자격이 충분해요. 하지만 꼭 숙소에서 쉬세요!'),
(90605, '그 거미를 꼭 챙겨야 했어.'),
(90606, '당신은 거액의 유산을 상속받게 될 것입니다. 그리고 경매장에서 그 돈을 탕진할 겁니다.'),
(90607, '페이스롤러를 사용하는 길은 지혜로 가는 길이 아닙니다.'),
(90608, '앞으로 수많은 레이드 전멸을 경험하게 될 겁니다.'),
(90609, '군대 한 팀과 싸우는 자는 순교자이고, 다섯 팀과 싸우는 자는 정예병이다.'),
(90610, '직접 약탈해 보기 전까지는 절대 알 수 없어.'),
(90611, '금화가 부딪히는 소리가 들릴 겁니다.'),
(90612, '당신 민족의 지도자가 당신을 생각하고 있습니다.'),
(90613, '언젠가는 그 거치대를 살 수 있을 거예요.'),
(90614, '정체를 알 수 없는 고기는 절대 먹지 마세요.'),
(90615, '정직한 고블린이나 술에 취하지 않은 드워프는 절대 믿지 마라.'),
(90616, '미래는 재앙으로 점철될 것 같다.'),
(90617, '금발 부츠 한 짝을 신은 키 큰 나이트 엘프를 조심하세요.'),
(90618, '일상적인 임무를 수행할 때 주의하십시오.'),
(90619, '평범한 것들 속에서 아름다움을 찾아보세요. 그리고 그것들을 팔아서 돈을 벌어보세요.'),
(90620, '서사시는 자식과 같습니다. 그 어떤 서사시도 당신이 쓴 것만큼 소중하지 않습니다.'),
(90621, '소개팅에 나가겠다고 약속한 사람은 픽업에 대한 의무를 지게 된다.'),
(90622, '나라면 당분간은 배를 타지 않을 거야.'),
(90623, 'Xerron을 만나지 않는 한 전망은 밝아 보입니다.'),
(90624, '다른 운세에서 더 나은 결과를 얻을 수도 있습니다.'),
(90625, '당신은 머지않아 100이 나올 가능성이 높습니다.'),
(90626, '불신은 마법을 파괴한다.'),
(90627, '지혜의 시작은 그것을 갈망하는 것이고, 지혜의 끝은 이론을 짜는 것이다.'),
(90628, '당신은 당신이 싫어하는 사람으로부터 선물을 받게 될 것입니다.'),
(90650, '안녕하세요, $N님. 운세를 들어보시겠어요?'),
(90651, '다시 읽으러 오셨나요?'),
(90652, '안 좋은 소식이 있어요. 말씀드릴까요?'),
(90653, '나라면 오늘은 파란색 옷을 입지 않을 거야.'),
(90654, '8은 제 행운의 숫자입니다. 항상 8에 걸죠.'),
(90655, '네 발을 읽어볼게. 어머나. 좋은 징조는 아닌 것 같군.'),
(90656, '나는 수많은 불행을 봤지만, 네 불행이 제일 심각하구나!'),
(90657, '조만간 새로운 여행 동반자를 찾아야 할 것 같네요.'),
(90658, '오늘 하루 어때요? 농담이에요, 이미 알고 있어요.'),
(90659, '땅에서 주운 빨간 버섯은 먹지 마세요. 나중에 제게 감사할 거예요.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(90660, '당신은 언젠가 진정한 사랑을 찾게 될 거예요. 하지만 그러고 나면 그 사랑을 어디에 두었는지 잊어버리겠죠.'),
(90661, '감옥 음식이 괜찮으시길 바랍니다.'),
(90662, '오늘 만나게 될 그 고블린 연금술사에게서 물약을 사지 마세요.'),
(90663, '오늘 저 오거 무리와 마주치지 마세요. 온몸의 뼈가 부러질 거예요.'),
(90664, '남은 수명이 얼마나 되는지 알고 싶으세요?'),
(90665, 'K로 시작하는 우스꽝스러운 이름을 가진 오크를 조심하세요. 그는 나쁜 놈입니다.'),
(90666, '지금 바로 경매장을 확인해 보세요. 믿기 힘든 특가 상품들이 있을지도 몰라요.'),
(90667, '수영할 줄 아시겠죠?'),
(90670, '상어는 호기심 어린 눈으로 당신을 바라보며 마치 무언가를 기대하는 듯 당신의 손을 쪼아댑니다.'),
(90987, '몇 주 전에 우리 배가 난파됐어요. 지금까지 어떻게든 살아남았죠. 멀록들이 정말 골칫거리인데, 도와주시겠어요?'),
(91190, '무슨 일로 이곳에 오셨습니까?'),
(91191, '은빛 여명회은 혼돈이 도사리고 있는 아제로스 내의 질서를 유지하기 위해 머나먼 땅에서 싸웁니다.'),
(91200, '이건 전부 고블린의 정밀함에 달린 거야. 오크가 저렇게 섬세한 부품을 다룰 수 있을 거라고 생각해?\r\n\r\n뭐 필요한 거 있어, 친구?'),
(91201, '나무 베는 일은 쉬운 일이 아니야, 특히 이 게으른 녀석들 때문에 더 그렇지!\r\n\r\n그래서 나 같은 유능한 현장 감독이 있는 거야, 생산성을 높이는 거지!'),
(91202, '안녕하세요! 돈을 아끼려고 직접 물약을 만들고 싶으시다면, 잘 찾아오셨습니다!'),
(91204, '나한테 마실 것 좀 주지 않으면, 얼른 꺼져, 꼬맹아!'),
(91205, '남태평양에서 온 온갖 진기한 물건들을 찾고 계신다면, 운이 좋으시군요!\r\n\r\n이런 물건들을 구할 수 있는 곳은 오직 Zeet\'s뿐입니다!\r\n\r\n참고로, 환불은 절대 불가합니다!'),
(91216, 'Wuzgut, 아무도 목재를 훔쳐가지 못하게 확실히 해 줘. 네가 사겠어?'),
(91220, '여기 로즐 노즐 좀 보세요! 목이 엄청 마르신 것 같네요. 얼굴에 땀이 줄줄 흐르고, 뜨거운 햇볕이 내리쬐니 그럴 만도 하죠!\r\n\r\n제 물 좀 드세요. 얼음처럼 차갑고 갈증도 싹 가시고, 가격도 아주 저렴해요!\r\n\r\n이 동네에서 이런 물은 찾기 힘들 거예요.'),
(91221, '술이 당기냐, 친구? 싸고 좋은 수제 술 있어!\r\n\r\n달라란의 시시한 와인보다 훨씬 빨리 취하게 해줄 걸세. 마음먹은 고블린이 뭘 할 수 있는지 보여주는 거지.'),
(91225, '스파크워터에 오신 것을 환영합니다!\r\n\r\n저는 이 건물을 처음부터 끝까지, 돌 하나 쌓는 것부터 시작해서 직접 설계하고 건축했습니다.\r\n\r\n혹시 건축 프로젝트가 있으시면 언제든 연락 주세요. 비용이 꽤 들겠지만, 그만한 가치가 충분히 있다고 자신 있게 말씀드릴 수 있습니다!'),
(91227, '트롬카, 친구. 고블린들은 확실히 고급 고기를 좋아하는 것 같군. 그것도 아주 많이 먹는군.'),
(91229, '그 플랫폼이 바다벌레들에게 점령당했다는 소문을 들었어. 걔네들이 날 괴롭히러 오지 않았으면 좋겠어!'),
(91230, '제 임무는 항구의 안전을 확보하는 겁니다. 사정거리 안에 미확인 선박이 들어오면 이 무기를 발사하죠. 화약으로 가득 찬 쇠구슬은 감히 우리를 건드리는 멍청한 배라면 어떤 배든 침몰시킬 겁니다.'),
(91231, '미스파이어 따위는 집어치워! 뭔가 보이면 이 비행기에 화약을 가득 채우라는 명령을 받았어!\r\n\r\n아마 동쪽 왕국들을 노리게 되겠지!'),
(91232, '흐흐, 똑똑해지고 싶은 거야? 그럼, 이런 두루마리나 책들을 좀 읽어보면 지식을 넓히는 데 도움이 될 거야. 몇 권만 읽어도 금방 지식이 쌓이긴 하겠지!'),
(91238, '안녕하세요! 스파크워터 주점에 오신 것을 환영합니다!\r\n\r\n편하게 앉으셔서 자리를 잡으세요! 음료가 필요하시면 저에게 말씀해주세요.'),
(91239, '뭘 원하는 거야, 친구? 오늘은 아무도 사형당할 예정이 없어.'),
(91240, '난 부수고 싶지 않아, 평화를 유지해야 해. 안 그러면 토르그가 어쩔 수 없이 부숴야 할 거야.'),
(91242, '제 유명한 와즈로켓 때문에 오셨나요?\r\n\r\n들어본 적이 없다고요? 무슨 말씀이세요?'),
(91243, '네네? $R이 고울팽에게 뭘 원하는 거죠?\r\n\r\n고울팽이 습지로 돌아왔어요! 고울팽이 여기의 위대한 지도자가 되어 모스하이드를 다시 하나로 만들 거예요! 네네!\r\n\r\n고울팽이 그놀 그놀 부족을 강하게 만들고 당신도 도와주세요!\r\n\r\n우리는 좋은 일을 해요! 네네!'),
(91244, '낚시를 즐겁게 마친 후 편히 쉬는 것보다 더 좋은 건 없죠.'),
(91245, '고블린들은 흥미로운 종족이지만, 좀 더 영적인 면모를 갖출 필요가 있다.'),
(91246, '길니아스는 어두운 시절을 겪었소. 그대 같은 새 벗이 있으니 희망은 남아 있소.$B$B얼라이언스가 우리를 버릴까 두려웠지만, 우리는 아직 여기 서 있소.$B$B저 알터랙 쓰레기들에게는 결코 무릎 꿇지 않겠소.$B$B우리가 승리할 것이오.'),
(91249, '어슬렁거리지 마세요! 볼일이 없으면 얼른 나가세요. 안 그러면 낭패를 볼 겁니다!'),
(91250, '저희는 전 세계 곳곳에 있는 친구들이 좋은 물자를 보내주고 있어서 도움을 받고 있습니다. 현재 이 항구는 레반투스크 마을로 향하는 배편을 보내고 있으니, 오지까지 가실 계획이라면 참고하세요.'),
(91251, '이 고블린들이 호드의 명예로운 일원으로서의 위상을 제대로 보여줄 수 있을지 곧 알게 될 것이다...'),
(91252, '석유 시추 플랫폼에서 잠시 벗어나 휴식을 취하니 정말 좋네요!'),
(91253, '그 빌어먹을 나무 베는 일에서 게으름 피우다가 해고당한 건 정말 최고의 행운이었어!\r\n\r\n아직 아무도 날 못 찾았고, 시간도 얼마든지 있으니, 다 엿이나 먹어라!'),
(91255, '고블린의 몸에는 온갖 베인 상처, 긁힌 상처, 멍, 그리고 찔린 상처가 가득하다.'),
(91256, '라즐의 가게에 오신 것을 환영합니다! 골목에 있는 얼간이 지트는 신경 쓰지 마세요. 그놈이 파는 물건은 싸구려 잡동사니일 뿐입니다!\r\n\r\n제가 파는 건 아제로스 전역에서 공수한 진짜 희귀 아이템들이에요! 수량이 한정되어 있으니 선착순으로 구매하세요. 이 세상의 모든 모험가에게 큰 도움이 될 겁니다!\r\n\r\n자, 어서 오세요! 라즐의 특별한 희귀 아이템들을 다른 누군가가 싹쓸이하기 전에 얼른 가져가세요!'),
(91259, '지금 누구랑 얘기하고 있는지 알아요?'),
(91266, '듀로타에서의 벌목 작업이 순조롭게 진행되고 있습니다!\r\n\r\n이 지역에 나무가 아주 많은 건 아니지만, 이 나무들은 엄청나게 크고 굵습니다. 덕분에 목재를 꽤 많이 얻을 수 있을 것 같습니다!'),
(91267, '지독한 더위 때문에 모든 파쇄기가 평소보다 훨씬 빨리 고장 나고 있어!\r\n\r\n이런 장비를 많이 써봤지만, 이렇게 문제가 많은 적은 처음이야!\r\n\r\n다 저 햇볕 때문이야. 릭스(Wrix)에 수리 좀 빨리 하라고 전해줘! 그동안 쌓아온 경험을 헛되게 하고 팔로 직접 파쇄해야 하는 건 정말 비효율적이라고!'),
(91274, '할 일은 언제나 많고, 그 모든 일을 끝내는 건 제 책임이에요! 배송도 예정되어 있고, 이 모든 돌과 광석을 사람들에게 가져다줘야 하거든요!\r\n\r\n제가 없었으면 여기 있는 것들의 절반도 존재하지 않았을 거예요! 참, 혹시 일자리 찾고 계세요?'),
(91277, '날 고용한 이유가 고작 곡괭이질이라니! 쉬운 일이네!'),
(91280, '난파당해 본 적 있어요? 솔직히 말해서, 정말 끔찍해요.'),
(91281, '선장의 답신을 기다리며 그는 서두르지 않고 있다.'),
(91285, '어둠이 도사리고 있으니, 마음을 잘 지키세요.'),
(91286, '볼트래칫은 꽤 힘든 시간을 보내고 있는 것 같지만, 나는 그렇지 않아, 하하!')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(91287, '환영합니다. 편하게 계세요.'),
(91288, '저희 집에 오신 것을 환영합니다. 필요하시면 여기서 쉬세요.'),
(91289, '대지의 근원적인 힘들 사이의 균형이 끊임없이 변화하고 있다.\r\n\r\n지구의 영역에 혼란이 일어나고 있다. 어디서부터, 어떻게 시작되었는지는 알 수 없지만, 시간이 흐를수록 단절이 심화되는 것을 느끼고 있다.'),
(91290, '우리 부족은 오랫동안 이 산봉우리 속에 숨어 지냈습니다. 이제야 고향에서 쫓겨나 어둠 속으로 내몰렸습니다.\r\n\r\n부족의 물자가 많이 떨어졌지만, 제가 가진 얼마 안 되는 것을 드리겠습니다. 와일드터스크가 당신을 위해 해 드릴 일이 있습니까?\r\n\r\n아니면, 당신이 우리를 위해 해 주실 일이 있습니까?'),
(91292, '스파크워터 항구 소식 들으셨나요?'),
(91296, '다양한 수배자 공고가 올라온 게시판.'),
(91297, '나는 패배했다. 이제 나를 어떻게 할 건가요?'),
(91298, '좋아, 좋아! 날 다시 구덩이로 데려가 줘, 하지만 죽이지만은 마!'),
(91299, '알았어, 알았어! 사장님 말씀대로 할게요!'),
(91300, '제발, 안 돼요! 저 금 있어요, 제가...'),
(91303, '안녕, $r. 사막은 수많은 용감한 모험가들의 목숨을 앗아갔지. 조심스럽게 걷고 앞길을 잘 살피렴.'),
(91350, '달라란은 파괴되었을지 모르지만, 우리는 여전히 마법에 대한 더 큰 지식을 위해 노력하고 있습니다.'),
(91400, '나는 잔치를 위한 고기도 준비하고 전쟁을 위한 가죽도 준비하는데, 네가 필요한 게 뭐냐?'),
(91401, '이봐, 와일드터스크 마을에 온 걸 환영해. 쓸데없는 일에 참견하지 마. 안 그러면 내가 가만두지 않을 거야!'),
(91402, '비록 우리가 집에서 쫓겨났지만, 영혼들은 여전히 ​​우리를 지켜보고 있고, 부두교의 힘은 우리 편이야!'),
(91403, '$r님, 안녕하세요. 무슨 일로 오셨나요?'),
(91405, '야, 내 리듬 방해하지 마!'),
(91411, '날씨가 흐트러졌군. 로그 경께서 우리에게 도움을 청하셨지만, 우리는 그를 도울 수 없어. 자네는 도울 수 있을지도 몰라!'),
(91412, 'Wildtusk는 Gortog의 친구입니다. Gortog를 도와주세요.'),
(91414, '산은 휴식과 안정을 취하기에 좋은 곳이다.'),
(91415, '사냥의 스릴은 세상에서 가장 멋진 것 중 하나지, 친구.\r\n\r\n고대에는 트롤들이 모든 것을 지배했었어!'),
(91710, '나는 한때 위대한 마법사였지만, 이제 모든 것을 뒤로하고 사과를 가꾸는 데 전념하는 것이 좋다.'),
(91711, '계속 말씀해 주세요, 듣고 있어요.'),
(91712, '이건 시간 낭비가 아니어야 할 텐데.'),
(91713, '$c님, 저를 도와주러 오신 건가요?'),
(91720, '$r님, Norga가 도와드릴 수 있는 게 뭘까요?'),
(91722, '이곳을 지키는 것이 제 임무입니다.'),
(91723, '영혼들이 우리와 소통하고 있으니, 내가 귀 기울이고 있어야 해!'),
(91724, '저는 바빠요, 무슨 용건이세요?'),
(91726, '우리는 포세이큰을 위해 이 땅을 되찾아주는 의무를 다해야 합니다.'),
(91729, '이곳에는 많은 미스터리가 있는데, 당신은 지식을 찾아 오셨습니까?'),
(91730, '나겔라스 공작을 방해하지 않는 편이 좋겠습니다.'),
(91742, '여기는 위험한 곳이니, 대비하는 게 나쁠 건 없죠.'),
(91747, '요리해 드릴 게 있으신가요?'),
(91748, '예?'),
(91749, '빨리해, $c, 나 지금 꽤 바빠.'),
(91750, '어둠의 여왕을 섬기러 왔느냐?'),
(91753, '$R님, 저를 위해 해주실 수 있는 일이 있을까요?'),
(91754, '이곳은 황무지나 다름없으니, 그나마 구할 수 있는 재료로 요리하는 법을 배우는 게 최선입니다.'),
(91755, '할 일이 많은데, 도와주시겠어요?'),
(91767, '저는 아이언포지 왕국의 국경을 점검하기 위해 파견되었습니다.'),
(91768, '플랙스위스커 전선은 아즈샤라를 조사하고 노움들을 위해 연구를 계속하기 위해 설립되었습니다!\r\n\r\n우리는 동족들과 멀리 떨어져 있지만, 큰 진전을 이루고 있습니다!\r\n\r\n플랙스위스커 전선을 돕기 위해 오셨습니까?'),
(91769, '안녕하세요! 저희 가게에는 손님이 별로 안 오시거든요!'),
(91770, '지그노의 친구는 내 친구이기도 해, $r!'),
(91771, '농사일은 정말 힘든 일이죠. 돼지에 대해서는 좀 아시죠?'),
(91775, 'Analyzor 53G가 오작동하는 것 같습니다.'),
(91776, '감히 내게 말을 걸다니, 진정한 왕족을 보러 오셨습니까?'),
(91777, '우리 같은 외부인에게 폐를 끼치지 않으면 살아남을 것이다.'),
(91778, '침입자여, 조심해서 걸으십시오. 조류가 당신을 끌어당길 수 있습니다.'),
(91779, '침입자여, 조심해서 걸으십시오. 조류가 당신을 끌어당길 수 있습니다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(91780, '스크락은 당신을 멍하니 바라봅니다.'),
(91781, '외부인이시여, 하버리지에 오신 것을 환영합니다. 저는 이곳의 지도자 산브클라입니다.\r\n\r\n저는 한때 지옥 같았던 고향을 떠나 더 나은 미래를 향해 우리 종족을 이끌고 있습니다.\r\n\r\n어쩌면 이곳이 이제 우리의 고향일지도 모르겠습니다. 더 나은 미래를 위해서 말이죠.\r\n\r\n이곳의 드레나이들은 친절하며 당신을 존중할 것입니다.'),
(91782, '평화롭게 오셨습니까? 아니면 저와 싸우러 오셨습니까?'),
(91783, '이곳에 오려면 엄청난 마법 능력을 지녀야 할 겁니다.'),
(91798, '음매.'),
(91799, '필멸자여, 내 영역에서 무엇을 원하는가?'),
(91854, '고르도쉬의 많은 이들이 폭군 왕을 따라 길을 잃었고, 내 환영은 오직 내 백성의 몰락만을 보여주었지만, 내 말을 듣는 자는 거의 없다.'),
(91883, '캘런에 발이 묶여 있으니 가족 걱정이 자꾸 드네요. 그래도 끔찍한 건 아니에요. 읽을거리가 많으니까요.'),
(91891, '블랙록은 호드에게 골칫거리이므로 반드시 처리해야 합니다.'),
(91950, '요리는 정교한 예술이며, 제한된 자원으로 요리를 해내는 것은 그 예술성을 더욱 높여줍니다.'),
(91953, '이처럼 황량한 섬에서도 우리는 믿음을 잃지 말아야 합니다.'),
(91954, '낚시하기에 정말 좋은 날이네요, 그렇지 않나요?'),
(91973, '힘과 명예 $r, 무엇이 필요하신가요?'),
(92000, '쿨 티라스의 수력술사들은 세계적으로 유명합니다. 바로 그 이유 때문에 우리는 우리의 마법을 비밀로 유지하고 있습니다.'),
(92001, '강력한 함대를 보유하려면 파도를 지배해야 합니다. 그것이 바로 우리 수력술사들이 하는 일입니다. 함대를 지휘하는 것은 물론, 바다의 흐름을 조종하여 우리에게 유리하게 만들거나, 적에게 불리하게 만드는 것이죠.'),
(92002, '이곳에서 낯선 얼굴을 보니 반갑군요. 저희는 꽤 오래전에 난파되어 이곳에서 그럭저럭 살아가고 있습니다.\r\n\r\n여기는 저희 함대를 이끌다 공격받았을 때 전사한 제독의 이름을 딴 \'카엘란의 휴식처\'입니다. 도와주러 오셨다면, 저희는 정말 도움이 절실히 필요합니다.'),
(92003, '나는 방화선의 갑판장이다. 자네가 내 갑판 위에 서 있는 건 위험해!\r\n\r\n내 갑판 위에서는 발밑을 조심해라, 알겠나?'),
(92005, '이 섬은 위험합니다. 야생 환경에 익숙하지 않다면 카엘란의 휴식처에만 머무르십시오.\r\n\r\n우리 마을 경계 밖에는 온갖 악이 도사리고 있으며, 우리의 약점을 시험하려 합니다.'),
(92006, '이 말뚝 너머로는 조심하세요. 고개를 갸우뚱거리며 걸으세요.\r\n\r\n방심하면 목숨을 잃을 수도 있습니다.'),
(92007, '선원들은 지나치게 오만하고 소란스러운 무리입니다.\r\n\r\n배에서는 유능할지 몰라도, 카엘란의 휴식처에 혼자 남겨두면 야생 동물만큼이나 골칫거리입니다.'),
(92009, '뭘 보고 있는 거야?'),
(92010, '해병대는 보통 모든 공로를 인정받지만, 실제 힘든 일은 모두 우리가 합니다.'),
(92011, '내가 누군지 알아? 바로 발다리온 스마이트다! 맞아, 바로 그 사람이야!\r\n\r\n나는 세계적으로 유명한 복서이자 쿨 티라스의 챔피언이지! 벌써 4년이나 고향에 못 갔지만, 마지막으로 갔을 때는 챔피언 자리를 지키고 있었어!\r\n\r\n이렇게 징집되다니 참 안타깝군. 특히 여기 갇히게 되다니…\r\n\r\n뭐, 어쩔 수 없지. 여기 있는 동료들도 꽤 괜찮으니까. 특히 고향에서 내가 얼마나 유명한지 생각하면 말이야.'),
(92012, '제 부하들이 당신을 잘 대접했기를 바랍니다. 스톰윈드를 떠난 후로 저희 부하들은 다소 초췌해졌습니다.'),
(92013, '풋내기라고? 여기서 이름을 떨치고 싶은 건가? 전설 속 영웅처럼 되고 싶은 건가?\r\n\r\n하지만 유감스럽게도, 여기서는 역겨운 늪물밖에 못 찾을 걸세.'),
(92014, '스톰윈드에서 무슨 소식 들었어? 그 망할 놈들이 우리를 여기 버려두고 갔어.'),
(92015, '괜히 소란 피우지 마세요. 지금도 인력이 부족한 상황입니다.'),
(92016, '새로운 얼굴을 보니 반갑네요. 진부함은 확실히 짜증스러울 수 있거든요.'),
(92017, '안녕하세요, 슬픔의 수호대에 오신 것을 환영합니다. 저는 성기사 자나토스입니다. 이곳을 지키고 있습니다.\r\n\r\n이 요새는 제1차 대전쟁 이전에 아제로스 왕국 서쪽 입구를 감시하기 위해 건설되었습니다.\r\n\r\n제1차 대전쟁 때 함락된 이후로 이곳은 황폐해졌습니다.\r\n\r\n이곳이 파괴된 후, 저는 이곳을 되찾기 위해 파견되었습니다. 어느 정도 복구를 진행하고 이곳을 점령했지만, 아직 할 일이 많습니다. 특히 바로 옆 늪지대의 어둠과 스토나드에 도사리고 있는 오크들 때문에 더욱 그렇습니다.'),
(92021, '여기 있는 부츠들은 모두 잘 정리해 놨어요. 혹시 부츠 찾으시는 거 있으세요?'),
(92022, '이제 안으로 들어갈 수는 없지만, 제 오두막은 그대로 둘 수 있게 해줬어요!\r\n\r\n버섯 좀 사실래요?'),
(92023, '어이, 다들 어디 갔어?'),
(92024, '나는 수많은 전쟁에 참전하여 많은 적을 물리쳤다. 드레노어에서부터 이곳 전초기지까지, 나는 이곳을 큰 영광으로 이끌 것이다.\r\n\r\n오그리마의 가장 뛰어난 지혜를 가진 이들이 나에게 호드의 작전을 지휘하도록 맡겼으니, 나는…\r\n\r\n당신은 도움을 주러 왔습니까? 아니면 당신의 이름을 떨치러 왔습니까?'),
(92025, '아, 보랄루스에 다시 가고 싶다… 배 수리가 끝나면 얼른 집으로 돌아가고 싶어. 수리가 끝나면 적어도 일 년 동안은 매일 모든 술집에 갈 거야.'),
(92026, '누가 좀 도와줄 수 있을까요? 쉘 담당자들을 찾고 있어요.'),
(92027, '나는 저축한 돈을 이 사람들에게 조개껍데기와 교환했는데, 그들은 일주일 안에 두 배로 불려주겠다고 약속했다.'),
(92028, '하지만 지금 그들은 여기 없네요. 저, 어… 잔돈이 좀 필요해요.'),
(92029, '조개껍데기를 잔돈으로 바꾸시겠어요?'),
(92030, '혹시 잔돈 있으신가요? 동전으로 갚겠습니다.'),
(92031, '난 미치지 않았어, 맹세해. 이 조개껍데기들은 엄청난 값어치가 있어.'),
(92032, '조개껍데기! 조개껍데기 좀 교환하고 싶어요!'),
(92132, '나는 내 의무를 다해야 한다.'),
(92133, '세상은 많이 변했고, 내가 떠났을 때와는 너무나도 달라 보입니다.\r\n\r\n무언가가 공기 중에 감돌지만, 무엇인지는 알 수 없습니다. 뭔가 잘못된 것 같은데, 생각은 뒤죽박죽이고 거의 갈피를 잡지 못하고 있습니다.\r\n\r\n하지만 당신은 보입니다. 당신은 내가 한때 고향이라 불렀던 곳, 내 동족들이 고향이라 불렀던 곳, 세월 속에 사라져 버린 곳에 있습니다.\r\n\r\n내가 왜 다시 여기에 있는지 모르겠지만, 당신이 나를 도와줄 것입니다.'),
(92137, '제발, 날 죽이지 마세요!\r\n\r\n제가 바로 유명한 사우스시 리저브 위스키의 제조법을 만든 밀주업자랍니다!\r\n\r\n원하신다면... 좀 사 가셔도 돼요!'),
(92168, '칼코르 포인트에 오신 것을 환영합니다. 길짐에 왜 켄타우로스가 있는지 궁금하실 텐데요.\r\n\r\n아주 오래전, 거의 6년 전쯤, 저희는 칼림도어를 떠나 남해 해적단에 합류했습니다. 용병이자 전사로 고용되었지만, 저희 두목이 저희를 배신하고 금화를 독차지했습니다.\r\n\r\n그는 잔혹하고 동료들을 전혀 배려하지 않는 성격 때문에 \'약탈자\'라는 악명을 얻었습니다. 칼코르 포인트라는 이름은 저희 용병단의 이름에서 따온 것이며, 저희는 이 이름을 자랑스럽게 생각합니다.\r\n\r\n언젠가는 고향으로 돌아가 동족과 재회할 수 있기를 바라지만, 그날은 아직 멀게만 느껴집니다.'),
(92171, '비극을 겪고도 계속 나아가며 세상에 좋은 모습을 유지하려면 용기가 필요합니다.'),
(92173, '여기서 문제를 일으키지 마세요. 당신과 싸우고 싶지 않아요.'),
(92174, '리쿠르고스는 자신이 저지른 일에 대한 대가를 치르게 될 것이다.'),
(92176, '꼬마가 도와주려고 왔어요? 정말 도와줄 수 있어요?'),
(92177, '음식 필요해? 필요한 거 있어? 나 물건 있어, 살 돈 있어?')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(92178, '갑옷이 필요하세요? 갑옷은 야생에서 쓰기 좋고, 무기도 좋지만, 전 무기는 못 만들어요! 당신처럼 작은 존재를 위해 뭘 만들어 드릴 수 있을지 한번 볼까요?'),
(92179, '마울오그에게 문제를 일으키지 마세요! 마울오그는 이미 충분히 골칫거리가 많습니다.'),
(92180, '나는 크룩조그 군주다. 이곳을 이끄는 자는 바로 나다. 우리는 한때 위대한 고르도쉬 부족의 일원이었지만, 이제는 홀로 남았다.\r\n\r\n너희는 나와 함께 마울로그의 영광을 되찾아야 한다!'),
(92181, '호드는 아제로스 전역에 걸쳐 연대를 구축하여, 궁극적으로 세력 균형을 우리에게 유리하게 바꾸고자 합니다.'),
(92182, '당신과 나 같은 탐험가들이 없었다면 세상에는 알려지지 않은 곳이 많았을 겁니다.'),
(92184, '아직 보지 못한 것을 내다보는 데는 상당한 지혜가 필요합니다. 저는 마울로그의 몰락을 예언했고, 제 백성들에게 이곳으로 피난하라고 경고했습니다. 부족을 구하기 위해서는 아직 해야 할 일이 많습니다. 외부의 도움 없이는 크룩조그 군주가 우리 백성을 파멸로 이끌 것입니다… 어쩌면 당신이 제가 두려운 꿈에서 본 그 사람일지도 모르겠습니다.'),
(92185, '하즈고르그는 많은 훌륭한 비전을 가지고 있으며, 미래를 볼 수 있습니다!'),
(92186, '위대한 예언자를 방해할 필요가 없다면 방해하지 마십시오. 그는 환상을 보고 있을지도 모릅니다.'),
(92187, '으... 오우거랑 트롤이 우글거리는 이 정글에 갇혔다고? 상상이나 해 봐?... 난 지금 상상만 해도 끔찍해.'),
(92188, '봐봐, 넌 오거가 아니잖아! 꼬마야, 도움이 필요한데, 도와줄 수 있겠니?'),
(92190, '라자리 일족은 광기에 휩싸이고 있다. 그들은 배신자라고 여긴 자들을 살해하고, 한때 금지되었던 흑마법을 사용하는 하주리 일족과 동맹을 맺고 있다.'),
(92191, '나는 그 난파 사고에서 살아남은 게 행운이었지만, 하필이면 이 황무지에 갇히게 되었어.'),
(92194, '피와 천둥, 블러드피스트 포인트는 아즈샤라로 향하는 새로운 원정대입니다. 당신은 지원 임무를 받았습니까?'),
(92196, '운명의 바람에 흔들리는 고요한 나뭇잎처럼 조용히 걸어가십시오. 스스로를 버려두는 것은 결코 좋은 생각이 아닙니다. 우리에게 주어진 모든 순간은 발전하고 기술을 연마하는 데 사용될 수 있습니다. 단 한순간이라도 낭비한다면, 그것은 삶과 죽음의 차이를 만들 수도 있습니다.'),
(92197, '저는 이번 원정대의 예지자로서 임무를 맡았습니다. 멀리 있는 상황을 주시하고 임박한 위험을 경고하는 것이 제 임무입니다. 또한, 저는 전장에서 스랄의 대표자로서의 역할도 수행할 것입니다.'),
(92199, '이 땅에는 뭔가 잘못된 것이 있는 것 같습니다. 마치 땅과 대지 자체가 큰 고통에 울부짖는 듯합니다. 당신도 그것을 느낄 수 있지 않습니까?'),
(92201, '대지모신시여, $R 님, 전장에서나 평화로운 곳에서나 축복을 내리소서.'),
(92217, '자기방어 수단이 필요하세요? 아즈샤라에서는 외교나 노움의 호의적인 태도가 안전을 보장해주지 않아요!'),
(92218, '여기선 할 일이 너무 많아요, 동시에 진행되는 프로젝트도 너무 많고요! 정신이 하나도 없네요.'),
(92219, '우리는 공학과 과학 분야 모두에서 놀랍고 경이로운 발전을 이루고 있습니다. 마법과 기술을 융합한 실험을 통해 큰 성공을 거두고 있죠!'),
(92220, '혁신만이 앞으로 나아갈 유일한 길이며, 때로는 고정관념에서 벗어난 사고가 필요합니다.'),
(92221, '저는 코도 가죽을 오랫동안 다뤄왔고, 확실히 이 분야에 가장 경험이 많습니다. 갑옷을 몇 개 드릴 수는 있지만, 재고가 한정되어 있습니다.'),
(92223, '나는 집에서 쫓겨났어. 펄볼그족이 통제 불능 상태가 됐거든.'),
(92936, '사우스쇼어는 아담하고 예쁜 마을이고, 제가 살던 곳과는 많이 다릅니다. 제3차 대전쟁의 참혹함을 겪지 않아서 다행이라고 생각합니다.'),
(92938, '저는 쿨 티라스의 시민이자 물 마법과 비전 마법 연구에 헌신하는 마법사, 마구스 발곤입니다.\r\n\r\n이 섬에는 수많은 불가사의가 숨겨져 있으며, 저는 그 모든 비밀을 밝히는 데 전념하고 있습니다.'),
(92940, '암벽 등반 작업은 여전히 ​​지루하기 짝이 없네요. 제 교대 시간이 빨리 끝나고 다른 동료가 대신해줬으면 좋겠어요. 사방에 모래가 날리고 락 크롤러들이 제 물건들을 엉망으로 만드는 것만큼 끔찍한 건 없거든요.'),
(92941, '우리는 원치 않는 함선을 폭파하기 위해 여기에 주둔하고 있습니다.'),
(100100, '비행기를 주의 깊게 살펴보니 옆면에 "너트 블래스텐톰의 소유물"이라는 문구가 휘갈겨 써져 있습니다.\r\n\r\n비행기는 작은 스티커들로 꾸며져 있습니다. 그중에는 작은 동전, 노란 앵무새, 망치가 있습니다.\r\n\r\n바닥에는 "FM 인수"라는 문구가 새겨져 있습니다.'),
(100200, '당신이 나와 함께 있어서 정말 좋군요 $N, 무엇을 도와드릴까요?'),
(100201, '아, $N이(가) 아닌가! 이 근방에서 정말 유명해졌더군.\r\n\r\n골드샤이어로 가야 하나? 음, 우리를 위해 해준 모든 일을 생각하면 거절할 수 없지. 특별한 호의로 이번 한 번만 그곳으로 순간이동시켜 주겠네.\r\n\r\n출발할 준비가 되었나? 일단 떠나면 한동안은 이곳으로 돌아올 수 없을 걸세.'),
(100202, '제가 도와드릴 일이 있으신가요? 지금 바쁘게 지내고 있습니다.'),
(100203, '제 유니콘들은 실버문 잔존 세력의 엘프들과 그들의 고귀한 동맹들에게만 판매합니다.'),
(100204, '오, 카라잔에 새로 오신 분들이시군요. 아, 이곳에 새로운 영혼들을 맞이하게 되어 정말 기쁩니다. 걱정 마세요, 제가 최대한 신속하게 여러분의 필요를 채워드리겠습니다. 하지만 지금은 주인님의 도착을 위해 숙소를 준비하느라 정신이 없습니다.\r\n그러니 그동안 다른 손님들과 함께 시간을 보내시며 위안을 얻으시길 바랍니다.'),
(100205, '모든 준비가 완료된 것 같으니, 이제 본격적인 소개를 할 시간인 것 같습니다.'),
(100400, '<이 돌은 낯선 마법으로 희미하게 맥동한다.>'),
(195007, '얼굴을 드러내지 않고 살인을 저지르는 전사는 명예가 없다.'),
(1000000, '아벤디스 여사께서 새 피를 고르실 때 성급하셨나 보군요. 만약 당신이 입구에서 나와 맞섰다면 여기까지 오지도 못했을 겁니다.\r\n$B꼴사납군요, 괴물, 혐오스러운 존재. 당신의 움직임, 싸우는 방식, 말하는 방식 모두 어둠의 주인의 꼭두각시 노릇을 하고 있는 겁니다. 혹시라도 양심이 조금이라도 남아 있다면, 한때 강력하다고 여겼던 존재에게 기도하십시오.\r\n$B당신 같은 비열한 놈에게 숨조차 제대로 쉬지 못했군요. 와서 최후를 맞이하십시오!'),
(1000001, '수년간 나는 비전 마법을 연구해 왔다. 기사단에서의 내 역할은 달랐지만 의미 있는 것이었다. 연구를 통해 강령술사들의 행적을 보아왔다. 자네처럼 강력한 괴물과 맞서 싸우게 될 줄은 상상도 못 했다.\r\n$B자네가 내 앞에 서서도 아직 공격하지 않고 있다는 사실이 조롱처럼 느껴지네. 어둠의 스승의 수치를 짊어진 자네가 자신을 그토록 과대평가하는 건가? 아아, 자네가 원하는 만족을 안겨주겠다.'),
(1000002, '나는 수도원이 예전 모습 그대로였음을 기억하고 싶다.$B\r\n예배와 기쁨의 장소, 젊은이들이 더 큰 목적을 찾아 찾아오는 곳. 바로 이 홀에서 수많은 이들이 수련하며 스스로를 지키는 법과 그들이 지켜야 할 가치를 배웠다.\r\n$B많은 이들이 빛에 사로잡히고, 이 불합리한 세상에 의해 학살당하고 불구가 되었다. 정의롭고 선한 사람들의 고통과 슬픔을 즐기는 너희 같은 존재들에게는 그저 장난감에 불과했다. 너희 모두를 저주한다. 너희는 우리가 스컬지의 비참한 하수인 몇 명에게 패배할 만큼 약하다고 생각하는가?\r\n발걸음을 세어 보아라. 그것이 너희의 마지막 발걸음이 될 것이다.$B 우리가 너희를 처리하고 나면, 우리의 조선공들은 준비될 것이고 우리는 우리만의 방식으로 정의를 구현할 것이다.\r\n$B어리석은 자들이여, 너희의 몰락이 다가온다. 나는 교단을 수호할 것이다!$B\r\n붉은십자군을 위하여!'),
(1000050, '우리는 곧 빛의 기적을 목격하게 될 것입니다. 알렉산드로스 모그레인이 곧 우리 앞에 나타날 것입니다.'),
(1000051, '나는 편히 쉴 수 없다. 붉은십자군이 몰락하는 것을 볼 때까지, 그리고 내 아들이 아버지를 죽인 죄에 대한 정의의 심판을 받을 때까지는.$B\r\n하지만 걱정하지 마라. 다른 누군가가 그 일을 해낼 것이다. 이 분노 속에서도 나는 마지막으로 아이들을 품에 안고 싶다. 나는 저 세상에서 편히 쉴 준비가 되어 있다, $N.'),
(2010799, '<강력한 힘으로 빛난다>.'),
(2010824, '곡물은 작은 자루에 담겨 있습니다.'),
(2010834, '이건 당신이 찾고 있는 화약통 중 하나인 것 같군요.'),
(2010866, '<강력한 힘으로 빛난다>.'),
(2010924, '그 식물에는 멀고어라는 자연환경과는 어울리지 않게 자란 듯한 신비로운 잎들이 달려 있습니다.'),
(2010933, '<수정이 불길하게 윙윙거린다.>'),
(2010934, '크리스탈은 침묵을 지킨다.'),
(2593000, '응? 뭘 원하는 거야? 내가 바쁜 게 안 보여? 볼일이 있으면 스타우트해머 중위에게 가 보라고.'),
(2593001, '야전 근무 신고를 하러 왔습니다. 서류에 서명이 필요합니다.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`) VALUES
(2593002, '그래? 우린 지금 당장이라도 공격이 들이닥칠 거라 예상하고 있네. 전초기지 방어를 도와주면 블랙앤빌 대장이 자네 서류에 서명해 줄 걸세.'),
(2593003, '준비됐습니다. (이벤트 시작)'),
(2593004, '그래, 그 공격을 막는 데 우리를 도왔다고? 그렇다고 내가 감탄할 줄 알았나.'),
(2593005, '도와줘서 고맙네. 유감스럽지만 이런 공격은 늘 있는 일이라네. 실리더스에선 그저 평범한 하루일 뿐이지.')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`, `female_text_loc1`) VALUES
(12388, '응, 진짜! <PH>', '응, 진짜! <PH>'),
(12427, '월드 오브 워크래프트와 Coca-Cola (R)가 함께 iCoke-월드 오브 워크래프트 여름 이벤트를 진행합니다. 특별 표시된 Coca-Cola 병뚜껑 아래의 코드를 찾아보세요. 그런 다음 이곳으로 돌아와 코드를 입력하면 게임 아이템을 받을 수 있습니다.', '월드 오브 워크래프트와 Coca-Cola (R)가 함께 iCoke-월드 오브 워크래프트 여름 이벤트를 진행합니다. 특별 표시된 Coca-Cola 병뚜껑 아래의 코드를 찾아보세요. 그런 다음 이곳으로 돌아와 코드를 입력하면 게임 아이템을 받을 수 있습니다.'),
(12830, 'iCoke 선물 상자 이벤트에 대해 알려주세요.', 'iCoke 선물 상자 이벤트에 대해 알려주세요.'),
(14625, '<의심스러운 눈으로 바라보는 사로잡힌 태양매 첩보원>$B$B한 번도 본 적이 없는데... 당신 누구요?', '<의심스러운 눈으로 바라보는 사로잡힌 태양매 첩보원>$B$B한 번도 본 적이 없는데... 당신 누구죠?'),
(30175, '보석세공', '보석세공'),
(41028, '이 살기 힘든 늪지대 한가운데서 신선한 고기와 음료를 찾을 줄은 몰랐을 거요. 비난할 수는 없지.', '이 험한 늪 한가운데서 신선한 고기와 마실 것을 발견할 줄은 상상도 못 했겠지. 그럴 만도 하지.\\N'),
(47024, '쉘코인에 투자하면 당신의 인생이 바뀔 수 있습니다. 내 인생을 바꿨죠. 난 한때 혼혈이라는 이유로 사회에서 배척당한 국외자였습니다. 아무도 내 가치를 증명할 기회를 주지 않았죠. 마를로스 카토스를 만나 그의 동료가 되는 날까지 전 단순한 금광 피온으로 노예처럼 일했습니다.\n\n당신도 미래에 투자하여 당신의 운명을 개척할 수 있습니다. 준비되셨나요?', '셸코인에 투자하면 인생이 바뀔 수 있습니다. 제 인생도 바뀌었죠. 저는 한때 혼혈이라는 이유로 사회에서 따돌림받던 외톨이였습니다. 누구도 제 가치를 증명할 기회를 주지 않았습니다. 그저 금광에서 일하는 막일꾼으로 고생하다가 말로스 카토스를 만나 그의 동업자가 되었죠.\n\n당신도 미래에 투자해서 자신의 운명을 직접 바꿀 수 있습니다. 준비됐습니까?\\N'),
(47026, '올라간다!', '오른다! 오른다고!\\N'),
(47027, '사라! 사라! 사라!', '사! 사! 지금 사!\\N'),
(47028, '팔아라!', '팔아!\\N'),
(47029, '난 올인한다!', '전부 걸겠어!\\N'),
(47046, '뱀이다! 도망쳐! 모두 도망쳐!', '뱀이다! 도망쳐! 모두 도망쳐!\\N'),
(51698, '전투에서 영원한 영광을 얻어 동료들을 뛰어넘는 꿈을 꾸는가? 피의 투기장에 들어와 아제로스 최고의 검투사들과 목숨을 건 승부를 벌여라. 평생 찾아 헤매던 영광이 마침내 그대의 것이 될 것이다.', '전투에서 영원한 영광을 얻어 동료들보다 우뚝 서는 꿈을 꾸는가? 피의 투기장에 들어가 아제로스 최고의 검투사들과 목숨을 건 승부를 벌여라. 평생 갈망해 온 영광을 손에 넣을 수 있을 것이다.\\N'),
(51699, '영웅이여, 우리의 말을 들어주십시오! 햇살 깃든 골짜기에 그대의 긴급한 도움이 필요합니다. 무한의 용군단 공작원들이 시간의 흐름을 조작하여 중요한 역사적 전투의 결과를 바꾸려 하고 있습니다. 성공한다면 우리가 아는 세계 자체가 달라질 수도 있습니다. 전투에 참가하여 상대 진영의 일원으로 위장한 그들의 요원들을 처치하십시오.', '영웅이여, 우리의 말을 들어 주십시오! 햇살숲 골짜기에 당신의 긴급한 도움이 필요합니다. 무한의 용군단 파괴공작원들이 시간을 교란해 중요한 역사적 전투의 결과를 바꾸려 하고 있습니다. 성공한다면 우리가 아는 세계 자체가 달라질 수 있습니다. 전투에 합류하여 상대 진영으로 위장한 그들의 요원들을 처치하십시오.\\N'),
(60316, '크르르... 스나를 섀도우포라고 부른다. 죽이는 게 필요하면 일거리는 많다. 머키 워터스는 남들이 하기 싫어하는 계약을 받는다. 네가 죽일 거리를 원한다면 제대로 찾아왔다. 골드 자루를 들고 물어봐라...', '으르릉... 나는 스날스 섀도포우. 누군가 죽여야 한다면 좋은 일거리 있지. 탁한 물결은 남들이 하기 싫어하는 일을 대신 맡아 준다. 죽이고 싶은 놈 있으면 제대로 찾아온 거야. 금화 자루 들고 부탁해...\\N'),
(60701, '흥미롭게 생긴 깃털을 발견했습니다.', '흥미롭게 생긴 깃털을 발견했습니다.\\N'),
(60903, '쉘 무역 회사에 오신 것을 환영합니다!\n\n난 천재야! 아제로스를 폭풍처럼 휩쓸 아주 새로운 통화를 발명했거든! 마법의 쉘코인은 각 동전이 유일무이하고 대체 불가능하여 물건을 교환하는 방식을 영원히 바꿀 거야.\n\n운이 다했나? 지금이 바로 쉘코인에 투자할 때다! 시장을 주시하고 대박을 터뜨려라!', '셸 주식회사 무역상사에 오신 것을 환영합니다!\n\n난 천재야! 아제로스를 뒤흔들 완전히 새로운 화폐를 발명했거든! 마법의 셸코인은 물건을 거래하는 방식을 영원히 바꿀 거야. 모든 동전이 하나뿐인 고유품이라 대체할 수도 없지.\n\n운이 안 풀리고 있다고? 바로 지금이 셸코인에 투자할 때야! 시세를 잘 보고 한몫 크게 잡으라고!\\N'),
(61773, '우리의 고통은 끝이 없습니다. 도와주시겠습니까?', '우리의 고통은 끝이 없습니다. 도와주시겠습니까?\\N'),
(61774, '저는 목이 마르지는 않았지만, 친절에 감사드립니다.', '목이 마르진 않았지만 친절은 고맙습니다.\\N'),
(61775, '내게서 떨어져!', '내게서 떨어져!\\N'),
(65014, '고대의 계약을 발동한다! 꿈의 길이여, 내 앞에 열리라.', '고대의 서약을 부른다! 꿈길이여, 내 앞에 열려라.\\N'),
(65015, '뭔가 잘못됐어…', '뭔가 잘못됐나?\\N'),
(65016, '고대의 계약을 발동한다! 에메랄드의 꿈으로 가는 길을 열어라!', '고대의 서약을 부른다! 에메랄드의 꿈으로 가는 길을 열어라!\\N'),
(65017, '이것들은 분명 나이트메어의 하수인들이었어. 어머, 대체 무슨 일이 벌어지고 있는 거지…', '분명 악몽의 하수인들이었어. 아, 대체 무슨 일이 벌어지고 있는 거지?\\N'),
(65018, '누가 감히 꿈의 길을 열 수 있을까?', '누가 감히 꿈길을 여는가?\\N'),
(65019, '이세라 부인…', '이세라 님?\\N'),
(65020, '빨리 말해, 랄라티우스. 악몽이 우리 진지로 다가오고 있어.', '빨리 말하라, 랄라티우스. 악몽이 우리 진지를 향해 전진하고 있다.\\N'),
(65021, '여신님, 저희에게 축복이 필요합니다. 각성을 막아줄 필멸의 영혼을 찾았습니다.', '여왕이시여, 당신의 축복이 필요합니다. 각성을 막으려는 필멸의 영혼을 찾았습니다.\\N'),
(65022, '정말 다행이다. 솔니우스는 이미 에메랄드 성소에 몸을 숨겼다. 각성이 임박했다.', '아슬아슬하게 때를 맞췄구나. 솔니우스는 이미 에메랄드 성소에 틀어박혔다. 각성이 시작되고 있다.\\N'),
(65023, '하지만 이 필멸자에게는 축복을 내릴 수 없다. 너무 위험하기 때문이다. 하이잘의 꿈의 길은 언제든 파괴될 수 있다.', '하지만 이 필멸자에게 내 축복을 줄 수는 없다. 너무 위험하다. 하이잘의 꿈길은 언제든 파괴될 수 있어.\\N'),
(65024, '라라니쿠스는 악몽에 굴복했다. 바로 지금 이 순간, 그는 꿈과 세계수의 연결고리를 끊기 위해 애쓰고 있다.', '라란니쿠스가 악몽에 굴복했다. 바로 지금, 그는 꿈과 세계수의 연결을 끊으려 하고 있다.\\N'),
(65025, '이런 일이 벌어진다면… 꿈속의 놀드랏실은 공격에 취약해지고, 꿈의 길은 닫혀 꿈속을 걸어 다닐 수 있는 선천적인 능력이 없는 자들은 모두 갇히게 될 것이다.', '그 일이 벌어지면... 꿈속의 놀드랏실의 모습은 공격에 취약해지고 꿈길은 닫혀, 타고난 꿈길 이동 능력이 없는 자들은 그 안에 갇히게 될 것이다.\\N'),
(65026, '라라니쿠스를 처치해야만 내가 축복을 내릴 수 있다.', '내 축복을 받으려면 먼저 라란니쿠스를 처치해야 한다.\\N'),
(65027, '이세라 님, 그들이 다가오고 있습니다. 가야 합니다.', '이세라 님, 놈들이 다가옵니다. 가야 합니다.\\N'),
(65028, '충실한 나의 하인, 랄라티우스. 에메랄드의 꿈의 운명은 네 손에 달려 있다.', '랄라티우스, 충실한 나의 종이여. 에메랄드의 꿈의 운명이 네 손에 달렸다.\\N'),
(65029, '안 돼…', '아, 안 돼...\\N'),
(65030, '%s는 시전 작업을 멈춥니다.', '%s|1이;가; 주문 시전을 멈춥니다.\\N'),
(65100, '준비됐어?', '준비됐나, 친구?\\N'),
(90257, '현재 경주가 진행 중입니다. 끝날 때까지 기다려 주세요.', '현재 경주가 진행 중입니다. 끝날 때까지 기다려 주세요.'),
(90630, '<고대 구조물이 받침대 형태로 만들어져 있다. 돌로 만들어진 것 같다. 마치 윙윙거리는 소리가 들리는 것 같아!>', '<받침대처럼 생긴 고대 구조물입니다. 돌로 만들어진 듯합니다. 맹세코 희미하게 웅웅거리는 소리가 들립니다!>\\N'),
(91974, '동굴은 안트노르미와 그 일당에게 침입당했지만, 우리는 그들을 막을 수 있습니다. 이 시간의 청동 원반을 사용하여 시간의 균열을 닫아야 합니다.$B$B 자, 서둘러! 내 뒤에 있는 시간의 균열을 닫고 나머지 두 개도 닫아!', '안트노르미와 그 무리가 동굴을 뚫고 들어왔지만, 우리가 놈들을 막을 수 있습니다. 이 시간의 청동 원반을 사용해 시간의 균열을 닫아야 합니다.$B$B서두르세요! 제 뒤의 시간의 균열을 닫고 남은 두 곳도 닫으십시오!\\N'),
(91975, '해냈군! 어서, 시간의 청동 원반을 내게 넘겨!', '해냈군요! 빨리, 시간의 청동 원반을 제게 주세요!\\N'),
(91976, '$n, 당신은 시간의 흐름을 망쳐놓은 것 같군요. 당신은 이곳에서 죽을 운명이 아니었습니다. 시간의 흐름을 바로잡으려면 당신의 실수를 바로잡아야 합니다. 제가 대신해 드릴 수는 없습니다.', '$n, 시간선을 깨뜨린 것 같군요. 당신은 여기서 죽을 운명이 아니었습니다. 시간선을 바로잡으려면 실수를 수정해야 합니다. 그 일은 제가 대신해 줄 수 없습니다.\\N'),
(91977, '해냈군요! 하지만 시간의 청동 원반은 잃어버린 것 같네요...', '해냈군요! 그런데 시간의 청동 원반을 잃어버린 것 같네요...\\N'),
(91978, '방해하지 말아 주세요. 시간 순서를 수정하는 데 엄청난 집중력이 필요합니다.', '방해하지 말아 주세요. 시간선을 바로잡는 데는 엄청난 집중력이 필요합니다.\\N'),
(92942, '야 몬?', '왜, 친구?\\N'),
(92950, '<비행 기계가 제자리에서 웅웅거리며 듀로타의 스파크워터 항구로 날아갈 승객을 기다리고 있습니다.>', '<비행기가 제자리에서 윙윙거리며 듀로타의 스파크워터 항구로 갈 승객을 기다립니다.>\\N'),
(92951, '비행기가 윙윙거리며 멈춰 서서 블랙스톤 섬으로 날아갈 승객을 기다리고 있다.', '<비행기가 제자리에서 윙윙거리며 블랙스톤 섬으로 갈 승객을 기다립니다.>\\N'),
(100000, '이 노래꽃은 타락의 바다인 악령의 숲에서 바위처럼 솟아 있습니다. 꽃잎에서는 용기를 북돋우고 결의를 다지게 하는 강렬한 향기가 피어납니다.', '악령의 숲을 뒤덮은 타락의 바다 한가운데, 이 노래꽃은 바위처럼 굳건히 피어 있습니다. 꽃잎에서 풍기는 강렬한 향기가 기운을 북돋우고 결의를 굳게 해 줍니다.\\N'),
(100001, '이 바람꽃은 악령의 숲이라는 어둠 속에서 등대처럼 빛을 발합니다. 탐스럽고 즙이 많은 열매가 주렁주렁 열려 있어 따먹기 좋게 익어 있습니다.', '어둠에 잠긴 악령의 숲에서 이 바람꽃은 한 줄기 등불처럼 눈에 띕니다. 통통하고 탐스러운 열매가 가지마다 주렁주렁 매달려 있어 금방이라도 따 먹을 수 있을 듯합니다.\\N')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`), `female_text_loc1` = VALUES(`female_text_loc1`);

INSERT INTO `locales_broadcast_text` (`entry`, `male_text_loc1`, `female_text_loc1`) VALUES
(100002, '이 싱싱한 채찍뿌리는 악령의 숲을 지배하는 병든 타락과 극명한 대조를 이룹니다. 부드럽고 건강한 뿌리에서는 맛있는 덩이줄기가 나와 식물 옆 땅에 놓여 있습니다.', '건강하게 자란 이 채찍뿌리는 악령의 숲을 뒤덮은 병든 타락과는 정반대의 모습입니다. 연하고 튼튼한 뿌리에서 먹음직스러운 덩이줄기가 돋아나 식물 옆 바닥에 놓여 있습니다.\\N'),
(100003, '이 생기 넘치는 밤의 용 식물은 악령의 숲을 갈라놓는 악마의 오염과 극명한 대조를 이룹니다. 밤의 용의 숨결이라 불리는 희귀하고 달콤한 열매가 주렁주렁 열려 있습니다.', '생기 넘치는 이 어둠용 식물은 악령의 숲을 찢어 놓은 악마의 타락과 선명한 대비를 이룹니다. \'어둠용의 숨결\'이라 불리는 희귀하고 탐스러운 열매가 가지에 무겁게 매달려 있습니다.\\N'),
(100401, '<고대 늑대 정령은 다른 일에 정신이 팔린 듯하다.>', '<고대 늑대 정령은 다른 무언가에 정신이 팔린 듯합니다.>\\N'),
(100402, '"영혼들은 언제나 우리를 부르고 있어요. 그저 귀 기울여 듣기만 하면 돼요."', '"정령들은 언제나 우리를 부르고 있지. 귀 기울일 줄만 알면 그 목소리를 들을 수 있다네." \\N'),
(100403, '치료사를 부르세요!', '치유사를 불러!\\N'),
(100404, '하지만 저는 아니에요!', '하지만 난 아니지!\\N'),
(100405, '$r, 너 수영할 줄 아길 바라.', '수영할 줄은 알겠지, $r?\\N'),
(100500, '쉴 곳을 찾고 계신가요, $c?', '쉴 곳을 찾고 있나, $c?\\N')
ON DUPLICATE KEY UPDATE `male_text_loc1` = VALUES(`male_text_loc1`), `female_text_loc1` = VALUES(`female_text_loc1`);
